window.__SUM[8]={"LR005391":{"pair":"ADAM10 -> EFNA5","headline":"ADAM10 forms a ternary complex with EphA3 and ephrin-A5 and cleaves ephrin-A5 in trans; this is a sheddase-substrate relationship, not a direct binary binding.","interaction_type":"functional only","direction_and_effect":"ADAM10 cleaves ephrin-A5 bound to EphA3; the cleavage occurs in trans, with ADAM10 and substrate on opposing cells [PMID:16239146]. UniProt records a ternary EFNA5-EPHA3-ADAM10 complex mediating EFNA5 shedding [DB:UniProt].","molecular_requirements":"A functional EphA3/ephrin-A5 complex creates a new recognition motif for the ADAM10 cysteine-rich domain; ADAM10 constitutively associates with EphA3 [PMID:16239146]. Direct ADAM10-ephrin-A5 binding is not reported.","affinity_potency":[],"species_and_systems":"Mouse species recorded for both partners in the curator row; the paper structure and functional work [PMID:16239146]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both flagged membrane (not secreted); EFNA5 transmembrane [flag]; cleavage between opposing cell membranes [PMID:16239146].","caveats":"One paper, abstract only. Another judged row was different-entity.","key_references":[{"PMID":"16239146","why":"ADAM10 cleaves ephrin-A5 in trans within the EphA3 complex"}],"covers":["LR002065","LR005391"]},"LR003555":{"pair":"ADAM12 -> ITGB1","headline":"ADAM12 disintegrin domain binds integrin alpha9beta1, implicating the beta1 chain only as part of the complex.","interaction_type":"direct binding","direction_and_effect":"Recombinant ADAM-12 and ADAM-15 disintegrin domains bind integrin alpha9beta1 in an RGD-independent manner [PMID:10944520].","molecular_requirements":"Evidence is for the alpha9beta1 heterodimer; beta1 is its partner chain, and beta1 alone is not shown [PMID:10944520].","affinity_potency":[],"species_and_systems":"Recombinant domains; species not reported in our evidence.","localisation_and_range":"ADAM12 is flagged secreted; ITGB1 not secreted [flag].","caveats":"One abstract-only paper; ITGB1 is credited through alpha9beta1, so expression of ITGA9 is needed to follow this evidence.","key_references":[{"PMID":"10944520","why":"alpha9beta1 binding to ADAM-12 disintegrin domain"}],"covers":["LR000005","LR003555"]},"LR003564":{"pair":"ADAM23 -> ITGB3","headline":"ADAM23 binds alphavbeta3 via its disintegrin domain; human, two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"ADAM 23 shows a specific interaction with alphavbeta3 via its disintegrin loop [PMID:10749942]; knockdown enhances alphavbeta3 activation 2- to 4-fold and migration/adhesion [PMID:19549921].","molecular_requirements":"beta3 acts with alphav; RGD-independent loop sequence [PMID:10749942].","affinity_potency":[],"species_and_systems":"Human cells, transfected HeLa, MDA-MB-435 [PMID:10749942][PMID:19549921]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM23 is flagged secreted [flag].","caveats":"Abstracts only; interaction modulatory effect annotated Stimulatory in the database but the 2009 paper shows ADAM23 dampens activation, which may conflict.","key_references":[{"PMID":"10749942","why":"Disintegrin loop binds alphavbeta3"},{"PMID":"19549921","why":"ADAM23 loss enhances alphavbeta3 activation"}],"covers":["LR000014","LR003564"]},"LR001629":{"pair":"ADAM29 -> ITGA4","headline":"Human ADAM29 supports integrin alpha4-dependent cell adhesion; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Human ADAM11, ADAM23 and ADAM29 selectively support integrin alpha4-dependent cell adhesion; the disintegrin-like domains of these catalytically inactive ADAMs are ligands [PMID:28913673].","molecular_requirements":"Alpha4-dependent; partner beta chain not stated in our evidence [PMID:28913673].","affinity_potency":[],"species_and_systems":"Human proteins; integrin binding assays [PMID:28913673]. Mouse pair is ortholog-inferred.","localisation_and_range":"ADAM29 is flagged non-secreted [flag].","caveats":"Abstract read only and the evidence sentence is truncated; adhesion support only, no affinity.","key_references":[{"PMID":"28913673","why":"Non-catalytic ADAM29 is an integrin alpha4 ligand"}],"covers":["LR001629","LR005017"]},"LR003573":{"pair":"ADAM9 -> ITGAV","headline":"ADAM9 disintegrin domain binds alphaV-containing integrins (alphaVbeta5 antibody-blocked adhesion); two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"GST-ADAM9 disintegrin domain recovered alphav and other integrin chains from renal lysate [PMID:15361064]. Myeloma cell adhesion to the recombinant disintegrin domain was completely blocked by anti-alpha(v)beta(5) but not antibodies to other subunits, and RGD peptides had no effect [PMID:11162558]. The curated effect is Stimulatory [flag].","molecular_requirements":"Partner is an alphaV heterodimer; beta5 is implicated by the antibody block [PMID:11162558], while the first paper also recovered beta1 [PMID:15361064]. Divalent cations (Mn2+, Ca2+) supported binding; RGD-independent [PMID:11162558].","affinity_potency":[],"species_and_systems":"Human; HEK-293/renal lysate [PMID:15361064] and myeloma cells with recombinant disintegrin domain [PMID:11162558]. Mouse pair is ortholog-inferred, not tested.","localisation_and_range":"Annotation flags mark ADAM9 as secreted [flag], but the papers use its disintegrin domain as a recombinant or cell-surface-expressed protein, so the physiologically relevant range (juxtacrine versus shed) is not settled in our evidence.","caveats":"Both papers read as abstracts only. The adhesion result in [PMID:11162558] is functional (antibody inhibition), not direct binding. One further paper was abstract_insufficient. Affinity not reported.","key_references":[{"PMID":"11162558","why":"alphaVbeta5 antibody blocks adhesion to ADAM9 disintegrin domain"},{"PMID":"15361064","why":"alphaV and beta1 chains captured by disintegrin domain"}],"covers":["LR000023","LR003573"]},"LR002079":{"pair":"ADGRG1 -> TGM2","headline":"GPR56 (ADGRG1) reported to bind TG2 in one abstract-only paper; ligand-receptor direction is unclear.","interaction_type":"direct binding","direction_and_effect":"GPR56 binds specifically to tissue transglutaminase TG2, a stromal component; GPR56 overexpression suppressed melanoma growth and metastasis [PMID:16757564]. UniProt also lists the interaction [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human melanoma cell variants and tumour models, per abstract [PMID:16757564]; the human pair is marked ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted and not transmembrane [flag]; the paper calls TG2 a stromal component [PMID:16757564].","caveats":"Abstract only; the binding assay is not described. Growth suppression is in vivo only [PMID:16757564]. UniProt cites the same paper plus two others [DB:UniProt].","key_references":[{"PMID":"16757564","why":"reports GPR56-TG2 binding and tumour suppression"}],"covers":["LR002079","LR005405"]},"LR005409":{"pair":"ADGRL1 -> TENM2","headline":"LPH1 (ADGRL1) binds teneurin-2 (Lasso splice variant) strongly; one abstract-only paper plus a UniProt statement.","interaction_type":"direct binding","direction_and_effect":"LPH1 and Lasso (a teneurin-2 splice variant) interact strongly and specifically and copurify from rat brain [PMID:21724987]. Cells expressing them attract each other and form junctions [PMID:21724987]. A C-terminal Lasso fragment interacts with LPH1 and induces Ca(2+) signals in presynaptic boutons [PMID:21724987]. UniProt describes teneurin-2 as a ligand of ADGRL1 [DB:UniProt].","molecular_requirements":"The splice variant Lasso was the isolated form [PMID:21724987].","affinity_potency":[],"species_and_systems":"Rat brain extract purification, cell co-culture, hippocampal neurons [PMID:21724987]; human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both membrane-bound; LPH1 presynaptic and Lasso postsynaptic, so trans-synaptic [PMID:21724987].","caveats":"Abstract only; no affinity reported. The stored evidence sentence only states copurification, which is weaker than direct binding.","key_references":[{"PMID":"21724987","why":"purification of Lasso/teneurin-2 as LPH1 ligand"}],"covers":["LR002083","LR005409"]},"LR003582":{"pair":"ADM2 -> CALCRL","headline":"ADM2 (intermedin) activates CRLR/RAMP receptor complexes, with binding competition and in vivo effects; strong evidence, but CALCRL needs a RAMP.","interaction_type":"direct binding","direction_and_effect":"Intermedin raised cAMP and competed with labelled CGRP for binding in SK-N-MC and L6 cells with endogenous CGRP receptors; it is a nonselective agonist across RAMP1, 2 and 3 with CRLR in 293T cells. In vivo it lowered blood pressure in rats and suppressed gastric emptying in mice [PMID:14615490]. GtoPdb: full agonist [DB:GtoPdb].","molecular_requirements":"A CRLR/RAMP receptor complex is required; no RAMP preference [PMID:14615490]. Score as CALCRL plus a RAMP.","affinity_potency":[{"value":"pEC50 7.5-9.1","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"},{"value":"pEC50 7.5-8.3","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Recombinant 293T cells, endogenous-receptor cell lines, and rats and mice in vivo [PMID:14615490]; curators annotate human ligand and receptor. Mouse pair is projected from human.","localisation_and_range":"ADM2 is flagged secreted [flag]; acts as a circulating or paracrine peptide on a membrane receptor.","caveats":"Abstract-only. Binding was competition with labelled CGRP, not a direct ADM2 radioligand. Two further papers are review_only; the second confirmed paper is not shown.","key_references":[{"PMID":"14615490","why":"intermedin signals through CRLR/RAMP complexes; in vivo effects"}],"covers":["LR000032","LR003582"]},"LR011691":{"pair":"ADM2 -> CALCRL:GPER1:RAMP3","headline":"No paper supports this complex; only database records for ADM2 with CALCRL and RAMP3, and nothing in our evidence for GPER1.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists ADM2 as a full agonist at CALCRL and at RAMP3 [DB:GtoPdb]. A cryoEM structure of the active adrenomedullin 2 receptor G protein complex with adrenomedullin 2 peptide is recorded [DB:PDB 6UVA]. UniProt says RAMP3 with CALCRL forms the receptor complex for ADM and ADM2 [DB:UniProt].","molecular_requirements":"Database records support CALCRL plus RAMP3 only [DB:UniProt][DB:PDB 6UVA]. A GPER1 requirement is not reported in our evidence; the complex may be over-scored by the least-expressed-subunit rule if GPER1 is low.","affinity_potency":[{"value":"pEC50 8.899999618530273-10.100000381469727","assay":"GtoPdb agonist record (ADM2-RAMP3)","system":"not given","cite":"DB:GtoPdb"},{"value":"pEC50 7.5-8.3","assay":"GtoPdb agonist record (ADM2-CALCRL)","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"ADM2 is flagged secreted and RAMP3 transmembrane [flag].","caveats":"No papers: both judged papers were abstract_insufficient. GPER1 membership is unsupported.","key_references":[],"covers":["LR011691"]},"LR001638":{"pair":"ADM2 -> RAMP3","headline":"ADM2 binds the RAMP3-CLR (AM2 receptor) complex among three RAMP-CLR ECDs; one abstract plus database support, RAMP3 acts with CLR.","interaction_type":"direct binding","direction_and_effect":"AM2/IMD bound the purified RAMP3-CLR ECD complex, preferring the CGRP and AM2 receptor complexes [PMID:30139742]. GtoPdb lists a full agonist [DB:GtoPdb]. A cryoEM structure with chains of ADM2 and RAMP3 is recorded [DB:PDB 6UVA].","molecular_requirements":"RAMP3 with CLR/CALCRL; UniProt says RAMP3 and CALCRL form the receptor complex for ADM and ADM2 [DB:UniProt].","affinity_potency":[{"value":"pEC50 8.899999618530273-10.100000381469727","assay":"GtoPdb agonist record","system":"not given","cite":"DB:GtoPdb"}],"species_and_systems":"Purified recombinant ECD complexes; curators annotate human ligand and receptor. Mouse pair projected from human.","localisation_and_range":"RAMP3 is flagged transmembrane; ADM2 secreted [flag].","caveats":"The one shown paper is abstract-only. One paper is pending; three are review_only.","key_references":[{"PMID":"30139742","why":"AM2/IMD binding across RAMP-CLR ECD complexes"}],"covers":["LR001638","LR005026"]},"LR002088":{"pair":"AGGF1 -> ITGA5","headline":"AGGF1 binds integrin alpha5beta1 on endothelial cells (antibody blocking, pull-down, cell binding); alpha5 and beta1 both appear required.","interaction_type":"direct binding","direction_and_effect":"AGGF1 interacts with alpha5beta1 and activates FAK, Src and AKT; siRNA for ITGA5 reduced AGGF1-stimulated AKT phosphorylation [PMID:34551592]. An RDD angiogenic domain (residues 604-613, FQRDDAPAS) is required; peptides carrying it block AGGF1 function, an RGD-mutant 15-mer did not [PMID:34551592].","molecular_requirements":"Only anti-alpha5, anti-beta1 and anti-alpha5beta1 antibodies blocked HUVEC binding to AGGF1; anti-alpha1, 2, 3, 4, 6, alphaV and beta3 did not. GST-AGGF1 pulled down integrin alpha5 from HUVEC extract, and the angiogenic-domain deletion lost alpha5 and beta1 pull-down [PMID:34551592]. Score as the alpha5beta1 pair.","affinity_potency":[{"value":"T1/2 18.7 nM","assay":"half-maximum binding concentration, cell adhesion assay (not a Kd)","system":"HUVEC","cite":"PMID:34551592"}],"species_and_systems":"Human HUVEC; mouse aortic endothelial cells showed similar signalling; angiogenic domain tested in a mouse peripheral-artery-disease model [PMID:34551592]. The mouse pair is projected from human.","localisation_and_range":"AGGF1 is flagged secreted [flag]; ITGA5 is flagged not secreted and receptor [flag].","caveats":"Binding was shown with cells, blocking antibodies and lysate pull-down, not purified proteins, so direct contact is inferred. Curators recorded the paper as abstract_only but excerpts were available.","key_references":[{"PMID":"34551592","why":"identifies integrin alpha5beta1 as AGGF1 receptor; maps RDD angiogenic domain"}],"covers":["LR002088","LR005414"]},"LR005418":{"pair":"AGRN -> ITGB1","headline":"The same single 1997 abstract-only paper as ITGAV: beta1 antibodies fully blocked agrin signalling, but direct binding is not shown.","interaction_type":"functional only","direction_and_effect":"Agrin-induced aggregation of acetylcholine receptors on cultured myotubes was completely blocked by antibodies to the beta1 integrin subunit [PMID:9367446]. Cells expressing alpha(v) and beta1 adhered to immobilised agrin, blocked by anti-beta1 antibodies [PMID:9367446].","molecular_requirements":"The abstract points to alpha(v)beta1 as the relevant integrin [PMID:9367446]; Reactome lists an Agrin:Integrin alphaVbeta1 complex [DB:Reactome]. A beta1-alone requirement is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species unspecified in the curator record [PMID:9367446]. Cultured myotubes and non-muscle cells.","localisation_and_range":"Agrin is a basal lamina-associated proteoglycan; ITGB1 is flagged as a non-secreted receptor [flag] [PMID:9367446].","caveats":"Abstract read only; antibody-block data cannot separate direct binding from modulation, and the authors say integrins are 'components or modulators' [PMID:9367446]. Only one paper supports this pair. No affinity reported.","key_references":[{"PMID":"9367446","why":"Anti-beta1 antibodies completely blocked agrin-induced receptor aggregation"}],"covers":["LR002092","LR005418"]},"LR003591":{"pair":"AGRP -> MC3R","headline":"AGRP is an antagonist of MC3R, supported by several abstract-read papers (functional, structural) and GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Recombinant Agouti-related protein was a potent, selective antagonist of Mc3r and Mc4r [PMID:9311920]; it acts as a competitive antagonist of alpha-MSH at MC-3 and MC-4 receptors [PMID:9819197]. GtoPdb records the interaction as an antagonist with pIC50 units [DB:GtoPdb]. An NMR paper calls AGRP an endogenous antagonist of MC3R and MC4R [PMID:11747427].","molecular_requirements":"The AGRP C-terminal domain AGRP(87-132) has binding and antagonism equivalent to the full-length protein [PMID:11747427]. The RFF111-113 triplet is the most critical portion for MC3R and MC4R binding, and the Cys-110 to Cys-117 loop is critical for antagonist activity [PMID:9893984]. The synthetic octapeptides bound MC3R with lower affinity than MC4R [PMID:9893984].","affinity_potency":[{"value":"pIC50 7.7","assay":"competitive antagonism of alpha-MSH, bacterially expressed AGRP","system":"MC3R, human protein","cite":"PMID:9819197"}],"species_and_systems":"Recombinant or synthetic human AGRP on human receptors per curation tags; transgenic mice used for the obesity phenotype [PMID:9311920].","localisation_and_range":"AGRP is flagged secreted and non-transmembrane [flag]; AGRP is a hypothalamic neuropeptide in the abstract [PMID:9311920].","caveats":"All papers read as abstracts. The NMR structure is of the ligand alone, not a co-structure [PMID:11747427]. Human pair is not ortholog-inferred; mouse is.","key_references":[{"PMID":"9311920","why":"Recombinant AGRP is a potent, selective Mc3r/Mc4r antagonist; transgenic obesity"},{"PMID":"9819197","why":"Competitive antagonism of alpha-MSH at MC-3 and MC-4 receptors; pIC50 7.7"},{"PMID":"9893984","why":"Maps the RFF111-113 triplet and Cys110-Cys117 loop"}],"covers":["LR000041","LR003591"]},"LR002097":{"pair":"AHSG -> TLR4","headline":"Fetuin-A (AHSG) is reported as a direct TLR4 ligand in mice, with mapped binding residues; supported by one paper.","interaction_type":"direct binding","direction_and_effect":"Fetuin-A acts as an agonist: in high-fat-diet mice, knockdown reduced Tlr4-mediated adipose inflammatory signalling, while FetA administration induced inflammation and insulin resistance [PMID:22842477].","molecular_requirements":"FFA-induced cytokine expression in adipocytes needed both FetA and Tlr4. FFAs did not act with galactoside-cleaved FetA or mutated Tlr4 [PMID:22842477].","affinity_potency":[],"species_and_systems":"Mouse experiments (mice and adipocytes) [PMID:22842477]; pair is human with mouse ortholog-inferred.","localisation_and_range":"AHSG is flagged secreted and TLR4 a receptor [flag]; the paper says FetA binds through its terminal galactoside moiety.","caveats":"Binding is reported as Leu100-Gly123 and Thr493-Thr516 in Tlr4 [PMID:22842477]. Single paper read as abstract only. No database records or affinity.","key_references":[{"PMID":"22842477","why":"FetA binds Tlr4 and mediates lipid-induced insulin resistance"}],"covers":["LR002097","LR005423"]},"LR001647":{"pair":"ALKAL2 -> LTK","headline":"ALKAL2 binds and robustly activates LTK in human systems; structural and cell evidence, no affinity values.","interaction_type":"direct binding","direction_and_effect":"ALKAL2 (AUG-alpha) binds and robustly activates LTK as well as ALK [PMID:26630010]. ALKAL1 and ALKAL2 are both strong activators of LTK [PMID:34646012]. GtoPdb lists agonist/activation [DB:GtoPdb].","molecular_requirements":"LTK-ALKAL2 complexes were 2 receptors : 1 cytokine [PMID:34646012]. The crystallised LTK complex was with ALKAL1; ALKAL1 is called the high-affinity cytokine for LTK [PMID:34646012], so ALKAL2 is the weaker-described partner here, though no values are given. Other subunit or co-receptor requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human recombinant proteins and cells expressing human LTK [PMID:26630010] [PMID:34646012]. Mouse pair inferred by orthology.","localisation_and_range":"ALKAL2 is flagged as secreted [flag]; Reactome has the LTK dimer:ALKAL1,2 complex at the plasma membrane [DB:Reactome].","caveats":"The LTK structural work used ALKAL1, so the ALKAL2-LTK result rests on the stoichiometry statement and the 2015 abstract [PMID:34646012] [PMID:26630010]; the latter was read as abstract only. No affinity or potency values for ALKAL2-LTK in our evidence. One row pending.","key_references":[{"PMID":"26630010","why":"Binding and robust LTK activation by ALKAL2"},{"PMID":"34646012","why":"LTK-cytokine complex stoichiometry and activation"}],"covers":["LR001647","LR005035"]},"LR005427":{"pair":"ANGPT2 -> ITGA5","headline":"No curated paper supports ANGPT2-ITGA5; the only paper involves alphaVbeta1, and UniProt alone asserts the ITGA5 interaction.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ANGPT2 interacts with ITGA5 [DB:UniProt]; direction and effect are not reported in our evidence. The judged paper describes Ang2 interacting with alpha(v)beta(1) integrin in Tie2-deficient human glioma cells, activating FAK, ERK1/2 and JNK and increasing MMP-2 expression [PMID:16424009].","molecular_requirements":"The paper implicates alpha(v) and beta(1) integrins, not alpha5 [PMID:16424009]. BioGRID records ANGPT2-ITGB1 affinity capture-Western and reconstituted complex, which concern the beta1 chain [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Human glioma cells and a murine brain xenograft in the alphaVbeta1 paper [PMID:16424009].","localisation_and_range":"ANGPT2 is flagged as secreted; ITGA5 is flagged as a receptor and not secreted [flag].","caveats":"Both rows for this pair on the one paper were judged pair_absent (verified negative for ITGA5 in that paper) [PMID:16424009]. Support rests on a UniProt annotation. Paralog issue: the alpha chain partner in the paper differs.","key_references":[{"PMID":"16424009","why":"Ang2 interacts with alphaVbeta1 integrin; ITGA5 not examined"}],"covers":["LR002101","LR005427"]},"LR008208":{"pair":"ANGPT2 -> ITGA5:ITGB1","headline":"No judged paper; rests on UniProt (ITGA5) and BioGRID (ITGB1) records only.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ANGPT2 interacts with ITGA5 [DB:UniProt]. BioGRID lists ANGPT2-ITGB1 reconstituted complex and affinity capture-Western records [DB:BioGRID]. Direction and effect are not reported in our evidence.","molecular_requirements":"The two integrin chains are supported separately by database entries (ITGA5 by UniProt, ITGB1 by BioGRID); no record in our evidence shows the alpha5beta1 heterodimer binding ANGPT2.","affinity_potency":[],"species_and_systems":"Human entities; experimental system not reported in our evidence for the alpha5beta1 pairing.","localisation_and_range":"ANGPT2 is flagged as secreted; the integrin chains are flagged as receptors and not secreted [flag].","caveats":"One paper row was abstract_insufficient. The related alphaVbeta1 paper [PMID:16424009] was judged pair_absent for ITGA5 in the single-chain pair, so alpha5 specificity is unsupported. The BioGRID entries cite that paper [DB:BioGRID].","key_references":[],"covers":["LR008208"]},"LR003609":{"pair":"ANGPTL4 -> TIE1","headline":"ANGPTL4 induces TIE1 phosphorylation in endothelial cells; functional evidence only, weaker than for TEK, with a possibly conflicting database record.","interaction_type":"functional only","direction_and_effect":"Native Ang4 induced Tie1 phosphorylation, less efficiently than the engineered COMP-Ang1 chimera [PMID:15851516].","molecular_requirements":"Activation was amplified via Tie2: Tie2 formed heteromeric complexes with Tie1 and enhanced Tie1 activation [PMID:15851516]. Whether Tie1 responds to Ang4 alone is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial cells and transfected cells; species not reported in our evidence [PMID:15851516].","localisation_and_range":"Ligand flagged secreted [flag]; receptor localisation not reported in our evidence.","caveats":"Abstract-only evidence, and it shows phosphorylation, not binding. A BioGRID reconstituted-complex record cites another paper [DB:BioGRID]; no binding data from it are shown in this dossier. Two further papers were judged abstract_insufficient.","key_references":[{"PMID":"15851516","why":"Ang4 induces Tie1 phosphorylation, amplified by Tie2"}],"covers":["LR000059","LR003609"]},"LR008190":{"pair":"ANGPTL3 -> ITGAV:ITGB3","headline":"Recombinant ANGPTL3 binds the integrin alphaVbeta3 heterodimer and activates integrin signalling; one abstract-level paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"Recombinant ANGPTL3 bound alpha(v)beta(3), induced dependent haptotactic endothelial adhesion and migration, and stimulated Akt, MAPK and FAK phosphorylation [PMID:11877390]. UniProt records binding to endothelial cells via ITGAV:ITGB3 [DB:UniProt].","molecular_requirements":"Both chains are in the evidenced complex (alphaV and beta3) [PMID:11877390]. The fibrinogen-like domain alone was sufficient for endothelial adhesion [PMID:11877390].","affinity_potency":[],"species_and_systems":"Endothelial cells and rat corneal assay; recombinant protein species not reported in our evidence [PMID:11877390].","localisation_and_range":"ANGPTL3 is liver-specific and secreted [PMID:11877390]; the receptor entity is flagged transmembrane [flag].","caveats":"Abstract-only; no affinity. Co-IP failed to detect ANGPTL3 binding to Tie2 [PMID:11877390].","key_references":[{"PMID":"11877390","why":"ANGPTL3 binds alphaVbeta3 and activates integrin signalling"}],"covers":["LR008190"]},"LR005436":{"pair":"ANGPTL4 -> ITGB1","headline":"ANGPTL4 is reported to bind integrin \u03b21 directly and drive FAK-Src-PAK1 signalling; abstract-level.","interaction_type":"direct binding","direction_and_effect":"ANGPTL4 binds integrins \u03b21 and \u03b25, but not \u03b23, as novel binding partners; \u03b21-bound ANGPTL4 activates FAK-Src-PAK1 signalling for keratinocyte migration [PMID:20952587]. ANGPTL4-deficient or neutralised mice show delayed wound reepithelialisation with impaired integrin-mediated signalling [PMID:20952587].","molecular_requirements":"Integrin \u03b21 alone is named as the binding partner; \u03b1-chain pairing is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Keratinocytes and mouse wound healing; species of the binding experiments not recorded in our fields [PMID:20952587]. The mouse pair is ortholog-inferred, not tested directly.","localisation_and_range":"ANGPTL4 flagged secreted; ITGB1 flagged receptor, non-secreted [flag]; wound-site paracrine signalling is implied by the paper.","caveats":"Abstract only; no affinity; an IntAct surface plasmon resonance record exists (PMID 21397862) [DB:IntAct]. The 'not \u03b23' statement excludes \u03b23 only.","key_references":[{"PMID":"20952587","why":"ANGPTL4 binds integrins \u03b21 and \u03b25 and signals through FAK-Src-PAK1"}],"covers":["LR002114","LR005436"]},"LR001656":{"pair":"ANXA2 -> TLR2","headline":"Monomeric ANXA2 binds and activates TLR2 in co-immunoprecipitation and reporter assays; single paper, human and mouse systems.","interaction_type":"direct binding","direction_and_effect":"Monomeric ANXA2 (ANXA2m) was identified as a TLR2-binding protein by mass spectrometry, and ANXA2 and TLR2 coimmunoprecipitated in GL261 lysates [PMID:26885373]. It acts as an agonist: it activated TLR2-expressing reporter cells and immature dendritic cells, upregulated CD80 and CD86, and induced IL-12p70, TNF-alpha and IFN-gamma; the adjuvant effect was TLR2-dependent in TLR2+/+ versus TLR2-/- mice [PMID:26885373]. BioGRID records the interaction from the same paper [DB:BioGRID].","molecular_requirements":"The monomeric form is the TLR2 ligand; the heterotetramer is described as signalling via TLR4 (background statement). The amino-terminal 15 amino acids of ANXA2m are necessary and sufficient for TLR2 binding and DC activation [PMID:26885373]. Whether other TLR2 partners are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Murine GL261 glioma lysates, human TLR2-expressing HEK-Blue reporter cells, murine and human DCs, and mice [PMID:26885373]. The human pair in this dossier is ortholog-inferred; the mouse pair is not.","localisation_and_range":"ANXA2 is flagged as secreted [flag]; the paper notes it can be intracellular, membrane-bound or secreted [PMID:26885373].","caveats":"Single paper, abstract plus excerpts; no affinity measured. Active form is oxygen-regulated (enriched at 5 % O2) and monomeric, which matters when scoring expression.","key_references":[{"PMID":"26885373","why":"Identifies monomeric ANXA2 as TLR2 ligand and maps the 15-aa N-terminal binding region."}],"covers":["LR001656","LR005043"]},"LR005445":{"pair":"ANXA2 -> TLR4","headline":"Annexin A2 tetramer activates macrophages through TLR4 in functional, knockdown and knockout experiments; no direct binding shown.","interaction_type":"functional only","direction_and_effect":"Soluble annexin A2 tetramer (A2t) activated human monocyte-derived macrophages and murine bone-marrow macrophages; TLR4 siRNA knockdown reduced the human response, anti-TLR4 (but not anti-TLR2) antibodies blocked activation, and TLR4-/- macrophages were refractory. MyD88-deficient macrophages showed a blunted response [PMID:19965653]. This is agonist activity.","molecular_requirements":"The active ligand is the heterotetramer of annexin A2 with S100A10 (A2t), so both chains matter for ligand expression [PMID:19965653]. Whether TLR4 needs co-receptors (e.g. MD-2/CD14) is not reported in our evidence. A previously cloned A2t receptor was dispensable [PMID:19965653].","affinity_potency":[],"species_and_systems":"Human monocyte-derived macrophages and mouse bone-marrow-derived macrophages, in vitro [PMID:19965653]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"ANXA2 is flagged as secreted [flag]; the paper describes soluble A2t that can be shed or secreted [PMID:19965653].","caveats":"Single paper, abstract only. No direct TLR4 binding assay; evidence is functional and genetic. The row is gene-level, not complex-level.","key_references":[{"PMID":"19965653","why":"TLR4 dependence of A2t macrophage activation by knockdown, antibody and knockout."}],"covers":["LR002128","LR005445"]},"LR005454":{"pair":"APOA1 -> SCARB1","headline":"ApoA-I binds SR-B1 in one recent paper by thermophoresis and pull-down; APOA1-Milano binds better.","interaction_type":"direct binding","direction_and_effect":"SR-B1 and APOA1 interact by microscale thermophoresis and affinity capture, with enhanced binding for APOA1-Milano [PMID:38479648]. Excess unlabeled APOA1 reduced DiI-LDL internalization in human coronary endothelial cells, and about 40% less DiI-LDL transcytosis, so APOA1 competes with LDL for SR-B1 [PMID:38479648].","molecular_requirements":"Not reported in our evidence beyond SR-B1 itself. Reconstituted HDL was a better competitor than lipid-free APOA1 [PMID:38479648].","affinity_potency":[],"species_and_systems":"Human coronary artery endothelial cells, HeLa cells expressing SR-B1-GFP, recombinant APOA1 and in vitro binding; male mice used in vivo [PMID:38479648].","localisation_and_range":"APOA1 is flagged secreted, not transmembrane; SCARB1 carries a receptor flag [flag].","caveats":"Pull-down used overexpressed SR-B1-GFP; no Kd is given in the excerpts. BioGRID and IntAct also list an earlier co-immunoprecipitation record [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"38479648","why":"Binding by thermophoresis and capture, plus LDL competition"}],"covers":["LR002137","LR005454"]},"LR003618":{"pair":"APOB -> LRP6","headline":"LRP6 binds apoB with low affinity in solid-phase assays and takes up LDL; evidence is partly indirect.","interaction_type":"direct binding","direction_and_effect":"Solid-phase assays showed low-affinity binding of LRP6 for lipid-bound apoB; the R611C mutant bound slightly more tightly [PMID:18948618]. Splenic B cells from LRP6+/- mice had about 30% reduced LDL uptake, and LRP6 colocalized with LDL [PMID:18948618].","molecular_requirements":"Not reported in our evidence beyond LRP6 itself; the mutant showed less efficient apoB dissociation at acidic pH [PMID:18948618].","affinity_potency":[],"species_and_systems":"Mouse splenic B cells and human lymphoblastoid cells [PMID:18948618]. Mouse pair is ortholog-inferred.","localisation_and_range":"LRP6 carries transmembrane and receptor flags [flag]; apoB flagged secreted.","caveats":"Affinity is low, no value is given, and the excerpts note undetectable affinity for apoE. Abstract and excerpts only. BioGRID lists the record from the same paper [DB:BioGRID].","key_references":[{"PMID":"18948618","why":"LRP6 binds apoB and mediates LDL uptake"}],"covers":["LR000069","LR003618"]},"LR005463":{"pair":"APOE -> LRP4","headline":"Co-IP of apoE and LRP4 in rat brain and transfected cells; abstract only.","interaction_type":"direct binding","direction_and_effect":"ApoE and LRP4 co-immunoprecipitated from LRP4-transfected Cos7 cells and brain homogenate [PMID:17889837]. An antibody to the LRP4 ligand-binding domain suppressed apoE binding to LRP4 in Cos7 cells and reduced neuronal viability [PMID:17889837].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human apoE with rat neurons and brain, Cos7 cells [PMID:17889837]. Mouse pair is ortholog-inferred.","localisation_and_range":"ApoE flagged secreted [flag]; LRP4 distributed on the neuronal surface [PMID:17889837].","caveats":"Abstract only; no affinity; co-IP does not prove direct binding.","key_references":[{"PMID":"17889837","why":"apoE-LRP4 co-IP and blocking antibody"}],"covers":["LR002148","LR005463"]},"LR003627":{"pair":"APOE -> SORL1","headline":"Two abstract-level reports show binding of apoE or apoE-rich lipoproteins to sorLA/LR11; high-affinity claim without a number.","interaction_type":"direct binding","direction_and_effect":"ApoE bound sorLA/LR11 at lumenal domain sites other than the propeptide-inhibitable site [PMID:11294867]. LR11 bound apoE-rich beta-VLDL with high affinity similar to LDLR and VLDLR, and took up and degraded it [PMID:11557679]. BioGRID, IntAct (SPR) and UniProt list the pair [DB:BioGRID] [DB:IntAct] [DB:UniProt].","molecular_requirements":"Furin cleavage activates sorLA [PMID:11294867].","affinity_potency":[],"species_and_systems":"Human receptor in hamster cells [PMID:11557679]; human sorLA [PMID:11294867].","localisation_and_range":"SORL1 flagged transmembrane receptor, apoE secreted [flag]; UniProt notes interaction with secreted SORL1 in cerebrospinal fluid [DB:UniProt].","caveats":"Both papers abstract only; one uses lipoproteins rather than free apoE; no numeric affinity given.","key_references":[{"PMID":"11294867","why":"apoE binding to sorLA lumenal domains"},{"PMID":"11557679","why":"LR11 binds apoE-rich beta-VLDL"}],"covers":["LR000078","LR003627"]},"LR005472":{"pair":"APP -> CNTN4","headline":"APP binds CNTN4 directly, via the CNTN4 second fibronectin repeat and the APP copper-binding domain, with a crystal structure; well supported.","interaction_type":"direct binding","direction_and_effect":"APP and APLP1 interact with CNTN3-5, and APLP2 also binds CNTN4 and CNTN5 [PMID:34958801]. A CNTN4-APP complex is described as guiding visual-system circuit assembly, citing earlier work [PMID:34958801]. Binding assays showed APP binds CNTN3 about equal to CNTN4, above CNTN5 [PMID:31318883]. Curator effect label (agonist) is not tested directly in these papers.","molecular_requirements":"Interface is CNTN FN2 plus the amyloid copper-binding domain; a chicken CNTN4-APP structure was solved at 2.05 \u00c5 [PMID:34958801]. CNTN4 is a GPI-anchored protein that acts through co-receptor complexes [PMID:34958801].","affinity_potency":[{"value":"K = 0.40 \u03bcM","assay":"biolayer interferometry","system":"zebrafish APPb with CNTN4","cite":"PMID:34958801"}],"species_and_systems":"Recombinant proteins: BLI with mouse and zebrafish proteins, crystallography with chicken CNTN4-APP; human APP(E1) aggregated so was not used [PMID:34958801]. Binding assays used proteins cloned from mouse cDNA [PMID:31318883]. Human pair is ortholog-inferred.","localisation_and_range":"Contactins are GPI-anchored with no intracellular region [PMID:34958801]; CNTN4 is flagged secreted and receptor, APP secreted and transmembrane [flag]. These interactions occur between cell-surface-anchored proteins in a co-receptor complex [PMID:34958801].","caveats":"No human-protein affinity is given in our evidence. The authors note their BLI values are weaker than earlier 17-35 nM values from dimeric Fc/AP fusions [PMID:34958801]. Primary 2022 paper read as abstract plus excerpts. IntAct lists a pull-down [DB:IntAct].","key_references":[{"PMID":"34958801","why":"BLI and structures of CNTN-amyloid pairs"},{"PMID":"31318883","why":"Alanine-scanning of the APP-CNTN binding interface"}],"covers":["LR002157","LR005472"]},"LR005481":{"pair":"APP -> TRPC6","headline":"One full-text paper shows TRPC6 binds APP C99 and inhibits gamma-secretase cleavage, reducing Abeta.","interaction_type":"direct binding","direction_and_effect":"TRPC6 interacts with APP (C99), prevents C99 interaction with PS1 and reduces Abeta production; labelled antagonist [PMID:26581893].","molecular_requirements":"TRPC6 does not interact with Notch; the effect is independent of its channel activity [PMID:26581893].","affinity_potency":[],"species_and_systems":"HEK293 and COS7 cells, mouse brain lysates, and APP/PS1 x TRPC6-transgenic mice [PMID:26581893].","localisation_and_range":"TRPC6 and APP (C99) colocalised in certain organelles [PMID:26581893].","caveats":"This is a regulator-substrate relationship rather than classical signalling. Single paper; no database support in the dossier.","key_references":[{"PMID":"26581893","why":"TRPC6-APP C99 interaction and Abeta reduction"}],"covers":["LR002167","LR005481"]},"LR003636":{"pair":"ARTN -> RET","headline":"ARTN activates RET, mainly through the GFRA3 co-receptor; functional evidence in two papers, no direct ARTN-RET binding shown.","interaction_type":"functional only","direction_and_effect":"ARTN is an agonist. It signals through RET with the co-receptor GFRalpha3 and ARTN-induced neurite outgrowth was abolished by anti-RET antibody [PMID:30853893]. In the original report ARTN activates GFRalpha3-RET and also GFRalpha1-RET [PMID:9883723].","molecular_requirements":"RET is the common signalling chain and needs a GFRalpha co-receptor (GFRalpha3 preferred) [PMID:9883723]. NCAM is also required for ARTN's neuritogenic effect in the 2019 study [PMID:30853893]. Electron microscopy structure and IntAct record of a RET chain with ARTN exist [DB:PDB 6Q2S] [DB:IntAct]; UniProt says ARTN acts via GFRA3 to activate RET [DB:UniProt].","affinity_potency":[],"species_and_systems":"2019 study: human recorded for both partners, with cerebellar granule neurons and PC12 cells (RET phosphorylation about 600% over control) [PMID:30853893]. 1998 study: recorded as mouse, neurons in culture, abstract only [PMID:9883723].","localisation_and_range":"ARTN is flagged secreted; RET is flagged as receptor [flag]. Paracrine signalling is implied, not tested.","caveats":"No direct ARTN-RET binding is shown in the papers; RET activation depends on a GFRalpha co-receptor. Mouse pair is ortholog-inferred. 9883723 was read as abstract only.","key_references":[{"PMID":"9883723","why":"Identified ARTN as ligand of GFRalpha3-RET"},{"PMID":"30853893","why":"RET phosphorylation and RET-dependent neurite outgrowth"}],"covers":["LR000087","LR003636"]},"LR002169":{"pair":"ARTN -> SDC3","headline":"ARTN binds the heparan sulfate chains of syndecan-3 with 10-50 nM affinity by SPR; one full-text paper, matrix-bound ligand.","interaction_type":"direct binding","direction_and_effect":"Immobilized, matrix-bound ARTN uses syndecan-3 as a receptor distinct from the GFRalpha-RET route, binding its heparan sulfate (HS) chains with high affinity; the interaction mediates cell spreading and neurite outgrowth with Src kinase involvement (agonist-type signalling) [PMID:21200028].","molecular_requirements":"Binding is through HS chains: heparinase III treatment strongly inhibited the GDNF-syndecan-3 interaction (shown for GDNF, not ARTN, in the excerpts) [PMID:21200028]. Whether syndecan-3 signals alone or presents ARTN to RET is not settled in our evidence.","affinity_potency":[{"value":"Kd 10-50 nM","assay":"surface plasmon resonance, immobilized ligand with HS-carrying syndecan-3 ectodomain (reported as range for GDNF, NRTN and ARTN)","system":"syndecan-3 purified from rat brain","cite":"PMID:21200028"}],"species_and_systems":"Ligand and receptor recorded as human; the SPR receptor was purified from rat brain [PMID:21200028]. Mouse pair is ortholog-inferred.","localisation_and_range":"ARTN is flagged secreted [flag]; the paper's effect needs ARTN immobilized on matrix, not soluble [PMID:21200028].","caveats":"Single paper. The Kd range is shared across three ligands, not ARTN alone. Syndecan-3 binding is via sugar chains, so it is a proteoglycan/heparan sulfate interaction rather than a classical protein-protein receptor.","key_references":[{"PMID":"21200028","why":"SPR and cell assays showing GFLs including ARTN use syndecan-3"}],"covers":["LR002169","LR005483"]},"LR003645":{"pair":"AVP -> AVPR2","headline":"Well supported direct binding and full agonism of vasopressin at the V2 receptor, with nanomolar affinity in human recombinant systems and structures in PDB.","interaction_type":"direct binding","direction_and_effect":"AVP acts as a full agonist; GtoPdb lists Type=Agonist, Action=Full agonist [DB:GtoPdb]. AVP binding to human V2 was displaced by the antagonist OPC-41061 [PMID:9864265]. In CHO cells AVP occupancy of V2 receptors decreased cell proliferation, in contrast to V1 and V3 [PMID:9322919].","molecular_requirements":"Single-chain GPCR; no co-receptor reported in our evidence. PDB entries 7BB6, 7BB7, 7DW9, 7KH0 and 7R0C exist [DB:PDB] and BioGRID lists a reconstituted complex [DB:BioGRID]; details of subunits are not reported in our evidence.","affinity_potency":[{"value":"Ki 4.2 nmol/L","assay":"radioligand competition binding","system":"human receptor-transfected cell lines","cite":"PMID:10519430"},{"value":"Ki 0.78 nM","assay":"[3H]AVP binding competition","system":"HeLa cells expressing human V2","cite":"PMID:9864265"},{"value":"Kd 2.14 nM","assay":"[3H]AVP saturation binding","system":"COS-1 cells expressing human V2","cite":"PMID:9459574"},{"value":"Kd 1.21 nM","assay":"[3H]AVP saturation binding","system":"CHO cells expressing hV2","cite":"PMID:9884074"}],"species_and_systems":"Human receptor in transfected CHO, COS-1 and HeLa cells. Rat and bovine tissues appear only as comparators in other papers [PMID:12446593][PMID:11012895]. No mouse experiment is in the dossier.","localisation_and_range":"AVP is flagged secreted and V2 as transmembrane [flag]; range is paracrine or endocrine.","caveats":"Nearly all papers were read as abstracts only. Several rows use V2 as a selectivity comparator [PMID:15084136][PMID:16158071]. The only full-text row [PMID:9322919] was browser-read and its quote is unverified. 4 papers were abstract_insufficient and 1 review_only.","key_references":[{"PMID":"9864265","why":"AVP Ki 0.78 nM at human V2 vs antagonist OPC-41061"},{"PMID":"9884074","why":"Kd of AVP at hV1A, hV1B, hV2 in CHO cells"},{"PMID":"9264324","why":"Agonist EC50 at human V2 and V1b, with binding comparison"}],"covers":["LR000096","LR003645"]},"LR000099":{"pair":"B2M -> HFE","headline":"B2M and HFE bind directly by several methods in human breast cancer cells; the paper's ERK-activation claim is inconsistent with its own excerpts.","interaction_type":"direct binding","direction_and_effect":"B2M directly interacted with HFE by co-IP, mass spectrometry, yeast two-hybrid and His pull-down in human breast cancer cells, and the paper reports that B2M activated ERK and induced apoptosis through HFE [PMID:39128984]. However, in MDA-MB-453 cells B2M overexpression or silencing did not significantly change p-ERK/ERK, while HFE overexpression increased it [PMID:39128984].","molecular_requirements":"The B2M/HFE complex was detected; endogenous interaction was seen in MDA-MB-453, MDA-MB-231 and MCF-7 cells but not BT474, possibly because HFE was undetectable there [PMID:39128984]. The databases list crystal structures of the two chains [DB:PDB 1A6Z, 1DE4].","affinity_potency":[],"species_and_systems":"Human breast cancer cell lines, recombinant B2M from E. coli and HA-HFE from HEK-293T for the pull-down [PMID:39128984]. Database records are human [DB:BioGRID, DB:IntAct]. The mouse pair is projected from human.","localisation_and_range":"The complex was mainly cytoplasmic with some on the cell membrane [PMID:39128984]; HFE is flagged transmembrane and B2M secreted [flag].","caveats":"B2M-HFE is also a heavy/light-chain-type association in structures, so ligand-receptor direction is not established. The functional ERK claim is internally mixed (above). The primary evidence is a single paper; 1 more row is pending.","key_references":[{"PMID":"39128984","why":"Co-IP, Y2H, pull-down of B2M-HFE in breast cancer cells"}],"covers":["LR000099","LR003648"]},"LR009612":{"pair":"B2M -> KIR2DL1","headline":"B2M-KIR2DL1 rests on a crystal structure of the receptor with an HLA-C ligand, not on direct B2M binding.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence for B2M; the structure is KIR2DL1 bound to HLA-Cw4 [DB:PDB 1IM9] and Reactome describes KIR2DL1 interacting with HLA-C group 2 [DB:Reactome R-HSA-199558].","molecular_requirements":"The KIR2DL1 complex involves HLA-C and B2M chains [DB:PDB 1IM9]; contact with B2M specifically is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in the database records; no paper-level evidence in our evidence set.","localisation_and_range":"B2M is flagged secreted [flag]; the receptor is flagged transmembrane [flag]; range is otherwise not reported in our evidence.","caveats":"No curator-verified paper supports this pair; it rests on database records alone (PDB, Reactome). ","key_references":[],"covers":["LR009612"]},"LR009720":{"pair":"B2M -> LILRB2","headline":"B2M-LILRB2 is database-supported by SPR and crystal structure of LILRB2 with HLA-G; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that LILRB2 recognises HLA-G in complex with B2M and a nonamer self-peptide, triggering differentiation of type 1 regulatory T cells and myeloid-derived suppressor cells [DB:UniProt Q8N423]; inhibitory or stimulatory effect on the receptor is not reported in our evidence.","molecular_requirements":"The ligand recognised is peptide-bound HLA-G-B2M [DB:UniProt Q8N423]; structure of LILRB2 with HLA-G [DB:PDB 2DYP].","affinity_potency":[],"species_and_systems":"Human proteins in database records; SPR [DB:IntAct P61769-Q8N423] and X-ray [DB:IntAct P61769-Q8N423].","localisation_and_range":"B2M is flagged secreted and LILRB2 a transmembrane receptor [flag]; the ligand acts in a membrane MHC class I complex per the database record.","caveats":"No curator-verified paper supports this pair (1 row review_only); B2M-specific contact is not reported in our evidence.","key_references":[],"covers":["LR009720"]},"LR012366":{"pair":"BAMBI -> FZD2:LRP6","headline":"Database-asserted only: a single IntAct coimmunoprecipitation record; no curator-verified paper for this pair.","interaction_type":"database-asserted only","direction_and_effect":"BAMBI is annotated as stimulatory toward this receptor complex [flag]. The only support is one IntAct coimmunoprecipitation record citing PMID 18838381 [DB:IntAct]. No verified paper for this pair is in our evidence; the one judged abstract was marked insufficient.","molecular_requirements":"Complex FZD2:LRP6 is annotated; LRP6 carries a transmembrane flag [flag]. Which subunit the IntAct record covers, and whether both are needed, is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair [flag]. IntAct method: anti tag coimmunoprecipitation [DB:IntAct]; cell system not reported in our evidence.","localisation_and_range":"Not reported in our evidence; BAMBI has no secreted or transmembrane flag in the dossier.","caveats":"Database support only, from one co-IP record. BAMBI is called a pseudoreceptor in the related paper title [PMID:18838381], so a ligand role is unclear. The same record is attached to several Frizzled:LRP6 pairs, so it does not distinguish between Frizzled paralogs.","key_references":[],"covers":["LR012366"]},"LR005490":{"pair":"BGN -> P2RX4","headline":"Biglycan activates the NLRP3 inflammasome through TLR2/4 and P2X4; evidence is functional, one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"Soluble biglycan induces the NLRP3/ASC inflammasome in macrophages, activating caspase-1 and releasing mature IL-1beta; this is brought about by interaction of biglycan with TLR2/4 and purinergic P2X(4)/P2X(7) receptors, which induces receptor cooperativity [PMID:19605353]. Biglycan-deficient mice had lower active caspase-1 and mature IL-1beta in kidney and lung in obstruction and sepsis models [PMID:19605353].","molecular_requirements":"TLR2/4 are also involved, and P2X4 and P2X7 are named together; whether P2X4 alone is sufficient is not reported in our evidence [PMID:19605353].","affinity_potency":[],"species_and_systems":"Macrophages and biglycan-deficient mice (mouse); human and mouse pairs are both ortholog-inferred [PMID:19605353].","localisation_and_range":"Soluble biglycan (secreted flag) acting on macrophage surface receptors [flag][PMID:19605353].","caveats":"Abstract-only. P2X4 and P2X7 are not distinguished in the evidence sentence, and no direct binding or affinity is shown.","key_references":[{"PMID":"19605353","why":"biglycan activates NLRP3 inflammasome via TLR2/4 and P2X4/P2X7"}],"covers":["LR002176","LR005490"]},"LR003654":{"pair":"BMP10 -> ACVR2B","headline":"Binding to the type II receptor ACVR2B is supported by one abstract-level binding study plus database records; no affinity in our evidence.","interaction_type":"direct binding","direction_and_effect":"BMP10 is annotated as stimulatory; GtoPdb lists it as an agonist at ACVR2B [DB:GtoPdb]. A kinetic and thermodynamic binding study reports that BMP9 discriminates among the type II receptors whereas BMP10 does not, which curators read as BMP10 binding ACVR2B (ActRIIB) [PMID:22718755]. BioGRID has a reconstituted-complex record for ACVR2B-BMP10 [DB:BioGRID].","molecular_requirements":"ACVR2B is a type II receptor; whether it needs a type I partner is not reported in our evidence for this pair.","affinity_potency":[],"species_and_systems":"Recombinant protein binding; curators annotate human ligand and receptor. The mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"BMP10 is annotated as secreted and the receptor as transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence tests range.","caveats":"Support is indirect (BMP10 'does not discriminate' among type II receptors) and read from the abstract only; no Kd for ACVR2B is given in our evidence. outcome_counts lists two confirmed rows but only one paper is shown.","key_references":[{"PMID":"22718755","why":"Binding analysis of BMP9/BMP10 with ALK1 and type II receptors"}],"covers":["LR000105","LR003654"]},"LR003663":{"pair":"BMP15 -> BMPR1B","headline":"Supported by binding evidence in two papers: BMP15 binds BMPR1B (ALK6) in granulosa cells and COS cells.","interaction_type":"direct binding","direction_and_effect":"BMP15 activates Smad1/5/8 signalling in granulosa cells [PMID:12419820]. A radiolabelled covalent-dimer BMP15 variant bound preferentially to endogenous BMPR1B and BMPR2 on COV434 cells, confirmed in COS cells overexpressing them [PMID:22294741].","molecular_requirements":"BMPR1B (ALK6) ectodomain co-immunoprecipitated BMP15 most effectively among receptor ectodomains tested [PMID:12419820]. BMPR2 was bound alongside BMPR1B, forming a signalling complex [PMID:22294741].","affinity_potency":[],"species_and_systems":"Rat primary granulosa cells and human COV434 cells with recombinant ectodomains [PMID:12419820]; recombinant human BMP15 in COV434 and COS cells [PMID:22294741]. Mouse pair is ortholog-inferred.","localisation_and_range":"BMP15 is annotated as secreted [flag]; the 2012 abstract calls it oocyte-derived and acting on ovarian somatic cells in a paracrine manner [PMID:22294741].","caveats":"Both papers are abstract-only. Only the engineered covalent-dimer variant (S356C) kept receptor binding after iodination, not the natural noncovalent dimer [PMID:22294741]. No Kd in our evidence.","key_references":[{"PMID":"22294741","why":"Radioligand binding of BMP15 variant to BMPR1B/BMPR2"},{"PMID":"12419820","why":"ALK6 ectodomain co-IPs BMP15 in granulosa cells"}],"covers":["LR000114","LR003663"]},"LR003672":{"pair":"BMP2 -> HJV","headline":"HJV (RGMc) binds BMP-2 directly in biochemical and SPR assays; well supported as a BMP co-receptor.","interaction_type":"direct binding","direction_and_effect":"BMP-2 interacts with single-chain RGMc species and binds cell-associated RGMc [PMID:18287331]. RGMs are described as co-receptors enhancing BMP cellular responses [PMID:23029472].","molecular_requirements":"Single-chain RGMc species bind BMP-2; mutants linked to juvenile hemochromatosis bind less (D165E, G313V) or not at all (G92V) in mouse RGMc [PMID:18287331]. Neogenin preferentially binds membrane-associated heterodimeric RGMc, unlike BMP-2 [PMID:18287331].","affinity_potency":[{"value":"Kd 9.4 nM","assay":"surface plasmon resonance","system":"system not reported in our evidence","cite":"PMID:23029472"}],"species_and_systems":"Mouse RGMc (human equivalents noted) for mutant binding [PMID:18287331]; SPR in a separate study [PMID:23029472]. Dossier covers the human pair and a projected mouse pair. PDB 4UI1 holds a structure with BMP2 and HJV chains [DB:PDB 4UI1].","localisation_and_range":"HJV is flagged secreted and receptor [flag]; it exists as membrane-linked and secreted isoforms [PMID:18287331].","caveats":"Both papers were read as abstract only (with limited excerpts). The Kd comes from the curator's assay note.","key_references":[{"PMID":"23029472","why":"SPR Kd for BMP2 binding to HJV"},{"PMID":"18287331","why":"BMP-2 binds RGMc species; mutants"}],"covers":["LR000123","LR003672"]},"LR002178":{"pair":"BMP2 -> RGMA","headline":"RGMA binds BMP2 directly by SPR with the weakest affinity among RGMs; one paper plus structure records.","interaction_type":"direct binding","direction_and_effect":"RGM family members are described as co-receptors enhancing cellular responses to BMPs [PMID:23029472]. RGMA showed the lowest affinity for most BMPs tested [PMID:23029472].","molecular_requirements":"Not reported in our evidence beyond binding to RGMA.","affinity_potency":[{"value":"Kd 22 nM","assay":"surface plasmon resonance","system":"system not reported in our evidence","cite":"PMID:23029472"}],"species_and_systems":"SPR, species not reported; mouse pair projected from human. PDB 4UHY holds a structure with BMP2 and RGMA chains [DB:PDB 4UHY].","localisation_and_range":"RGMA flagged secreted and receptor [flag].","caveats":"Single paper, read as abstract with limited excerpts; the Kd is from the curator's assay note. IntAct also records SPR [DB:IntAct].","key_references":[{"PMID":"23029472","why":"SPR of RGMs with BMPs"}],"covers":["LR002178","LR005492"]},"LR007119":{"pair":"BMP4 -> ACVR2B:BMPR1B","headline":"Complex not supported: neither BMPR1B nor ACVR2B was required for BMP4 signalling in hMSC (explicit negative).","interaction_type":"conflicting","direction_and_effect":"In primary human mesenchymal stem cells, BMPR1B and ACVR2B were expressed at low levels and were not found to play a significant role in signalling by BMP-4 or the other BMPs tested [PMID:18436533]. GtoPdb lists BMP4 as agonist at ACVR2B and BMPR1B individually [DB:GtoPdb]; BioGRID records a BMP4-BMPR1B reconstituted complex [DB:BioGRID 282659].","molecular_requirements":"Complex not evidenced as a unit.","affinity_potency":[],"species_and_systems":"Human primary mesenchymal stem cells (negative) [PMID:18436533].","localisation_and_range":"BMP4 flagged secreted; receptors transmembrane [flag].","caveats":"Only verified paper is an abstract-only negative; low expression there does not exclude activity elsewhere. Database records are of single chains.","key_references":[{"PMID":"18436533","why":"Negative result for both chains in hMSC"}],"covers":["LR007119"]},"LR007128":{"pair":"BMP5 -> ACVR2B:BMPR1B","headline":"BMP5 to ACVR2B:BMPR1B rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Chains in the complex: ACVR2B and BMPR1B; whether both are required or either alone suffices is not reported in our evidence. The pair is a complex; the database rows are per chain, not for the assembled complex, and not every chain has UniProt support.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Screened papers: 4 review_only, 3 abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR007128"]},"LR011196":{"pair":"BMP5 -> BMPR1B","headline":"BMP5 to BMPR1B rests on a GtoPdb agonist assertion only; no verified paper in our evidence.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP5 as agonist (Stimulatory) on the receptor chain(s) [DB:GtoPdb].","molecular_requirements":"Single receptor chain; coreceptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental species and system not reported in our evidence; the pair is annotated human.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine; the receptor's localisation is not reported in our evidence.","caveats":"No curator-confirmed paper. Three screened papers were abstract_insufficient. GtoPdb entries show no affinity ('Affinity Units=-') [DB:GtoPdb].","key_references":[],"covers":["LR011196"]},"LR003681":{"pair":"BMP5 -> HJV","headline":"BMP5 binds HJV in SPR with Kd 17 nM; single paper, human/human labels, abstract-level curation.","interaction_type":"direct binding","direction_and_effect":"HJV is an RGM-family BMP co-receptor; curators label the effect agonist [PMID:23029472]. HJV showed the highest affinity among RGMs for BMP5, BMP6 and BMP7 [PMID:23029472].","molecular_requirements":"Not reported in our evidence for this pair (no co-receptor or complex requirement tested for BMP5 in the excerpts).","affinity_potency":[{"value":"Kd 17 nM","assay":"SPR","system":"HJV vs BMP5, mean of 4-9 experiments","cite":"PMID:23029472"}],"species_and_systems":"Curators label both partners human; SPR with recombinant proteins, 4-9 experiments per interaction [PMID:23029472]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP5 is flagged secreted and not transmembrane [flag], so signalling would be paracrine or endocrine. HJV is flagged secreted [flag].","caveats":"One paper, read as an abstract by the curators with full-text excerpts available. No functional assay for BMP5 with this receptor is shown in the excerpts. None of the RGMs bound BMP9 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGMs for BMP ligands"}],"covers":["LR000132","LR003681"]},"LR007137":{"pair":"BMP6 -> ACVR2B:BMPR1B","headline":"Complex pair supported by database records only; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP6 as agonist at ACVR2B and at BMPR1B [DB:GtoPdb]. UniProt says BMP6 initiates canonical BMP signalling by associating with type I receptor ACVR1 and type II receptor ACVR2B [DB:UniProt].","molecular_requirements":"BioGRID records ACVR2B-BMP6 affinity capture-western and BMP6-BMPR1B reconstituted complex, as separate pairwise records [DB:BioGRID]. PDB 9N4K (cryoEM, ALK2-ActRIIB bound to BMP6) concerns ACVR1, not BMPR1B [DB:PDB 9N4K]. The UniProt text names ACVR1 as the type I partner of ACVR2B [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species of the database experiments is not reported in our evidence.","localisation_and_range":"BMP6 is flagged as secreted [flag], so action would be paracrine or endocrine; the receptor is flagged as a transmembrane receptor [flag].","caveats":"No paper was judged (four review-only, one abstract-insufficient). The BMPR1B and ACVR2B chains are supported separately, not as one complex; the structure and UniProt function line point to ACVR1 as the type I partner.","key_references":[],"covers":["LR007137"]},"LR005049":{"pair":"BMP6 -> HJV","headline":"Direct SPR binding of BMP6 to HJV, Kd 8.1 nM, in one 2012 paper; highest affinity among RGMs for BMP6.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance measured binding of HJV to BMP6 with K(D) 8.1 nM; curated effect is agonist [PMID:23029472].","molecular_requirements":"RGM proteins are described as BMP co-receptors; the paper measured RGM protein binding to BMP ligands, and receptor chains needed for signalling are not reported in our evidence [PMID:23029472].","affinity_potency":[{"value":"Kd 8.1 nM","assay":"surface plasmon resonance","system":"recombinant RGM proteins with BMP ligands","cite":"PMID:23029472"}],"species_and_systems":"Recombinant human proteins per curator; abstract-level curation with full-text excerpts describing SPR (mean of 4-9 experiments) [PMID:23029472]. Mouse pair is ortholog-inferred.","localisation_and_range":"UniProt notes BMP6 acts as a ligand for hemojuvelin/HJV in regulating HAMP/hepcidin expression and iron metabolism [DB:UniProt]. The receptor is flagged as secreted [flag], which may reflect a soluble form; membrane or soluble role is not shown in our evidence.","caveats":"Affinity data are from an in vitro SPR matrix; no cellular signalling result for this pair is reported in our evidence. Compared with other RGMs: HJV 8.1, RGMB 28, RGMA 55 nM for BMP6 [PMID:23029472].","key_references":[{"PMID":"23029472","why":"SPR affinity matrix of RGM proteins for BMP ligands"}],"covers":["LR001663","LR005049"]},"LR003690":{"pair":"BMP7 -> ACVR2B","headline":"BMP7 binds ACVR2B (ActR-IIB) directly; SPR affinity in the same range as for ACVR2A, plus cell-based evidence.","interaction_type":"direct binding","direction_and_effect":"BMP7 binds the type II receptor ActR-IIB with comparable affinity to ActR-II and BMPR-IB [PMID:19735544]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"ACVR2B is a type II chain; BMP7 also binds type I receptors, with comparable affinities in vitro [PMID:19735544]. Whether ACVR2B alone is sufficient for signalling is not reported in our evidence.","affinity_potency":[{"value":"KD(eq) 9.2 nM","assay":"SPR, immobilised ActR-IIB ECD, soluble BMP7","system":"recombinant proteins","cite":"PMID:19735544"}],"species_and_systems":"Recombinant human ligand and receptor ectodomains in SPR [PMID:19735544]. The dossier includes human and mouse pairs, neither ortholog-inferred.","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Only one paper is shown in detail and it is a binding screen of multiple receptors; four confirmed rows were counted overall.","key_references":[{"PMID":"19735544","why":"SPR binding parameters for BMP7 with ActR-IIB"}],"covers":["LR000141","LR003690"]},"LR007146":{"pair":"BMP7 -> ACVR2B:BMPR1B","headline":"Only chain-level support: BMP7 binds ActRIIB in P19 cells; the BMPR1B chain is not shown in the cited paper.","interaction_type":"direct binding","direction_and_effect":"In P19 embryonic carcinoma cells BMP7 and activin bind the same type II receptors, ActRII and IIB, but recruit distinct type I receptors; ALK2 was the major BMP7 type I receptor [PMID:9748228]. GtoPdb lists agonist action for each chain [DB:GtoPdb].","molecular_requirements":"ACVR2B support only; the BMPR1B chain is not reported in this paper, which names ALK2 as the major type I receptor [PMID:9748228].","affinity_potency":[],"species_and_systems":"P19 cells (species not stated in the dossier) [PMID:9748228].","localisation_and_range":"BMP7 is flagged secreted and the receptor transmembrane [flag], suggesting paracrine signalling to a cell-surface receptor; the papers do not address range.","caveats":"Read as abstract only. The supporting sentence covers the ACVR2B chain and not the combination with BMPR1B. BioGRID lists BMP7-BMPR1B reconstituted-complex records [DB:BioGRID]. Four papers were review_only.","key_references":[{"PMID":"9748228","why":"BMP7 binds ActRII/IIB in P19 cells, recruiting ALK2"}],"covers":["LR007146"]},"LR002187":{"pair":"BMP7 -> RGMA","headline":"BMP7 binds RGMA directly by SPR (Kd 63 nM); single abstract-level paper with full-text support, human proteins.","interaction_type":"direct binding","direction_and_effect":"Curators record the effect as agonist; the paper's abstract describes RGM proteins as co-receptors that enhance cellular responses to BMP ligands, but this paper measured binding only [PMID:23029472].","molecular_requirements":"Binding was measured for the RGM protein alone; type I/II BMP receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"Kd 63 nM","assay":"surface plasmon resonance","system":"recombinant human proteins (curator-annotated species)","cite":"PMID:23029472"}],"species_and_systems":"SPR with recombinant proteins; curators annotate both partners as human, mouse pair is ortholog-inferred [PMID:23029472].","localisation_and_range":"Both BMP7 and RGMA are flagged secreted [flag]; range of action not reported in our evidence.","caveats":"RGMA bound BMP7 with intermediate affinity, between HJV (20 nM) and RGMB (166 nM) [PMID:23029472]. BMP7 had the lowest relative affinity of the BMPs tested for the RGMs, and BMP7-RGM data needed CM4 sensor chips because fitting on CM5 chips was poor [PMID:23029472]. Curator read depth is abstract-only. Only one paper.","key_references":[{"PMID":"23029472","why":"SPR kinetics of all RGM-BMP pairs including BMP7"}],"covers":["LR002187","LR005501"]},"LR001665":{"pair":"BMP8A -> ACVR2A","headline":"BMP8A acts through ACVR2A in mouse spermatogonia (functional, abstract-level); GtoPdb also lists agonism.","interaction_type":"functional only","direction_and_effect":"Agonist (curator annotation). BMP8A activated SMAD1/5/8 via ALK3 with ACVR2A or BMPR2, and SMAD2/3 via ALK5 with ACVR2A, ACVR2B or TGFBR2 [PMID:28465413]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"ACVR2A is a type II partner for either ALK3 (SMAD1/5/8) or ALK5 (SMAD2/3); it is not shown acting alone [PMID:28465413].","affinity_potency":[],"species_and_systems":"Undifferentiated mouse spermatogonia and cultured mouse testis explants; abstract-only read; the human pair is listed without ortholog inference but the experiments were mouse [PMID:28465413].","localisation_and_range":"BMP8A is flagged secreted [flag]; the abstract does not state range of action.","caveats":"Evidence is signalling through receptor complexes, not binding; no affinity reported. Abstract only.","key_references":[{"PMID":"28465413","why":"BMP8A signals through SMAD1/5/8 and SMAD2/3 receptor complexes in mouse spermatogonia"}],"covers":["LR001665"]},"LR007155":{"pair":"BMP8A -> ACVR2B:BMPR1B","headline":"BMP8A -> ACVR2B:BMPR1B: each chain has separate abstract-level evidence (mouse, zebrafish); the pair is not shown together.","interaction_type":"functional only","direction_and_effect":"In mouse spermatogonia BMP8A signalled through ACVR2B, with ALK5, to SMAD2/3 [PMID:28465413]. In zebrafish, Bmp8a interacts with Alk6a and drives type I interferon production [PMID:33750893]. GtoPdb lists agonist records at both ACVR2B and BMPR1B [DB:GtoPdb].","molecular_requirements":"Neither paper shows ACVR2B and BMPR1B acting together; the complex is assembled from separate chain evidence.","affinity_potency":[],"species_and_systems":"Mouse spermatogonia [PMID:28465413] and bmp8a-/- zebrafish [PMID:33750893]; both abstract-only.","localisation_and_range":"BMP8A is flagged secreted [flag]; range of action not otherwise reported.","caveats":"The two papers use different species and different receptors; the human complex is not directly tested. Zebrafish evidence is labelled direct binding by curators but the abstract gives only an 'interacts' statement. One abstract was insufficient and three papers were review-only.","key_references":[{"PMID":"28465413","why":"Mouse spermatogonia ACVR2B signalling"},{"PMID":"33750893","why":"Zebrafish Bmp8a-Alk6a interaction"}],"covers":["LR007155"]},"LR008253":{"pair":"BMP8B -> ACVR1:ACVR2B","headline":"BMP8B -> ACVR1:ACVR2B rests on GtoPdb agonist records only; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B as an agonist at ACVR1 and ACVR2B [DB:GtoPdb]; no verified paper supports the effect.","molecular_requirements":"Complex is assembled from separate chain records; subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"Not reported in our evidence; the ligand has no secretion flag in the dossier.","caveats":"Judged papers were abstract-insufficient, review-only or about a different entity; none confirmed this pair. No affinity.","key_references":[],"covers":["LR008253"]},"LR008451":{"pair":"BMP8B -> BMPR1A","headline":"BMP8B -> BMPR1A rests only on a GtoPdb agonist record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists BMP8B-BMPR1A as Type=Agonist, Action=Agonist [DB:GtoPdb]; annotated Stimulatory.","molecular_requirements":"BMPR1A is a type I receptor chain; whether a type II partner (such as BMPR2) is required is not reported in our evidence. The complex pair BMP8B -> BMPR1A:BMPR2 is a separate entry.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence (human entities).","localisation_and_range":"Receptor flagged transmembrane [flag]; range not reported in our evidence.","caveats":"No curator-verified paper; several candidate papers were judged abstract-insufficient, review-only or about a different entity, so none supports the pair. The GtoPdb record is a database assertion, not an experiment.","key_references":[],"covers":["LR008451"]},"LR007182":{"pair":"C10orf99 -> SUSD2","headline":"One 2014 study supports C10orf99 as a secreted ligand acting through SUSD2 in colon cancer cells; binding itself is not shown in our excerpts.","interaction_type":"functional only","direction_and_effect":"Secreted CSBF/C10orf99 inhibited colon cancer cell growth and induced G1 arrest by down-regulating cyclin D and CDK6; soluble sSUSD2-Fc blocked the effect, supporting SUSD2 as receptor [PMID:25351403]. Curator label: agonist.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"~10 ng/ml","assay":"optimum of a bell-shaped dose-response (growth inhibition)","system":"colon cancer cells","cite":"PMID:25351403"}],"species_and_systems":"Human colon cancer cell lines and tissue [PMID:25351403].","localisation_and_range":"Annotated secreted ligand; the paper describes a 6.5 kDa classical secreted protein [PMID:25351403, flag].","caveats":"Single paper, no database records. The excerpts say interaction with SUSD2 was previously deduced; a direct binding measurement is not reported in our evidence. The bell-shaped dose-response means high doses lose activity.","key_references":[{"PMID":"25351403","why":"only paper; function blocked by soluble SUSD2-Fc"}],"covers":["LR007182"]},"LR005508":{"pair":"C1qa -> Adgrb1","headline":"Candidate C1q receptor from an unbiased pull-down screen in human neural stem cells; mouse pair is projected from human evidence.","interaction_type":"functional only","direction_and_effect":"C1q was cross-linked to membrane proteins and BAI1 was among five transmembrane candidates identified by pull-down and mass spectrometry; the proximity-ligation assay was reported to validate the C1q-BAI1 interaction and the curator labels it agonist [PMID:32894219].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were in human neural stem cells (hNSC); the mouse pair is ortholog-inferred, not tested in mouse [PMID:32894219].","localisation_and_range":"C1q is annotated secreted [flag]. Cell-surface receptor role is a candidate assignment.","caveats":"Candidate-level evidence; functional validation in the paper was for CD44 only, not for BAI1. Paper read as abstract and excerpts. The receptor is annotated as secreted, which looks odd for a receptor.","key_references":[{"PMID":"32894219","why":"screen identifying five candidate C1q receptors in hNSC"}],"covers":["LR005508"]},"LR002196":{"pair":"C1QA -> DDR1","headline":"C1q is reported to activate DDR1 and drive HepG2 migration and invasion; direct binding is not shown in our evidence.","interaction_type":"functional only","direction_and_effect":"C1q induced activation and upregulation of DDR1, and DDR1 knockdown attenuated C1q-induced migration and invasion of HepG2 cells [PMID:29559654]. C1q also activated MAPK and PI3K/Akt signalling [PMID:29559654].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human HepG2 cells, with similar results in SUN182 cells; the mouse pair is ortholog-inferred [PMID:29559654].","localisation_and_range":"C1q annotated secreted [flag].","caveats":"The title and excerpts rest on DDR1 phosphorylation and siRNA assays; no physical binding assay is described. One paper only.","key_references":[{"PMID":"29559654","why":"C1q activates DDR1 in hepatocellular cells"}],"covers":["LR002196","LR005510"]},"LR001674":{"pair":"C1QB -> CD33","headline":"Assembled C1q binds CD33 on human monocytes and triggers its inhibitory signalling; one human paper, chain-level row.","interaction_type":"direct binding","direction_and_effect":"C1q treatment increased phosphorylated CD33 (2-5 fold versus controls, n >= 6), i.e. activation of CD33 inhibitory ITIM signalling in human monocytes; gC1q did the same, CLR did not [PMID:28325905].","molecular_requirements":"Whole C1q is required to crosslink CD33 and LAIR-1; the globular head (gC1q) binds CD33 while the collagen-like region (CLR) does not [PMID:28325905]. This row encodes one chain (C1QB) of the C1q complex; the paper used assembled C1q, so chain-alone sufficiency is not shown.","affinity_potency":[],"species_and_systems":"Human proteins and cells: slot blots with purified proteins, C1q binding to CD33-transfected HEK293T cells and lysates, immunoblots and proximity ligation assay in freshly isolated human monocytes [PMID:28325905]. IntAct lists a surface plasmon resonance record from the same paper [DB:IntAct].","localisation_and_range":"C1q is secreted (ligand flag) [flag]; CD33 acts on the monocyte surface, with C1q bridging CD33 and LAIR-1 on the same cell [PMID:28325905].","caveats":"Abstract-level curation, but full-text excerpts were available. Sialic acid masking of CD33 C2 domains reduces C1q-CD33 interaction [PMID:28325905]. Single paper; chain-level attribution (C1QB) is inherited from the complex.","key_references":[{"PMID":"28325905","why":"C1q binds CD33, activates its ITIM and crosslinks CD33/LAIR-1 on human monocytes"}],"covers":["LR001674"]},"LR005517":{"pair":"C1QB -> CD44","headline":"CD44 mediates C1q signalling and chemotaxis in human neural stem cells; functional plus proximity-ligation support from one paper.","interaction_type":"functional only","direction_and_effect":"CRISPR-Cas9 CD44 knockout was used to test that CD44 mediates C1q-induced signalling (p-ERK) and chemotaxis in hNSC; the abstract reports CD44 mediates these effects in vitro and hNSC migration and repair in vivo after spinal cord injury [PMID:32894219]. Stimulatory.","molecular_requirements":"The ligand studied was assembled C1q (C1QA:C1QB:C1QC), not the single C1QB chain; chain-alone activity is not shown [PMID:32894219]. Co-receptor or subunit requirements on the CD44 side are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human neural stem cells in vitro (CD44 identified among five candidate C1q receptors by crosslinking and mass spectrometry, then proximity ligation assay indicating close contact <30 nm); in vivo spinal cord injury model, host species not stated in the excerpts [PMID:32894219].","localisation_and_range":"C1q is secreted (ligand flag); CD44 is flagged as transmembrane and also secreted [flag]. Acts on cell-surface CD44 of the responding cell [PMID:32894219].","caveats":"Curated from the abstract plus excerpts. Proximity ligation shows nearness, not a measured affinity; no Kd reported. Mouse interaction is ortholog-inferred only.","key_references":[{"PMID":"32894219","why":"CD44 identified as C1q receptor on hNSC; knockout abolishes C1q-induced signalling/chemotaxis"}],"covers":["LR002203","LR005517"]},"LR003708":{"pair":"C3 -> ITGAX","headline":"iC3b fragment of C3 binds ITGAX (CD11c, p150,95); supported by binding and cell-based papers.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose isolated p150,95 from human membranes [PMID:4062888]. Cells with human p150,95 alpha subunit and a chicken beta subunit bound IgM-iC3b erythrocytes [PMID:7512600]. Dendritic cell phagocytosis of Francisella depended on C3 opsonins and CR3/CR4 [PMID:16857732].","molecular_requirements":"p150,95 is the alphaX:beta2 heterodimer sharing the beta subunit with CR3 [PMID:4062888]. Cells needed a heterologous (chicken) beta subunit for activation of binding [PMID:7512600]. Ligand recognition maps to the I domain [PMID:7512600].","affinity_potency":[],"species_and_systems":"Human materials: membranes, transfectants and dendritic cells [PMID:4062888][PMID:7512600][PMID:16857732]. Mouse pair is ortholog-inferred. BioGRID and IntAct list reconstituted-complex and SPR records [DB:BioGRID][DB:IntAct].","localisation_and_range":"Membrane integrin; contact-dependent (annotation [flag]).","caveats":"Abstract only for all papers. Ligand is iC3b, not intact C3. Phagocytosis paper implicates both CR3 and CR4 so it cannot isolate ITGAX [PMID:16857732].","key_references":[{"PMID":"4062888","why":"iC3b affinity isolation of p150,95"},{"PMID":"7512600","why":"CD11c/CD18 as iC3b receptor"},{"PMID":"16857732","why":"CR4 role in complement-dependent phagocytosis"}],"covers":["LR000159","LR003708"]},"LR008217":{"pair":"C3 -> ITGAX:ITGB2","headline":"iC3b fragment of C3 binds p150,95 (ITGAX:ITGB2); one abstract-only 1985 paper plus database records.","interaction_type":"direct binding","direction_and_effect":"iC3b-Sepharose affinity chromatography showed iC3b binds CR3 and p150,95 from human spleen membranes and leukocytes [PMID:4062888]. BioGRID and IntAct record related interactions [DB:BioGRID][DB:IntAct].","molecular_requirements":"Complex of ITGAX and ITGB2; shares the beta2 subunit with CR3 [PMID:4062888].","affinity_potency":[],"species_and_systems":"Human spleen membranes and polymorphonuclear leucocytes [PMID:4062888].","localisation_and_range":"Membrane integrin complex; contact-dependent by annotation [flag].","caveats":"Single abstract-only paper. Ligand is iC3b, not intact C3. The receptor entity is flagged is_receptor 0 in the complex record.","key_references":[{"PMID":"4062888","why":"iC3b affinity isolation of p150,95"}],"covers":["LR008217"]},"LR005535":{"pair":"C9 -> Cd59b","headline":"Mouse pair inferred from human data: CD59 binds C9 in peptide assays; no mouse experiments in our evidence.","interaction_type":"direct binding","direction_and_effect":"Both C8alpha and C9 bind a similar or overlapping site on CD59, which regulates MAC formation [PMID:16844690].","molecular_requirements":"Human C9 residues 365-371 are the primary CD59 recognition domain [PMID:16844690].","affinity_potency":[],"species_and_systems":"Experiments used human proteins and peptides; the mouse Cd59b pair is ortholog-inferred and mouse Cd59b was not tested in our evidence.","localisation_and_range":"Not reported in our evidence beyond flags: C9 secreted [flag].","caveats":"Abstract only. Paralog issue: mouse has Cd59b, and the paper concerns human CD59.","key_references":[{"PMID":"16844690","why":"Human CD59-C9 binding site mapping"}],"covers":["LR005535"]},"LR005058":{"pair":"CADM3 -> CADM1","headline":"Direct CADM3-CADM1 binding by SPR (Kd 80.1 nM) and heterophilic cell adhesion; well supported.","interaction_type":"direct binding","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent heterophilic cell-cell adhesion with Necl-2 (CADM1) [PMID:15741237]. CADM1-Fc also bound CADM3 in SPRi [PMID:30131958]. Reactome lists a Necl-1:Necl-2 trans heterodimer [DB:Reactome].","molecular_requirements":"Full ectodomains in SPRi; no extra subunit reported [PMID:30131958].","affinity_potency":[{"value":"Kd 80.1 nM","assay":"SPRi, CADM1-Fc analyte with CADM3-Fc","system":"purified Fc fusions","cite":"PMID:30131958"}],"species_and_systems":"Cell-aggregation assays (abstract-level, human-labelled) [PMID:15741237]; recombinant SPRi [PMID:30131958]. Both human and mouse pairs listed, not inferred.","localisation_and_range":"Membrane-bound pair [flag]. Necl-1 is neural-tissue specific, at contact sites among axons, terminals and glia [PMID:15741237]; trans, contact-dependent.","caveats":"The cell-aggregation paper was read as abstract only [PMID:15741237]. Kd is for CADM1-Fc as analyte.","key_references":[{"PMID":"15741237","why":"Heterophilic Necl-1 / Necl-2 adhesion"},{"PMID":"30131958","why":"SPRi Kd 80.1 nM"}],"covers":["LR001682","LR005058"]},"LR001683":{"pair":"CADM3 -> CADM3","headline":"Homophilic CADM3 adhesion shown in cell-aggregation assays and SPRi; two papers.","interaction_type":"direct binding","direction_and_effect":"Necl-1 (CADM3) showed Ca2+-independent homophilic cell-cell adhesion [PMID:15741237]. SPRi detected homophilic interactions of CADM3 [PMID:30131958]. Self-binding, so no direction.","molecular_requirements":"Homodimer of the ectodomain; no extra subunit reported.","affinity_potency":[],"species_and_systems":"Cell aggregation assays, abstract only [PMID:15741237]; recombinant SPRi [PMID:30131958]. Human and mouse pairs both listed, not inferred.","localisation_and_range":"Membrane-bound [flag]; Necl-1 sits at non-junctional contact sites of axons, terminals and glial processes, in neural tissue [PMID:15741237]. Reactome lists Necl transhomodimerisation [DB:Reactome].","caveats":"Abstract-level for the aggregation study. No Kd for CADM3-CADM3 in our evidence; the SPRi curated sentence is about CADM1-Fc.","key_references":[{"PMID":"15741237","why":"Homophilic Necl-1 adhesion"},{"PMID":"30131958","why":"SPRi CADM-family interactions"}],"covers":["LR001683","LR005059"]},"LR005544":{"pair":"CADM4 -> CADM1","headline":"CADM4 binds CADM1 directly by SPRi, a newly reported heterophilic interaction with a cell-spreading readout; one paper.","interaction_type":"direct binding","direction_and_effect":"Surface plasmon resonance imaging showed CADM1 interacts with CADM4, which had not been reported previously [PMID:30131958]. ATN1 leukemia cells (CADM1-expressing) spread on CADM4-Fc-coated glass; CADM1 knockdown or a neutralizing CADM1 antibody blocked spreading [PMID:30131958]. The pair is adhesive and has no ligand/receptor polarity in the paper; the 'agonist' label is the curator's.","molecular_requirements":"SPRi detects only direct two-molecule interactions [PMID:30131958]. No accessory subunit is reported. Co-culture immunoprecipitation of CADM4-FLAG and CADM1-GFP cells also pulled down CADM1 [PMID:30131958].","affinity_potency":[{"value":"Kd 192.7 nM","assay":"SPRi, CADM1-Fc with CADM4-Fc (Table 1)","system":"recombinant Fc proteins","cite":"PMID:30131958"}],"species_and_systems":"Recombinant Fc-fusion ectodomains in SPRi (human proteins) [PMID:30131958]. Mouse pair is projected from human evidence (ortholog_inferred), not tested.","localisation_and_range":"Both are annotated as transmembrane [flag]; the paper describes a trans-heterophilic interaction between neighbouring cells, i.e. contact-dependent (juxtacrine) [PMID:30131958].","caveats":"Single paper. Earlier affinity chromatography and cell-adhesion assays could not detect this interaction, and the authors suggest it may give too little adhesion activity [PMID:30131958]. The curator's assay_class here is 'structural' with read depth abstract_only, although full text is available.","key_references":[{"PMID":"30131958","why":"SPRi screen of CADM-family pairwise interactions, with Kd table and cell assays"}],"covers":["LR002234","LR005544"]},"LR003717":{"pair":"CALCA -> RAMP1","headline":"alpha-CGRP acts on receptor complexes containing RAMP1 (with CALCRL or CALCR); RAMP1 is a subunit, not a stand-alone receptor. Multiple functional and binding studies.","interaction_type":"direct binding","direction_and_effect":"alpha-CGRP is an agonist at RAMP1-containing receptors: CRLR/RAMP1 gives a CGRP receptor [PMID:9620797], and [125I]halphaCGRP binding and cAMP signalling were seen with RAMP1/CRLR [PMID:11693189] and CTR2/RAMP1 [PMID:14722252]. In rat trigeminal neurons CGRP also acts through CTR/RAMP1 (AMY1) in addition to CLR/RAMP1 [PMID:26125036]. GtoPdb lists full agonist [DB:GtoPdb].","molecular_requirements":"RAMP1 works only as part of a heterodimer: CRLR/RAMP1 [PMID:12234182][PMID:9620797] or CTR/RAMP1 (AMY1) [PMID:26125036][PMID:14722252]. Shortening the RAMP1 transmembrane domain progressively impaired hCRLR association and abolished CGRP receptor function [PMID:12234182]. In CTRa assays the RAMP1 C-terminal domain increased CGRP potency [PMID:16531504]. Using CALCRL-RAMP1 for scoring is supported; RAMP1 alone is not a receptor.","affinity_potency":[{"value":"pEC50 8.9 to 11.3","assay":"GtoPdb agonist record (cAMP potency)","system":"database record, system not given in dossier","cite":"DB:GtoPdb"}],"species_and_systems":"Experiments used human clones in HEK-293 or COS-7 cells (recombinant) [PMID:14722252][PMID:16531504][PMID:12234182], human/porcine CRLR [PMID:11693189] and rat trigeminal ganglion neurons and tissue with human tissue expression [PMID:26125036]. Mouse pair is projected from human evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; paracrine or endocrine action is implied by that flag only.","caveats":"All shown papers were read as abstracts except one full text [PMID:26125036]. The evidence concerns the receptor complex, not direct CGRP contact with RAMP1 itself; one curator note says the cross-linking is for the RAMP-GPCR complex [PMID:11023820]. Reference [PMID:30139742] is a structure of the AM2/IMD fragment on RAMP1-CLR, not CGRP. CGRP also signals via CTR/RAMP1, so a RAMP1 hit does not identify the CALCRL receptor [PMID:26125036].","key_references":[{"PMID":"9620797","why":"RAMP1 with CRLR defines the CGRP receptor"},{"PMID":"11693189","why":"[125I]halphaCGRP binding to RAMP1/CRLR"},{"PMID":"26125036","why":"CGRP acts via CALCRL/RAMP1 and CTR/RAMP1 in trigeminal neurons"}],"covers":["LR000172","LR003717"]},"LR006822":{"pair":"CALM1 -> PDE1A","headline":"Calmodulin-PDE1A rests on a GtoPdb activator record alone.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists calmodulin as activator of PDE1A [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not stated.","localisation_and_range":"Intracellular calmodulin; no secreted flag in our evidence. Not reported in our evidence beyond the entity annotation flags.","caveats":"No papers were confirmed; support is from curated database records only. One abstract was insufficient.","key_references":[],"covers":["LR006822"]},"LR008460":{"pair":"CALM2 -> MYLK2","headline":"CALM2 activates MYLK2 according to GtoPdb only; no curated paper supports the pair.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists CALM2 as an activator of MYLK2 (Type=Activator; Action=Activation), and the interaction is annotated Stimulatory [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human entities; no experimental system or species of assay is reported in our evidence.","localisation_and_range":"Not reported in our evidence; no localisation flag is given for the ligand.","caveats":"Support rests on a database record alone, with no affinity (Affinity Units=-) and no verified primary paper. Judged papers were all assigned to a different entity (3 rows). Calmodulin acts here as a Ca2+-sensor regulator of an enzyme rather than a classical secreted ligand; the receptor label comes from an annotation flag [flag].","key_references":[],"covers":["LR008460"]},"LR009207":{"pair":"CALM3 -> KCNQ1","headline":"CALM3 and KCNQ1 form a calmodulin-channel complex seen in cryo-EM structures; no curated paper tests a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. PDB entries show human KCNQ1-CaM in the apo state and in complex with ML277 [DB:PDB 7XNI] [DB:PDB 7XNK].","molecular_requirements":"The structures hold one calmodulin chain and one KCNQ1 chain per entry [DB:PDB 7XNI]. Subunit stoichiometry beyond that is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human KCNQ1-CaM, cryo-EM (Electron Microscopy) [DB:PDB 7XNI] [DB:PDB 7XNK].","localisation_and_range":"Not reported in our evidence.","caveats":"Eight PDB records are the only support, and the structures are of a calmodulin-bound channel, not of a signalling ligand binding a receptor. The PDB chain is calmodulin generally; the CALM3 gene assignment comes from the pair definition, not the structure. The one judged paper concerned a different entity.","key_references":[{"PMID":"36763058","why":"Cryo-EM structures of human KCNQ1-CaM (PDB 7XNI, 7XNK)"}],"covers":["LR009207"]},"LR009513":{"pair":"CALR -> MTNR1A","headline":"Only proteomic co-purification records link calreticulin and MTNR1A; no ligand-receptor evidence.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. BioGRID lists Affinity Capture-MS and IntAct lists tandem affinity purification between the two [DB:BioGRID] [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and cell system are not reported in our evidence beyond the assay type.","localisation_and_range":"Not reported in our evidence.","caveats":"Support is high-throughput co-purification only; the one judged paper concerned a different entity. Calreticulin is a chaperone, so the association may reflect receptor folding rather than signalling.","key_references":[],"covers":["LR009513"]},"LR005553":{"pair":"CBLN1 -> NRXN1","headline":"CBLN1 links GluRdelta2 to presynaptic neurexins; supported by one abstract-read paper in mouse neurons.","interaction_type":"direct binding","direction_and_effect":"The GluRdelta2 N-terminal domain interacts with presynaptic neurexins through Cbln1; the extracellular domain of NRXN1beta suppressed Cbln1's synaptogenic activity [PMID:20537373].","molecular_requirements":"The complex is a three-part bridge: Cbln1 is required, since GluRdelta2 synaptogenic activity was abolished in Cbln1-knockout cultures and restored by recombinant Cbln1 [PMID:20537373]. NRXN knockdown also hindered it.","affinity_potency":[],"species_and_systems":"Mouse cerebellar primary cultures and in vivo, per the abstract (Cbln1 knockout mice); curators recorded human [PMID:20537373]. The human pair is ortholog-inferred.","localisation_and_range":"CBLN1 is flagged secreted and NRXN1 transmembrane [flag]; action across the synapse.","caveats":"Abstract read only. Direct CBLN1-NRXN1 binding is not measured in the abstract; the evidence is competitive suppression and knockdown. The NRXN1beta (not alpha) isoform is the one named. A second confirmed paper was not shown.","key_references":[{"PMID":"20537373","why":"Cbln1 bridges GluRdelta2 NTD and presynaptic neurexins"}],"covers":["LR002243","LR005553"]},"LR003726":{"pair":"CCK -> CCKBR","headline":"Well supported agonist-receptor pair: human CCK2 receptor binding (Kd ~20 nM for CCK8 conjugates) and signalling in several papers, plus GtoPdb, IntAct and PDB.","interaction_type":"direct binding","direction_and_effect":"CCK-8 stimulated phosphatidylinositol hydrolysis and Ca2+ mobilization in cells expressing the cloned receptor [PMID:7681836]; CCK-8 and gastrin I both bound and signalled [PMID:8349705]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Contact points: His207 with Asp8 of CCK [PMID:10438490]; Tyr189 and Asn358 with the C-terminal amide [PMID:12695525]. PDB 8IA7 has both chains [DB:PDB 8IA7].","affinity_potency":[{"value":"Kd approximately 20 nmol/L","assay":"saturation binding of 111In-DTPAGlu-G-CCK8","system":"NIH-3T3 and A431 cells overexpressing CCKBR","cite":"PMID:15001692"},{"value":"Kd 20-40 nM","assay":"binding of two labelled CCK8 derivatives","system":"A431 cells overexpressing CCK-BR","cite":"PMID:15068617"},{"value":"pIC50 8.8","assay":"binding","system":"human brain CCK-B receptor in CHO cells","cite":"PMID:8349705"},{"value":"pIC50 9.9-10.0","assay":"GtoPdb record","system":"database","cite":"PMID:7681836"}],"species_and_systems":"Human receptor in CHO, COS-7, NIH-3T3 and A431 cells; nude mouse xenografts for tracer imaging [PMID:15001692, PMID:15068617]. Mouse pair is projected.","localisation_and_range":"CCK flagged secreted, CCKBR transmembrane [flag].","caveats":"Affinity values for the Kd entries come from modified CCK8 conjugates, not native CCK. The receptor also binds gastrin [PMID:8349705]. All papers read as abstracts.","key_references":[{"PMID":"7681836","why":"Cloning of the human CCK-B/gastrin receptor with CCK-8 signalling"},{"PMID":"8349705","why":"Human brain CCK-B receptor binding and signalling in CHO cells"},{"PMID":"10438490","why":"His207-Asp8 direct contact point"}],"covers":["LR000181","LR003726"]},"LR005562":{"pair":"CCL11 -> ACKR1","headline":"Direct strong binding of CCL11 to human Duffy antigen (ACKR1) on erythrocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CCL11 binds Duffy on red blood cells; effect on signalling or scavenging is not reported in our evidence [PMID:15358176].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 67.3 nM","assay":"radioligand displacement","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human erythrocytes [PMID:15358176]. Mouse pair is projected from human evidence.","localisation_and_range":"CCL11 flagged secreted, ACKR1 transmembrane [flag].","caveats":"Ki < 100 nM is the paper's strong-binding class [PMID:15358176]. Single paper.","key_references":[{"PMID":"15358176","why":"Chemokine binding profile of the Duffy antigen"}],"covers":["LR002253","LR005562"]},"LR000189":{"pair":"CCL13 -> ACKR4","headline":"One paper reports MCP-4 binding to the receptor then named CCR11 (ACKR4), but the interpretation is contested.","interaction_type":"direct binding","direction_and_effect":"Radiolabelled MCP-4 bound a single high-affinity site on receptor-transfected cells and chemotaxis assays were run [PMID:10734104].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 0.14 nM","assay":"radiolabelled MCP-4 competition binding","system":"receptor-transfected murine L1.2 cells","cite":"PMID:10734104"}],"species_and_systems":"Human receptor expressed in murine L1.2 cells [PMID:10734104].","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Curator note: another paper reported different ligands (CCL19/21/25) for this receptor and the MCP claims were not upheld. One abstract-only paper; no database support.","key_references":[{"PMID":"10734104","why":"MCP-4 binding to CCR11 (ACKR4) IC50 0.14 nM"}],"covers":["LR000189"]},"LR000198":{"pair":"CCL15 -> CCR1","headline":"CCL15 (MIP-5) binds human CCR1 with nanomolar competition affinity; supported by a binding paper, GtoPdb, UniProt and PDB structures.","interaction_type":"direct binding","direction_and_effect":"CCL15 competed with 125I-MIP-1alpha for CCR1 binding [PMID:9346309]; GtoPdb lists a full agonist [DB:GtoPdb]. UniProt notes that CCR1 interacts with CCL15 [DB:UniProt].","molecular_requirements":"PDB entries 7VL9 and 7VLA contain a chain of Q16663 and a chain of P32246 [DB:PDB 7VL9]; subunit requirements are not reported in our evidence.","affinity_potency":[{"value":"IC50 12 nM","assay":"competition with 125I-MIP-1alpha","system":"CCR1 receptor-binding assay","cite":"PMID:9346309"}],"species_and_systems":"Human ligand and receptor; the original paper was read as an abstract only [PMID:9346309].","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Agonist status rests on the abstract and GtoPdb; CCL15 also binds CCR3 with 2.5 nM, so CCR1 is not exclusive [PMID:9346309].","key_references":[{"PMID":"9346309","why":"Identification of MIP-5 and its CCR1 binding"}],"covers":["LR000198"]},"LR003735":{"pair":"CCL17 -> ACKR1","headline":"CCL17 binds human ACKR1 (Duffy) with Ki 58.0 nM and competes moderately for CXCL1 binding; binding only.","interaction_type":"direct binding","direction_and_effect":"Binding only; no signalling reported in our evidence. CCL17 showed strong binding (Ki < 100 nM class) to Duffy on red blood cells [PMID:15358176] and moderately inhibited 125I-CXCL1 binding to DARC [PMID:13679391].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 58.0 nM","assay":"radioligand displacement","system":"human red blood cells","cite":"PMID:15358176"}],"species_and_systems":"Human chemokine and human Duffy antigen (erythrocytes; DARC F-2 cells) [PMID:15358176][PMID:13679391]. The mouse pair is projected from human evidence.","localisation_and_range":"Secreted ligand and transmembrane receptor according to entity annotation flags [flag]; paracrine/endocrine range implied by the secreted flag only.","caveats":"Quote for PMID 13679391 is a browser-read sentence not yet spot-checked. Evidence from only two papers.","key_references":[{"PMID":"15358176","why":"Ki for CCL17 at Duffy antigen"},{"PMID":"13679391","why":"Competition for CXCL1 binding to DARC"}],"covers":["LR000207","LR003735"]},"LR010872":{"pair":"CCL18 -> ERG28","headline":"Only a single IntAct two-hybrid record links CCL18 and ERG28; no curated paper supports a ligand-receptor role.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"ERG28 carries no receptor flag in the dossier; CCL18 is secreted [flag].","caveats":"Support is one IntAct physical association from a two-hybrid pooling approach [DB:IntAct]; no papers were judged and none confirm the pair.","key_references":[],"covers":["LR010872"]},"LR002259":{"pair":"CCL18 -> GPER1","headline":"Functional-only evidence from one abstract-read paper in cancer cell lines; CCL18-GPER1 pairing itself is treated as background.","interaction_type":"functional only","direction_and_effect":"CCL18 acts as an agonist at GPR30/GPER1 per the curator, but the paper reports CCL18 and estradiol do not give identical signalling: CCL18 decreased MMP7 in A549 cells and increased ERK activation in A549 but decreased it in MCF-7 [PMID:32487604].","molecular_requirements":"Not reported in our evidence (no subunit or co-receptor data).","affinity_potency":[],"species_and_systems":"Human ligand and human receptor; human cancer cell lines A549, MCF-7 and MDA-MB-231 (qPCR, In-Cell Western, western blot, ELISA) [PMID:32487604].","localisation_and_range":"Ligand flagged secreted [flag]; receptor localisation not reported in our evidence.","caveats":"Only one paper, read as abstract only. No binding assay is described; GPR30 as a CCL18 receptor is stated as prior knowledge. Cell-type-dependent and opposite ERK responses.","key_references":[{"PMID":"32487604","why":"Functional comparison of CCL18 and estradiol signalling via GPR30"}],"covers":["LR002259"]},"LR003753":{"pair":"CCL2 -> ACKR2","headline":"Direct binding of CCL2 to ACKR2 (D6), a promiscuous beta-chemokine receptor, with human CCL2 about 30-fold lower affinity than murine JE.","interaction_type":"direct binding","direction_and_effect":"hD6 binds most beta-chemokines with high affinity and did not flux calcium after ligand binding, so signalling capacity is unclear [PMID:9405404]; the second paper reports MCP-1 competing for MCP-3 binding with IC50 1.2 nM [PMID:9364936].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 1.2 nM","assay":"competition for MCP-3 binding","system":"receptor then named CCR10 (cloned human receptor)","cite":"PMID:9364936"}],"species_and_systems":"Human ligand and receptor, CHO cells stably expressing human D6 [PMID:9405404]. Mouse pair is ortholog-inferred. UniProt lists CCL2 among ACKR2 chemokine ligands [DB:UniProt].","localisation_and_range":"Ligand is flagged as secreted and not transmembrane [flag], so signalling is presumably paracrine or endocrine; receptor is flagged transmembrane [flag].","caveats":"The text states human MCP1 binds hD6 with approximately 30-fold lower affinity than the presumed murine homologue JE [PMID:9405404]. The 9364936 paper names its receptor CCR10, not ACKR2; the match is by curator assignment. Four other papers were review-only.","key_references":[{"PMID":"9405404","why":"hD6 characterisation, promiscuous binding, MCP1 lower affinity"},{"PMID":"9364936","why":"Binding of MCP-1 to cloned receptor, IC50 1.2 nM"}],"covers":["LR000232","LR003753"]},"LR003744":{"pair":"Ccl21a -> Cxcr3","headline":"Mouse CCL21 acting on mouse CXCR3 is supported by binding and signalling papers, but none distinguish Ccl21a from other mouse CCL21 genes.","interaction_type":"functional only","direction_and_effect":"Mouse CXCR3-transfected cells responded to CCL21 (6Ckine) with calcium flux in a chemokine screen [PMID:9653165]. SLC/6Ckine/Exodus 2 showed lower-affinity binding to murine CXCR3 [PMID:10556837]. Murine 6C-kine bound CXCR3 and inhibited tumour growth in SCID mice [PMID:11225989].","molecular_requirements":"Not reported in our evidence beyond CXCR3 as receptor.","affinity_potency":[],"species_and_systems":"Murine CXCR3 in L1.2 pre-B cells [PMID:10556837], mouse CXCR3-transfected cells [PMID:9653165], and murine 6C-kine in a human tumour xenograft in SCID mice [PMID:11225989]. No mouse-gene-specific (Ccl21a) experiment is identified.","localisation_and_range":"Ligand is flagged secreted and receptor flagged a receptor [flag]; no transmembrane flag is given. Secreted ligand acts on a cell-surface receptor.","caveats":"Abstract-only reads; no affinity for CCL21 is quoted. Binding was lower affinity than for IP10, ITAC and Mig [PMID:10556837]. The papers say 6Ckine/CCL21 generically, so assignment to Ccl21a versus Ccl21b/c is not resolved in our evidence. No database record. The abstract of PMID:11225989 notes human 6C-kine does not bind CXCR3.","key_references":[{"PMID":"9653165","why":"CCL21 identified as mouse CXCR3 ligand"},{"PMID":"10556837","why":"lower-affinity CCL21 binding to murine CXCR3"},{"PMID":"11225989","why":"murine 6C-kine binds CXCR3 and acts in vivo"}],"covers":["LR003744"]},"LR001692":{"pair":"CCL22 -> ACKR2","headline":"CCL22 competes for uptake by ACKR2 in one trophoblast study; database annotation also lists CCL22 as an ACKR2 ligand.","interaction_type":"functional only","direction_and_effect":"Uptake of fluorescent CCL2 by ACKR2-expressing HEK cells and human trophoblasts fell when a 10-fold excess of unlabelled CCL22 (among others) was added, so CCL22 interacts with ACKR2 [PMID:25297873]. ACKR2 is a scavenger: it binds many inflammatory CC chemokines but does not stimulate migration or conventional signalling [PMID:25297873]. UniProt lists CCL22 among ACKR2 chemokine ligands [DB:UniProt].","molecular_requirements":"ACKR2 alone in HEK cells was enough for competition of uptake; no other subunits reported.","affinity_potency":[],"species_and_systems":"Human HEK-ACKR2 cells and primary human trophoblasts [PMID:25297873]. The mouse pair is projected from human; the same paper used mouse Ackr2 knockouts but not for CCL22 in our evidence.","localisation_and_range":"Ligand is flagged secreted and receptor flagged transmembrane [flag]; this is an annotation, not from the papers, and implies paracrine/endocrine signalling to a cell-surface receptor. ACKR2 is described as an internalising scavenger [PMID:25297873].","caveats":"Only an indirect competition-of-uptake result from a browser-read quote (unverified); no direct CCL22 binding or affinity. UniProt alone lacks a quoted assay. No affinity reported.","key_references":[{"PMID":"25297873","why":"CCL22 competes for ACKR2-mediated CCL2 uptake"}],"covers":["LR001692","LR005065"]},"LR003762":{"pair":"CCL3 -> ACKR2","headline":"Human D6/ACKR2 binds many beta-chemokines, but the only verified paper tested murine MIP-1a, not human CCL3; support is weak and indirect.","interaction_type":"direct binding","direction_and_effect":"D6 (ACKR2) is a promiscuous beta-chemokine receptor binding most beta-chemokines [PMID:9405404]. UniProt lists CCL3 among ACKR2 ligands [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human D6 expressed in transduced cells; binding was measured by displacement of radioiodinated murine MIP-1a, and the highest-affinity ligands included murine MIP-1a and MIP-1b [PMID:9405404]. Both human and mouse pairs here are ortholog-inferred.","localisation_and_range":"ACKR2 is flagged as a receptor and transmembrane [flag]; CCL3 as secreted [flag].","caveats":"The paper does not report a human CCL3 value in our excerpts; the human and mouse pairs rest on murine ligand against human receptor. Other papers are review-only or abstract-insufficient. No affinity numbers are in our evidence.","key_references":[{"PMID":"9405404","why":"Cloning of human D6 with displacement binding of beta-chemokines"}],"covers":["LR000245","LR003762"]},"LR003771":{"pair":"CCL5 -> GPR75","headline":"Two papers support CCL5 activating GPR75 (Gq signalling), one at subnanomolar potency in transfected cells; no direct binding measurement in the dossier.","interaction_type":"functional only","direction_and_effect":"RANTES at subnanomolar concentrations stimulated luciferase reporter activity, IP3 and Ca2+ in GPR75-transfected cells, blocked by the PLC inhibitor U73122, indicating Gq signalling [PMID:17001303]. In SH-SY5Y cells, CCL5 induced AKT/GSK3b/ERK phosphorylation despite CCR1/CCR3/CCR5 antagonists, was pertussis-toxin-insensitive, caused GPR75 internalisation, and CRISPR knockdown (about 70% GPR75 reduction) reduced CCL5-induced pERK [PMID:29772059]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"GPR75 acts alone in these assays; pathway is Gq (PLC/PI3K) [PMID:17001303][PMID:29772059].","affinity_potency":[{"value":"pEC50 9.59","assay":"reporter/IP3/Ca2+ response to RANTES","system":"GPR75-transfected cells (human ligand and receptor)","cite":"PMID:17001303"}],"species_and_systems":"Human ligand and receptor: transfected cells, HT22 line expressing GPR75 endogenously [PMID:17001303]; human SH-SY5Y neuroblastoma cells and rat primary cortical neurons [PMID:29772059]. Mouse pair is ortholog-inferred.","localisation_and_range":"CCL5 flagged secreted; GPR75 flagged transmembrane receptor [flag].","caveats":"First paper read as abstract only. 'Binds' is asserted by the authors but only signalling and internalisation data are shown. UniProt notes GPR75 activation may affect insulin secretion [DB:UniProt]. The 2018 paper notes CCL4 and CCL7 gave no effect in the earlier study, citing prior work [PMID:29772059].","key_references":[{"PMID":"17001303","why":"Deorphanisation: RANTES activates GPR75, pEC50 9.59"},{"PMID":"29772059","why":"Independent SH-SY5Y signalling, internalisation and CRISPR knockdown"}],"covers":["LR000261","LR003771"]},"LR003780":{"pair":"CCL7 -> CCR5","headline":"MCP-3 (CCL7) binds human CCR5 with IC50 2.14 nM but without a functional response and blocks MIP-1beta activation, so it is a natural antagonist.","interaction_type":"direct binding","direction_and_effect":"MCP-3 competed for [125I]-MIP-1beta binding to CCR5 (IC50 2.14 nmol/L) yet elicited no functional response, inhibited CCR5 activation by MIP-1beta, and did not induce significant receptor endocytosis, so it may be a natural antagonist [PMID:10477718]. GtoPdb: antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"IC50 2.14 nmol/L","assay":"competition vs [125I]-MIP-1beta","system":"stable CCR5-expressing cell line (human)","cite":"PMID:10477718"}],"species_and_systems":"Human ligand and receptor in a recombinant cell line [PMID:10477718]; mouse pair is ortholog-inferred.","localisation_and_range":"CCL7 flagged secreted; CCR5 flagged transmembrane receptor [flag].","caveats":"Single paper, abstract only; antagonism is not agonism, relevant for scoring signalling. The abstract's IC50 list is ordered by ligand and the 2.14 value was assigned to MCP-3 by the curators.","key_references":[{"PMID":"10477718","why":"MCP-3 binds CCR5 without activation and antagonises it"}],"covers":["LR000270","LR003780"]},"LR002268":{"pair":"CCN1 -> LRP1","headline":"CCN1 co-immunoprecipitates with LRP1 in human fibroblasts and LRP1 is needed for CCN1-driven ROS and apoptosis with TNFalpha; one paper.","interaction_type":"direct binding","direction_and_effect":"CCN1 interacts with LRP1 in a protein complex, and binding to LRP1 is critical for CCN1-induced ROS generation and apoptotic synergism with TNFalpha [PMID:22363611]. Anti-CCN1 antibodies pulled down the 515 kDa LRP1 subunit from primary human skin fibroblasts, and receptor-associated protein (RAP) abolished this co-immunoprecipitation [PMID:22363611].","molecular_requirements":"LRP1 acts alongside integrins alpha(v)beta(5), alpha(6)beta(1) and syndecan 4 as part of a multi-receptor setup [PMID:22363611]. The 515 kDa LRP1 chain was the one detected.","affinity_potency":[],"species_and_systems":"Primary human skin fibroblasts, human CCN1; siRNA knockdown of LRP1. Mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag] but described in the papers as matrix-associated, so adhesion-type contact with receptors on neighbouring cells is plausible.","caveats":"Co-immunoprecipitation shows a complex, which may be indirect, no purified-protein binding or affinity is reported. Single paper; full text excerpts used.","key_references":[{"PMID":"22363611","why":"CCN1-LRP1 co-IP and LRP1 requirement for ROS and apoptosis"}],"covers":["LR002268","LR005569"]},"LR005571":{"pair":"CCN1 -> TLR4","headline":"CCN1 binds TLR4 directly and activates MyD88-dependent signalling; supported by one full-text paper.","interaction_type":"direct binding","direction_and_effect":"CCN1 acts as an agonist: it binds TLR4 directly and drives MyD88-dependent cytokine expression and neutrophil mobilization [PMID:32144270]. Induction of Tnfa and Il6 was reduced in Tlr4-knockout BMDMs [PMID:32144270].","molecular_requirements":"Recombinant TLR4 lacking MD2 bound immobilized CCN1 in a solid-phase assay; CD14 control did not bind [PMID:32144270]. A CCN1-DM mutant that cannot bind LPS still bound TLR4 and induced signalling, so activation was independent of LPS binding [PMID:32144270]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"KD 291 nM","assay":"SPR, TLR4 immobilized, CCN1 as analyte","system":"recombinant human TLR4","cite":"PMID:32144270"}],"species_and_systems":"Human recombinant proteins for binding; signalling shown in mouse bone-marrow-derived macrophages (wild-type, Myd88 and Tlr4 knockout) [PMID:32144270]. The mouse pair is ortholog-inferred.","localisation_and_range":"CCN1 is flagged secreted [flag]; the authors propose it acts as a DAMP in sterile inflammation after tissue injury [PMID:32144270].","caveats":"Single study. Affinity is moderate (hundreds of nM), similar to its alphavbeta3 binding in the same paper [PMID:32144270]. No independent replication in our evidence.","key_references":[{"PMID":"32144270","why":"SPR, solid-phase binding and knockout BMDM signalling for CCN1-TLR4"}],"covers":["LR002270","LR005571"]},"LR005067":{"pair":"CCN2 -> FGFR2","headline":"CCN2 binds FGFR2 in a protein-array screen and enhances FGFR2 binding to FGF2 and FGF4; abstract-level, one paper.","interaction_type":"direct binding","direction_and_effect":"CCN2 bound FGFR2 and enhanced FGFR2 binding to FGF2 and FGF4, and CCN2 with FGF2 had a collaborative effect on ERK phosphorylation and osteoblastic differentiation [PMID:23142580]. This points to a positive modulator rather than a competing ligand.","molecular_requirements":"Binding to FGFR2 is also reported for FGFR3, with higher affinity toward FGFR2 [PMID:23142580]. Subunit or domain requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Protein-array screen, then confirmation of binding; osteoblastic cells for function; species not specified in the abstract [PMID:23142580]. IntAct holds the protein-array record [DB:IntAct].","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. No affinity value reported. Database support is the same paper [DB:IntAct].","key_references":[{"PMID":"23142580","why":"Protein-array binding of CCN2 to FGFR2 and enhancement of FGF binding"}],"covers":["LR001698","LR005067"]},"LR000387":{"pair":"CCN2 -> NTRK1","headline":"CTGF activates TrkA in human mesangial cells, shown by cross-linking and phosphorylation; abstract-level, one paper.","interaction_type":"direct binding","direction_and_effect":"CTGF stimulated TrkA phosphorylation at Tyr490 and Tyr674/675, blocked by the Trk inhibitor K252a, which also blocked CTGF-induced signalling and TIEG induction; the authors conclude TrkA is a tyrosine kinase receptor for CTGF [PMID:15601748].","molecular_requirements":"Cross-linked rCTGF formed complexes with TrkA and with the neurotrophin co-receptor p75NTR [PMID:15601748]. Whether p75NTR is required is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human mesangial cells with recombinant CTGF [PMID:15601748]. The mouse pair is ortholog-inferred.","localisation_and_range":"CCN2 is flagged as secreted [flag], so paracrine or autocrine action is plausible; this is annotation, not shown by the papers.","caveats":"Abstract read only. Evidence is cross-linking and phosphorylation; no affinity value is reported in our evidence.","key_references":[{"PMID":"15601748","why":"Cross-linking and phosphorylation showing TrkA as a CTGF receptor"}],"covers":["LR000387","LR003893"]},"LR002277":{"pair":"CCN3 -> ITGA6","headline":"CCN3 supports adhesion via integrin alpha6beta1, but direct binding is not shown; functional evidence from one paper.","interaction_type":"functional only","direction_and_effect":"CCN3 supports HUVEC adhesion partly through alpha6beta1, but CCN3-induced migration did not depend on alpha6beta1 [PMID:12695522]. Agonist effect is assigned by curators for adhesion.","molecular_requirements":"The receptor is the alpha6beta1 heterodimer [PMID:12695522]. Heparan sulfate proteoglycans were also involved [PMID:12695522].","affinity_potency":[],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"Function only: blocking in adhesion assays implicates alpha6beta1; direct binding was demonstrated only for alphavbeta3 and alpha5beta1, not alpha6beta1 [PMID:12695522]. No database record for this pair in our evidence. Human-only.","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002277"]},"LR005580":{"pair":"CCN3 -> ITGB1","headline":"CCN3 binds integrin alpha5beta1 directly (half-maximal binding 50 nM); beta1 evidence is via the alpha5beta1 heterodimer.","interaction_type":"direct binding","direction_and_effect":"CCN3 is an agonist for alpha5beta1-dependent adhesion and migration of HUVECs [PMID:12695522]. CCN3 binds directly to immobilized integrins alphavbeta3 and alpha5beta1 with half-maximal binding at 10 nM and 50 nM CCN3 respectively [PMID:12695522]. UniProt also notes that CCN3 inhibits MMP9 expression through ITGB1 engagement [DB:UniProt PMID 21871891].","molecular_requirements":"ITGB1 pairs with ITGA5 (binding shown) and ITGA6 (adhesion, no direct binding) in this paper [PMID:12695522]. Whether the beta1 chain alone suffices is not reported in our evidence.","affinity_potency":[{"value":"50 nM","assay":"half-maximal binding (EC50) to alpha5beta1, solid-phase ELISA","system":"purified integrin, recombinant human CCN3","cite":"PMID:12695522"}],"species_and_systems":"Recombinant human CCN3 (baculovirus-expressed) and purified integrins; HUVEC cells; rat cornea angiogenesis assay [PMID:12695522].","localisation_and_range":"CCN3 is a matricellular protein, and its adhesion activity is shown on coated protein [PMID:12695522]; a secretion annotation for CCN3 is not in our dossier.","caveats":"The 50 nM value is for the alpha5beta1 heterodimer, not ITGB1 alone. Single primary paper; UniProt and GtoPdb cite it [DB:UniProt][DB:GtoPdb].","key_references":[{"PMID":"12695522","why":"Direct CCN3-integrin binding and HUVEC adhesion, migration and angiogenesis"}],"covers":["LR002279","LR005580"]},"LR000279":{"pair":"CD14 -> ITGA4","headline":"Direct solid-phase binding of CD14-Fc to integrin alpha4beta1 reported in one abstract-read paper; ITGA4 is one chain of the receptor.","interaction_type":"direct binding","direction_and_effect":"CD14-Fc bound affinity-purified alpha4beta1 in a dose-dependent manner and Jurkat cells adhered to CD14-Fc via alpha4beta1 [PMID:17274987].","molecular_requirements":"Receptor is the alpha4beta1 heterodimer; re-expressing the alpha4 subunit in alpha4beta1-negative K562 cells conferred adhesion [PMID:17274987].","affinity_potency":[],"species_and_systems":"Human cells and recombinant CD14-Fc (Jurkat, K562 transfectants); the mouse pair is ortholog-inferred, not tested [PMID:17274987].","localisation_and_range":"CD14 is flagged secreted and a receptor [flag]; it is described as GPI-linked on the cell surface in the abstract, so juxtacrine adhesion is the tested setting [PMID:17274987].","caveats":"Single paper, read as abstract only. No database records. No affinity reported.","key_references":[{"PMID":"17274987","why":"CD14-Fc binds alpha4beta1 in solid phase; Jurkat adhesion"}],"covers":["LR000279","LR003789"]},"LR005076":{"pair":"CD200R1 -> CD200","headline":"Established CD200-CD200R binding; this row has the reverse orientation, CD200 is the ligand.","interaction_type":"direct binding","direction_and_effect":"Human CD200R was characterised and its binding to human CD200 defined [PMID:12960329]. CD200R is described as delivering an apparent inhibitory signal, unlike the activating CD200RLa/b [PMID:12960329].","molecular_requirements":"Mouse CD200RLa and CD200RLb pair with DAP12 and did not bind mouse CD200 [PMID:12960329].","affinity_potency":[],"species_and_systems":"Human CD200R with human CD200 per curator labels; mouse pair also listed; mouse work on paralogues [PMID:12960329].","localisation_and_range":"Both partners flagged secreted, receptor and transmembrane [flag]; not otherwise reported.","caveats":"One paper, abstract only; no affinity in our evidence. Database records support CD200-CD200R1 binding (BioGRID reconstituted complex, IntAct, Reactome) [DB:BioGRID][DB:IntAct][DB:Reactome]. The pair is the reverse of the usual CD200 -> CD200R1 direction.","key_references":[{"PMID":"12960329","why":"First human CD200R characterisation and CD200 binding"}],"covers":["LR001708","LR005076"]},"LR002286":{"pair":"CD24 -> L1CAM","headline":"Direct binding of CD24 to L1 shown in two abstract-level reports; sialic-acid dependent; human pair is ortholog-inferred from mouse work.","interaction_type":"direct binding","direction_and_effect":"Binding of CD24 to L1 depends on alpha2,3-sialic acid on CD24 and, by trans-interaction of L1 with sialylated CD24, determines promotion or inhibition of neurite outgrowth depending on cell type [PMID:11283023]. Brain HSA (mouse CD24) also bound L1 [PMID:9048906].","molecular_requirements":"Sialylated CD24 glycoform is required; L1 binding of HSA was resistant to high salt and did not need divalent cations, and treatment with OSGE reduced binding [PMID:9048906].","affinity_potency":[],"species_and_systems":"Mouse HSA/CD24 from brain [PMID:9048906]; the human pair is ortholog-inferred. Reactome lists an L1:HSA complex [DB:Reactome].","localisation_and_range":"CD24 is flagged transmembrane (GPI-anchored per the paper); L1CAM flagged secreted and transmembrane [flag]. Trans-interaction between cells [PMID:11283023].","caveats":"Abstract-only evidence; no affinity; the carbohydrate dependence means binding is lectin-like rather than protein-protein.","key_references":[{"PMID":"11283023","why":"L1 binds sialylated CD24; neurite outgrowth"},{"PMID":"9048906","why":"Brain HSA binds L1"}],"covers":["LR002286"]},"LR005085":{"pair":"CD38 -> PECAM1","headline":"Soluble CD38 acts on CD31 (PECAM1) on human sperm, shown by proximity ligation and signalling; single paper.","interaction_type":"functional only","direction_and_effect":"Soluble CD38 in seminal plasma increased sperm capacitation through interaction with CD31 on sperm; CD31 was tyrosine phosphorylated by Src and signalled via Erk1/2, giving acrosome reaction and hypermotility, blocked by Src/Ras/MEK inhibitors [PMID:26407101].","molecular_requirements":"Shc, SHP-2, Grb2, SOS and Src associated with phosphorylated CD31 [PMID:26407101]. Other requirements not reported.","affinity_potency":[],"species_and_systems":"Human sperm, recombinant sCD38 (e.g. 600 ng/ml) [PMID:26407101]; mouse pair projected. UniProt describes CD38/CD31 signalling in T lymphocytes [DB:UniProt].","localisation_and_range":"CD38 flagged secreted and transmembrane [flag]; the paper uses a soluble form from seminal plasma acting paracrine on sperm [PMID:26407101].","caveats":"A proximity ligation assay indicates proximity but no binding constant is reported. The mouse pair is inferred from human data.","key_references":[{"PMID":"26407101","why":"sCD38 activates CD31 on sperm"}],"covers":["LR001718","LR005085"]},"LR009117":{"pair":"CD40LG -> TRAF3","headline":"No paper evidence for CD40L binding TRAF3; the only support is a Reactome complex that actually binds CD40.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. Reactome records a TRAF2:TRAF1:cIAP1,2:TRAF3:NIK regulatory complex binding CD40, not CD40LG [DB:Reactome R-HSA-5676597].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"TRAF3 carries no secreted, receptor or transmembrane flag [flag]; it is an intracellular adaptor in the Reactome record [DB:Reactome R-HSA-5676597].","caveats":"No confirmed paper; two papers were abstract_insufficient and two judged a different entity. The Reactome reaction concerns CD40, so the pair looks like a mapping artefact rather than a ligand-receptor interaction.","key_references":[],"covers":["LR009117"]},"LR001719":{"pair":"CD44 -> SELE","headline":"CD44 glycoforms act as E-selectin ligands in two abstract-only papers plus IntAct and Reactome records; direction is reversed in the pair.","interaction_type":"direct binding","direction_and_effect":"The sialylated, fucosylated N-glycan glycoform of CD44 on human CD34+ progenitor cells serves as an E-selectin ligand, mediating rolling over a wider shear range than PSGL-1 [PMID:11402070]. Glycoproteomics in breast cancer cells identified CD44 (HCELL) and CD13 as key E-selectin ligands [PMID:29777742]. IntAct has coimmunoprecipitation and solid-phase assay records for the pair [DB:IntAct P16070-P16581].","molecular_requirements":"Activity depends on a specific glycoform (sLeX-type decoration on N-glycans) present only on primitive CD34+ cells, not mature hematopoietic cells [PMID:11402070]. Glycan-dependent, so gene-level expression will not predict it.","affinity_potency":[],"species_and_systems":"Human progenitor cells in shear-based adhesion assays [PMID:11402070]; human breast cancer cell lines and clinical tissue [PMID:29777742].","localisation_and_range":"CD44 carries secreted, receptor and transmembrane flags and SELE a transmembrane flag [flag]; the interaction is cell-surface and contact-dependent in rolling assays [PMID:11402070].","caveats":"Both papers abstract-only (the first also had full-text excerpts). Binding is to a glycan on CD44 rather than a protein-protein interface. E-selectin is the receptor here, CD44 the ligand as in the pair. Species for the breast cancer study not recorded in the dossier [PMID:29777742].","key_references":[{"PMID":"11402070","why":"CD44 glycoform as E-selectin ligand on human progenitors"},{"PMID":"29777742","why":"CD44 (HCELL) and CD13 as E-selectin ligands in breast cancer"}],"covers":["LR001719","LR005086"]},"LR000288":{"pair":"CD5L -> CD5","headline":"Pair rests on one 1998 abstract describing a B-cell ligand called CD5L; its identity relative to this entity is unclear.","interaction_type":"direct binding","direction_and_effect":"CD5-Ig bound a B-cell ligand termed CD5L, not blocked by anti-CD72 mAb, and CD5-Ig induced proliferation of resting B cells [PMID:9723705].","molecular_requirements":"The ligand was composed of 77-80 and 38-40 kDa polypeptide chains in immunoprecipitates and was distinct from CD72 [PMID:9723705].","affinity_potency":[],"species_and_systems":"Splenic and peritoneal B cells and B lymphoma lines; species not stated in the abstract [PMID:9723705]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Appears to be a B-cell surface ligand [PMID:9723705]; annotation flags mark both partners as secreted [flag].","caveats":"Abstract-only; the paper does not clone or identify the molecule, so the link to the gene CD5L is not shown in our evidence. No databases or affinity.","key_references":[{"PMID":"9723705","why":"CD5-Ig binding to a B cell ligand named CD5L"}],"covers":["LR000288","LR003797"]},"LR002295":{"pair":"CD6 -> CD44","headline":"New 2024 CD6-CD44 interaction found by proximity labeling and confirmed biochemically; one paper only.","interaction_type":"direct binding","direction_and_effect":"CD44 is a novel CD6 receptor; CD6 stimulation caused RhoA/ROCK-dependent actomyosin remodelling and tight junction disassembly in RPE cells [PMID:37820034].","molecular_requirements":"CD44, CD166 and CDCP1 cluster into a tripartite receptor complex upon CD6 binding and all components were required for tight junction disassembly [PMID:37820034].","affinity_potency":[],"species_and_systems":"RPE cells; species not stated in the abstract (curator label: human) [PMID:37820034]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both transmembrane by flags (also flagged secreted) [flag]; CD6 acts as a ligand on T cells toward RPE cells [PMID:37820034].","caveats":"Abstract-only; no affinity or detail on biophysical methods in our evidence. Only one of two confirmed papers is shown. No database records.","key_references":[{"PMID":"37820034","why":"CD44 identified as CD6 receptor; tripartite complex"}],"covers":["LR002295","LR005594"]},"LR001728":{"pair":"CD80 -> CD274","headline":"CD80 and PD-L1 interact according to databases and one mouse tumour study showing trans interaction; the literature on cis versus trans is conflicted.","interaction_type":"conflicting","direction_and_effect":"Blocking PD-L1/CD80 interactions in mice augmented antitumour immunity by expanding IFN-gamma-producing CD8+ T cells and IFN-gamma-dependent NOS2-expressing tumour-associated macrophages [PMID:37036990]. The paper reports that cis PD-L1/CD80 interactions may have the opposite effect on antitumour immunity, with a net benefit of blockade [PMID:37036990]. UniProt notes this interaction blocks PD-L1/PD-1 binding [DB:UniProt]. Which partner is ligand is not defined; both are annotated as receptors [flag].","molecular_requirements":"Trans interaction effects required tumour MHC-I expression and T-cell CD28 expression [PMID:37036990].","affinity_potency":[],"species_and_systems":"Mouse tumour models (MC38 and B16) for the paper [PMID:37036990]; the mouse pair is the direct one and the human pair is ortholog-inferred. Databases include surface plasmon resonance, protein array and cross-linking records [DB:IntAct] and a structure [DB:PDB 7TPS].","localisation_and_range":"Both partners are annotated as secreted, receptor and transmembrane [flag]. The paper concerns cell-cell (trans) contact between tumour and T cells, versus same-cell (cis) contact on antigen-presenting cells [PMID:37036990].","caveats":"Only one paper, read as an abstract with full-text excerpts. Previous reports claimed that only cis interactions exist, which this paper disputes [PMID:37036990]. The paper used antibody blockade and genetically engineered mice, not a binding assay. No affinity in our evidence. Species of the experiment is not listed in the curator fields.","key_references":[{"PMID":"37036990","why":"Mouse study showing trans PD-L1/CD80 interactions and the effect of blockade"}],"covers":["LR001728","LR005093"]},"LR005094":{"pair":"CD80 -> CD28","headline":"CD80 binds CD28 and is well supported by mutagenesis, binding assays and databases, though two curated papers are indirect.","interaction_type":"direct binding","direction_and_effect":"The interaction record annotates CD80 as stimulatory to CD28. Mutagenesis of soluble CD80 mapped 11 IgV-domain residues supporting receptor binding, with similar effects on CTLA4Ig and CD28Ig binding, suggesting overlapping sites [PMID:7545666]. Recombinant soluble s1CD80 bound CD28-Ig and CD152-Ig, and recombinant sCD80 inhibited the mixed lymphocyte reaction and T-cell proliferation, a decoy-like effect [PMID:17953528].","molecular_requirements":"Membrane CD80 uses both IgV and IgC domains: IgC-domain mutations of conserved residues completely ablated receptor binding [PMID:7545666]. The soluble form s1CD80 lacks the transmembrane domain; s2CD80 also lacks the IgC-like domain [PMID:17953528].","affinity_potency":[],"species_and_systems":"Human CD80 and CD28 constructs [PMID:7545666] [PMID:17953528]. The mouse pair is ortholog-inferred. Reactome has CD28:B7-1 complexes [DB:Reactome] and BioGRID/IntAct hold reconstituted-complex and solid-phase records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"CD80 is membrane-bound on antigen-presenting cells with a soluble spliced form in serum (0 to 1 mg/l in 24% of healthy people) [PMID:17953528]; the CD80 flags show secreted and transmembrane [flag].","caveats":"Both main papers were abstract-only. No affinity in our evidence. PMID:21530327 is about B7-H2 binding CD28, and only its statement that B7-1 and B7-2 use different domains concerns this pair; it was curated from the abstract.","key_references":[{"PMID":"7545666","why":"Mutagenesis mapping of CD80 residues for CD28/CTLA-4 binding"},{"PMID":"17953528","why":"Soluble CD80 binds CD28-Ig and inhibits T-cell responses"}],"covers":["LR001729","LR005094"]},"LR005607":{"pair":"CDH2 -> ASTN1","headline":"N-cadherin binds astrotactin and supports neuron-glia adhesion; one abstract-level paper with mouse in vivo and cell data.","interaction_type":"direct binding","direction_and_effect":"ASTN1 binds N-cadherin and the interaction supports cell-cell adhesion. N-cadherin acts as a cis ligand on the neuron and a trans ligand on glia; loss of glial Cdh2 slowed granule cell migration more severely than neuronal loss [PMID:30262652].","molecular_requirements":"The ASTN1 C-terminal ectodomain (MACPF, FNIII, ANX-like region) was needed: CDH2 co-precipitated with full-length ASTN1 but not ASTN1-\u0394CTD in HEK 293T cells [PMID:30262652].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation from HEK 293T cells and P7 mouse cerebellar lysates, cerebellar slice cultures and granule-cell/glia chimeras; the mouse pair is the experimental one [PMID:30262652]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound; acts in cis and trans at the neuron-glia migration junction [PMID:30262652].","caveats":"Only one paper, curated from abstract plus excerpts; binding affinity is not reported, and curator notes say the direct-binding label rests on co-IP and cell assays.","key_references":[{"PMID":"30262652","why":"ASTN1-CDH2 cis and trans binding in glial-guided migration"}],"covers":["LR002309","LR005607"]},"LR005616":{"pair":"CDH6 -> CDH6","headline":"Cadherin-6 binds itself preferentially in SPR on mouse proteins; human pair inferred.","interaction_type":"direct binding","direction_and_effect":"Homophilic binding was favored over all heterophilic interactions for only cadherin-6 and cadherin-20 [PMID:29742438].","molecular_requirements":"Cadherin-6, -9 and -10 share a specificity group [PMID:29742438].","affinity_potency":[],"species_and_systems":"Type II cadherin binding was measured by SPR and AUC on purified mouse EC1-EC2 fragments, with A431D cell co-culture; the human pair is inferred by orthology [PMID:29742438].","localisation_and_range":"Membrane-bound adhesion molecules, contact-dependent; CDH6 is flagged transmembrane [flag].","caveats":"Single paper; SPR heterophilic affinities could not be determined because of competing homodimerization, so only relative response levels are available [PMID:29742438]. Human result is ortholog-projected, not measured. BioGRID also lists a CDH6 - CDH6 co-localization record, which is not binding evidence [DB:BioGRID] [PMID:10207020].","key_references":[{"PMID":"29742438","why":"Homophilic cadherin-6 preference in SPR"}],"covers":["LR002318","LR005616"]},"LR001737":{"pair":"CEACAM1 -> CD209","headline":"Lewis x glycan-mediated binding of neutrophil CEACAM1 to DC-SIGN, supported by two abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"DC-SIGN (CD209) binds CEACAM1 through Lewis x glycans expressed on neutrophil-derived CEACAM1 [PMID:16246332]; CEACAM1 is fucosylated by fucosyltransferase IX and interacts with DC-SIGN via Lewis x residues [PMID:16282604]. The interaction regulates dendritic cell-neutrophil contact [DB:UniProt].","molecular_requirements":"Binding is glycan-mediated, so the glycosylation state of CEACAM1 matters. For neutrophil-DC contact, binding of DC-SIGN to both CEACAM1 and Mac-1 was required [PMID:16246332].","affinity_potency":[],"species_and_systems":"Human cells and proteins (curated); IntAct lists a solid phase assay [DB:IntAct].","localisation_and_range":"CEACAM1 on neutrophils engaging DC-SIGN on dendritic cells, i.e. cell-contact (juxtacrine) from the papers [PMID:16246332]; CEACAM1 is annotated secreted, receptor and transmembrane [flag].","caveats":"Both papers read as abstract only. This is a lectin-glycan interaction, not a classical protein-protein interface, so expression of CEACAM1 transcript does not imply the Lewis x modification.","key_references":[{"PMID":"16246332","why":"DC-SIGN binds neutrophil CEACAM1 via Lewis x; needed with Mac-1"},{"PMID":"16282604","why":"CEACAM1 fucosylation by FUT9 and DC-SIGN binding"}],"covers":["LR001737"]},"LR005625":{"pair":"CEMIP -> ANXA1","headline":"Secreted CEMIP (KIAA1199) G8 domain binds membrane ANXA1 in rheumatoid arthritis synoviocytes; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"The G8 domain of secreted KIAA1199 bound ANXA1, anchoring it to the membrane and enabling extracellular hyaluronic acid degradation; classed as agonist [PMID:33473125]. Interaction was shown by co-IP in RA fibroblast-like synoviocytes and 293T cells [PMID:33473125].","molecular_requirements":"Only wild-type KIAA1199 and G8-containing mutants co-precipitated with ANXA1; G8 deletion lost the in vivo effect [PMID:33473125].","affinity_potency":[],"species_and_systems":"Human RA synoviocytes and ANXA1-expressing 293T cells; collagen-induced arthritis and knockout mice [PMID:33473125]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted CEMIP attaches to the cell membrane via ANXA1 [PMID:33473125]. ANXA1 is flagged non-transmembrane [flag], so it acts as an anchor rather than a classical receptor.","caveats":"Co-IP evidence; affinity not reported. No database records.","key_references":[{"PMID":"33473125","why":"G8 domain of sKIAA1199 binds ANXA1 for membrane attachment"}],"covers":["LR002336","LR005625"]},"LR000297":{"pair":"CGA -> LHCGR","headline":"The CGA alpha chain contacts LHCGR; LH and hCG bind with high affinity, but receptor specificity comes from the beta chain.","interaction_type":"direct binding","direction_and_effect":"Cross-linking showed hCG alpha bound the LH/CG receptor exodomain [PMID:10342833]. LH and hCG are full agonists; hCG and LH displaced radiolabeled hCG with ED50 4.3 and 4.8 ng/ml and induced cAMP [PMID:1922095] [PMID:12727981]. Exon 10 deletion impaired LH but not hCG action [PMID:12727981].","molecular_requirements":"Ligands are heterodimers of CGA with LHB (LH) or a CGB product (hCG); recombinant FSH, with the same CGA, was not effective, so the beta chain determines specificity [PMID:1922095].","affinity_potency":[{"value":"Kd 1.2x10^-10 M","assay":"radioligand binding, 125I-hCG","system":"transfected human 293 cells expressing human LH receptor","cite":"PMID:1922095"},{"value":"ED50 4.3 ng/ml (hCG), 4.8 ng/ml (LH)","assay":"displacement of 125I-hCG","system":"transfected human 293 cells","cite":"PMID:1922095"},{"value":"pKd 9.899999618530273 to 11.800000190734863","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:1922095"}],"species_and_systems":"Human proteins in cell lines [PMID:1922095] [PMID:12727981]. Equine, rat and ovine LH/CG failed to displace hCG on the human receptor [PMID:1922095]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted hormone acting on transmembrane receptor [flag].","caveats":"Abstract-only papers. CGA alone is not the specific ligand. Structures: [DB:PDB 7FIG] [DB:PDB 7FIH] [DB:PDB 7FII]; [DB:BioGRID] [DB:GtoPdb]. Two further confirmed rows not shown.","key_references":[{"PMID":"1922095","why":"Kd and displacement data for human LH/hCG on human LHR"},{"PMID":"10342833","why":"hCG alpha cross-links to the LHR exodomain"},{"PMID":"12727981","why":"Binding vs activation dissociated by exon 10 deletion"}],"covers":["LR000297","LR003804"]},"LR003807":{"pair":"CHAD -> ITGB1","headline":"Chondroadherin engages beta1 integrins (as alpha2beta1); ITGB1 evidence is via the heterodimer.","interaction_type":"direct binding","direction_and_effect":"Annotated stimulatory [flag]. Anti-beta1 antibody reduced adhesion of chondrocytes to chondroadherin by 2/3 at 100 \u03bcg/ml, indicating beta1 integrins are involved; alpha2beta1 was identified as a chondroadherin-binding integrin [PMID:9281592].","molecular_requirements":"ITGB1 acts as part of alpha2beta1, requiring ITGA2; divalent cations Mg2+ or Mn2+ needed, not Ca2+ [PMID:9281592].","affinity_potency":[],"species_and_systems":"Bovine chondrocytes in the abstract and excerpts; curator note cites human fibroblasts [PMID:9281592].","localisation_and_range":"Matrix ligand flagged secreted [flag].","caveats":"Evidence is from a single 1997 paper read as abstract (full-text excerpts available). Chain-only support: the paper identifies the heterodimer; antibody inhibition was partial. No affinity reported.","key_references":[{"PMID":"9281592","why":"Anti-beta1 inhibition and alpha2beta1 identification"}],"covers":["LR000301","LR003807"]},"LR001746":{"pair":"CLEC11A -> ITGA11","headline":"Integrin alpha11 (as alpha11beta1) binds Osteolectin/CLEC11A with nanomolar affinity and is required for the osteogenic response, in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"alpha11beta1 binds Osteolectin and is required for its osteogenic response; Osteolectin acts as an agonist, promoting Wnt-pathway activation [PMID:30632962]. Itga11 deletion blocked the response in mouse MC3T3-E1 cells and in human bone marrow stromal cells [PMID:30632962].","molecular_requirements":"The receptor is the alpha11beta1 heterodimer; flag-tagged Osteolectin pulled down endogenous integrin alpha11 and beta1 [PMID:30632962].","affinity_potency":[{"value":"Kd 1.0 nM","assay":"binding of alpha11beta1 to Osteolectin (curated value; abstract says nanomolar)","system":"not specified in dossier","cite":"PMID:30632962"}],"species_and_systems":"Human Osteolectin overexpressed in mouse MC3T3-E1 cells for pulldown; recombinant mouse Osteolectin used for osteogenesis; Lepr-cre;Itga11fl/fl mice show reduced osteogenesis [PMID:30632962]. Mouse pair is ortholog-inferred.","localisation_and_range":"CLEC11A flagged secreted [flag]; the receptor is a membrane integrin.","caveats":"Single paper; the species of the affinity assay is not stated in our evidence. No database records.","key_references":[{"PMID":"30632962","why":"Identifies integrin alpha11beta1 as Osteolectin receptor"}],"covers":["LR001746","LR005106"]},"LR002349":{"pair":"CLEC1B -> PDPN","headline":"CLEC-2 (CLEC1B) and podoplanin bind directly, with crystal structure and flow cytometry support; the biological direction is podoplanin to CLEC-2.","interaction_type":"direct binding","direction_and_effect":"Podoplanin is the physiological ligand activating platelet CLEC-2, so the stored direction CLEC1B -> PDPN is reversed [PMID:17616532]. Podoplanin induced platelet aggregation, and recombinant CLEC-2 inhibited aggregation induced by podoplanin-expressing tumour cells or lymphatic endothelial cells [PMID:17616532]. UniProt says PDPN binding triggers CLEC1B activation in platelets [DB:UniProt].","molecular_requirements":"Binding depends on sialic acid on podoplanin O-glycans [PMID:17616532]. Crystal structures show both podoplanin and rhodocytin bind the noncanonical side face of CLEC-2 [PMID:25458834] [DB:PDB 3WSR].","affinity_potency":[],"species_and_systems":"Human proteins; platelets and flow cytometry [PMID:17616532]. Mouse pair is ortholog-inferred.","localisation_and_range":"PDPN is membrane-bound (juxtacrine, e.g. on tumour or lymphatic endothelial cells) per the paper [PMID:17616532]; CLEC1B is annotated secreted in the entity flags, which conflicts with its platelet-receptor role [flag].","caveats":"Both papers abstract only. No affinity in our evidence.","key_references":[{"PMID":"17616532","why":"Podoplanin-CLEC-2 association; platelet aggregation"},{"PMID":"25458834","why":"Crystal structures of CLEC-2 with podoplanin"}],"covers":["LR002349","LR005631"]},"LR005634":{"pair":"CLSTN3 -> NRXN1","headline":"Calsyntenin-3 binds \u03b2-neurexins as a synaptic adhesion pair; isoform-specific evidence for NRXN1 is not shown (abstract only).","interaction_type":"direct binding","direction_and_effect":"Clstn3 is a postsynaptic adhesion molecule that induces presynaptic differentiation via presynaptic neurexins; \u03b2-Nrxns directly interact via their LNS domain with Clstn3 and Clstn3 cadherin domains [PMID:32434929].","molecular_requirements":"Splice site 4 (SS4) insert-positive \u03b2-Nrxn variants, but not insert-negative variants, reversed the impaired Clstn3 synaptogenic activity; Clstn3 selectively formed complexes with SS4-positive Nrxns in vivo [PMID:32434929].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier; hippocampal neurons and Clstn3 conditional knockout mice (mouse pair is the non-inferred one) [PMID:32434929]. Human pair is ortholog-inferred.","localisation_and_range":"Both partners transmembrane/adhesion proteins (not flagged secreted [flag]); trans-synaptic, contact-dependent [PMID:32434929].","caveats":"Abstract only. The evidence sentence names \u03b2-Nrxns collectively, not NRXN1 specifically; the title mentions both \u03b1- and \u03b2-neurexins but gene-level assignment is not shown [PMID:32434929]. The UniProt entry Q9ULB1 notes an interaction with CLSTN3 [DB:UniProt Q9ULB1]. The paper notes direct binding had been debated [PMID:32434929].","key_references":[{"PMID":"32434929","why":"\u03b2-neurexin LNS domain binds Clstn3; SS4-dependent synaptogenic activity"}],"covers":["LR002354","LR005634"]},"LR002358":{"pair":"CLU -> LRP8","headline":"Clusterin binds ApoER2 and triggers a Reelin-like signal; one abstract-only paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Clusterin binds ApoER2 (LRP8) and VLDLR and is internalized by cells expressing either; binding triggers a Reelin-like signal in Dab1-expressing cells, inducing Dab1 phosphorylation and activation of PI3K/Akt and n-cofilin [PMID:24381170]. Agonist-like.","molecular_requirements":"Dab1 is needed for the signal in the described cells; either receptor alone was sufficient for internalization [PMID:24381170].","affinity_potency":[],"species_and_systems":"Species not specified in the dossier abstract; cell lines and subventricular zone explants [PMID:24381170]. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"Clusterin is flagged secreted [flag]; present in the subventricular zone where Reelin is absent [PMID:24381170], so paracrine.","caveats":"Abstract only; affinity not reported. UniProt records the interaction citing the same paper [DB:UniProt P10909]. Because both pairs rely on one paper, they are not independent.","key_references":[{"PMID":"24381170","why":"Clusterin binds ApoER2/VLDLR and activates the Reelin pathway"}],"covers":["LR002358","LR005638"]},"LR003816":{"pair":"CNTN2 -> CNTNAP2","headline":"Direct, specific CNTN2-CNTNAP2 ectodomain binding with low nanomolar affinity, plus mouse knockout evidence.","interaction_type":"direct binding","direction_and_effect":"CNTNAP2 and CNTN2 ectodomains bind directly and specifically, with low nanomolar affinity [PMID:27621318]. Association of TAG-1 with Caspr2 is essential for juxtaparanodal organisation [PMID:12975355].","molecular_requirements":"Ectodomains are sufficient for binding [PMID:27621318]. CNTNAP2 domain architecture is mapped by electron microscopy [PMID:27621318].","affinity_potency":[],"species_and_systems":"Human ectodomains [PMID:27621318]; TAG-1 knockout mice [PMID:12975355]. Mouse pair inferred from human.","localisation_and_range":"CNTN2 flagged secreted [flag]; in axons the proteins act at juxtaparanodes [PMID:12975355].","caveats":"Both papers abstract-only; affinity is stated only as 'low nanomolar' with no exact value in our evidence.","key_references":[{"PMID":"27621318","why":"Direct ectodomain binding, low nanomolar"},{"PMID":"12975355","why":"In vivo requirement at juxtaparanodes"}],"covers":["LR000310","LR003816"]},"LR002367":{"pair":"CNTN2 -> NCAM1","headline":"No curator-confirmed paper; only a Reactome complex record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence; Reactome lists an NCAM1-Contactin-2 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Species not stated beyond human and mouse entities.","localisation_and_range":"CNTN2 flagged secreted; NCAM1 flagged secreted and transmembrane [flag].","caveats":"Eight judged papers were all abstract_insufficient; support is a database assertion only.","key_references":[],"covers":["LR002367","LR005647"]},"LR001755":{"pair":"CNTN6 -> NOTCH1","headline":"CNTN6 (NB-3) is reported to activate Notch signalling in oligodendrocyte lineage cells; functional evidence from one abstract, no binding data.","interaction_type":"functional only","direction_and_effect":"NB-3 (the curator's name for CNTN6) acts as a Notch ligand: it triggers nuclear translocation of the Notch intracellular domain, promotes oligodendrogliogenesis and differentiation via Deltex1, and raises myelin-associated glycoprotein transcripts [PMID:15082708]. Effect labelled agonist.","molecular_requirements":"Not reported in our evidence beyond Deltex1 acting downstream [PMID:15082708].","affinity_potency":[],"species_and_systems":"Progenitor and oligodendrocyte cultures; species labelled human by the curator, but the abstract does not name the species [PMID:15082708].","localisation_and_range":"CNTN6 is annotated non-secreted and NOTCH1 transmembrane [flag].","caveats":"Abstract-only; direct physical binding of CNTN6 to NOTCH1 is not shown in our evidence. This is a non-canonical Notch ligand claim from a single study [PMID:15082708]. The pair is ortholog-inferred in both species.","key_references":[{"PMID":"15082708","why":"NB-3 activating Notch signalling in oligodendrocyte generation"}],"covers":["LR001755","LR005113"]},"LR005652":{"pair":"CNTN6 -> PTPRG","headline":"Direct structural evidence that PTPRG binds CNTN6; one abstract-level paper, with a co-crystal only for mouse CNTN4.","interaction_type":"direct binding","direction_and_effect":"Crystal structures show the carbonic-anhydrase-like domain of PTPRG interacts directly with the second and third Ig repeats of contactins; PTPRG binds CNTN3, 4, 5 and 6, whereas PTPRZ binds only CNTN1 [PMID:20133774]. The effect on signalling is not reported in our evidence.","molecular_requirements":"Binding uses the PTPRG carbonic-anhydrase-like domain and the contactin Ig repeats 2-3 region; the binding site is conserved among CNTN3, 4, 5 and 6 [PMID:20133774].","affinity_potency":[],"species_and_systems":"Crystal structures used mouse CNTN4 (four N-terminal Ig repeats) with mouse PTPRG carbonic-anhydrase-like domain; the specificity result covers the CNTN family [PMID:20133774]. Curator species labels are human for this pair.","localisation_and_range":"CNTN6 and PTPRG are both annotated non-secreted [flag].","caveats":"Abstract-only read. The co-crystal structure is for CNTN4-PTPRG; CNTN6 binding is stated in the abstract as a specificity result, with no detail on assay or affinity in our evidence [PMID:20133774].","key_references":[{"PMID":"20133774","why":"Crystal structures and contactin specificity of PTPRG"}],"covers":["LR002372","LR005652"]},"LR002376":{"pair":"COL11A2 -> DDR2","headline":"Support is indirect: a paper on collagen type XI with no chain identification, plus IntAct records for the pair.","interaction_type":"functional only","direction_and_effect":"DDR2 mediated high-affinity binding of cancer-associated fibroblasts to collagen type XI [PMID:36233024].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"CAFs; species not reported in our evidence [PMID:36233024]. IntAct records cite surface plasmon resonance and NMR from PMID 17703188, which is not among the judged papers [DB:IntAct P13942-Q16832].","localisation_and_range":"COL11A2 is annotated secreted and not transmembrane [flag].","caveats":"The curated paper refers to collagen type XI generally, not COL11A2; the IntAct records are the only pair-specific support and their paper is not in our judged set [PMID:36233024][DB:IntAct P13942-Q16832].","key_references":[{"PMID":"36233024","why":"Collagen XI binding to DDR2 in CAFs (chain not specified)"}],"covers":["LR002376","LR005655"]},"LR003825":{"pair":"COL18A1 -> ITGA5","headline":"Endostatin, a collagen XVIII fragment, binds alpha5beta1 integrin on human endothelial cells; two abstract-read papers.","interaction_type":"direct binding","direction_and_effect":"Recombinant human endostatin interacts with alpha5 and alphaV integrins on human endothelial cells; immobilised endostatin supports survival and migration, whereas soluble endostatin inhibits integrin-dependent migration [PMID:11158588]. Human endostatin competes with fibronectin and RGD cyclic peptide for alpha5beta1 binding and inhibits endothelial migration, not proliferation [PMID:12682293].","molecular_requirements":"The binder is the alpha5beta1 heterodimer; the receptor entry names ITGA5 alone [PMID:12682293]. Ligand is endostatin, the proteolytic C-terminal fragment of collagen XVIII, not intact COL18A1 [PMID:11158588].","affinity_potency":[],"species_and_systems":"Human endostatin and human endothelial cells; both papers read as abstracts only [PMID:11158588] [PMID:12682293]. BioGRID and IntAct list COL18A1-ITGB1 records [DB:BioGRID] [DB:IntAct].","localisation_and_range":"Ligand is a secreted proteolytic fragment (paracrine/autocrine); receptor is membrane-bound.","caveats":"Immobilised and soluble endostatin have opposite functional effects [PMID:11158588]. Both papers read as abstracts only. No affinity reported.","key_references":[{"PMID":"11158588","why":"Endostatin interacts with alpha5 and alphaV integrins on human endothelial cells"},{"PMID":"12682293","why":"Endostatin competes with RGD peptide to bind alpha5beta1"}],"covers":["LR000319","LR003825"]},"LR005661":{"pair":"COL18A1 -> ITGAV","headline":"Mixed: one abstract-read paper reports endostatin interacting with alphaV integrins; another reports alpha5beta1 only.","interaction_type":"conflicting","direction_and_effect":"Recombinant human endostatin interacts with alpha5 and alphaV integrins on human endothelial cells; soluble endostatin inhibits integrin-dependent migration [PMID:11158588].","molecular_requirements":"Which alphaV beta partner is not resolved; the entity is annotated as integrin alphaVbeta3 [flag]. Ligand is endostatin, the collagen XVIII fragment, not intact COL18A1 [PMID:11158588].","affinity_potency":[],"species_and_systems":"Human endothelial cells, human endostatin; abstract only [PMID:11158588].","localisation_and_range":"Ligand is a secreted fragment; receptor is membrane-bound.","caveats":"Conflicting: a second paper states human endostatin activity is mediated by alpha5beta1 and that alphaVbeta3 is used by tumstatin, and it was judged pair_absent [PMID:12682293]. The positive paper is an abstract-only read. No affinity.","key_references":[{"PMID":"11158588","why":"Endostatin interacts with alpha5 and alphaV integrins"},{"PMID":"12682293","why":"Negative: alphaVbeta3 attributed to tumstatin, endostatin to alpha5beta1"}],"covers":["LR002382","LR005661"]},"LR003834":{"pair":"COL1A1 -> ITGAV","headline":"One abstract-level paper: an alphav-containing complex on neuroblastoma cells mediates binding to type I collagen.","interaction_type":"direct binding","direction_and_effect":"An alphav-beta complex mediates binding to fibronectin and type I collagen in human neuroblastoma cells [PMID:1693626]. Annotated effect is stimulatory.","molecular_requirements":"The complex named in the abstract is alphav with a novel beta1-related subunit ('beta n'), not beta3; alphavbeta3 is reported to bind vitronectin [PMID:1693626]. ITGAV is annotated as integrin alphaVbeta3 [flag], which does not match.","affinity_potency":[],"species_and_systems":"Human neuroblastoma cell lines [PMID:1693626].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract excerpt only (full text listed available). The collagen-binding complex is alphav-beta n, not alphavbeta3. No database support.","key_references":[{"PMID":"1693626","why":"alphav-containing integrin binds type I collagen on neuroblastoma cells"}],"covers":["LR000328","LR003834"]},"LR002385":{"pair":"COL1A1 -> OSCAR","headline":"OSCAR is reported as a collagen receptor costimulating osteoclastogenesis; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"OSCAR is a collagen receptor that costimulates osteoclastogenesis in DAP12-deficient humans and mice; recorded as agonist [PMID:21841309].","molecular_requirements":"OSCAR signals through ITAM-containing adaptors (FcR gamma, DAP12 named in the abstract) [PMID:21841309]; the specific requirement for this pair is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse osteoclast differentiation cells [PMID:21841309].","localisation_and_range":"COL1A1 is flagged secreted and not transmembrane [flag]; type I collagen is an extracellular matrix ligand, so signalling is by cell contact with matrix (inferred from the flag; not stated in the papers read).","caveats":"Abstract only. A collagen assay cannot separate COL1A1 from COL1A2. The evidence sentence does not itself state binding. No database support.","key_references":[{"PMID":"21841309","why":"OSCAR identified as collagen receptor"}],"covers":["LR002385","LR005664"]},"LR003843":{"pair":"COL2A1 -> ITGA10","headline":"Alpha10 was isolated from chondrocytes by collagen II affinity purification and cloned; strong binding evidence for the beta1 partnered chain, abstract-read.","interaction_type":"direct binding","direction_and_effect":"A novel collagen type II-binding integrin alpha subunit was isolated from bovine chondrocytes by collagen II affinity purification; the human alpha10 was cloned from a chondrocyte library [PMID:9685391]. Direction: collagen to integrin; 'Stimulatory' label in dossier [flag].","molecular_requirements":"Alpha10 is described as a new member of the beta1-integrin family, so ITGB1 pairing is expected; whether alpha10 alone binds is not reported in our evidence [PMID:9685391].","affinity_potency":[],"species_and_systems":"Bovine chondrocytes for purification, human cDNA for sequence [PMID:9685391]; mouse pair is ortholog-inferred.","localisation_and_range":"Matrix ligand, cell-surface receptor (flags); contact signalling inferred.","caveats":"Abstract read only; no affinity reported. Two further papers were abstract-insufficient.","key_references":[{"PMID":"9685391","why":"Alpha10 purified on collagen II and cloned"}],"covers":["LR000337","LR003843"]},"LR005670":{"pair":"COL3A1 -> ADGRG1","headline":"Collagen III was identified as the ligand of GPR56 (ADGRG1) with matching mouse knockout phenotypes; also supported by UniProt.","interaction_type":"direct binding","direction_and_effect":"COL3A1 was identified as the GPR56 ligand by an in vitro biotinylation/proteomics approach; Col3a1-null mice show cortical overmigration similar to Gpr56-null mice, and collagen III inhibited neural migration in vitro via GPR56 [PMID:21768377]. GPR56 couples to Galpha(12/13) and activates RhoA on ligand binding. Curator label: antagonist (migration inhibition).","molecular_requirements":"Not reported in our evidence beyond GPR56 coupling to Galpha(12/13).","affinity_potency":[],"species_and_systems":"Mouse knockouts and in vitro assays; curators record human ligand and receptor [PMID:21768377]. Pair projected to human and mouse.","localisation_and_range":"COL3A1 flagged secreted; ADGRG1 flagged both secreted and transmembrane [flag]; matrix contact inferred.","caveats":"Abstract read only. UniProt states interaction with COL3A1 and role in cortical development [DB:UniProt]. One review-only and one pending paper not shown.","key_references":[{"PMID":"21768377","why":"Col3a1 identified as GPR56 ligand"}],"covers":["LR002391","LR005670"]},"LR002394":{"pair":"COL3A1 -> OSCAR","headline":"Collagen binding to OSCAR reported in human and mouse; support is one abstract-only paper, not chain-specific.","interaction_type":"direct binding","direction_and_effect":"OSCAR is described as a receptor that binds specific motifs within fibrillar collagens and costimulates osteoclastogenesis; the curator labels the effect agonist [PMID:21841309].","molecular_requirements":"OSCAR is described as FcRgamma-associated (ITAM adaptor) [PMID:21841309]. Whether COL3A1 specifically is the binding chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human and mouse samples were both used (DAP12-deficient humans and mice), so the mouse pair is not only a projection [PMID:21841309].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only. The paper speaks of fibrillar collagens as a class; the curator notes a collagen-binding assay cannot separate individual chains [PMID:21841309].","key_references":[{"PMID":"21841309","why":"OSCAR binds fibrillar collagen motifs and costimulates osteoclastogenesis"}],"covers":["LR002394","LR005673"]},"LR003852":{"pair":"COL4A1 -> ITGB1","headline":"Alpha1beta1 integrin recognition of collagen IV mapped structurally; ITGB1 stands for the heterodimer.","interaction_type":"direct binding","direction_and_effect":"A collagen IV fragment binds integrin alpha1beta1, and altering Arg(461) of alpha2(IV) and Asp(461) of alpha1(IV) abolished binding [PMID:8223488]. Database effect label is stimulatory.","molecular_requirements":"ITGB1 acts as the partner of alpha1 (alpha1beta1); both collagen chains contribute residues [PMID:8223488].","affinity_potency":[],"species_and_systems":"Purified type IV collagen fragments; species not stated in our evidence [PMID:8223488].","localisation_and_range":"Ligand is flagged secreted, not transmembrane [flag]; as a collagen it is a matrix ligand, but this is not shown by the cited papers.","caveats":"Abstract only; the paper concerns alpha1beta1, so ITGB1 alone is not shown to be sufficient. No affinity reported. Two other papers were abstract_insufficient.","key_references":[{"PMID":"8223488","why":"Maps alpha1beta1 recognition site on collagen IV"}],"covers":["LR000346","LR003852"]},"LR005706":{"pair":"COL8A2 -> SLC4A11","headline":"SLC4A11 extracellular loop 3 was reported to interact with COL8A2 by mass spectrometry; matrix-adhesion context.","interaction_type":"direct binding","direction_and_effect":"A GST fusion protein of SLC4A11-EL3 interacts with COL8A2, identified by mass spectrometry; the abstract states a direct interaction [PMID:31691803]. An anti-EL3 antibody suppressed cell adhesion, identifying EL3 as the Descemet's membrane binding site [PMID:31691803].","molecular_requirements":"EL3 of SLC4A11 is required for binding [PMID:31691803].","affinity_potency":[],"species_and_systems":"SLC4A11-transfected HEK293 cells and primary human corneal endothelial cells; mouse pair is ortholog-inferred [PMID:31691803].","localisation_and_range":"Ligand flagged secreted [flag]; COL8A2 is a principal Descemet's membrane protein, so matrix adhesion [PMID:31691803].","caveats":"Abstract only for this pair; identification is by mass spectrometry, no affinity reported. Receptor is a solute transporter whose signaling-receptor role is not established in our evidence.","key_references":[{"PMID":"31691803","why":"SLC4A11-EL3 interacts with COL8A2 and mediates cell adhesion"}],"covers":["LR002427","LR005706"]},"LR003870":{"pair":"COLQ -> MUSK","headline":"Single abstract-level report of ColQ binding MuSK at the neuromuscular junction; part of a proposed ternary complex.","interaction_type":"direct binding","direction_and_effect":"ColQ binds MuSK by cross-linking/immunoprecipitation and transfection of MuSK constructs; the authors propose MuSK helps anchor acetylcholinesterase (AChE) at the synapse. Effect on MuSK signalling is not reported in our evidence [PMID:15159418].","molecular_requirements":"ColQ clustering needs two heparin-binding sites in its collagen domain and its COOH terminus; a ColQ-perlecan-MuSK ternary complex is proposed, so this is not a simple pairwise interaction [PMID:15159418].","affinity_potency":[],"species_and_systems":"Cross-linking and immunoprecipitation in Torpedo postsynaptic membranes, plus MuSK constructs in MuSK-deficient myotubes or COS-7 cells; the curation lists human for both partners, and the mouse pair is ortholog-inferred [PMID:15159418].","localisation_and_range":"ColQ carries a secreted flag and is anchored in the synaptic basal lamina per the paper [flag][PMID:15159418].","caveats":"Only one paper, read as abstract-based; described by the authors as the first evidence of ColQ-MuSK binding; no affinity reported.","key_references":[{"PMID":"15159418","why":"First evidence that ColQ binds MuSK; ternary complex with perlecan proposed"}],"covers":["LR000364","LR003870"]},"LR000369":{"pair":"CORT -> SSTR3","headline":"Cortistatin binds SSTR3 with high affinity in two recombinant-receptor binding papers, plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"Human cortistatin-17 bound all human SSTR subtypes much like rat CST-14 and inhibited forskolin-induced cAMP production through SSTRs [PMID:9125122]. [125I]Tyr10-CST bound all five receptors with high affinity and no marked selectivity versus somatostatin [PMID:9650799]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"pKd 10.06","assay":"[125I]Tyr10-CST radioligand binding","system":"human sst3 stably expressed in CCL39 cells","cite":"PMID:9650799"},{"value":"pKi 8.7-9.9","assay":"GtoPdb full agonist","system":"not reported","cite":"PMID:15333679"}],"species_and_systems":"Human receptors in CCL39 cells [PMID:9650799]; human peptide on human SSTRs [PMID:9125122]; mouse pair ortholog-inferred.","localisation_and_range":"CORT secreted and SSTR3 transmembrane by flags [flag].","caveats":"Abstract-level reads; pan-SSTR binding, so not subtype-specific, and the radioligand is an iodinated CST14 analogue [PMID:9650799]. BioGRID also lists the pair [DB:BioGRID].","key_references":[{"PMID":"9650799","why":"Binding of cortistatin to all five human SSTRs, pKd values"},{"PMID":"9125122","why":"Human cortistatin binds all SSTR subtypes and lowers cAMP"}],"covers":["LR000369","LR003875"]},"LR005715":{"pair":"CRIPTO -> CDON","headline":"Cripto (TDGF1) binds the CDON ectodomain in pull-downs; one full-text paper, mouse genetics with HEK293T binding assays.","interaction_type":"direct binding","direction_and_effect":"CDON-Fc interacted efficiently with TDGF1-AP, similar to its interaction with SHH-N-AP [PMID:32876567]. Interaction was reported alongside genetic interaction of Cdon with Tdgf1 in ethanol-induced holoprosencephaly [PMID:32876567].","molecular_requirements":"CDON-Fc did not bind the negative control CD164-AP and interacted only weakly with AP-tagged ALK4, ActRIIA and ActRIIB [PMID:32876567]. Co-receptor role in Nodal signalling is proposed in this paper.","affinity_potency":[],"species_and_systems":"Ectodomain pull-downs in HEK293T cells; the study is a mouse model [PMID:32876567]. Human pair is as listed; the mouse pair is inferred.","localisation_and_range":"CRIPTO is flagged secreted [flag]; the CDON ectodomain was used as a secreted fusion in vitro [PMID:32876567].","caveats":"Single paper. Ectodomain pull-down does not show signalling direction; CDON is a co-receptor rather than a classic receptor. No affinity reported.","key_references":[{"PMID":"32876567","why":"Pull-downs show CDON and LRP2 bind TDGF1"}],"covers":["LR002436","LR005715"]},"LR004824":{"pair":"CRIPTO -> GPC1","headline":"Cripto-1 binds Glypican-1 and signals through c-Src independently of Nodal and ALK4; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"CR-1 specifically binds Glypican-1 and activates c-Src, triggering MAPK and Akt signalling [PMID:12649175]. Active Src was required for CR-1-induced transformation and migration of mouse mammary epithelial cells [PMID:12649175].","molecular_requirements":"Signalling is independent of Nodal and ALK4 [PMID:12649175]. Glypican-1 is a membrane-associated heparan sulfate proteoglycan, so it is a co-receptor rather than a signalling receptor on its own.","affinity_potency":[],"species_and_systems":"Mouse mammary epithelial cells with human CR-1 [PMID:12649175]. IntAct lists a co-immunoprecipitation record [DB:IntAct].","localisation_and_range":"CRIPTO is flagged secreted and GPC1 flagged secreted and receptor [flag]; GPC1 is described as membrane-associated [PMID:12649175].","caveats":"Single paper read as abstract only; no affinity reported. The mouse pair is inferred from human.","key_references":[{"PMID":"12649175","why":"CR-1 binds Glypican-1 and activates c-Src"}],"covers":["LR001429","LR004824"]},"LR002439":{"pair":"CRLF1 -> IL6ST","headline":"CRLF1 to IL6ST (gp130) is a downstream member of the CLC/CLF-CNTFR complex; direct CRLF1-gp130 binding is not shown.","interaction_type":"functional only","direction_and_effect":"CLC/CLF activated JAK1, JAK2 and TYK2, causing tyrosine phosphorylation of gp130 and LIFR in human neuroblastoma cells [PMID:11294841]. gp130 is a signalling chain of the CNTF receptor complex [PMID:10966616]. GtoPdb lists an agonist record [DB:GtoPdb].","molecular_requirements":"Signalling needs the composite CLC/CLF ligand, the membrane-bound form of CNTFR alpha, and gp130 with LIFR [PMID:11294841, PMID:10966616].","affinity_potency":[],"species_and_systems":"Human neuroblastoma cells [PMID:11294841]; mouse system [PMID:10966616]. Mouse pair is inferred.","localisation_and_range":"CRLF1 is flagged secreted [flag].","caveats":"Both papers read as abstracts only. The phosphorylation is a downstream effect of the complex engaging CNTFR, not evidence of direct CRLF1-gp130 binding. Treat as a complex member.","key_references":[{"PMID":"11294841","why":"CLC/CLF activates JAKs and gp130/LIFR phosphorylation"},{"PMID":"10966616","why":"Defines the CLC/CLF ligand and receptor chains"}],"covers":["LR002439","LR005718"]},"LR000378":{"pair":"CSF2 -> SDC2","headline":"GM-CSF was reported to bind syndecan-2 on osteoblasts; one abstract-read paper, a proteoglycan co-receptor rather than a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"Biotinylated recombinant human GM-CSF was found to bind syndecan-2; syndecan-2 and GM-CSF co-localised by immuno-EM, and antisense knockdown abolished mitogenic activity [PMID:10734053].","molecular_requirements":"Syndecan-2 co-immunoprecipitated with the GM-CSF receptor alpha chain, suggesting it works alongside the receptor, not instead of it [PMID:10734053].","affinity_potency":[],"species_and_systems":"Human primary osteoblasts, recombinant human GM-CSF [PMID:10734053]. Mouse pair is ortholog-inferred.","localisation_and_range":"Receptor is annotated transmembrane and non-secreted [flag]; heparan sulfate proteoglycan at the cell surface per the paper [PMID:10734053].","caveats":"Single paper, abstract only. SDC2 is a proteoglycan co-receptor, so effect on the cell depends on GM-CSF receptor alpha; BioGRID records the same study as a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"10734053","why":"GM-CSF binding to syndecan-2 in osteoblasts"}],"covers":["LR000378","LR003884"]},"LR002448":{"pair":"CSPG4 -> ITGB1","headline":"CSPG4 (NG2) forms a complex with alpha3beta1 on endothelial cells; one abstract-read paper, agonist effect.","interaction_type":"direct binding","direction_and_effect":"Soluble NG2 stimulates endothelial motility and angiogenesis; signal transduction is through alpha3beta1, so NG2 acts as an agonist [PMID:15181153].","molecular_requirements":"NG2, galectin-3 and alpha3beta1 form a ternary complex; galectin-3 potentiates but alpha3beta1 transduces the signal [PMID:15181153]. ITGB1 is evidenced only as part of alpha3beta1.","affinity_potency":[],"species_and_systems":"Curator labels list mouse as the experimental species; the human and mouse pairs are ortholog-inferred [PMID:15181153].","localisation_and_range":"CSPG4 flagged secreted and transmembrane [flag]; soluble NG2 acted on the endothelial surface [PMID:15181153].","caveats":"Abstract-only single paper; complex formation, not pairwise NG2-ITGB1 binding.","key_references":[{"PMID":"15181153","why":"NG2 engages alpha3beta1 integrin and galectin-3 on endothelial cells"}],"covers":["LR002448","LR005724"]},"LR005724":{"pair":"CSPG4 -> ITGB1","headline":"CSPG4 (NG2) forms a complex with alpha3beta1 on endothelial cells; one abstract-read paper, agonist effect.","interaction_type":"direct binding","direction_and_effect":"Soluble NG2 stimulates endothelial motility and angiogenesis; signal transduction is through alpha3beta1, so NG2 acts as an agonist [PMID:15181153].","molecular_requirements":"NG2, galectin-3 and alpha3beta1 form a ternary complex; galectin-3 potentiates but alpha3beta1 transduces the signal [PMID:15181153]. ITGB1 is evidenced only as part of alpha3beta1.","affinity_potency":[],"species_and_systems":"Curator labels list mouse as the experimental species; the human and mouse pairs are ortholog-inferred [PMID:15181153].","localisation_and_range":"CSPG4 flagged secreted and transmembrane [flag]; soluble NG2 acted on the endothelial surface [PMID:15181153].","caveats":"Abstract-only single paper; complex formation, not pairwise NG2-ITGB1 binding.","key_references":[{"PMID":"15181153","why":"NG2 engages alpha3beta1 integrin and galectin-3 on endothelial cells"}],"covers":["LR002448","LR005724"]},"LR001764":{"pair":"CX3CL1 -> ITGAV","headline":"Direct, high-affinity binding of the CX3CL1 chemokine domain to integrin alphavbeta3, supported by two papers from one group plus database records.","interaction_type":"direct binding","direction_and_effect":"FKN-CD directly bound alpha(v)beta(3) at K(D) of 3.0 \u00d7 10(-10) M in 1 mM Mn(2+) [PMID:23125415]. FKN-CD activated recombinant soluble alphavbeta3 in cell-free conditions and on CX3CR1-negative K562 and CHO cells, whereas the integrin-binding-defective mutant K36E/R37E did not, so activation can occur without CX3CR1 [PMID:24789099]. UniProt lists ITGAV:ITGB3 as a co-receptor in CX3CR1-dependent signalling [DB:UniProt].","molecular_requirements":"The functional unit is alphav with beta3 (alphavbeta3). A ternary complex of integrin, FKN-CD and CX3CR1 is critical for CX3CR1 signalling and integrin activation; a docked second site (site 2) is proposed for CX3CR1-independent activation [PMID:24789099]. Mutations K36E/R37E reduce integrin binding while the CX3CR1-binding residue R47A did not [PMID:23125415].","affinity_potency":[{"value":"Kd 0.3 nM","assay":"direct binding, ELISA-type; reported as K(D) 3.0 \u00d7 10(-10) M, 1 mM Mn(2+)","system":"human FKN-CD with recombinant soluble alphavbeta3","cite":"PMID:23125415"}],"species_and_systems":"Human ligand and human receptor; recombinant proteins, K562 and CHO transfectants, U937 cells. Mouse pair ortholog-inferred. IntAct lists co-IP, ELISA and pull-down records [DB:IntAct].","localisation_and_range":"Ligand flagged secreted and transmembrane [flag]; paper reports membrane-bound fractalkine also bound alpha(v)beta(3) [PMID:23125415].","caveats":"Both papers come from the same research group and the key binding result rests on recombinant protein; docking models guide the site assignments. Authors say the result contradicts earlier work [PMID:23125415]. In one text passage, a blocking antibody and cyclic RGDfV did not effectively block adhesion (data not shown) [PMID:23125415].","key_references":[{"PMID":"23125415","why":"Direct binding with sub-nanomolar K(D) and co-receptor model"},{"PMID":"24789099","why":"CX3CR1-independent integrin activation by FKN-CD"}],"covers":["LR001764","LR005122"]},"LR002457":{"pair":"CXCL10 -> ACKR2","headline":"CXCL10 is reported as a strong agonist of ACKR2 in beta-arrestin recruitment assays; one full-text study.","interaction_type":"functional only","direction_and_effect":"CXCL10 induced beta-arrestin recruitment to ACKR2 and was identified as a new strong agonist; ACKR2 internalised CXCL10 and reduced its extracellular availability, consistent with a scavenger role [PMID:33801414].","molecular_requirements":"DPP4 (CD26) N-terminal processing drastically reduced CXCL10 activity toward ACKR2, so the intact N-terminus matters [PMID:33801414].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, cell-based NanoBiT/NanoBRET assays [PMID:33801414]. Mouse pair is listed in the dossier, not tested here.","localisation_and_range":"CXCL10 is flagged secreted and ACKR2 transmembrane [flag].","caveats":"Functional readout only; no direct binding affinity is reported in our evidence. Single paper.","key_references":[{"PMID":"33801414","why":"CXCL10 as ACKR2 agonist and scavenged ligand"}],"covers":["LR002457","LR005733"]},"LR005733":{"pair":"CXCL10 -> ACKR2","headline":"CXCL10 is reported as a strong agonist of ACKR2 in beta-arrestin recruitment assays; one full-text study.","interaction_type":"functional only","direction_and_effect":"CXCL10 induced beta-arrestin recruitment to ACKR2 and was identified as a new strong agonist; ACKR2 internalised CXCL10 and reduced its extracellular availability, consistent with a scavenger role [PMID:33801414].","molecular_requirements":"DPP4 (CD26) N-terminal processing drastically reduced CXCL10 activity toward ACKR2, so the intact N-terminus matters [PMID:33801414].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, cell-based NanoBiT/NanoBRET assays [PMID:33801414]. Mouse pair is listed in the dossier, not tested here.","localisation_and_range":"CXCL10 is flagged secreted and ACKR2 transmembrane [flag].","caveats":"Functional readout only; no direct binding affinity is reported in our evidence. Single paper.","key_references":[{"PMID":"33801414","why":"CXCL10 as ACKR2 agonist and scavenged ligand"}],"covers":["LR002457","LR005733"]},"LR000396":{"pair":"CXCL11 -> CCR3","headline":"CXCL11 acts as a natural antagonist of CCR3 in human cells; binding competition and functional inhibition, abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"I-TAC/CXCL11, Mig and IP10 compete with eotaxin for binding to CCR3-bearing cells and inhibit eotaxin-induced migration and Ca2+ changes; none induced CCR3 internalisation, so they are pure antagonists, not agonists [PMID:11110785]. A second paper restates CXCL11 as a potent natural CCR3 antagonist as background [PMID:15178708]. GtoPdb records the interaction as an antagonist [DB:GtoPdb]. Inhibitory effect on CCR3 signalling.","molecular_requirements":"Not reported in our evidence. A hybrid with the eight N-terminal residues of I-TAC placed on eotaxin bound CCR3 with higher affinity than I-TAC [PMID:11110785].","affinity_potency":[],"species_and_systems":"Human ligand and human receptor, CCR3-bearing cells [PMID:11110785].","localisation_and_range":"CXCL11 flagged secreted, CCR3 transmembrane [flag]; paracrine.","caveats":"Both papers read as abstracts only; the second cites the CCR3 antagonism as background, not as its own result [PMID:15178708]. No affinity numbers reported.","key_references":[{"PMID":"11110785","why":"Primary report of CXCL11 competition and inhibition at CCR3"}],"covers":["LR000396"]},"LR007173":{"pair":"CXCL11 -> DPP4","headline":"No verified paper evidence; only an IntAct enzymatic-study record, consistent with protease cleavage rather than receptor signalling.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. The only record is an IntAct enzymatic study between the two proteins [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; no experimental system shown in the dossier.","localisation_and_range":"CXCL11 flagged secreted, DPP4 transmembrane [flag].","caveats":"Judged papers were abstract_insufficient or review_only, none confirmed. An enzymatic-study record does not itself show receptor-ligand signalling.","key_references":[],"covers":["LR007173"]},"LR003906":{"pair":"CXCL12 -> CXCR4","headline":"Canonical, extensively supported agonist interaction with direct binding, signalling and structures; nanomolar affinities reported in several human systems.","interaction_type":"direct binding","direction_and_effect":"SDF-1 was identified as the natural ligand of LESTR/fusin, renamed CXCR4, inducing Ca2+ and chemotaxis in transfected cells [PMID:8752280, PMID:8752281]. Binding and signalling were confirmed in T cell lines (chemotaxis, Ca2+ rise, internalisation) [PMID:9551924], and chemotaxis in HUVEC was blocked by anti-CXCR4 [PMID:10233851]. GtoPdb lists it as agonist [DB:GtoPdb]. HMGB1 forms a heterocomplex with CXCL12 that signals only via CXCR4 [PMID:22370717].","molecular_requirements":"The CXCL12 N-terminal 9 residues are sufficient for activation; the dimer of 1-9 was active and a 1-9[P2G] dimer was an antagonist [PMID:9712844]. CXCR4 can heteromerise with ChemR23, with negative binding cooperativity [PMID:23469143]. A single chain is enough; no co-receptor is required in the evidence.","affinity_potency":[{"value":"Kd 1.23 nM","assay":"125I-SDF-1alpha competitive binding, Scatchard","system":"HUVEC","cite":"PMID:10233851"},{"value":"Kd between 5 and 10 nM","assay":"Scatchard of SDF-1alpha binding","system":"human T cell lines","cite":"PMID:9551924"},{"value":"pIC50 9.3","assay":"125I-CXCL12 competition binding","system":"hCXCR4 in HEK293T membranes","cite":"PMID:30476826"},{"value":"half-maximal chemoattractant activity 5 nM","assay":"chemotaxis of native SDF-1","system":"T lymphocytes/CEM cells","cite":"PMID:9712844"},{"value":"pKd 7.7-8.2","assay":"GtoPdb affinity range","system":"curated database","cite":"PMID:9551924"}],"species_and_systems":"Mostly human ligand and receptor in primary cells and cell lines; some experiments used mouse cells (3T3, bone marrow) [PMID:22370717]. Human and mouse pairs are listed.","localisation_and_range":"CXCL12 is flagged secreted and CXCR4 transmembrane [flag]; acts on cells as a soluble chemokine.","caveats":"Several papers are abstract-only. Four rows are functional (survival, migration, heteromer) rather than binding. PDB structures exist (e.g. 2K03, 8K3Z) [DB:PDB 2K03]. CXCR4 and ACKR3 are both receptors for CXCL12 per UniProt [DB:UniProt].","key_references":[{"PMID":"8752281","why":"De-orphanisation of CXCR4 by SDF-1"},{"PMID":"9551924","why":"Kd, signalling, internalisation in T cells"},{"PMID":"30476826","why":"Radioligand competition on hCXCR4 (pIC50 9.3)"}],"covers":["LR000401","LR003906"]},"LR002466":{"pair":"CXCL13 -> ACKR5","headline":"CXCL13 binds GPR182 (ACKR5) with nanomolar affinity and is scavenged by it; supported by two papers including knockout-mouse data.","interaction_type":"direct binding","direction_and_effect":"GPR182 binds CXCL13 with nanomolar affinity but binding did not induce typical Gq/Gi signalling or beta-arrestin recruitment; the receptor internalises ligand-independently, so it acts as an atypical scavenger [PMID:33875597]. GPR182-deficient mice had more than 10-fold higher plasma CXCL13 [PMID:33875597] and a 3.5-fold increase in serum CXCL13 [PMID:37554323]. CXCL13 is reported as bound and efficiently scavenged by GPR182 [PMID:37554323].","molecular_requirements":"Beta-arrestins are required for ligand-independent internalisation and scavenging; the C-terminus is in part dispensable [PMID:37554323]. One receptor chain only, no complex partner reported.","affinity_potency":[{"value":"Kd 20 nM","assay":"competition binding, human GPR182 with hCXCL13","system":"GPR182-expressing cells (Table 1B)","cite":"PMID:37554323"},{"value":"Kd 9 nM","assay":"competition scavenging, human GPR182 with hCXCL13","system":"GPR182-expressing cells (Table 1B)","cite":"PMID:37554323"}],"species_and_systems":"Human and murine chemokines were tested on human and mouse GPR182 in cell lines, with similar affinities across species [PMID:33875597]; in vivo data come from GPR182-knockout mice [PMID:33875597][PMID:37554323]. GPR182 is expressed in endothelial cells of most organs, mainly sinusoidal and lymphatic vessels [PMID:33875597].","localisation_and_range":"Soluble chemokine cleared from plasma and tissue interstitium by an endothelial receptor [PMID:33875597][PMID:37554323]; CXCL13 flagged secreted [flag].","caveats":"Both papers were read as abstracts by the curators, with full text excerpts available. Binding does not lead to canonical signalling, so this is scavenging rather than activation. UniProt records the same scavenger role [DB:UniProt].","key_references":[{"PMID":"33875597","why":"Identifies GPR182 as atypical receptor binding CXCL13 with nanomolar affinity; knockout raises plasma CXCL13"},{"PMID":"37554323","why":"Kd and scavenging values for CXCL13; GPR182 as sole scavenger of CXCL13 among ACKRs"}],"covers":["LR002466"]},"LR005742":{"pair":"CXCL17 -> CXCR4","headline":"One 2024 BRET study reports CXCL17 as a low-potency, GAG-dependent inhibitor of CXCR4; no second source.","interaction_type":"functional only","direction_and_effect":"CXCL17 produced no agonist response at CCR1-10 or CXCR1-3, 5 and 6, but inhibited CXCL12-mediated CXCR4 Gi and beta-arrestin-2 responses and competed for CXCL12 binding [PMID:38502733]. It also decreased the basal beta-arrestin-2 BRET, indicating inhibition of constitutive CXCR4 activity [PMID:38502733].","molecular_requirements":"Inhibition of ligand binding occurred only in intact cells, mimicked by GAG binders surfen and protamine sulfate; disrupting putative GAG binding domains in CXCL17 prevented CXCR4 binding, implying a GAG-containing accessory protein [PMID:38502733].","affinity_potency":[{"value":"pIC50 6.93 \u00b1 0.28","assay":"inhibition of CXCL12 Gi BRET response","system":"HEK293 cells","cite":"PMID:38502733"},{"value":"pKi = 6.25 \u00b1 0.19","assay":"NanoBRET competition with CXCL12-AF647","system":"HEK293 cells with Nluc/CXCR4","cite":"PMID:38502733"},{"value":"pIC50 = 7.24 \u00b1 0.08","assay":"decrease of basal CXCR4/beta-arrestin2 BRET","system":"HEK293 cells","cite":"PMID:38502733"}],"species_and_systems":"Recombinant human-labelled pair in HEK293, Cos-7 and HeLa cells; species of the proteins not stated in our excerpts [PMID:38502733].","localisation_and_range":"CXCL17 flagged secreted [flag]; mucosal chemokine per the abstract [PMID:38502733].","caveats":"Single abstract/excerpt-based paper. Low potency compared with AMD3100 (pIC50 = 7.52 \u00b1 0.03). Not shown in purified membranes. No in vivo data. No database record.","key_references":[{"PMID":"38502733","why":"BRET evidence that CXCL17 inhibits CXCR4 signalling and ligand binding"}],"covers":["LR002468","LR005742"]},"LR003915":{"pair":"CXCL9 -> CCR3","headline":"CXCL9 (Mig) acts as an antagonist of CCR3, binding and blocking eotaxin responses, not activating it; abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Antagonist. Mig, I-TAC and IP10 competed for eotaxin binding to CCR3-bearing cells and inhibited eotaxin-induced migration and Ca2+ changes; none of the three induced CCR3 internalisation, so they act as pure antagonists [PMID:11110785]. GtoPdb lists an antagonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human chemokines on CCR3-bearing cells; human experiment species per curators [PMID:11110785]. Mouse pair is ortholog-inferred.","localisation_and_range":"Secreted ligand, transmembrane receptor [flag].","caveats":"Abstract-only reads. No affinity for CXCL9 at CCR3 is reported in our evidence. The paper's abstract names I-TAC, Mig and IP10 together, so CXCL9-specific numbers are not reported. One additional paper was review-only.","key_references":[{"PMID":"11110785","why":"CXCR3 agonists compete with eotaxin at CCR3, pure antagonists"}],"covers":["LR000418","LR003915"]},"LR001773":{"pair":"CYTL1 -> CCR2","headline":"CYTL1 is reported as a functional CCR2 (CCR2B) agonist, with binding, chemotaxis and knockout evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"Agonist: CYTL1 chemoattracts monocytes and macrophages through CCR2B and the ERK pathway; pertussis toxin sensitivity indicates Gi-coupled signalling [PMID:27084102].","molecular_requirements":"CCR2B is the receptor isoform tested; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CYTL1 and CCR2B in HEK293 cells (chemotaxis, internalization, radioactive binding); human monocytes responded but PBLs did not. Human and mouse recombinant CYTL1 attracted wild-type but not Ccr2-/- mouse macrophages [PMID:27084102].","localisation_and_range":"CYTL1 is flagged as secreted [flag]; CCR2 is flagged as a transmembrane receptor [flag]. Signalling is therefore paracrine/endocrine by annotation.","caveats":"Single paper, read as abstract only; no affinity value reported in our evidence.","key_references":[{"PMID":"27084102","why":"Binding, chemotaxis and Ccr2-/- macrophage evidence for CYTL1-CCR2B"}],"covers":["LR001773","LR005130"]},"LR002475":{"pair":"DAG1 -> NRXN1","headline":"Alpha-dystroglycan binds neurexin-1alpha directly with defined domains; binding requires LARGE glycans; one paper.","interaction_type":"direct binding","direction_and_effect":"alphaDAG binding at LNS2 prevents neuroligin binding at LNS6 (steric hindrance), and its binding is mutually exclusive with neurexophilin-1 [PMID:25157101].","molecular_requirements":"alphaDAG binds both LNS2 and LNS6 of Nrxn1alpha independent of splice inserts SS#2/SS#4, mostly via LARGE-dependent glycans on the mucin region; unglycosylated alphaDAG does not bind. Mutating the laminin-binding Thr-315/Thr-317 region did not reduce complex formation [PMID:25157101].","affinity_potency":[],"species_and_systems":"LARGE-modified recombinant alphaDAG pulled down alpha-neurexin from mouse brain lysate [PMID:25157101]. Curator record lists human; both human and mouse pairs are ortholog-projected.","localisation_and_range":"Neurexin-1 is flagged transmembrane [flag]; dystroglycan is flagged secreted and transmembrane [flag]. Trans-synaptic contact is implied by the paper's synapse context [PMID:25157101].","caveats":"Abstract plus excerpts only. Reactome lists a Dystroglycan:NRXN1 complex [DB:Reactome R-HSA-2426312]. Effect is blocking of neuroligin, not signalling.","key_references":[{"PMID":"25157101","why":"Domain mapping, LARGE glycan dependence, neuroligin exclusion"}],"covers":["LR002475","LR005749"]},"LR005751":{"pair":"DAG1 -> NRXN3","headline":"Neurexin-3 splice variants that bind dystroglycan enable inhibitory synapse function; functional evidence from one abstract.","interaction_type":"functional only","direction_and_effect":"Neurexin-3 splice variants mediating binding to dystroglycan enable inhibitory synapse function in rescue experiments in Neurexin-3 conditional knockout mice; a minimal dystroglycan-binding fragment sustains this [PMID:36997523].","molecular_requirements":"Splice-variant dependent; no other subunits reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse conditional knockout rescue [PMID:36997523]. The human pair is ortholog-projected.","localisation_and_range":"Neurexin-3 is flagged transmembrane [flag]; dystroglycan is flagged secreted and transmembrane [flag].","caveats":"Abstract only. Physical binding is not shown in this paper in our evidence. One further review-only row not shown.","key_references":[{"PMID":"36997523","why":"Neurexin-3 dystroglycan-binding variants rescue inhibitory synapse function"}],"covers":["LR002477","LR005751"]},"LR003924":{"pair":"DCN -> MET","headline":"Decorin binds Met directly with high affinity and drives Met degradation; one paper with excerpts.","interaction_type":"direct binding","direction_and_effect":"Antagonist overall: transient Met activation, c-Cbl recruitment and rapid Met degradation, suppression of beta-catenin and of Met-mediated migration and growth [PMID:19433454].","molecular_requirements":"Not reported in our evidence beyond Met itself.","affinity_potency":[{"value":"Kd~1.5 nM","assay":"direct binding, displaced by HGF","system":"decorin-Met","cite":"PMID:19433454"}],"species_and_systems":"Human HeLa cells (100 nM recombinant decorin) with phospho-RTK arrays [PMID:19433454]. Mouse pair is ortholog-projected.","localisation_and_range":"Decorin flagged secreted; MET transmembrane receptor [flag].","caveats":"Single paper; also displaced less efficiently by internalin B. BioGRID records affinity capture and reconstituted complex [DB:BioGRID 677024]. One abstract-insufficient row not shown.","key_references":[{"PMID":"19433454","why":"High-affinity Met binding and degradation"}],"covers":["LR000427","LR003924"]},"LR002484":{"pair":"DEFB4A -> CCR2","headline":"Fc-fused human beta-defensin 2 binds CCR2 and induces chemotaxis; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"hBD2:Ig bound CCR2-transfected HEK293 cells, induced CCR2-specific chemotaxis of HEK293 cells and human monocytes, and CCR2-deficient mouse cells failed to migrate toward it; CCL2/MCP-1 preincubation abolished hBD-induced migration and hBD2:Ig inhibited MCP-1 migration [PMID:20483750]. Curators label this agonist [PMID:20483750]. Reactome lists a bound complex [DB:Reactome].","molecular_requirements":"Not reported in our evidence; the ligand is a fusion protein in the key study, with no subunit or co-receptor requirement tested.","affinity_potency":[],"species_and_systems":"Human beta-defensin 2 and 3 Fc fusion proteins (hBD2:Ig, hBD3:Ig) and their mouse orthologs bound human CCR2 in HEK293 cells and acted on human monocytes and CCR2-deficient versus wild-type mouse peritoneal exudate cells [PMID:20483750]. Mouse orthologs bound human or mouse CCR2 [PMID:20483750].","localisation_and_range":"Ligand is flagged secreted [flag]; no range data in our evidence, so paracrine action is implied by the flag only.","caveats":"Single paper; the paper names hBD2 and does not distinguish the DEFB4A and DEFB4B loci, and Reactome cites the same paper [DB:Reactome]. Ligand is an Ig-Fc fusion. No Kd reported.","key_references":[{"PMID":"20483750","why":"hBD2/3 Ig fusions bind CCR2 and induce chemotaxis"}],"covers":["LR002484"]},"LR003933":{"pair":"DKK1 -> KREMEN2","headline":"Direct high-affinity binding reported for Kremen2, with a ternary complex with LRP6; mainly one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Kremen2 is a high-affinity Dkk1 receptor that cooperates with Dkk1 to block Wnt/beta-catenin signalling [PMID:12050670].","molecular_requirements":"Kremen2 forms a ternary complex with Dkk1 and LRP6 and induces rapid endocytosis and removal of LRP6 from the plasma membrane [PMID:12050670]. Reactome lists a KRM:DKK:LRP5/6 complex at the plasma membrane [DB:Reactome R-HSA-3769399].","affinity_potency":[],"species_and_systems":"Species not stated in the abstract; the human pair is ortholog-inferred and the mouse pair is not [PMID:12050670].","localisation_and_range":"KREMEN2 is flagged as a receptor [flag].","caveats":"Abstract only; no affinity value in our evidence. One further row is pending.","key_references":[{"PMID":"12050670","why":"Kremen1/2 are high-affinity Dkk1 receptors; Kremen2-Dkk1-LRP6 ternary complex"}],"covers":["LR000441","LR003933"]},"LR003942":{"pair":"DLL1 -> NOTCH3","headline":"DLL1 directly binds soluble Notch3 and signals through mouse Notch3; two verified papers.","interaction_type":"direct binding","direction_and_effect":"Delta1 directly bound soluble Notch3 extracellular fusion protein in solid-phase assays with different affinities, in a Ca2+-dependent manner [PMID:11006133]. Murine Notch3 signals in response to Delta 1 and Jagged 1 [PMID:12482954]; the paper's evidence is about the R142C CADASIL mutant signalling as well as wild-type.","molecular_requirements":"Notch3 extracellular domain suffices for binding in the fusion assay [PMID:11006133]. Further subunit requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human fusion proteins [PMID:11006133]; stable cell lines expressing murine Notch 3 [PMID:12482954]. BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"Membrane-bound ligand; DLL1 flagged secreted and transmembrane [flag].","caveats":"Both abstract-only. Species not recorded for PMID:12482954. Three abstract-insufficient, one review-only and one pending paper not shown. No affinity numbers in our evidence.","key_references":[{"PMID":"11006133","why":"Direct binding of Delta1 to soluble Notch3"},{"PMID":"12482954","why":"Murine Notch3 signals in response to Delta 1"}],"covers":["LR000450","LR003942"]},"LR005760":{"pair":"DMP1 -> ITGAV","headline":"Supported by an abstract-only human cell study showing DMP1 signalling via alphaVbeta3 integrin; chain-level evidence.","interaction_type":"functional only","direction_and_effect":"DMP1 acts via alphaVbeta3 integrin: it stimulates focal adhesion kinase phosphorylation, activates ERK and JNK, and the effect is blocked by anti-alphaVbeta3 antibody [PMID:21642437]. Direction is agonist.","molecular_requirements":"The alphaVbeta3 heterodimer is the implicated receptor; the paper does not resolve which chain contacts DMP1 [PMID:21642437].","affinity_potency":[],"species_and_systems":"Human mesenchymal stem cells and osteoblast-like cells [PMID:21642437].","localisation_and_range":"DMP1 annotated secreted [flag]; an extracellular matrix protein signalling via the cell surface [PMID:21642437].","caveats":"Abstract only. Evidence rests on an antibody block of the heterodimer, not a binding assay, so the ITGAV chain-specific contribution is not shown. Another paper is also counted as confirmed but not shown.","key_references":[{"PMID":"21642437","why":"DMP1 signals via alphaVbeta3 integrin in human cells"}],"covers":["LR002492","LR005760"]},"LR002493":{"pair":"DMP1 -> ITGB3","headline":"Supported by the same abstract-only study as ITGAV: DMP1 engages alphaVbeta3 integrin and activates FAK.","interaction_type":"functional only","direction_and_effect":"DMP1 interacts with alphaVbeta3 integrin and stimulates focal adhesion kinase phosphorylation; the effect is blocked by anti-alphaVbeta3 antibody [PMID:21642437].","molecular_requirements":"The paper implicates the alphaVbeta3 heterodimer; the chain-specific role of beta3 is not resolved [PMID:21642437].","affinity_potency":[],"species_and_systems":"Human mesenchymal stem cells and osteoblast-like cells [PMID:21642437].","localisation_and_range":"DMP1 annotated secreted [flag].","caveats":"Abstract only; antibody blockade, not binding. Same paper supports the ITGAV pair, so these are not independent.","key_references":[{"PMID":"21642437","why":"DMP1 signals via alphaVbeta3 integrin"}],"covers":["LR002493","LR005761"]},"LR001782":{"pair":"DNAJB11 -> PRTG","headline":"One abstract-only paper identifies ERdj3 (DNAJB11) as a putative PRTG ligand that antagonises neuronal differentiation.","interaction_type":"functional only","direction_and_effect":"ERdj3 was identified as a putative PRTG ligand by yeast two-hybrid screening and an in situ binding assay; purified ERdj3 reduced neurogenesis in P19 cells, an effect blocked by anti-PRTG antibody or purified PRTG ectodomain [PMID:20335479]. Forced ERdj3 expression in chick neural tube impaired neuronal differentiation [PMID:20335479].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"P19 embryonal carcinoma cells, chick neural tube, mouse embryo PRTG expression; the dossier labels experiment species as human [PMID:20335479].","localisation_and_range":"DNAJB11 annotated secreted [flag]; the paper describes it as normally ER-resident and acting extracellularly here.","caveats":"Described as 'putative'. Abstract only; no affinity. The only evidence is from one group.","key_references":[{"PMID":"20335479","why":"Identifies ERdj3 as a PRTG ligand"}],"covers":["LR001782","LR005138"]},"LR005139":{"pair":"Dsc1 -> Dsg1a","headline":"Mouse pair projected from human data; SPR on human ectodomains showed heterophilic Dsg-Dsc binding.","interaction_type":"direct binding","direction_and_effect":"All experiments passing a Dsg over a Dsc surface, or the reverse, showed binding responses indicative of strong heterophilic interaction [PMID:27298358].","molecular_requirements":"Not reported in our evidence beyond ectodomain use.","affinity_potency":[{"value":"KD 3.6-43.9 uM","assay":"SPR (Biacore T100), all pairwise human Dsg/Dsc combinations; range across pairs, not specific to this pair","system":"human ectodomains","cite":"PMID:27298358"}],"species_and_systems":"Experiments used human proteins; the mouse pair is ortholog-inferred [PMID:27298358].","localisation_and_range":"Not annotated for the mouse entities in our evidence; adhesive cadherin binding [PMID:27298358].","caveats":"Browser-read full text, with the curator noting the quote is unverifiable and spot-check pending. Affinity is a range across all pairs. No mouse experiments.","key_references":[{"PMID":"27298358","why":"SPR of human Dsc/Dsg ectodomains"}],"covers":["LR005139"]},"LR001791":{"pair":"DSC3 -> DSG1","headline":"DSC3 -> DSG1: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (IntAct), which are not independent of the evidence above. [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001791"]},"LR005148":{"pair":"DSC3 -> DSG2","headline":"DSC3 -> DSG2: heterophilic desmosomal cadherin binding, supported by a single family-wide paper.","interaction_type":"direct binding","direction_and_effect":"The paper reports that all desmogleins form adhesive dimers with all desmocollins, with affinities characteristic of each Dsg:Dsc pair, so this pair is covered by the family-wise heterophilic result [PMID:27298358]. Binding is trans-cellular and heterodimers are called the fundamental adhesive unit of desmosomes [PMID:27298358].","molecular_requirements":"Ectodomains of one Dsg and one Dsc are sufficient for dimer formation in the reported solution biophysics and bead aggregation; binding uses a strand-swap mechanism with charge-based heterophilic preference [PMID:27298358]. No further subunits or co-receptors reported.","affinity_potency":[],"species_and_systems":"Experiments used human proteins (solution biophysics, SPR and coated-bead aggregation) [PMID:27298358]. Pair is recorded for: human, mouse (ortholog-projected). The mouse entry is projected from human evidence.","localisation_and_range":"Membrane-bound desmosomal cadherins acting in trans between adjacent cells (juxtacrine/contact) [PMID:27298358]; entity flags mark both as receptors and transmembrane where set [flag].","caveats":"Curators read only the abstract; the paper's family-wide statement is applied to this pair, one of 25 companion rows, and no pair-specific affinity is in our dossier. The crystal structures cited cover Dsg2, Dsg3, Dsc1 and Dsc2 only [PMID:27298358]. Database records also exist (IntAct), which are not independent of the evidence above. [DB:IntAct]","key_references":[{"PMID":"27298358","why":"Family-wise Dsg:Dsc heterophilic binding by biophysics, SPR, bead aggregation and crystal structures"}],"covers":["LR001792","LR005148"]},"LR007290":{"pair":"EBI3:IL27 -> IL27RA:IL6ST","headline":"IL-27 signals via IL27RA with gp130; binding to IL27RA alone does not signal.","interaction_type":"functional only","direction_and_effect":"IL-27 bound WSX-1, but this was insufficient to mediate cellular effects without gp130 in reconstituted cells [PMID:14764690]. GtoPdb lists agonist actions [DB:GtoPdb].","molecular_requirements":"Both IL27RA and IL6ST are needed for signalling [PMID:14764690]. Structures with IL27RA and EBI3 chains exist [DB:PDB 7U7N]; UniProt: IL6ST engages site 3 of IL27 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; cells reconstituted with WSX-1 with or without gp130; abstract only.","localisation_and_range":"Ligand flagged as a secreted complex [flag].","caveats":"Abstract-only for the confirming paper; two further papers were review_only.","key_references":[{"PMID":"14764690","why":"IL-27 needs WSX-1 plus gp130"}],"covers":["LR007290"]},"LR000459":{"pair":"EDIL3 -> ITGAV","headline":"EDIL3 acts through integrin alphaVbeta3 in endothelial and VSMC assays; ITGAV alone is not isolated.","interaction_type":"functional only","direction_and_effect":"Del1 promoted alphavbeta3-dependent endothelial attachment and migration, blocked by an anti-alphavbeta3 antibody; an RGD-to-RAD mutant was inactive [PMID:10196194]. Del1 mediates VSMC adhesion, migration and proliferation via alpha(v)beta(3) [PMID:11959660].","molecular_requirements":"The receptor is the alphaVbeta3 heterodimer; this row records the alphaV chain only [PMID:10196194]. RGD motif required.","affinity_potency":[],"species_and_systems":"Human Del1 on chicken CAM (primary cells) [PMID:10196194]; VSMC adhesion assays [PMID:11959660].","localisation_and_range":"Del1 described as an extracellular matrix protein [PMID:10196194].","caveats":"Both papers abstract only; no binding measurement.","key_references":[{"PMID":"10196194","why":"Del1 RGD-dependent alphavbeta3 adhesion and angiogenesis"},{"PMID":"11959660","why":"Del1 acts on VSMC via alpha(v)beta(3)"}],"covers":["LR000459","LR003950"]},"LR003951":{"pair":"EDN1 -> EDNRA","headline":"Well supported: ET-1 binds and activates ETA (EDNRA), shown by binding, displacement and functional assays.","interaction_type":"direct binding","direction_and_effect":"ET-1 acts as agonist at ETA: radioligand binding in human cells [PMID:10770212], 125I-ET-1 displacement on cloned ETAR in COS cells [PMID:8440682], constriction in human vessels [PMID:7647976], and secretion in rat adrenal [PMID:9082970].","molecular_requirements":"ET-1 binds both ETA and ETB, whereas ET-3 prefers ETB; ETA is blocked by BQ-123 [PMID:9082970][PMID:8440682]. A single receptor chain is involved.","affinity_potency":[{"value":"EC50 5.7 nM","assay":"vessel constriction dose-response (stated for ET-2 as equipotent with ET-1)","system":"human coronary artery","cite":"PMID:7647976"},{"value":"pIC50 7.8-8.5","assay":"GtoPdb affinity","system":"not reported","cite":"DB:GtoPdb"}],"species_and_systems":"Human cells and vessels; cloned receptor in COS cells; the adrenal study used rat tissue; the mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond ET-1 being a ligand for GPCRs [DB:UniProt].","caveats":"All papers abstract only. ETA site density 16,500 sites/cell in FNC-B4 cells [PMID:10770212]; the EC50 is given for ET-2 in comparison with ET-1.","key_references":[{"PMID":"10770212","why":"Radioligand binding to ETA in human cells"},{"PMID":"8440682","why":"125I-ET-1 displacement on cloned ETAR"},{"PMID":"7647976","why":"Human vessel pharmacology via ETA"}],"covers":["LR000460","LR003951"]},"LR000468":{"pair":"EFNA1 -> EPHA2","headline":"Ephrin-A1 is a well-supported ligand of EPHA2 with binding, structural, and cell evidence.","interaction_type":"direct binding","direction_and_effect":"Soluble EphA2-Fc bound strongly to cells expressing ephrin-A1a but only weakly to the ephrin-A1b isoform [PMID:14692877]; in mouse ESCs, EFNA1 activation of EPHA2 supports pluripotency and restrains ERK1/2 [PMID:32170114]; EphA2 is tyrosine-phosphorylated in xenograft vasculature, presumably via ephrin-A1 [PMID:11146556]. Stimulatory.","molecular_requirements":"Splice isoform matters: ephrin-A1a binds strongly, ephrin-A1b weakly [PMID:14692877]. EPHA2 pTyr in ESCs depends on EFN ligand, and RSK-driven serine/threonine phosphorylation of EPHA2 blunts the response [PMID:32170114].","affinity_potency":[{"value":"apparent KD in Fig. 1 (value not given)","assay":"ELISA, biotinylated ephrin Fc on immobilised Eph Fc","system":"not specified","cite":"PMID:22568954"}],"species_and_systems":"Human cells [PMID:14692877][PMID:11146556]; mouse ESCs, full text read [PMID:32170114]. Mouse pair is ortholog-inferred. Co-immunoprecipitation, ITC-type and structures are listed: PDB 3CZU, 3HEI, 3MBW [DB:PDB 3CZU]; BioGRID and IntAct records [DB:BioGRID][DB:IntAct].","localisation_and_range":"EFNA1 annotated secreted and transmembrane, EPHA2 transmembrane [flag]; the papers show cell-surface ligand on adjacent cells (EFNA1-expressing cells stimulating EPHA2 cells) [PMID:32170114].","caveats":"Ephrin-A1 binds EphA2 better than ephrin-A4 or ephrin-A5 in one ELISA [PMID:22568954]; no KD number is reported in the excerpt. Several papers read as abstracts only.","key_references":[{"PMID":"32170114","why":"EFNA1 activation of EPHA2 in mouse ESCs"},{"PMID":"14692877","why":"isoform-dependent EphA2-Fc binding"},{"PMID":"22568954","why":"ephrin-A1 Fc binds EphA2 best among ephrin-As"}],"covers":["LR000468","LR003959"]},"LR003960":{"pair":"EFNA1 -> EPHA3","headline":"Database-asserted only: BioGRID and UniProt list EFNA1 as an EPHA3 ligand; no papers judged.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA1 acts as a ligand for EPHA3 inhibiting epithelial-to-mesenchymal transition of cardiac cells [DB:UniProt PMID:12794130]; a BioGRID reconstituted complex is recorded [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the supporting experiments not reported in our evidence; human pair is ortholog-inferred, mouse is not.","localisation_and_range":"Annotations flag EFNA1 secreted and transmembrane and EPHA3 secreted [flag]; no paper text on localisation.","caveats":"No curated paper evidence for this pair; support is database-only.","key_references":[],"covers":["LR000469","LR003960"]},"LR000477":{"pair":"EFNA2 -> EPHA3","headline":"Ephrin-A2 and EphA3 are reported as a receptor pair; one rat axon-guidance paper and a UniProt note.","interaction_type":"functional only","direction_and_effect":"Soluble ephrin-A2 and ephrin-A5 at nanomolar concentrations abolished repulsive axon-guidance activity; soluble EphA3 extracellular domain did likewise, whereas EphB3 did not [PMID:9751130]. UniProt lists EPHA3 among binders [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat retinal ganglion cell axons in vitro stripe assay [PMID:9751130].","localisation_and_range":"EFNA2 annotated transmembrane, not secreted; EPHA3 secreted and transmembrane [flag].","caveats":"The paper shows competition of repulsive activity, not direct binding; read as abstract only. Binding ligand-receptor specificity is stated as background (EphA3 is a receptor for ephrin-A2 and ephrin-A5).","key_references":[{"PMID":"9751130","why":"soluble ephrin-A2/EphA3 block axon repulsion"}],"covers":["LR000477","LR003968"]},"LR000486":{"pair":"EFNA3 -> EPHA4","headline":"Ephrin-A3 signals through EphA4 in mouse hippocampus, but binds EphA4 more weakly than other Eph receptors.","interaction_type":"direct binding","direction_and_effect":"Activation of EphA4 by ephrin-A3 induced dendritic spine retraction in adult mouse hippocampal slices; inhibiting the interaction distorted spine shape [PMID:12496762]. Ephrin-A3 binds EphA4 more weakly than other Eph receptors [PMID:22568954].","molecular_requirements":"Not reported beyond the pair; kinase-inactive EphA4 was used in slices [PMID:12496762].","affinity_potency":[],"species_and_systems":"Mouse hippocampal slices and EphA4 knockout mice [PMID:12496762]; ELISA plus pull-down from mouse hippocampus [PMID:22568954]. The human pair is ortholog-inferred.","localisation_and_range":"Both are flagged membrane-bound [flag]; ephrin-A3 is on astrocytic processes and EphA4 on spines, so signalling is glia-to-neuron contact [PMID:12496762].","caveats":"Binding strength is lower than for other Eph receptors [PMID:22568954]; that paper was a browser read with an unverifiable quote. 12496762 was read as an abstract only.","key_references":[{"PMID":"12496762","why":"Ephrin-A3 activates EphA4 to retract spines in mouse hippocampus"},{"PMID":"22568954","why":"Relative binding of ephrin-A3 to Eph receptors"}],"covers":["LR000486","LR003977"]},"LR002529":{"pair":"EGFL7 -> NOTCH3","headline":"Secreted EGFL7 binds human NOTCH3 by co-IP and acts as a Notch antagonist; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Secreted EGFL7 binds a Notch region involved in ligand-mediated activation and acts as an antagonist of Notch signalling; EGFL7 expression in neural stem cells decreased Notch-specific signalling [PMID:19503073].","molecular_requirements":"Not reported in our evidence beyond Notch receptors binding EGFL7 via EGF-like domains; control receptors with EGF-like domains did not interact [PMID:19503073].","affinity_potency":[],"species_and_systems":"Endogenous human NOTCH3 co-immunoprecipitated recombinant human EGFL7 in cell lines; tagged proteins in HEK293 cells [PMID:19503073]. BioGRID lists a two-hybrid record [DB:BioGRID].","localisation_and_range":"EGFL7 is secreted [flag] and the Notch receptor is transmembrane [flag]; binding was retained with the two proteins on apposing cells [PMID:19503073].","caveats":"One paper supports all three Notch paralogs, and this row has no independent confirmation. No affinity reported in our evidence.","key_references":[{"PMID":"19503073","why":"EGFL7 binds Notch1-4 and antagonises Notch signalling"}],"covers":["LR002529","LR005797"]},"LR005157":{"pair":"ENAM -> CD63","headline":"Enamelin binds the CD63 extracellular region (residues 103-205) in one abstract-only paper; direct binding, thinly supported.","interaction_type":"direct binding","direction_and_effect":"Enamelin interacts with the CD63 region of residues 103-205, as do amelogenin and ameloblastin; the paper proposes this mediates endocytosis of secreted enamel matrix proteins [PMID:17708745]. Agonist/antagonist effect: not reported in our evidence.","molecular_requirements":"CD63 residues 103-205 (predicted within the EC2 domain) are the binding region [PMID:17708745]. Co-receptors or subunits: not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and human receptor are recorded as the experiment species [PMID:17708745]; the mouse pair is ortholog-inferred. The abstract does not state the assay system.","localisation_and_range":"ENAM is flagged secreted and CD63 as a receptor [flag]; the paper describes secreted matrix proteins meeting membrane-bound CD63 at ameloblast secretory surfaces [PMID:17708745].","caveats":"One paper, read as abstract only; the abstract is mostly about amelogenin and mentions enamelin briefly. No affinity data. CD63 is a membrane protein with an endocytic role rather than a classical signalling receptor.","key_references":[{"PMID":"17708745","why":"Maps CD63 103-205 interaction with enamel matrix proteins including enamelin"}],"covers":["LR001801","LR005157"]},"LR008523":{"pair":"ENPP1 -> INSR","headline":"ENPP1 (PC-1) coimmunoprecipitates with the insulin receptor and inhibits its signalling, shown in two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"PC-1 inhibits insulin receptor tyrosine kinase activity when overexpressed in MCF-7 cells, and not that of the IGF-I receptor [PMID:10615944]. The Q (GLN121) allele inhibits IR autophosphorylation and downstream signalling more strongly than the K allele [PMID:11289049]. Effect: inhibitory.","molecular_requirements":"Association needs the IR alpha-subunit; PC-1 did not associate with an alpha-subunit mutant lacking region 485-599 [PMID:10615944]. PC-1 was not associated with the IGF-I receptor [PMID:10615944].","affinity_potency":[],"species_and_systems":"Human MCF-7 cells; the inhibition was also seen in mouse R-/hIR and human HEK 293 cells [PMID:11289049]. Overexpression/transfection systems.","localisation_and_range":"ENPP1 is a membrane glycoprotein [PMID:10615944]; the interaction is in-cis on the cell membrane, not a secreted ligand signal.","caveats":"Both papers read as abstract only. Coimmunoprecipitation shows association, and a modulator-of-receptor effect rather than classical ligand binding; ENPP1 is not flagged secreted or receptor. No affinity values.","key_references":[{"PMID":"10615944","why":"PC-1 associates with the IR alpha-subunit and inhibits kinase activity"},{"PMID":"11289049","why":"Q and K PC-1 alleles interact with IR; Q inhibits more"}],"covers":["LR008523"]},"LR005805":{"pair":"EPHA10 -> EFNA3","headline":"EPHA10-EFNA3 rests only on a UniProt function statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 binds EFNA3, EFNA4 and EFNA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EPHA10 is flagged secreted in our annotation [flag], unusual for an Eph receptor; EFNA3 flags are non-secreted transmembrane [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; support is a single database sentence. No affinity data.","key_references":[],"covers":["LR002537","LR005805"]},"LR002538":{"pair":"EPHA10 -> EFNA4","headline":"EPHA10-EFNA4 rests only on a UniProt function statement; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EPHA10 binds EFNA3, EFNA4 and EFNA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"EPHA10 is flagged secreted in our annotation [flag], unusual for an Eph receptor; EFNA4 flags are secreted and transmembrane [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Two review-only rows; support is a single database sentence. No affinity data.","key_references":[],"covers":["LR002538","LR005806"]},"LR005814":{"pair":"EPHA3 -> EFNA2","headline":"EPHA3-EFNA2 rests on one UniProt sentence; no verified papers.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states EFNA2 binds EPHA3, EPHA4 and EPHA5 [DB:UniProt]. Effect: not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence; the mouse pair is non-inferred and the human pair ortholog-inferred.","localisation_and_range":"EPHA3 is flagged secreted, EFNA2 non-secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Four judged rows were review-only or abstract-insufficient. Single database statement, no affinity data.","key_references":[],"covers":["LR002546","LR005814"]},"LR002547":{"pair":"EPHA3 -> EFNA3","headline":"EPHA3-EFNA3: one abstract-only colorectal cancer paper reports binding and reverse signalling; BioGRID reconstituted complex.","interaction_type":"direct binding","direction_and_effect":"EphA3 was confirmed to bind EFNA3 by co-immunoprecipitation in CRC cells, and EphA3/EFNA3 reverse signalling (into the EFNA3 cell) promoted EMT through ERK1/2 and metastasis [PMID:40928719]. BioGRID lists a reconstituted complex [DB:BioGRID].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Colorectal cancer cells and nude-mouse models were used in the paper [PMID:40928719]; species of the cells is not stated in the abstract we hold. Human and mouse pairs are both ortholog-inferred.","localisation_and_range":"EPHA3 is flagged secreted, EFNA3 non-secreted [flag].","caveats":"One paper, abstract only; the ephrin-side (reverse) signalling is a functional claim in cancer cells. No affinity data. Eight other rows were review-only or abstract-insufficient.","key_references":[{"PMID":"40928719","why":"EphA3 binds EFNA3 by co-IP; reverse signalling drives EMT via ERK"}],"covers":["LR002547","LR005815"]},"LR005823":{"pair":"EPHA4 -> EFNB2","headline":"EPHA4-EFNB2 is supported by crystal structure, NMR and UniProt records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the EphA4-ephrinB2 complex is recorded [DB:PDB 2WO2]; IntAct lists x-ray crystallography and NMR [DB:IntAct]. UniProt states EFNB2 binds EPHA4, EPHA3 and EPHB4 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiment species not reported in our evidence.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity data. Cross-subclass (A receptor, B ephrin) binding.","key_references":[],"covers":["LR002555","LR005823"]},"LR002556":{"pair":"EPHA4 -> EFNB3","headline":"EPHA4-EFNB3 is supported by a crystal structure and BioGRID/IntAct records; no verified papers.","interaction_type":"direct binding","direction_and_effect":"A crystal structure of the human EphA4 ectodomain with human ephrinB3 is recorded [DB:PDB 4BKF]; BioGRID lists a reconstituted complex [DB:BioGRID]; IntAct lists ELISA and coimmunoprecipitation associations [DB:IntAct]. UniProt states EphA4 is highly promiscuous [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins in PDB 4BKF [DB:PDB 4BKF]; both pair versions are ortholog-inferred.","localisation_and_range":"Neither partner is flagged secreted [flag]. The pair is oriented Eph -> ephrin in our records; the evidence describes Eph-ephrin binding without establishing which partner acts as ligand here.","caveats":"Database evidence only; two review-only rows. No affinity values in our dossier.","key_references":[],"covers":["LR002556","LR005824"]},"LR002565":{"pair":"EPHA6 -> EFNA4","headline":"Database-only pair: BioGRID affinity capture-MS and one IntAct co-immunoprecipitation; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"EFNA4 carries both secreted and transmembrane flags [flag]; EPHA6 is receptor-flagged only. Range is unclear from our evidence.","caveats":"No curator-verified paper; support is database records only. Records are an Affinity Capture-MS entry [DB:BioGRID 3648313] and an anti-tag coimmunoprecipitation [DB:IntAct EBI-54500804]; these show association in a cell system, not defined direct binding. Affinity not reported in our evidence.","key_references":[],"covers":["LR002565","LR005833"]},"LR005841":{"pair":"EPHA8 -> EFNA2","headline":"UniProt asserts an EPHA8-EFNA2 interaction; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt (EFNA2 entry) states it interacts with EPHA8 [DB:UniProt]. Effect is not reported. Both partners carry the receptor annotation flag [flag], so ligand/receptor direction is not established by our evidence.","molecular_requirements":"Requirements: not reported in our evidence.","affinity_potency":[],"species_and_systems":"No paper was verified for this pair; species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"Both partners are annotated as transmembrane [flag], so any interaction would be juxtacrine (cell contact); this comes from annotation flags only.","caveats":"No curator-verified paper; support is database records only. Only a UniProt subunit sentence; no assay or affinity in our evidence.","key_references":[],"covers":["LR002573","LR005841"]},"LR002592":{"pair":"EPHB3 -> EFNB2","headline":"EPHB3-hFc binds EFNB2-expressing cells in one henipavirus paper where it served as an expression control; other support is database records.","interaction_type":"direct binding","direction_and_effect":"Soluble EPHB3 (1,210-0.4 nM, fivefold dilution) stained cells expressing EFNB2 or EFNB3 and was used to validate receptor expression; no agonist or antagonist effect was reported [PMID:38426726]. UniProt states forward and reverse signalling through the EFNB2/EPHB3 complex regulate migration and adhesion of cells that tubularize the urethra and septate the cloaca [DB:UniProt].","molecular_requirements":"Not reported beyond the two partners.","affinity_potency":[],"species_and_systems":"Flow cytometry on cell lines expressing EFNB2 or EFNB3 with soluble human-Fc-tagged EPHB3; the species of the cell lines and of EPHB3 is not reported in our excerpts [PMID:38426726].","localisation_and_range":"Both partners transmembrane-flagged [flag]; binding was shown with soluble EPHB3-hFc to cell-surface ephrin [PMID:38426726].","caveats":"The paper's focus is Nipah and related virus receptor-binding proteins; EPHB3 binding is described as a cognate receptor 'previously reported' and was used as a control, with no EPHB3 Kd reported in our excerpts. The Kd values quoted in the excerpts (1.45 nM, 0.34 nM) are for a Hendra virus protein with EFNB3 and EFNB2, not EPHB3. IntAct co-immunoprecipitations also exist [DB:IntAct EBI-21582984], [DB:IntAct EBI-54556805].","key_references":[{"PMID":"38426726","why":"Soluble EPHB3-hFc binding to EFNB2- and EFNB3-expressing cells, used as a validation control in a henipavirus study."}],"covers":["LR002592","LR005860"]},"LR007065":{"pair":"F2 -> ITGA2B:ITGB3","headline":"Prothrombin as an integrin alphaIIbbeta3 ligand rests only on database records.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states that integrin alpha-IIb/beta-3 is a receptor for prothrombin among other ligands [DB:UniProt P08514]. BioGRID lists a reconstituted complex for ITGA2B-F2 [DB:BioGRID 278302].","molecular_requirements":"The heterodimer is the receptor in the UniProt statement [DB:UniProt P08514]; the BioGRID record names only ITGA2B [DB:BioGRID 278302].","affinity_potency":[],"species_and_systems":"Species and system: not reported in our evidence.","localisation_and_range":"Complex is annotated transmembrane [flag].","caveats":"No papers in this dossier; support is from databases only, and effect is not reported in our evidence.","key_references":[],"covers":["LR007065"]},"LR000549":{"pair":"F7 -> F3","headline":"Factor VIIa binds cell-bound tissue factor; well supported by structure and database records.","interaction_type":"direct binding","direction_and_effect":"Association of factor VIIa with cell-bound tissue factor initiates the extrinsic coagulation pathway [PMID:9925787]. Annotation lists the effect as stimulatory.","molecular_requirements":"In the 2.1 A crystal structure, TF-bound VIIa is extended, with its light chain wrapping around the two-domain TF cofactor; the complex was inhibitor-stabilised with a BPTI mutant [PMID:9925787]. Many PDB structures exist [DB:PDB 1DAN] [DB:PDB 1J9C].","affinity_potency":[],"species_and_systems":"Human proteins in the structure [PMID:9925787]; also IntAct X-ray and ELISA records [DB:IntAct P08709-P13726].","localisation_and_range":"Reactome places the complex at the plasma membrane [DB:Reactome R-HSA-140734]; F7 annotated secreted [flag].","caveats":"One paper judged, abstract-only; its structure includes an inhibitor and gives no affinity for F7-F3. TF acts as a cofactor, not a signalling-only receptor.","key_references":[{"PMID":"9925787","why":"2.1 A crystal structure of TF-VIIa-inhibitor complex"}],"covers":["LR000549","LR004040"]},"LR001809":{"pair":"FAM3D -> FPR2","headline":"FAM3D acts as an agonist at FPR2 (and FPR1) in neutrophils; functional evidence from one full-text paper.","interaction_type":"functional only","direction_and_effect":"FAM3D is reported as a dual agonist of FPR1 and FPR2 that induces Mac-1-mediated neutrophil recruitment through FPR-related Gi protein and beta-arrestin signaling [PMID:29853563]. The FPR2 antagonist WRW13 (5 \u03bcmol/L) significantly inhibited FAM3D-induced Mac-1 activation and neutrophil adhesion [PMID:29853563].","molecular_requirements":"The effect depended on both FPR1 and FPR2; inhibiting either one blocked FAM3D-induced Mac-1 activation, and the dual antagonist Boc-PLPLP also blocked it [PMID:29853563]. FPR2 alone is therefore not shown to be sufficient.","affinity_potency":[],"species_and_systems":"Experiments used human neutrophils (flow cytometry, antagonists) and FAM3D-knockout mice with elastase- or CaPO4-induced aneurysm [PMID:29853563]. Mouse pair is listed separately in the dossier, not as an ortholog projection.","localisation_and_range":"FAM3D is flagged secreted; FPR2 is flagged transmembrane receptor [flag]. Endothelial cell-derived FAM3D induced neutrophil recruitment [PMID:29853563].","caveats":"Single paper. No direct binding measurement (no Kd or binding assay) in our evidence; support is antagonist inhibition and signaling readouts. Receptor identity relies on pharmacology and the paper's statement that FPR1 and FPR2 are the functional receptors.","key_references":[{"PMID":"29853563","why":"Full-text study: FAM3D activates neutrophil Mac-1 via FPR1/FPR2, Gi and beta-arrestin signaling."}],"covers":["LR001809","LR005165"]},"LR000558":{"pair":"FBN1 -> ITGA5","headline":"Fibrillin-1 supports adhesion via integrin alpha5 beta1; functional evidence, with affinity stated as low elsewhere.","interaction_type":"functional only","direction_and_effect":"Human dermal fibroblasts adhered to fibrillin-1 fragments and microfibrils via RGD and cations, with strong alpha 5 beta 1 interactions and some alpha v beta 3 contribution [PMID:12807887]. In HUVECs the fibrillin-1 fragment PF14 acted via alpha v beta 3 and alpha 5 beta 1 integrins to raise calcium [PMID:20686071].","molecular_requirements":"The receptor is the alpha5 beta1 heterodimer; an RGD-independent adhesion sequence was also found in fibrillin [PMID:12807887]. UniProt lists ITGA5:ITGB1 as a fibrillin-1 receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human fibroblasts and HUVECs with recombinant fragments or microfibrils [PMID:12807887] [PMID:20686071]. Reactome has a fibrillin-1 integrin binding reaction [DB:Reactome].","localisation_and_range":"FBN1 is flagged secreted and not transmembrane [flag]; microfibrils are matrix structures [PMID:12807887].","caveats":"Both papers abstract only and functional; direct binding is not shown in these two. No affinity reported in our evidence for this pair.","key_references":[{"PMID":"12807887","why":"Fibroblast adhesion to fibrillin-1 via alpha5beta1."},{"PMID":"20686071","why":"Endothelial signaling by fibrillin-1 fragment via alpha5beta1 and alphaVbeta3."}],"covers":["LR000558","LR004049"]},"LR002619":{"pair":"FCER2 -> ITGB2","headline":"CD23 binds CD11b-CD18 and CD11c-CD18 beta2 integrins; evidence is for the heterodimers, not CD18 alone.","interaction_type":"direct binding","direction_and_effect":"Recombinant CD23 liposomes bound COS cells expressing CD11b-CD18 or CD11c-CD18 but not CD11a-CD18, and CD23 increased IL-1 beta, IL-6 and TNF alpha in monocytes [PMID:7621072]. Labelled agonist.","molecular_requirements":"The abstract names CD11b and CD11c, the alpha chains, as the partners; CD18 binding alone is not shown, and CD11a-CD18 (same CD18) did not bind [PMID:7621072]. So ITGB2 is needed with a specific alpha chain.","affinity_potency":[],"species_and_systems":"Human CD23, COS transfectants and monocytes.","localisation_and_range":"CD23 flagged secreted and transmembrane [flag].","caveats":"Abstract-only read. ITGB2 is shared by all beta2 integrins; the specificity lies in the alpha chain. No affinity reported.","key_references":[{"PMID":"7621072","why":"CD23 binding to beta2 integrin complexes"}],"covers":["LR002619"]},"LR005166":{"pair":"Fcer2a -> Cr2","headline":"Mouse pair projected from human data: CD23 binds CD21 (CR2), with SPR and mapping; three papers, all human proteins.","interaction_type":"direct binding","direction_and_effect":"CD23 binds CD21 and IgE simultaneously at distinct sites on the CD23 lectin domain [PMID:16172256]. CD23 is reported as a functional ligand for CD21 [PMID:7515913]. Effect direction recorded as agonist [PMID:7515913].","molecular_requirements":"On CD21 the CD23 site lies in short consensus repeats (SCR) 5-8 with a contribution of SCR 1-2, and depends on N-linked sugar at Asn370 and Asn295 but not Asn492 [PMID:7515913]. Binding does not need calcium [PMID:16172256].","affinity_potency":[{"value":"KD = 8.7 \u00b1 0.9 \u00d7 10\u22127 M","assay":"SPR, derCD23 with CD21(D1-2)","system":"recombinant human proteins","cite":"PMID:16172256"}],"species_and_systems":"All experiments used human proteins; the mouse pair is ortholog-inferred and no mouse experiment is in our evidence. UniProt notes CD21 acts as a ligand for CD23 [DB:UniProt].","localisation_and_range":"Fcer2a is flagged secreted and receptor [flag]; the paper describes CD23 as a type II membrane protein with soluble and membrane forms [PMID:16172256].","caveats":"Two of three papers were read as abstracts only. PMID:16785534 concerns IFN-alpha binding to CR2 and mentions CD23 only as another ligand.","key_references":[{"PMID":"16172256","why":"NMR and SPR of CD23-CD21 binding"},{"PMID":"7515913","why":"maps CD23 site on CD21 SCR 5-8"}],"covers":["LR005166"]},"LR000567":{"pair":"FGA -> ITGAV","headline":"Fibrinogen is recognised by alphaVbeta3 per one paper's background statement; weakest support, with BioGRID peptide record on ITGB3.","interaction_type":"functional only","direction_and_effect":"Fibrinogen is recognised by alphaVbeta3 and alphaIIbbeta3 but not alpha5beta1; recorded as agonist [PMID:15031111].","molecular_requirements":"The receptor is alphaVbeta3 (protein name annotation); the beta3 chain is probably needed. ITGAV alone not tested.","affinity_potency":[],"species_and_systems":"Human fibrinogen on mouse blastocyst trophoblast cells; human interaction is ortholog-inferred [PMID:15031111].","localisation_and_range":"FGA secreted [flag].","caveats":"The cited statement is background from earlier work, not this paper's own result. The BioGRID record is FGA - ITGB3, not ITGAV [DB:BioGRID]. Only paper judged.","key_references":[{"PMID":"15031111","why":"trophoblast outgrowth on fibrinogen"}],"covers":["LR000567"]},"LR004077":{"pair":"FGF1 -> CD44","headline":"Direct cell-surface binding of FGF1 to CD44 from one abstract-read proximity-labelling study; proposed as a reservoir, not a signalling receptor.","interaction_type":"direct binding","direction_and_effect":"An APEX2-FGF1 proximity-labelling screen in RPE1 cells identified CD44 and CSPG4 as FGF1 interactors; FGF1 co-localized with both at the cell surface and binds CD44 through its heparin-binding moiety [PMID:29812912]. They are proposed as storage molecules forming an FGF1 reservoir rather than direct signalling receptors [PMID:29812912].","molecular_requirements":"FGF1 binds via its heparin-binding moiety, and CD44 is a proteoglycan co-receptor-like partner; the method was validated by detecting FGFR4 [PMID:29812912]. Whether a signalling complex forms is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human FGF1 and human RPE1 cells [PMID:29812912]. Mouse record is ortholog-inferred.","localisation_and_range":"FGF1 is flagged secreted and CD44 flagged both secreted and transmembrane [flag]; the paper places the interaction at the cell surface [PMID:29812912].","caveats":"Abstract only; proximity labelling does not prove direct binding strength, no affinity reported. Curated as agonist but the paper frames CD44 as a non-signalling reservoir [PMID:29812912]. No database records.","key_references":[{"PMID":"29812912","why":"APEX2-FGF1 proximity labelling identifies CD44 and CSPG4"}],"covers":["LR000593","LR004077"]},"LR000594":{"pair":"FGF1 -> FGFR1","headline":"Well-supported direct FGF1-FGFR1 binding, with structures, SPR and cell assays; FGF1 activates it, heparan sulfate required in some assays.","interaction_type":"direct binding","direction_and_effect":"FGF1 binds FGFR1 and activates it; in a study of FGFR1 and FGFR4, FGFR1 binds FGF-1 and FGF-2 equally [PMID:10336501]. FGF1 binds FGFR1 directly based on receptor presence and without KLB [PMID:22442730]. UniProt records FGF1 inducing FGFR1 phosphorylation [DB:UniProt]. A kinase-deficient FGFR1 variant binds FGF1 yet gives no autophosphorylation, proposed as a regulatory decoy [PMID:8756477].","molecular_requirements":"Heparan sulfate is a required co-factor for the binding specificity [PMID:10336501]; ternary FGF1-FGFR1c-perlecan heparan sulfate complexes form [PMID:24509440]. KLB is not needed [PMID:22442730]. FGFR1 variant lacking the kinase domain is inactive [PMID:8756477].","affinity_potency":[],"species_and_systems":"Human FGF1 and FGFR1 in recombinant, 293 cell and perlecan systems [PMID:22442730][PMID:24509440]; BaF3 mitogenic assays with species unspecified [PMID:16597617][PMID:8663044]. Human and mouse records both exist.","localisation_and_range":"FGF1 is flagged secreted and FGFR1 a transmembrane receptor [flag]; paracrine ligand, membrane receptor.","caveats":"A phage-display peptide study is indirect [PMID:11032250]. BaF3 papers were browser-read with quotes pending spot-check [PMID:16597617]. Many papers are abstract only. Structures and binding assays exist in databases [DB:PDB 1EVT][DB:PDB 3OJV][DB:BioGRID][DB:IntAct]. Affinity values not shown in our evidence.","key_references":[{"PMID":"22442730","why":"FGF1 binds FGFR1 directly, KLB-independent"},{"PMID":"10336501","why":"FGFR1 binds FGF-1 and FGF-2 equally; heparan sulfate needed"},{"PMID":"24509440","why":"Ternary FGF1-FGFR1c-perlecan complexes in full text"}],"covers":["LR000594","LR004078"]},"LR004059":{"pair":"FGF10 -> FGFR2","headline":"FGF10 binds and activates FGFR2b specifically, supported by a co-crystal structure and binding data.","interaction_type":"direct binding","direction_and_effect":"FGF10 and FGF7 activate only the b isoform of FGFR2 [PMID:12591959]. FGF10 is a potent keratinocyte mitogen and bound the KGFR (FGFR2b) with high affinity but not detectably FGFR1c or FGFR2c [PMID:9582367]. FGF10 strongly activated FGFR2b in BaF3 cells [PMID:16597617]. Agonist.","molecular_requirements":"Isoform specificity comes from the alternatively spliced D3 domain: FGF10 contacts two b-specific loops, and FGF10 binding rotates Ig domain 2 [PMID:12591959]. Mitogenic activity differed from KGF in its heparin sensitivity [PMID:9582367].","affinity_potency":[{"value":"active from 0.1 nM, maximal at around 5 nM","assay":"mitogenesis of Balb/MK keratinocytes (potency, not binding)","system":"recombinant FGF-10 on mouse keratinocytes","cite":"PMID:9582367"}],"species_and_systems":"Crystal structure of the FGFR2b ligand-binding region with FGF10 [PMID:12591959] (PDB 1NUN) [DB:PDB 1NUN]. Recombinant human FGF10 on mouse cells [PMID:9582367]. BaF3 panel [PMID:16597617]. Mouse pair is projected.","localisation_and_range":"FGF10 flagged secreted [flag]; paracrine signalling from mesenchyme to epithelium is not stated in our evidence.","caveats":"Specific to FGFR2b, not FGFR2c: a gene-level FGF10-FGFR2 pair hides this. Two papers were abstract-only [PMID:12591959][PMID:9582367].","key_references":[{"PMID":"12591959","why":"co-crystal structure, b-isoform specificity"},{"PMID":"9582367","why":"high-affinity binding of FGF-10 to FGFR2b, no FGFR1c/2c"},{"PMID":"16597617","why":"strong FGFR2b activation in BaF3"}],"covers":["LR000575","LR004059"]},"LR000576":{"pair":"FGF16 -> FGFR1","headline":"FGF16 activates FGFR1c-expressing BaF3 cells with high activity; functional evidence from one panel study.","interaction_type":"functional only","direction_and_effect":"FGF9, FGF16 and FGF20 activated FGFRc isoforms and FGFR4 with high activity [PMID:16597617]. Agonist.","molecular_requirements":"Activity is on the c splice form; isoform-specific, so FGFR1c rather than FGFR1b is the relevant receptor [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF16 flagged secreted; FGFR1 a membrane receptor [flag].","caveats":"Single functional paper, read as full text in a browser (quote unverified); activity is mitogenesis in BaF3 cells, not binding. Two other judged rows were review-only.","key_references":[{"PMID":"16597617","why":"BaF3 FGF-FGFR specificity panel"}],"covers":["LR000576","LR004060"]},"LR004068":{"pair":"FGF18 -> FGFR1","headline":"FGF18 activates FGFR1c in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-like domain form of FGFR4 [PMID:16597617]. Agonist.","molecular_requirements":"c isoform [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF18 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified; one abstract-insufficient paper not shown [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000584","LR004068"]},"LR000585":{"pair":"FGF18 -> FGFR2","headline":"FGF18 activates FGFR2c in a BaF3 mitogenic panel; one functional paper.","interaction_type":"functional only","direction_and_effect":"FGF8, FGF17 and FGF18 specifically activated FGFR1c, 2c, 3c and the two Ig-like domain form of FGFR4 [PMID:16597617]. Agonist.","molecular_requirements":"c isoform [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 mitogenic panel [PMID:16597617]; species of FGFR constructs not reported. Mouse pair projected from human.","localisation_and_range":"FGF18 flagged secreted [flag].","caveats":"Mitogenic activity in BaF3 cells, not binding; browser-read full text, quote unverified; one abstract-insufficient paper not shown [PMID:16597617].","key_references":[{"PMID":"16597617","why":"BaF3 panel"}],"covers":["LR000585","LR004069"]},"LR002628":{"pair":"FGF18 -> GLG1","headline":"Fgf18 interacts physically with Cfr (Glg1), a co-receptor that promotes Fgf18-Fgfr3c signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Cfr-deficient mice resemble Fgf18-deficient mice, and Cfr and Fgf18 interact genetically and physically [PMID:20023171]. Cfr introduction facilitated Fgf18-dependent proliferation of Fgfr3c-expressing Ba/F3 cells [PMID:20023171]. Dlk binds Cfr and interrupts the Cfr-Fgf18 interaction [PMID:20023171].","molecular_requirements":"Cfr acts as a co-receptor facilitating Fgf18 signalling through Fgfr3c, not as a standalone signalling receptor [PMID:20023171]. Dlk competes with Fgf18 for Cfr.","affinity_potency":[],"species_and_systems":"Mouse knockout and Ba/F3 cell assays [PMID:20023171]; the human pair is projected from mouse (ortholog_inferred).","localisation_and_range":"GLG1 is flagged a transmembrane receptor [flag]; Fgf18 is secreted [flag].","caveats":"Single paper, abstract only; the nature of the physical assay (direct binding vs co-purification) is not detailed in the dossier. Co-receptor role means Fgfr3c expression is also needed.","key_references":[{"PMID":"20023171","why":"Cfr-Fgf18 interaction and Dlk antagonism"}],"covers":["LR002628","LR005894"]},"LR004095":{"pair":"FGF2 -> FGFR4","headline":"FGF2 binds FGFR4 with high affinity in human-protein assays; evidence is abstract-level.","interaction_type":"direct binding","direction_and_effect":"Basic FGF (FGF2) binds with high affinity to FGFR1, FGFR2 and FGFR4 [PMID:8530375]; confirmed as binding well in a second study [PMID:10950949]. BaF3 assays showed FGF2 activity on FGFR-expressing lines [PMID:8663044]. Dossier modulatory effect: stimulatory [flag].","molecular_requirements":"Not reported for FGFR4 specifically in our evidence (heparin, co-receptors).","affinity_potency":[],"species_and_systems":"Human ligand and receptor in binding studies [PMID:8530375][PMID:10950949]; BaF3 species not stated [PMID:8663044]. No database records.","localisation_and_range":"FGF2 and FGFR4 both annotated secreted and transmembrane-capable [flag].","caveats":"All three papers read as abstract only. The FGFR4-specific result in the BaF3 paper is not given in the evidence sentence. No affinity value reported.","key_references":[{"PMID":"8530375","why":"bFGF binds FGFR4 with high affinity"},{"PMID":"10950949","why":"FGF-2 binds FGFR4 well"}],"covers":["LR000611","LR004095"]},"LR001818":{"pair":"FGF22 -> FGFR1","headline":"Weak functional evidence: FGF22 gave only weak activity toward FGFR1b in a mitogenic screen.","interaction_type":"functional only","direction_and_effect":"FGFs 10 and 22 showed weak activity toward FGFR1b and failed to activate other FGFR lines in the BaF3 screen [PMID:16597617].","molecular_requirements":"Only FGFR1b showed weak response; heparan sulfate modulation noted in the abstract generally [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cells; species unspecified [PMID:16597617].","localisation_and_range":"FGF22 secreted [flag]; FGFR1 transmembrane [flag].","caveats":"Single weak functional result, quote browser-read and unverified [PMID:16597617]. UniProt lists FGF22 among FGFR1 interactors in vitro, citing the same screen [DB:UniProt]. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR001818","LR005173"]},"LR004086":{"pair":"FGF22 -> FGFR2","headline":"FGF22 strongly activates FGFR2b in a BaF3 mitogenic screen; functional evidence only.","interaction_type":"functional only","direction_and_effect":"FGFs 7, 10 and 22 all strongly activated FGFR2b [PMID:16597617]; stimulatory.","molecular_requirements":"The b splice form of FGFR2 is the responsive isoform in the sentence cited [PMID:16597617].","affinity_potency":[],"species_and_systems":"BaF3 cells; species unspecified [PMID:16597617].","localisation_and_range":"FGF22 secreted [flag]; FGFR2 transmembrane [flag].","caveats":"Single paper, functional readout only, quote browser-read and unverified [PMID:16597617]. Two further rows (review_only, abstract_insufficient) not shown. Mouse pair is projected from human.","key_references":[{"PMID":"16597617","why":"BaF3 receptor-specificity screen of the FGF family"}],"covers":["LR000602","LR004086"]},"LR005175":{"pair":"FGF23 -> KL","headline":"Database-asserted only: Klotho-FGF23 appears in structures and Reactome; no paper confirmed.","interaction_type":"database-asserted only","direction_and_effect":"No papers confirmed the pair (two rows judged abstract_insufficient). PDB shows FGF23 with alpha-Klotho in a ternary complex [DB:PDB 5W21] and cryo-EM complex [DB:PDB 7YSH]; Reactome has Klotho bound to FGF23 [DB:Reactome R-HSA-190208]; BioGRID has an affinity-capture-Western record [DB:BioGRID].","molecular_requirements":"Structures include FGFR1c as well, so KL binding may depend on FGFR1c [DB:PDB 5W21].","affinity_potency":[],"species_and_systems":"Species not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"Rests on databases; both human and mouse pairs are ortholog-inferred.","key_references":[],"covers":["LR001820","LR005175"]},"LR000639":{"pair":"FGF8 -> FGFR3","headline":"FGF8 binds FGFR3 well in a soluble-receptor assay and activates FGFR3c in BaF3 cells.","interaction_type":"direct binding","direction_and_effect":"Soluble FGFR3 bound FGF8 and FGF9 well but FGF2 poorly [PMID:10574949]. FGF8 subfamily members activated FGFRs 1c, 2c and 3c in BaF3 cells [PMID:16597617].","molecular_requirements":"A broad region spanning Ig domain II and N-terminal sequences determines FGF8/FGF9 binding specificity to chimeric receptors [PMID:10574949]. c splice form is responsive [PMID:16597617].","affinity_potency":[],"species_and_systems":"Soluble human FGFR3 binding domain with chimeric receptors, abstract only [PMID:10574949]; BaF3 cells with unspecified species [PMID:16597617][PMID:8663044]. BioGRID affinity capture-Western and IntAct surface plasmon resonance records exist [DB:BioGRID][DB:IntAct]. Mouse pair is projected from human.","localisation_and_range":"Localisation is not reported in our evidence.","caveats":"No affinity value is reported. In the same study, soluble FGFR1 bound FGF8 poorly [PMID:10574949], showing receptor-specific differences. BaF3 quotes are browser-read and pending spot-check.","key_references":[{"PMID":"10574949","why":"FGFR3 binds FGF8 well; chimeric mapping"},{"PMID":"16597617","why":"FGF8 subfamily activates FGFR3c"}],"covers":["LR000639","LR004123"]},"LR002637":{"pair":"FGFBP1 -> NRP1","headline":"FGFBP1 bound NRP1 on an optical biosensor; one paper, binding only.","interaction_type":"direct binding","direction_and_effect":"FGF-binding protein interacted with neuropilin-1 immobilised on a biosensor [PMID:15695515]. Effect on signalling is not reported for FGFBP1.","molecular_requirements":"Binding is ionic-strength dependent and inhibited by heparin, suggesting a heparin-mimetic site on NRP1 [PMID:15695515].","affinity_potency":[],"species_and_systems":"Human proteins; recombinant biosensor assay [PMID:15695515]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"FGFBP1 is flagged secreted; NRP1 transmembrane [flag].","caveats":"Single paper. Strong binding for FGF-1, 2, 4 and 7 is stated in the full text; FGFBP1 is only listed among interacting proteins, and the solution assay was shown for FGF-2, FGF-4 and HGF/SF, not FGFBP1 [PMID:15695515]. Kinetic constants quoted are for other ligands. Heparin-mediated bridging is possible.","key_references":[{"PMID":"15695515","why":"Biosensor screen of heparin-binding proteins on NRP1"}],"covers":["LR002637","LR005903"]},"LR005904":{"pair":"FGFR1 -> NRP1","headline":"FGFR1 interacts with NRP1 in a single biosensor study; receptor-receptor, not a classic ligand pair.","interaction_type":"direct binding","direction_and_effect":"FGF receptor 1 was among proteins able to interact with NRP1 immobilised on a sensor surface [PMID:15695515]. Direction and effect are not reported.","molecular_requirements":"Interactions were heparin-inhibited and ionic-strength dependent [PMID:15695515].","affinity_potency":[],"species_and_systems":"Optical biosensor with recombinant proteins; species not stated in the abstract [PMID:15695515]. Both species projected by ortholog inference.","localisation_and_range":"Both FGFR1 and NRP1 are flagged transmembrane [flag]; FGFR1 is flagged not secreted [flag].","caveats":"Abstract-only read for this row; one paper. Pair is membrane receptor to membrane receptor, so function is unclear. Heparin-binding sites may explain the interaction.","key_references":[{"PMID":"15695515","why":"Biosensor interaction of FGFR1 with NRP1"}],"covers":["LR002638","LR005904"]},"LR002646":{"pair":"FLRT1 -> UNC5D","headline":"FLRT1 binds UNC5D directly in a full-text extracellular binding screen; one paper, no affinity reported.","interaction_type":"direct binding","direction_and_effect":"A high-throughput extracellular binding screen found all three FLRTs binding all four Unc5s near saturation (mean Abs650nm value = 2.14), with ELISA titration on purified protein and CHO.K1 cell aggregation [PMID:26633812]. In stripe assays FLRT1 elicited attraction (16%) or repulsion (5%) in a small share of neurons, and Unc5D repelled 12% [PMID:26633812]; the pair-specific effect was not tested in our evidence.","molecular_requirements":"Purified ectodomains were used for the ELISA titrations and full-length proteins for the cell aggregation assay; subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Binding screen used purified ectodomains and CHO.K1 cells; neurite assays used mouse retinal neurons. The record covers a human and a mouse pair; the paper's species labels in the curated row are human for both partners [PMID:26633812].","localisation_and_range":"Both partners carry transmembrane flags and the cell aggregation assay indicates interaction between opposing cell surfaces (contact-mediated) [PMID:26633812]; FLRT1 is also flagged secreted [flag].","caveats":"Single paper only; no affinity and no pair-specific functional result.","key_references":[{"PMID":"26633812","why":"Full-text screen showing all FLRT x Unc5 pairs bind near saturation."}],"covers":["LR002646","LR005912"]},"LR002655":{"pair":"FLRT2 -> UNC5D","headline":"FLRT2 binds UNC5D directly; supported by a binding screen and a repulsion study, plus BioGRID reconstituted-complex records.","interaction_type":"direct binding","direction_and_effect":"UNC5D binds FLRT2 specifically, and shed FLRT2/3 ectodomains act as repulsive guidance cues for Unc5-positive neurons; deleting FLRT2 or Unc5D makes SVZ neurons migrate prematurely to the cortical plate, while Unc5D overexpression has the opposite effect [PMID:21673655]. In a 126 x 126 extracellular screen, all twelve FLRT x Unc5 combinations bound near saturation [PMID:26633812].","molecular_requirements":"Ectodomains are sufficient for binding in the screen (purified ectodomains) [PMID:26633812]; no subunit or co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Screen used purified ectodomains, CHO.K1 aggregation and mouse retina [PMID:26633812]; the 2011 paper studied developing mouse neocortex neurons (read as abstract only, species not stated in the abstract) [PMID:21673655]. Dossier lists human and mouse interactions; the human one is ortholog-inferred.","localisation_and_range":"FLRT2 is annotated secreted and transmembrane [flag]; shed ectodomains act as repulsive cues [PMID:21673655], so both soluble and contact modes are possible. UNC5D is a transmembrane receptor [flag].","caveats":"The 2011 paper was read as abstract only. No affinity reported in our evidence. BioGRID lists reconstituted-complex records [DB:BioGRID].","key_references":[{"PMID":"21673655","why":"Unc5D binds FLRT2 specifically; repulsion and migration phenotypes"},{"PMID":"26633812","why":"Binding screen showing all FLRT x Unc5 pairs bind"}],"covers":["LR002655","LR005921"]},"LR005922":{"pair":"FLRT3 -> ADGRL1","headline":"FLRT3 binds latrophilin-1 (ADGRL1); supported by pull-down and a splicing study, but ADGRL1 evidence is secondary to ADGRL3.","interaction_type":"direct binding","direction_and_effect":"Ecto-FLRT3-Fc pulled down many LPHN1 and LPHN3 peptides, and ecto-LPHN1-Fc bound all FLRT isoforms in cell binding [PMID:22405201]. Latrophilin-1 binding to FLRT3 is not affected by its N-terminal alternative splicing, unlike teneurin binding [PMID:24273166]. Direction/effect: the curator-assigned effect is agonist [PMID:24273166], but our evidence does not show agonism.","molecular_requirements":"Teneurin and FLRT3 bind latrophilin-1 independently [PMID:24273166]. Subunit requirements otherwise not reported in our evidence.","affinity_potency":[],"species_and_systems":"Rat brain extract, rat/HEK293 cell assays and mass spectrometry [PMID:22405201]; the splicing paper was read as abstract only [PMID:24273166]. Dossier lists human and mouse interactions.","localisation_and_range":"FLRT3 is annotated secreted and transmembrane, ADGRL1 transmembrane [flag]; the high-affinity interaction was shown in trans [PMID:22405201].","caveats":"The 2014 paper cites FLRT3-LPHN1 as an established ligand rather than testing it as its main result [PMID:24273166]. Two further judged papers were abstract-insufficient. No affinity for ADGRL1 reported.","key_references":[{"PMID":"22405201","why":"FLRT family identified as latrophilin ligands; LPHN1 and LPHN3 pulled down by FLRT3"},{"PMID":"24273166","why":"LPHN1-FLRT3 binding unaffected by splicing"}],"covers":["LR002656","LR005922"]},"LR007209":{"pair":"FLRT3:TENM3 -> ADGRL3","headline":"Structure-based, database-only support that FLRT3 binds ADGRL3; no curated paper and no evidence for TENM3's role.","interaction_type":"database-asserted only","direction_and_effect":"FLRT3 LRR domain in complex with the LPHN3 olfactomedin domain is recorded as a structure [DB:PDB 5CMN]; UniProt notes ADGRL3 interacts with FLRT3 and TENM2, promoting synapse formation (by similarity) [DB:UniProt]. Effect on signalling is not reported in our evidence.","molecular_requirements":"The ligand is the FLRT3:TENM3 complex, but the database records concern an FLRT3 chain with the ADGRL3 olfactomedin domain [DB:PDB 5CMN] [DB:IntAct]; TENM3 involvement is not reported in our evidence. CCC tools scoring the complex would require TENM3 expression without support.","affinity_potency":[],"species_and_systems":"Experiment species not stated beyond the human entries; the crystal structure is of the human proteins as recorded [DB:PDB 5CMN].","localisation_and_range":"FLRT3 is flagged secreted and transmembrane, TENM3 transmembrane [flag]; contact-based signalling is plausible only from these flags.","caveats":"No curated paper confirms the pair (3 pending). Evidence is database records only, and none addresses TENM3.","key_references":[],"covers":["LR007209"]},"LR009225":{"pair":"FN1 -> CD79A","headline":"Weak support: one IntAct competition-binding record and no confirmed paper for fibronectin and CD79A.","interaction_type":"database-asserted only","direction_and_effect":"IntAct lists a competition-binding experiment for this pair [DB:IntAct]. Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"FN1 is flagged secreted and not transmembrane [flag]; CD79A has no flags.","caveats":"Two papers were judged, none confirmed (1 review-only, 1 abstract-insufficient). The only support is one database row.","key_references":[{"PMID":"18243143","why":"PMID attached to the IntAct competition-binding record (not a curated paper)"}],"covers":["LR009225"]},"LR002664":{"pair":"FN1 -> FLRT2","headline":"FLRT2 co-immunoprecipitates and colocalizes with fibronectin in chondroprogenitor cells; direct contact is not shown.","interaction_type":"direct binding","direction_and_effect":"FLRT2 colocalized with fibronectin on the cell surface and in ECM, associated with Fn-coated beads, and decreased when Fn fibril formation was blocked; co-immunoprecipitation showed they interact directly or indirectly [PMID:24585683].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"ATDC5 chondroprogenitor cell line; curator fields list human, and the mouse pair is not orthology-inferred [PMID:24585683].","localisation_and_range":"FLRT2 is flagged secreted and transmembrane, FN1 secreted [flag]; FLRT2 was found in the ECM [PMID:24585683].","caveats":"Single abstract-only paper; co-immunoprecipitation cannot separate direct from indirect binding, and the curator label of direct binding is stronger than the text.","key_references":[{"PMID":"24585683","why":"FLRT2-fibronectin colocalization and co-IP in ATDC5 cells"}],"covers":["LR002664","LR005930"]},"LR000657":{"pair":"FN1 -> ITGA2B","headline":"Fibronectin binding to the alphaIIb integrin subunit is supported by two papers, but evidence concerns the alphaIIbbeta3 heterodimer.","interaction_type":"direct binding","direction_and_effect":"A fibronectin C-terminal heparin-binding peptide (residues Ala1704-Glu1718) bound directly to alphaIIbbeta3 and inhibited fibronectin fragment binding to thrombin-stimulated platelets [PMID:8663002]. In mouse trophoblast, adhesion to fibronectin was inhibited by a function-blocking anti-alphaIIb antibody [PMID:15031111]. Agonist/adhesion.","molecular_requirements":"Both papers concern the alphaIIbbeta3 heterodimer; alphaIIb alone is not tested separately in our evidence. RGDS peptide did not inhibit binding of the 29-kDa fragment [PMID:8663002].","affinity_potency":[],"species_and_systems":"Human platelets and human fibronectin fragment [PMID:8663002]; mouse blastocyst trophoblast with human FN substrates [PMID:15031111]; mouse pair is orthology-inferred.","localisation_and_range":"FN1 flagged secreted, ITGA2B flagged receptor [flag]; matrix-to-cell contact.","caveats":"The 1996 paper is listed as abstract-level; BioGRID and Reactome records support alphaIIbbeta3 binding fibronectin [DB:BioGRID] [DB:Reactome]. 3 further papers were abstract-insufficient.","key_references":[{"PMID":"8663002","why":"non-RGD fibronectin site binds alphaIIbbeta3"},{"PMID":"15031111","why":"alphaIIb function-blocking antibody inhibits trophoblast adhesion to FN"}],"covers":["LR000657","LR004141"]},"LR004149":{"pair":"FN1 -> ITGB3","headline":"Fibronectin binds beta3 integrins (alphavbeta3, alphaIIbbeta3) in several assays; support is multi-paper but mostly integrin-complex level.","interaction_type":"direct binding","direction_and_effect":"Purified alphavbeta3 bound fibronectin among other ligands [PMID:1694173]. A fibronectin-derived peptide (Ala1704-Glu1718) bound directly to alphaIIbbeta3 and inhibited fibronectin-fragment binding to platelets [PMID:8663002]. In mouse trophoblast cells an anti-alphaIIb antibody blocked fibronectin-driven outgrowth, an agonist-type adhesion effect [PMID:15031111].","molecular_requirements":"The receptor is the integrin heterodimer: alphaV-beta3 [PMID:1694173, PMID:11423542] or alphaIIb-beta3 [PMID:8663002, PMID:28092265], not beta3 alone. The fibronectin synergy site reinforces alphaIIbbeta3 binding [PMID:28092265]. A C-terminal heparin-binding site acts in addition to RGD [PMID:8663002].","affinity_potency":[],"species_and_systems":"Human purified/platelet systems [PMID:1694173, PMID:8663002]; mouse trophoblast with human fibronectin [PMID:15031111]; Fn1 synergy-site mutant mice [PMID:28092265]. Structures (PDB 4MMX, 6NAJ) are listed [DB:PDB 4MMX].","localisation_and_range":"Fibronectin is flagged secreted [flag]; it acts as an adhesive matrix ligand (matrix-bound, contact-dependent), inferred from paper context.","caveats":"Several papers were read as abstracts only. Affinity not reported in our evidence. 8663002 is a competition readout flagged borderline and concerns alphaIIbbeta3. 1694173 is mainly about alphavbeta5. Database support: BioGRID, IntAct, Reactome [DB:Reactome R-HSA-349593].","key_references":[{"PMID":"11423542","why":"alphav-beta3 adhesion to fibronectin versus vitronectin"},{"PMID":"8663002","why":"Fibronectin peptide binds alphaIIbbeta3 directly"},{"PMID":"28092265","why":"Fibronectin synergy site and beta3 integrins in mice"}],"covers":["LR000665","LR004149"]},"LR000666":{"pair":"FN1 -> ITGB6","headline":"Fibronectin binds integrin alphavbeta6 in one affinity-chromatography study.","interaction_type":"direct binding","direction_and_effect":"alphavbeta6 from human carcinoma cell lysates bound immobilized fibronectin but not vitronectin or collagen I, and was eluted by an RGD peptide, so it acts as an RGD-dependent fibronectin receptor [PMID:1532572].","molecular_requirements":"The binding entity is the alphav-beta6 heterodimer [PMID:1532572].","affinity_potency":[],"species_and_systems":"Human pancreatic carcinoma FG-2 cell lysates [PMID:1532572]. Mouse pair is projected by orthology.","localisation_and_range":"Fibronectin is flagged secreted [flag]; matrix ligand for a cell-surface integrin (inferred).","caveats":"Single paper read as abstract only; affinity not reported in our evidence. BioGRID lists a reconstituted complex from the same paper [DB:BioGRID].","key_references":[{"PMID":"1532572","why":"alphavbeta6 as RGD-dependent fibronectin-binding protein"}],"covers":["LR000666","LR004150"]},"LR005931":{"pair":"FN1 -> SDC4","headline":"Syndecan-4 binds the FNIII13 site of fibronectin; one abstract-level paper in human cells.","interaction_type":"direct binding","direction_and_effect":"FNIII13 was characterised as the syndecan-4 binding site in fibronectin; overexpression of syndecan-4, but not syndecan-1 or -2, reverted the tenascin-C-induced adhesion defect [PMID:11731446].","molecular_requirements":"The HepII/syndecan-4 site in FNIII13; tenascin-C competes by binding FNIII13 [PMID:11731446].","affinity_potency":[],"species_and_systems":"Human glioblastoma and breast carcinoma cells; mouse pair is inferred [PMID:11731446].","localisation_and_range":"Receptor flagged as receptor [flag]; fibronectin secreted [flag]; matrix-contact interaction (inferred).","caveats":"Abstract only; no affinity reported. Mouse row ortholog-inferred. Species of cells stated by dossier as human.","key_references":[{"PMID":"11731446","why":"FNIII13 as syndecan-4 binding site"}],"covers":["LR002665","LR005931"]},"LR001827":{"pair":"FNDC5 -> ITGB5","headline":"Irisin interacts with alphaV/beta5 integrin in biophysical studies; single paper.","interaction_type":"direct binding","direction_and_effect":"Biophysical studies identified interacting surfaces between irisin and alphaV/beta5 integrin; alphaV inhibition blocked irisin signalling in osteocytes and fat cells [PMID:30550785].","molecular_requirements":"Acts via the alphaV/beta5 heterodimer [PMID:30550785].","affinity_potency":[],"species_and_systems":"Cells and mice; FNDC5-null mice resisted ovariectomy-induced osteolysis [PMID:30550785].","localisation_and_range":"FNDC5 flagged secreted [flag]; muscle-secreted hormone [PMID:30550785].","caveats":"One paper; the inhibition used a general alphaV inhibitor, not beta5-specific. No affinity reported. No database record.","key_references":[{"PMID":"30550785","why":"Irisin interacts with alphaV/beta5 integrin"}],"covers":["LR001827","LR005182"]},"LR004158":{"pair":"GALP -> GALR2","headline":"Human GALP binds GALR2 in transfected human cells (IC50 28 nM); a single abstract-level paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"GALP acts as an agonist at GALR2; competition binding in SH-SY5Y cells showed intermediate affinity of the three subtypes [PMID:15944009]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. GALP(3-32) is at least as potent as full-length GALP(1-60) in the same study [PMID:15944009].","affinity_potency":[{"value":"IC50 = 28 nM","assay":"competition ligand binding","system":"human neuroblastoma SH-SY5Y cells transfected with the receptor, human GALP(1-60)","cite":"PMID:15944009"}],"species_and_systems":"Human receptor in transfected human SH-SY5Y cells; the dossier lists the ligand species as porcine for the experiment. The mouse pair is projected from human evidence.","localisation_and_range":"GALP is flagged as secreted and the receptor as a transmembrane receptor [flag].","caveats":"Single paper, abstract only; other papers are pending. GALP shares its N-terminal 13 residues with galanin, so cross-reactivity with galanin receptors is expected, not specific [PMID:15944009].","key_references":[{"PMID":"15944009","why":"Ligand binding of human GALP(1-60) at GalR1, GalR2 and GalR3"}],"covers":["LR000674","LR004158"]},"LR000675":{"pair":"GALP -> GALR3","headline":"Human GALP binds GALR3 in transfected human cells (IC50 10 nM); a single abstract-level paper plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"GALP acts as an agonist at GALR3; competition binding in SH-SY5Y cells showed highest affinity of the three subtypes [PMID:15944009]. GtoPdb lists an agonist action [DB:GtoPdb].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. GALP(3-32) is at least as potent as full-length GALP(1-60) in the same study [PMID:15944009].","affinity_potency":[{"value":"IC50 = 10 nM","assay":"competition ligand binding","system":"human neuroblastoma SH-SY5Y cells transfected with the receptor, human GALP(1-60)","cite":"PMID:15944009"}],"species_and_systems":"Human receptor in transfected human SH-SY5Y cells; the dossier lists the ligand species as porcine for the experiment. The mouse pair is projected from human evidence.","localisation_and_range":"GALP is flagged as secreted and the receptor as a transmembrane receptor [flag].","caveats":"Single paper, abstract only; other papers are pending. GALP shares its N-terminal 13 residues with galanin, so cross-reactivity with galanin receptors is expected, not specific [PMID:15944009].","key_references":[{"PMID":"15944009","why":"Ligand binding of human GALP(1-60) at GalR1, GalR2 and GalR3"}],"covers":["LR000675","LR004159"]},"LR004167":{"pair":"GCG -> GCGR","headline":"Well-established agonist pair with a receptor crystal structure and database support; the structure paper models, not solves, glucagon binding.","interaction_type":"direct binding","direction_and_effect":"Glucagon binding to GCGR triggers glucose release from the liver during fasting [PMID:23863937]. GtoPdb lists glucagon as a full agonist [DB:GtoPdb].","molecular_requirements":"The crystal structure of the human GCGR seven-transmembrane domain at 3.4 A, with mutagenesis and a hybrid glucagon model, shows the ~12 kDa extracellular domain positioned by a stalk on TM1 to capture glucagon and insert its N-terminus into the transmembrane domain [PMID:23863937]. PDB complexes exist [DB:PDB 5YQZ] [DB:PDB 6LMK]. IntAct lists saturation binding [DB:IntAct].","affinity_potency":[],"species_and_systems":"Human GCGR structure and mutagenesis [PMID:23863937]; the mouse pair is projected from human evidence.","localisation_and_range":"GCG is flagged secreted and GCGR transmembrane [flag].","caveats":"Only two papers are confirmed; three were abstract-insufficient and one review-only. The structure paper's glucagon complex is a model. No affinity values are reported in our evidence; GtoPdb gives pEC50 units without a value shown [DB:GtoPdb].","key_references":[{"PMID":"23863937","why":"Crystal structure of the human GCGR transmembrane domain with glucagon model"}],"covers":["LR000683","LR004167"]},"LR000684":{"pair":"GCG -> GLP1R","headline":"Glucagon acts on GLP1R as an agonist per databases, but most confirmed papers test GLP-1 rather than glucagon.","interaction_type":"direct binding","direction_and_effect":"GtoPdb lists glucagon as a full agonist at GLP1R [DB:GtoPdb]. In a GLP-1R/beta-arrestin-2 fusion, apparent affinity increased selectively for glucagon, not GLP-1 itself [PMID:15528268].","molecular_requirements":"Receptor N-terminal fragment binds GLP-1 with lower affinity than wild-type receptor, and the TM1-TM3 region is also needed [PMID:11116211]. Whether glucagon needs the same determinants is not reported in our evidence.","affinity_potency":[{"value":"IC50 5.2 nM","assay":"GLP-1 binding to wild-type GLP-1R (a GLP-1 result, not glucagon)","system":"receptor expressed in cells","cite":"PMID:11116211"}],"species_and_systems":"Human ligand and receptor recorded for most papers; the rat GLP-I receptor in CHO cells was used in PMID:7937318. The mouse pair is projected from human evidence.","localisation_and_range":"GCG is flagged secreted and GLP1R transmembrane [flag].","caveats":"Only PMID:15528268 involves glucagon, in a fusion-construct system that may not reflect native receptor. That paper's curated 9.2 pKi has no stated ligand and GtoPdb lists pKi 6.9-7.0, so it is not used. PMIDs 11116211 and 8404634 test GLP-1, and PMID:7937318 reports oxyntomodulin as a weak agonist. All abstract-only. Structures exist [DB:PDB 3IOL].","key_references":[{"PMID":"15528268","why":"Glucagon affinity at GLP-1R/beta-arrestin-2 fusion"},{"PMID":"7937318","why":"Rat GLP-1R pharmacology including oxyntomodulin"},{"PMID":"8404634","why":"Cloning of human GLP-1 receptor; ligand is GLP-1"}],"covers":["LR000684","LR004168"]},"LR002673":{"pair":"GDF1 -> ACVR2A","headline":"Weak functional evidence only: a GDF3 paper cites GDF1 as using ActRIIA (ACVR2A); GtoPdb asserts agonism.","interaction_type":"functional only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at this receptor [DB:GtoPdb]. The only paper states that GDF3 signalling, 'similar to GDF1', is mediated by ALK4, ActRIIA, ActRIIB and Cripto in Smad-dependent reporter assays [PMID:17936261].","molecular_requirements":"Type I ALK4, type II ActRIIA/ActRIIB and the co-receptor Cripto are named; native GDF1 was incapable of signalling in heterologous cells unless a heterologous prodomain, Furin or Nodal co-expression was used [PMID:17936261].","affinity_potency":[],"species_and_systems":"Mouse is the species with primary evidence; the human pair is ortholog-projected. The abstract does not state the cell species [PMID:17936261].","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"Abstract-only. GDF1 receptor usage is background in a paper about GDF3, not its own result [PMID:17936261]. Native GDF1 is poorly processed, so potency is not reported in our evidence.","key_references":[{"PMID":"17936261","why":"GDF3 (and, by reference, GDF1) use ALK4, ActRIIA/B and Cripto"}],"covers":["LR002673","LR005938"]},"LR006804":{"pair":"GDF1 -> BMPR1A","headline":"Database-asserted only: GtoPdb lists an agonist action; no confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists GDF1 as an agonist at BMPR1A [DB:GtoPdb]; no paper confirms it in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"No experimental system reported in our evidence.","localisation_and_range":"GDF1 is flagged secreted [flag].","caveats":"No confirmed paper. One paper was abstract-insufficient. Affinity and species are not reported in our evidence.","key_references":[],"covers":["LR006804"]},"LR002682":{"pair":"GDF15 -> RET","headline":"RET acts as coreceptor for GFRAL in GDF15 signalling; direct GDF15-RET binding is not shown.","interaction_type":"functional only","direction_and_effect":"GFRAL requires association with the coreceptor RET to elicit intracellular signalling in response to GDF15 [PMID:28846099].","molecular_requirements":"RET depends on GFRAL as the GDF15-binding chain [PMID:28846099]; UniProt describes a 2:2:2 GDF15, GFRAL and RET ternary complex [DB:UniProt]; PDB 6Q2J and IntAct electron microscopy list Q99988 with P07949 [DB:PDB 6Q2J][DB:IntAct].","affinity_potency":[],"species_and_systems":"Human reagents per curator; mouse pair ortholog-inferred. Abstract-level evidence [PMID:28846099].","localisation_and_range":"GDF15 flagged secreted [flag]; GFRAL expression limited to hindbrain neurons [PMID:28846099].","caveats":"RET is a coreceptor; use the GFRAL-RET complex in scoring rather than RET alone. Only one abstract-read paper. Affinity not reported.","key_references":[{"PMID":"28846099","why":"GFRAL requires RET for GDF15 signalling"}],"covers":["LR002682","LR005947"]},"LR007227":{"pair":"GDF2 -> ACVR2A:ACVRL1","headline":"BMP9 signalling needs the ALK1 plus type-II receptor complex; support is one functional abstract plus database records.","interaction_type":"functional only","direction_and_effect":"BMP9 activates the ID1 BMP-response element dose-dependently (EC50 = 45 +/- 27 pg/mL), and this is abolished by silencing ALK1 or adding ALK1 extracellular domain [PMID:17068149]. GtoPdb lists agonist records for both ACVR2A and ACVRL1 [DB:GtoPdb].","molecular_requirements":"ALK1 is required; endoglin overexpression increases the response, and silencing both BMPRII and ActRIIA completely abolishes it [PMID:17068149]. UniProt notes BMP9 can form a heteromeric complex with ENG and ACVRL1 [DB:UniProt].","affinity_potency":[{"value":"EC50 = 45 +/- 27 pg/mL","assay":"ID1 BMP response element activation","system":"microvascular endothelial cells","cite":"PMID:17068149"}],"species_and_systems":"Human microvascular endothelial cells [PMID:17068149]. Pair is human only.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"The one confirmed paper was read as an abstract only and shows function, not direct binding to this complex [PMID:17068149]. Complex-level binding is not reported; BioGRID records are for ACVR2A-GDF2 alone [DB:BioGRID].","key_references":[{"PMID":"17068149","why":"BMP9 activation of ALK1 signalling needs BMPRII and ActRIIA"}],"covers":["LR007227"]},"LR004176":{"pair":"GDF2 -> ACVR2B","headline":"BMP-9 binds ActRIIB directly, with a crystal structure and cell-free binding data; the binding is weaker than to ALK1.","interaction_type":"direct binding","direction_and_effect":"BMP-9 is an agonist-type ligand in a ternary complex with ALK1 and ActRIIB [PMID:22718755][DB:PDB 4FAO]. Activin A competed with BMP-9 for binding to recombinant ACVR2A and ACVR2B in a cell-free assay, and activin A inhibited BMP-9 signalling in myeloma cells [PMID:26047946].","molecular_requirements":"Crystal structure of a ternary complex of BMP9 with the extracellular domains of ALK1 and ActRIIB [PMID:22718755]. BMP-9 also bound ActR-IIB in HUVECs [PMID:17311849].","affinity_potency":[],"species_and_systems":"Crystal structure and ELISA-type binding used recombinant extracellular domains [PMID:22718755][PMID:26047946]; HUVEC cross-linking [PMID:17311849]; myeloma cell lines for function [PMID:26047946]. Species of the structure is not stated for this row.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"BMP-9 binds ActR-IA, ActR-IIA and ActR-IIB only weakly by BIAcore [PMID:15851468]. Activin A competes for the same receptor [PMID:26047946]. Two binding sentences were read from a browser and are marked unverified [PMID:15851468][PMID:17311849]; the 22718755 and 15851468 papers are abstract-level in the dossier.","key_references":[{"PMID":"22718755","why":"Crystal structure of BMP9-ALK1-ActRIIB ternary complex"},{"PMID":"26047946","why":"Direct BMP-9 binding to recombinant ACVR2B; activin A competition"},{"PMID":"15851468","why":"BIAcore: weak BMP-9 binding to ActR-IIB"}],"covers":["LR000692","LR004176"]},"LR008262":{"pair":"GDF2 -> ACVR2B:ACVRL1","headline":"No curated papers; the complex rests on database records of the ALK1/ActRIIB ternary structure.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists agonist records for ACVR2B and ACVRL1 [DB:GtoPdb]. UniProt says BMP9 was identified in a complex with ACVRL1 and ACVR2B and signals through ACVRL1 but not other Alks [DB:UniProt].","molecular_requirements":"The PDB structure 4FAO contains BMP9 with ALK1 and ActRIIB chains [DB:PDB 4FAO].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the structure record.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"No papers were judged for this complex; the two review_only rows are not shown. Support is from databases only [DB:GtoPdb][DB:PDB 4FAO][DB:UniProt].","key_references":[{"PMID":"22718755","why":"Source of the PDB 4FAO ternary complex record"}],"covers":["LR008262"]},"LR000693":{"pair":"GDF2 -> ACVRL1","headline":"BMP9 is a high-affinity ligand of the type-I receptor ALK1, supported by crystal structures, binding and functional data.","interaction_type":"direct binding","direction_and_effect":"BMP9 is an agonist for ALK1 [PMID:22718755][PMID:32238803][DB:GtoPdb]. BMP9 activated an ID1-promoter reporter and Smad1/5/8 phosphorylation, abolished by ALK1 silencing or soluble ALK1 ectodomain [PMID:17068149]. Soluble ALK-1 blocked the activity of the BMP-9 pro-region complex [PMID:15851468].","molecular_requirements":"Type-II partners are needed: silencing both BMPRII and ActRIIA abolishes the response, and endoglin overexpression enhances it [PMID:17068149]. BMP-9 also bound endoglin with high affinity [PMID:17311849]. The BMP9:ALK1 ectodomain complex has 2:2 stoichiometry for BMP10 and a similar BMP9 assembly [PMID:32238803]. The pro-region does not interfere with ALK1 binding or signalling [PMID:15851468][PMID:32238803].","affinity_potency":[{"value":"EC50 = 45 +/- 27 pg/mL","assay":"ID1 BMP response element activation","system":"microvascular endothelial cells","cite":"PMID:17068149"}],"species_and_systems":"Human (ligand and receptor) in structural work [PMID:22718755][PMID:32238803]; transfected COS cells, endothelial cells and glioblastoma cells [PMID:17311849]; C2C12 cells [PMID:32238803]. Mouse pair is projected from human evidence.","localisation_and_range":"BMP-9 is flagged as secreted and non-transmembrane, the receptor as transmembrane [flag]; this implies paracrine/endocrine signalling to a cell-surface receptor (from annotation flags only).","caveats":"Several rows are abstract-only [PMID:22718755][PMID:15851468][PMID:17311849]. The 23029472 sentence uses ALK1-Fc only as a positive control in an RGM binding study, and 19956691 shows ALK1 ectodomain inhibition of BMP9 luciferase activity as a side result [PMID:23029472][PMID:19956691]. The affinity values are not given in the dossier.","key_references":[{"PMID":"15851468","why":"BIAcore and soluble ALK-1 blockade identify ALK-1 as a BMP-9 receptor"},{"PMID":"22718755","why":"Ternary BMP9-ALK1-ActRIIB structure"},{"PMID":"17068149","why":"BMP9 activates ALK1 signalling, EC50 = 45 +/- 27 pg/mL"}],"covers":["LR000693","LR004177"]},"LR004185":{"pair":"GDF5 -> ROR2","headline":"Indirect only: Ror2 forms a ligand-independent complex with GDF5's receptor BRI-b and modulates GDF5 signalling; no direct GDF5-Ror2 binding shown.","interaction_type":"functional only","direction_and_effect":"Ror2 modulates GDF5 signalling by inhibiting Smad1/5 signalling and activating a Smad-independent pathway, both needed for chondrogenic differentiation in ATDC5 cells [PMID:15569154]. Overall effect is modulatory rather than agonist.","molecular_requirements":"Ror2 and BRI-b (BMPR1B) form a ligand-independent heteromeric complex that needs Ror2's frizzled-like CRD domain, and Ror2 is transphosphorylated by BRI-b [PMID:15569154]. GDF5 acts through BRI-b in this model.","affinity_potency":[],"species_and_systems":"ATDC5 cells and Ror2, BRI-b and Gdf5 deficient mouse crosses [PMID:15569154]. The mouse pair is listed directly; the human pair is ortholog-inferred.","localisation_and_range":"Ligand is flagged secreted [flag], so signalling is expected to be paracrine; not otherwise reported in our evidence.","caveats":"Only one paper, read as an abstract; it does not demonstrate GDF5 binding to Ror2. Treat as a co-receptor or modulator via BMPR1B, not as a direct receptor. No database records.","key_references":[{"PMID":"15569154","why":"Ror2/BRI-b complex modulates GDF5 signalling"}],"covers":["LR000701","LR004185"]},"LR007236":{"pair":"GDF6 -> ACVR2A:BMPR1B","headline":"No paper confirms this combination; only database annotation of the chains, with no direct evidence for the complex.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in any verified paper in our evidence. UniProt says GDF6 seems to positively regulate chondrogenic differentiation through BMPR1A, BMPR1B, BMPR2 and ACVR2A subunits, activating SMAD1-SMAD5-SMAD8 [DB:UniProt]. A BioGRID record concerns GDF6 with BMPR1B only [DB:BioGRID].","molecular_requirements":"Complex requirement is untested: no curator-verified paper covers ACVR2A and BMPR1B together.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag]; range beyond that is not reported in our evidence.","caveats":"All judged papers (4) were review_only. Both chains are named in UniProt, but only as a list of possible subunits.","key_references":[],"covers":["LR007236"]},"LR007245":{"pair":"GDF7 -> BMPR1B:BMPR2","headline":"GDF7 -> BMPR1B:BMPR2: functional evidence only, from one abstract-only paper; chains not shown together.","interaction_type":"functional only","direction_and_effect":"ALK6 overexpression conferred GDF7 signalling in COS7 cells [PMID:16049014]. BMPR2 is not named in the cited sentence. GtoPdb lists agonist records for the individual chains [DB:GtoPdb].","molecular_requirements":"Complex of BMPR1B (ALK6) and BMPR2. Evidence comes from separate manipulations (receptor overexpression or shRNA of one chain), not from a test of the assembled pair [PMID:16049014]. Whether one chain alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"COS7 transfectants and MC3T3 cells with shRNA and Smad1/5/8 reporters; curator species fields are blank or human, abstract-only [PMID:16049014].","localisation_and_range":"Ligand is flagged secreted and the receptor complex as transmembrane [flag], implying paracrine signalling to a cell-surface receptor; not otherwise reported in our evidence.","caveats":"Single abstract-only paper. No binding or affinity data for the assembled complex in our evidence. Direct binding of GDF7 to the individual chains is documented in other rows, not this one.","key_references":[{"PMID":"16049014","why":"Receptor overexpression and shRNA define the type I and type II requirements for GDF7."}],"covers":["LR007245"]},"LR004194":{"pair":"GDNF -> GFRA1","headline":"Well supported direct binding: GFRA1 is the high-affinity GDNF binding receptor that then recruits RET.","interaction_type":"direct binding","direction_and_effect":"GDNFR-alpha (GFRA1) binds GDNF specifically and mediates Ret activation [PMID:8674117]. Both GDNF and neurturin bound GFR alpha1-Fc bodies with similar affinity [PMID:9883723]. Reactome, BioGRID, UniProt and PDB 6Q2N agree [DB:Reactome][DB:BioGRID][DB:UniProt][DB:PDB 6Q2N].","molecular_requirements":"GFRA1 acts as co-receptor for RET: UniProt describes a 2:2:2 GDNF:GFRA1:RET ternary complex [DB:UniProt]. Soluble GFRA1 plus GDNF activated Ret in cells lacking GFRA1 [PMID:8674117].","affinity_potency":[],"species_and_systems":"Expression cloning and Neuro-2a cells, with curators recording human ligand and receptor [PMID:8674117]; receptor-Fc binding assay in [PMID:9883723]. The mouse pair is ortholog-inferred.","localisation_and_range":"GFRA1 is GPI-linked [PMID:8674117]; GDNF is flagged secreted [flag], so the complex acts at the cell surface in paracrine fashion.","caveats":"No affinity value is in the dossier. PMID:9482105 is a gene-structure paper that only restates the binding. PMID:9883723 was read in a browser with the quote unverified.","key_references":[{"PMID":"8674117","why":"Cloning of GDNFR-alpha; binds GDNF and mediates Ret activation"},{"PMID":"9883723","why":"GDNF binds GFR alpha1-Fc"}],"covers":["LR000710","LR004194"]},"LR007029":{"pair":"GJA1 -> GJA5","headline":"GJA1 (Cx43) - GJA5 (Cx40) rests on database records only; no curator-confirmed paper.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists a co-purification between GJA1 and GJA5 [DB:BioGRID][PMID:11557558]. Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both partners are flagged transmembrane (gap-junction class) [flag].","caveats":"One paper judged abstract_insufficient; support rests on one database record.","key_references":[],"covers":["LR007029"]},"LR010467":{"pair":"GLS:SLC1A1 -> GRIN1:GRIN2A","headline":"Protein-association records only; no paper confirms GLS:SLC1A1 -> GRIN1:GRIN2A as a ligand-receptor pair.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. BioGRID lists affinity capture-Western records between SLC1A1 and NMDA receptor subunits (GRIN1 and GRIN2 chains) [DB:BioGRID][PMID:17459877].","molecular_requirements":"Only the SLC1A1 member of the ligand complex appears in the BioGRID records; the other ligand subunit (GLS/GLS2) is not covered in our evidence [DB:BioGRID].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Not reported in our evidence.","caveats":"No paper confirmed; judged papers were different_entity or abstract_insufficient. The records are transporter-receptor co-capture, not binding of a secreted ligand.","key_references":[],"covers":["LR010467"]},"LR008505":{"pair":"GNAS -> CRHR1","headline":"Database-asserted only: UniProt says CRHR1 couples mainly to G(s) (GNAS); BioGRID has an affinity-capture record.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states CRHR1 is mainly coupled to G(s) G protein (GNAS), mediating activation of adenylate cyclase [DB:UniProt][PMID:18292205][PMID:32004469][PMID:32004470].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists Affinity Capture-Western [PMID:10598591]; species and cell system not reported in our evidence.","localisation_and_range":"CRHR1 is annotated as a transmembrane receptor [flag]; coupling to GNAS is intracellular.","caveats":"No paper in our evidence supports this pair; it rests on database records alone. Judged rows: 'different_entity' (1) and 'abstract_insufficient' (1). This is receptor-G protein coupling.","key_references":[],"covers":["LR008505"]},"LR002709":{"pair":"GREM1 -> FGFR1","headline":"Gremlin1 is reported as an FGFR1 ligand that activates MAPK signalling; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Gremlin1 binds FGFR1 and activates downstream MAPK signalling; this promotes lineage plasticity and castration resistance in prostate cancer [PMID:35624341]. Agonist. An anti-Gremlin1 antibody acted synergistically with androgen deprivation therapy [PMID:35624341].","molecular_requirements":"Gremlin1 interacts with FGFR1 differently from the canonical ligand FGF1, according to docking and mutagenesis [PMID:35624341]. No co-receptor requirement is reported in our evidence.","affinity_potency":[],"species_and_systems":"Human prostate cancer models; curators list human/human [PMID:35624341]. Mouse pair is ortholog-inferred.","localisation_and_range":"GREM1 is flagged as secreted; FGFR1 as transmembrane [flag].","caveats":"One paper, abstract only; binding method and affinity not described in our evidence. Gremlin1 is also a BMP antagonist, but BMP effects are not reported here.","key_references":[{"PMID":"35624341","why":"Identifies Gremlin1 as an FGFR1 ligand activating MAPK"}],"covers":["LR002709","LR005974"]},"LR000729":{"pair":"GRP -> NMBR","headline":"GRP is a weak agonist of NMBR, supported by mouse itch data and a simulation study.","interaction_type":"functional only","direction_and_effect":"In mice, GRP can signal through both NMBR and GRPR, though to NMBR to a much lesser extent [PMID:25209280]. Molecular dynamics simulation supports GRP(14-27) as a weak NMBR agonist [PMID:40579433]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse knock-out and itch behaviour [PMID:25209280]; MD simulation of the receptor-peptide complex (not experimental binding) [PMID:40579433]. Human pair is not experimentally covered by the curated papers; mouse pair is ortholog-inferred.","localisation_and_range":"GRP is flagged secreted; NMBR is flagged as a transmembrane receptor [flag].","caveats":"No direct binding assay in the curated papers; both read as abstracts only. GtoPdb gives pIC50 6.83-6.91 [DB:GtoPdb], well below GRP's GRPR potency in other pairs.","key_references":[{"PMID":"25209280","why":"Mouse itch: GRP signals through NMBR weakly"},{"PMID":"40579433","why":"GRP(14-27) as weak NMBR agonist in simulation"}],"covers":["LR000729","LR004211"]},"LR001836":{"pair":"HAVCR1 -> HAVCR1","headline":"Homophilic TIM-1 self-binding is supported by structure and binding assays in mouse, with human TIM-1 also shown to bind itself.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of murine TIM-1 identified a homophilic TIM-TIM adhesion interaction [PMID:17363299]. This is a self-adhesion interaction, not a classical ligand-to-receptor signal; effect on signalling is not reported in our evidence.","molecular_requirements":"Mutations in the DE loop of the IgV domain affected homophilic binding. For human TIM-1, high-affinity binding required both IgV and mucin domains, as seen with mouse TIM-1 [PMID:17363299].","affinity_potency":[],"species_and_systems":"Structures and binding were of murine TIM-1; human TIM-1-Fc proteins also bound human TIM-1, with lower affinity than mTIM-1, using Fc proteins and receptor-coated beads on cells [PMID:17363299]. UniProt separately notes HAVCR1 on injured kidney tubular epithelial cells interacts with CD5L, which is a different partner [DB:UniProt].","localisation_and_range":"Membrane-bound adhesion receptor (flag: not secreted), so acts by cell contact [flag].","caveats":"Evidence is a single structural paper read as abstract by curators; no affinity value reported. The UniProt record concerns CD5L, not self-binding [DB:UniProt].","key_references":[{"PMID":"17363299","why":"Structure of mTIM-1 and homophilic binding, conserved in human TIM-1"}],"covers":["LR001836","LR005191"]},"LR000738":{"pair":"HBEGF -> ERBB4","headline":"HB-EGF binds and activates HER4 (ERBB4) in transfected cells and cardiac myocytes; supported by IntAct and Reactome records.","interaction_type":"direct binding","direction_and_effect":"HB-EGF bound NIH 3T3 cells overexpressing HER4 alone, independent of HER1, and induced HER4 tyrosine phosphorylation, PI3-K association and chemotaxis [PMID:9135143]. In mouse cardiac myocytes HB-EGF induced ErbB2 and ErbB4 phosphorylation [PMID:12621152]. It was not mitogenic for HER4-expressing cells [PMID:9135143].","molecular_requirements":"HER4 alone was sufficient for binding; HER2 or HER3 alone did not bind [PMID:9135143]. Coreceptor needs for signalling are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NIH 3T3 transfectants, MDA-MB-453 cells and astrocytes [PMID:9135143]; mouse in vivo [PMID:12621152]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted and transmembrane flags on HB-EGF [flag]; chemotactic factor acting on cells [PMID:9135143].","caveats":"Abstracts only. Reactome entry is generic ERBB4 binding of NRGs or EGF-like ligands [DB:Reactome R-HSA-1236398]; GtoPdb lists no action or affinity [DB:GtoPdb].","key_references":[{"PMID":"9135143","why":"HB-EGF binds and activates HER4"},{"PMID":"12621152","why":"HB-EGF induces ErbB4 phosphorylation in vivo"}],"covers":["LR000738","LR004220"]},"LR009342":{"pair":"HLA-A -> APLP2","headline":"Reported physical binding of APLP2 to HLA-A in tumour cell lines; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"APLP2 was found to bind HLA-A24, and more strongly HLA-A2 [PMID:19184004]. Effect and direction are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human tumour cell lines [PMID:19184004].","localisation_and_range":"Both partners are annotated as transmembrane [flag]; the pair is classed Receptor-Receptor.","caveats":"One paper, abstract only, with sparse methodological detail. Whether binding is direct is not shown in our evidence.","key_references":[{"PMID":"19184004","why":"APLP2 binds HLA-A24 and more strongly HLA-A2"}],"covers":["LR009342"]},"LR002718":{"pair":"HLA-A -> KIR2DS4","headline":"Full-length KIR2DS4 binds HLA-A*11 and some HLA-C; activation occurs with A*1102 but not A*1101; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Full-length KIR2DS4 binds specifically to subsets of C1+ and C2+ HLA-C and to HLA-A*11; activation of 2DS4+ NKL cells occurred with A*1102 but not A*1101 or HLA-C [PMID:19858347].","molecular_requirements":"Only full-length KIR2DS4 is functional; the deleted form is not a receptor. A proline-valine motif at positions 71-72 is largely responsible for the specificity [PMID:19858347].","affinity_potency":[],"species_and_systems":"Human proteins; KIR2D-Fc binding assays and NKL cell activation [PMID:19858347].","localisation_and_range":"Both annotated as transmembrane or receptors [flag]; contact-dependent.","caveats":"Allotype-specific: A*1102 and A*1101 differ by one Lys19-to-Glu substitution and behave differently. The paper also reports HLA-C binding.","key_references":[{"PMID":"19858347","why":"KIR2DS4 binds HLA-A*11 and activates NKL cells with A*1102"}],"covers":["LR002718"]},"LR000747":{"pair":"HLA-A -> KIR3DL2","headline":"NKAT4 (KIR3DL2) reported as a receptor specific for HLA-A3; one abstract-level functional paper from 1996.","interaction_type":"functional only","direction_and_effect":"NKAT4 encodes a 70-kDa receptor specific for HLA-A3; killer inhibitory receptors inhibit cytotoxicity on binding MHC class I [PMID:8617928]. The effect is inhibitory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NK-cell-related cDNA; experimental system details are not reported in our evidence [PMID:8617928].","localisation_and_range":"Both annotated as transmembrane or receptors [flag]; contact-dependent.","caveats":"One paper, read as an abstract; the abstract names NKAT4 and the link to KIR3DL2 comes from the curator's notes. Specific to HLA-A3, so other HLA-A alleles are not covered. Pair record says Stimulatory while the evidence is inhibitory. Two papers pending.","key_references":[{"PMID":"8617928","why":"NKAT4 is a receptor specific for HLA-A3"}],"covers":["LR000747"]},"LR000756":{"pair":"HLA-C -> KIR2DL3","headline":"Direct binding of HLA-C (C1 group) to KIR2DL3 by SPR, with Kd about 7 \u03bcM for HLA-Cw7; human systems.","interaction_type":"direct binding","direction_and_effect":"KIR2DL3 is an inhibitory NK receptor recognising HLA-C of group C1 (Asn80) [PMID:28352266]. HLA-Cw7 bound its NK inhibitory receptor specifically in SPR, with no cross-reactivity [PMID:9768753].","molecular_requirements":"KIR2DL3 bound HLA-Cw7 presenting peptide RYRPGTVAL at 1:1 stoichiometry [PMID:10497191]. Binding to C1 allotype was peptide-selective [PMID:28352266].","affinity_potency":[{"value":"Kd approximately 7 microM at 25 degrees C","assay":"surface plasmon resonance, soluble KIR2DL3 with HLA-Cw7/RYRPGTVAL","system":"recombinant human proteins","cite":"PMID:10497191"}],"species_and_systems":"Human recombinant proteins [PMID:10497191][PMID:9768753][PMID:28352266].","localisation_and_range":"HLA-C is annotated transmembrane [flag]; contact-dependent.","caveats":"All papers read as abstracts or excerpts. Kd is for one allele and peptide. PMID:9768753 names receptors NKAT1/NKAT2, with NKAT2 as the HLA-Cw7 partner.","key_references":[{"PMID":"10497191","why":"SPR Kd and 1:1 stoichiometry for KIR2DL3-HLA-Cw7"},{"PMID":"9768753","why":"SPR specificity of soluble HLA-C and NK receptors"},{"PMID":"28352266","why":"KIR2DL3-C1 binding peptide-selective"}],"covers":["LR000756"]},"LR010629":{"pair":"HLA-C -> LILRA3","headline":"Single abstract-level report that soluble LILRA3 prefers HLA-C free heavy chain; thinly supported.","interaction_type":"direct binding","direction_and_effect":"Soluble LILRA3 displayed a preference for binding HLA-C free heavy chain [PMID:21270408]. Signalling effect: not reported in our evidence.","molecular_requirements":"Prefers free (beta2-microglobulin-free) heavy chain; folded class I preference not reported for LILRA3 [PMID:21270408].","affinity_potency":[],"species_and_systems":"Human; binding survey of more than 90 HLA class I alleles [PMID:21270408].","localisation_and_range":"LILRA3 is described as a soluble protein [PMID:21270408], so it could act as a secreted binder; HLA-C is flagged transmembrane [flag].","caveats":"Abstract only; no affinity or assay details; one paper.","key_references":[{"PMID":"21270408","why":"LILR binding survey; soluble LILRA3 binds HLA-C free heavy chain"}],"covers":["LR010629"]},"LR002727":{"pair":"HLA-DRB1 -> CD4","headline":"Recombinant CD4 binds the DR4 beta chain directly (1992 abstract), with PDB structures of CD4 mutant with HLA-DR1.","interaction_type":"direct binding","direction_and_effect":"Soluble CD4 bound recombinant soluble DR4 heterodimers and the isolated DR4 beta chain alone [PMID:1574119]. Co-receptor effect: not reported in our evidence.","molecular_requirements":"The DR4 beta chain alone was sufficient; two of twelve DR4-beta peptides interacted with CD4, mapping the CD4-binding region to the beta2 domain (curator note) [PMID:1574119]. PDB 3S4S, 3S5L, 3T0E list a DRB1 chain with a CD4 chain [DB:PDB 3S4S].","affinity_potency":[],"species_and_systems":"Recombinant soluble human proteins [PMID:1574119].","localisation_and_range":"HLA-DRB1 flagged not secreted [flag].","caveats":"Abstract only; no affinity. The PDB records have no listed paper in this dossier.","key_references":[{"PMID":"1574119","why":"Soluble CD4 binds DR4 heterodimer and beta chain alone"}],"covers":["LR002727"]},"LR000765":{"pair":"HLA-G -> KLRD1","headline":"Conflicting: functional NK data suggest CD94 involvement, but curators judged three structural papers as negatives; ligand is HLA-E.","interaction_type":"conflicting","direction_and_effect":"Blocking CD94 reversed NK inhibition by HLA-G-transfected cells, with CD94 predominating among receptors [PMID:9405670]; CD94/NKG2A+ clones showed reduced lysis of HLA-G targets [PMID:9295021]. Effect is inhibitory (antagonist).","molecular_requirements":"CD94/NKG2 heterodimers bind HLA-E presenting peptides from class I leader sequences; in the crystal structure HLA-G supplies only the peptide [PMID:18332182].","affinity_potency":[],"species_and_systems":"Human NK cell lines and clones with transfected 721.221 cells [PMID:9405670, PMID:9295021].","localisation_and_range":"HLA-G flagged secreted [flag].","caveats":"Three papers are verified negatives: HLA-E is the CD94/NKG2 ligand and HLA-G is not [PMID:18083576, PMID:18332182, PMID:18448674]. A curator note says the 721.221-HLA-G transfectants unknowingly co-expressed HLA-E [PMID:9405670]. Functional papers read as abstracts only. PDB 3CDG is HLA-E-based [DB:PDB 3CDG].","key_references":[{"PMID":"9405670","why":"CD94 blocking reverses HLA-G inhibition of NK cells"},{"PMID":"18332182","why":"structure shows HLA-G only as HLA-E peptide"}],"covers":["LR000765"]},"LR002736":{"pair":"HMGB1 -> ITGB3","headline":"HMGB1 binds soluble integrin alphavbeta3 and colocalises with beta3 on macrophages; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"HMGB1 colocalised with beta3-integrin on macrophage membranes, bound soluble alphavbeta3 but not alphavbeta5, suppressed the MFG-E8-alphavbeta3 interaction and blocked alphavbeta3-dependent uptake of apoptotic cells [PMID:20826760]. This is an inhibitory effect on efferocytosis.","molecular_requirements":"Evidence is for the alphavbeta3 heterodimer; beta3 alone was not tested separately in our evidence [PMID:20826760].","affinity_potency":[],"species_and_systems":"Macrophages and soluble integrins; species not stated in the abstract. Curated as human; the mouse pair is ortholog-inferred.","localisation_and_range":"HMGB1 is flagged secreted [flag]; integrin is membrane-bound on macrophages [PMID:20826760].","caveats":"Single abstract-only paper, no affinity, and it is the same paper that supports the ITGAV pair, so the two are not independent.","key_references":[{"PMID":"20826760","why":"HMGB1 binds alphavbeta3 and colocalises with beta3"}],"covers":["LR002736","LR005984"]},"LR005193":{"pair":"HP -> CD163","headline":"Evidence concerns haptoglobin-HMGB1 complexes signalling via CD163; haptoglobin alone binding CD163 is database-supported.","interaction_type":"functional only","direction_and_effect":"Haptoglobin-HMGB1 complexes induce heme oxygenase-1 and IL-10 in wild-type but not CD163-deficient macrophages; loss of haptoglobin or CD163 enhances mortality in mouse sepsis models [PMID:27294203]. Reactome lists haptoglobin:hemoglobin binding CD163 [DB:Reactome].","molecular_requirements":"The paper's active ligand is the haptoglobin-HMGB1 complex, not haptoglobin alone [PMID:27294203]. Haptoglobin-hemoglobin binding of CD163 is described in Reactome [DB:Reactome]; PDB lists structures with chains of P00738 and Q86VB7 [DB:PDB 8XMP].","affinity_potency":[],"species_and_systems":"Macrophages and mouse sepsis models; curated as human proteins [PMID:27294203]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Paper read as abstract only. CD163 uptake of haptoglobin is described in the paper as established background, not tested here [PMID:27294203].","key_references":[{"PMID":"27294203","why":"Haptoglobin-HMGB1 complexes act via CD163 in macrophages and mouse sepsis"}],"covers":["LR001844","LR005193"]},"LR002745":{"pair":"HP -> TLR4","headline":"Haptoglobin is reported to act as a TLR4 ligand in osteoclast cultures; functional evidence only.","interaction_type":"functional only","direction_and_effect":"Haptoglobin stimulates IFN-beta via a TLR4-dependent mechanism, which reduces c-Fos and inhibits osteoclastogenesis; Hp-deficient mice show reduced bone volume and more osteoclasts [PMID:31076532].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Osteoclast precursor cultures and Hp-deficient mice; curated as human on both sides [PMID:31076532]. The mouse pair is ortholog-inferred.","localisation_and_range":"HP is flagged as secreted [flag].","caveats":"Abstract-only reading; no binding measurement is reported, only TLR4-dependence of the IFN-beta response.","key_references":[{"PMID":"31076532","why":"Haptoglobin induces IFN-beta via TLR4 and suppresses osteoclastogenesis"}],"covers":["LR002745","LR005993"]},"LR000774":{"pair":"HSP90B1 -> TLR4","headline":"Gp96 activates dendritic cells through TLR4 in mouse experiments; functional evidence only.","interaction_type":"functional only","direction_and_effect":"The Gp96-TLR2/4 interaction activates NF-kappaB reporters and MAPK/MSK, and induces IkappaBalpha degradation; bone-marrow dendritic cells from TLR4-mutant C3H/HeJ mice, and more markedly from C3H/HeJ TLR2-/- mice, fail to respond [PMID:11912201].","molecular_requirements":"Response requires Gp96 endocytosis; the paper names TLR2 and TLR4 together as a pathway [PMID:11912201]. UniProt states HSP90B1 interacts with TLR4 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Mouse dendritic cells and TLR-expressing cell lines [PMID:11912201]. The mouse pair is ortholog-inferred.","localisation_and_range":"HSP90B1 carries no secreted flag [flag]; described as an ER-resident protein acting after release [PMID:11912201].","caveats":"Abstract-only reading; no direct binding or affinity reported, and the effect is not separated between TLR2 and TLR4.","key_references":[{"PMID":"11912201","why":"Gp96 activates DCs via TLR2/4; knockout cells fail to respond"}],"covers":["LR000774","LR004233"]},"LR002754":{"pair":"HSPA4 -> TLR4","headline":"Mouse-cell functional evidence (abstract only) for released Hsp70 acting via TLR4; one BioGRID pull-down record. Human pair is ortholog-projected.","interaction_type":"functional only","direction_and_effect":"Hsp70 released in membrane vesicles by mouse mesoangioblasts interacts in an autocrine manner with TLR4 and CD91 to stimulate migration [PMID:27925208].","molecular_requirements":"CD91 is co-named as an interacting receptor; whether TLR4 acts alone is not reported in our evidence [PMID:27925208].","affinity_potency":[],"species_and_systems":"Mouse mesoangioblasts in vitro [PMID:27925208]. BioGRID lists an HSPA4 - TLR4 Affinity Capture-Western record; its species and system are not reported in our evidence [DB:BioGRID].","localisation_and_range":"HSPA4 is flagged secreted [flag]; autocrine action after vesicle release is reported [PMID:27925208].","caveats":"Paper read as abstract only; no affinity. The paper's protein is called Hsp70. The BioGRID record is an affinity-capture result, which is weaker than direct binding.","key_references":[{"PMID":"27925208","why":"Autocrine Hsp70 via TLR4 and CD91 in mouse mesoangioblast migration"}],"covers":["LR002754","LR006001"]},"LR006831":{"pair":"HTN1 -> TMEM97","headline":"Histatin-1 is reported as an endogenous ligand of TMEM97 (sigma-2 receptor), with radioligand Ki 239 nm and co-immunoprecipitation in corneal cells.","interaction_type":"direct binding","direction_and_effect":"Synthetic histatin-1 bound TMEM97 in HEK293T membranes in a radioligand assay, and TMEM97 antibody co-precipitated histatin-1 from human corneal epithelial cells; curators label it an agonist [PMID:34233061]. GtoPdb and UniProt record the interaction [DB:GtoPdb] [DB:UniProt].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[{"value":"Ki 239 nm","assay":"radioligand competition binding (haloperidol reference 44 nm)","system":"HEK293T membranes containing TMEM97","cite":"PMID:34233061"}],"species_and_systems":"Human proteins; HEK293T membranes and human corneal epithelial (HCE) cells [PMID:34233061].","localisation_and_range":"The paper calls TMEM97 an endoplasmic reticular protein; UniProt places the interaction at the ER membrane, so this may be intracellular rather than a cell-surface paracrine pair [PMID:34233061] [DB:UniProt].","caveats":"Only one paper. ER localisation means a surface pool must be assumed for cell-cell signalling inference.","key_references":[{"PMID":"34233061","why":"Histatin-1 as endogenous sigma-2/TMEM97 ligand: Ki and co-IP"}],"covers":["LR006831"]},"LR007092":{"pair":"IAPP -> CALCR:RAMP3","headline":"Database-asserted only: UniProt describes CALCR with RAMP3 as an amylin receptor; no curated paper confirms this specific complex.","interaction_type":"database-asserted only","direction_and_effect":"Together with CALCR, RAMP3 acts as a receptor complex for amylin/IAPP [DB:UniProt]. GtoPdb lists full agonist records for IAPP-CALCR [DB:GtoPdb].","molecular_requirements":"Requires CALCR plus RAMP3 per UniProt [DB:UniProt]; PDB 8F0K is a Gs complex of the human Amylin3 receptor with a pramlintide analogue [DB:PDB 8F0K].","affinity_potency":[],"species_and_systems":"Species and experimental system of the database records are not reported in our evidence.","localisation_and_range":"IAPP is flagged secreted and the complex transmembrane [flag].","caveats":"No curated paper: one row different_entity and one abstract_insufficient. GtoPdb entries are for IAPP-CALCR rather than the complex.","key_references":[],"covers":["LR007092"]},"LR004239":{"pair":"IAPP -> RAMP3","headline":"Amylin signals through CALCR with RAMP3 (AMY3); supported by cAMP pharmacology and a tumour study, with RAMP3 not shown to act alone.","interaction_type":"functional only","direction_and_effect":"Amylin and pramlintide activated all three AMY receptors in a cAMP response [PMID:24169554]. In a cancer paper, amylin acted through CalcR and RAMP3 to inhibit glycolysis and induce reactive oxygen species and apoptosis; knockdown of CALCR or RAMP3 prevented these effects [PMID:25409149]. GtoPdb lists a full agonist (pEC50 8.6 to 10.8) [DB:GtoPdb].","molecular_requirements":"Both CALCR and RAMP3 were needed in the knockdown experiments [PMID:25409149]. UniProt says RAMP3 with CALCR acts as the amylin receptor [DB:UniProt]. Structures of the human Amylin3 receptor with Gs exist [DB:PDB 8F0K].","affinity_potency":[{"value":"pEC50 8.6 to 10.8","assay":"GtoPdb agonist record","system":"not reported in our evidence","cite":"DB:GtoPdb"}],"species_and_systems":"HEK293S and COS-7 cells [PMID:24169554]; human H1299 cells and p53-null mice [PMID:25409149]. Mouse pair is ortholog-inferred.","localisation_and_range":"Paper text states IAPP is a secreted protein [PMID:25409149]; RAMP3 is flagged transmembrane [flag].","caveats":"Both abstracts were read for the cAMP paper; the tumour paper had full text. The tumour paper's effect is on downstream cell behaviour in a mixed knockdown setting, and curators labelled the effect as antagonist, which refers to tumour inhibition, not receptor antagonism.","key_references":[{"PMID":"24169554","why":"cAMP activation at AMY1-3 receptors"},{"PMID":"25409149","why":"Amylin needs CALCR and RAMP3 for anti-tumour effects"}],"covers":["LR000781","LR004239"]},"LR000783":{"pair":"ICAM1 -> IL2RA","headline":"One 1990 abstract reports ICAM-1 physically associated with the IL-2 receptor alpha chain on T cells; association rather than ligand binding.","interaction_type":"functional only","direction_and_effect":"A 95-kDa protein identified as ICAM-1 was cross-linked by radiolabeled IL-2 on activated T cells, indicating physical proximity to the IL-2 receptor alpha subunit [PMID:1976256]. The abstract says it interacts physically with the high-affinity IL-2 receptor; direction and agonist or antagonist effect are not reported in our evidence.","molecular_requirements":"Proximity to the alpha subunit of the multichain high-affinity IL-2 receptor [PMID:1976256].","affinity_potency":[],"species_and_systems":"Human activated T cells; methods were purification, immunoprecipitation and IL-2 cross-linking [PMID:1976256].","localisation_and_range":"Both are cell-surface proteins in a cis arrangement on T cells; not stated as a secreted signal [PMID:1976256].","caveats":"Abstract only. This is a cell-surface association, not a demonstrated ligand-receptor interaction, and the evidence is old and single-paper. Cross-linking by IL-2 does not show ICAM-1 binds IL2RA directly.","key_references":[{"PMID":"1976256","why":"ICAM-1 identified as p95 near IL-2 receptor alpha"}],"covers":["LR000783"]},"LR001845":{"pair":"ICAM1 -> SPN","headline":"ICAM-1 reported as a ligand for CD43 (sialophorin) in a single 1991 abstract-level paper; thin evidence.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 was identified as a ligand for CD43; Daudi cells bound immobilised CD43, and CD43 expression in a murine T-cell hybridoma enhanced antigen-specific response to Daudi cells [PMID:1683685]. Effect direction is not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human CD43 expressed in a murine HLA-DR-specific T-cell hybridoma, with human Daudi cells and purified immobilised CD43 [PMID:1683685]. Mouse pair is ortholog-inferred.","localisation_and_range":"Both partners are membrane-bound (cell-cell contact) in the experiment [PMID:1683685]; ICAM1 also carries a secreted flag [flag].","caveats":"Abstract only; no affinity. IntAct lists a solid-phase assay for this pair (PMID 35922511) [DB:IntAct], but no detail beyond that.","key_references":[{"PMID":"1683685","why":"Original report of ICAM-1 as a CD43 ligand"}],"covers":["LR001845","LR005194"]},"LR004248":{"pair":"ICAM2 -> ITGB2","headline":"ICAM-2 acts on beta2 integrins mainly through LFA-1; support is abstract-level mutagenesis and an adhesion study.","interaction_type":"functional only","direction_and_effect":"LFA-1 alpha-chain (CD11a) I-domain mutations defined a binding surface for ICAM-1 and ICAM-2; Lys-263-to-alanine preferentially abolished ICAM-2 binding, and Thr-175-to-alanine reduced ICAM-2 binding ~70% [PMID:9786897]. Pig ICAM-2 supported firm adhesion of human LFA-1 cells [PMID:15023143].","molecular_requirements":"ITGB2 is the shared beta chain; the mutational evidence maps to the alpha chain (CD11a) I-domain [PMID:9786897]. UniProt describes ITGAL:ITGB2 as the receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human LFA-1 mutants [PMID:9786897]; pig ICAM-2 with human LFA-1 in transfectants [PMID:15023143]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane-bound; contact-dependent adhesion.","caveats":"Both abstract-only; the beta chain itself is not shown to bind ICAM-2 alone. Four abstract_insufficient and one pending row not shown.","key_references":[{"PMID":"9786897","why":"Mutagenesis mapping of the LFA-1 I-domain surface for ICAM-2"}],"covers":["LR000790","LR004248"]},"LR000792":{"pair":"ICAM3 -> ITGAD","headline":"ICAM-3 is preferentially bound by integrin alpha-D/beta-2 (discovery paper); one abstract plus BioGRID and UniProt records.","interaction_type":"direct binding","direction_and_effect":"The alphaD beta2 leukointegrin binds preferentially to ICAM-3 [PMID:8777714]; UniProt lists ICAM-3 as a ligand of ITGAD/ITGB2 [DB:UniProt].","molecular_requirements":"Binding is of the alphaD/CD18 heterodimer, so ITGB2 is also needed [PMID:8777714].","affinity_potency":[],"species_and_systems":"Species not specified in the curated fields [PMID:8777714].","localisation_and_range":"Membrane-bound adhesion; contact-dependent.","caveats":"Abstract only; no affinity. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"8777714","why":"Discovery of alphaD/CD18 binding preferentially to ICAM-3"}],"covers":["LR000792"]},"LR004257":{"pair":"ICAM5 -> ITGAL","headline":"Direct LFA-1 binding to ICAM-5 domain 1 is supported by human binding assays, a crystal structure record and UniProt.","interaction_type":"direct binding","direction_and_effect":"ICAM-5 domain 1 supports CD11a/CD18 interaction; deleting it abolishes binding, and antibodies to domain 1 block it [PMID:10741396]. LFA-1-mediated HL-60 adhesion to recombinant telencephalin was seen, curated as agonist [PMID:8995416]. PDB 3BN3 holds ICAM5 and ITGAL chains [DB:PDB 3BN3]; IntAct lists X-ray crystallography [DB:IntAct].","molecular_requirements":"The alphaL chain (LFA-1) is the partner. Only domain 1 of ICAM-5 is needed; domain 6 also supports leukocyte binding, possibly not via integrins [PMID:10741396]. Binding was divalent-cation- and PMA-independent, unlike canonical LFA-1 ligand binding [PMID:8995416].","affinity_potency":[{"value":"50 nM","assay":"lowest soluble ICAM-5 domain 1 concentration that inhibited T-cell binding to immobilized ICAM-5","system":"human T cells, immobilized ICAM-5","cite":"PMID:10741396"}],"species_and_systems":"Human ICAM-5 and LFA-1; human T cells binding rat hippocampal neurons [PMID:10741396]; HL-60 cells [PMID:8995416]. Mouse pair ortholog-inferred.","localisation_and_range":"ICAM5 carries a secreted flag only [flag]; the cloning paper reports a single transmembrane region [PMID:8995416] and neuron-leukocyte adhesion is described in UniProt [DB:UniProt]: contact-dependent.","caveats":"Two papers shown are abstract only; two further confirmed rows and one pending row are not shown. The 50 nM figure is an inhibition concentration, not a Kd.","key_references":[{"PMID":"10741396","why":"Domain 1 of ICAM-5 binds CD11a/CD18; T cell-neuron assay"},{"PMID":"8995416","why":"LFA-1-mediated adhesion to human telencephalin"}],"covers":["LR000803","LR004257"]},"LR002763":{"pair":"IFNA1 -> CR2","headline":"Direct binding of IFN-alpha to CR2 by SPR and ELISA in one paper; unusual non-IFNAR receptor.","interaction_type":"direct binding","direction_and_effect":"CR2 binds IFN-alpha in the same affinity range as C3d/iC3b, EBV-gp350 and CD23. Anti-CR2 mAb 171 diminished IFN-alpha-responsive gene induction in human B cells [PMID:16785534]. The curator labelled it agonist.","molecular_requirements":"IFN-alpha binds CR2 short consensus repeat domains 1 and 2, the site used by the three other ligands [PMID:16785534].","affinity_potency":[],"species_and_systems":"Human proteins; SPR, ELISA and purified human peripheral blood B cells [PMID:16785534]. The mouse pair is ortholog-inferred.","localisation_and_range":"IFNA1 is flagged secreted and CR2 transmembrane [flag].","caveats":"Abstract only; the abstract says IFN-alpha generally, so IFNA1 specifically is an inference [PMID:16785534]. No numeric affinity reported. UniProt and BioGRID list the pair [DB:UniProt] [DB:BioGRID].","key_references":[{"PMID":"16785534","why":"SPR/ELISA binding of IFN-alpha to CR2 SCR1-2"}],"covers":["LR002763","LR006010"]},"LR004266":{"pair":"IFNA1 -> IFNAR2","headline":"Direct binding of IFNA1 to IFNAR2, but notably weak (220 nM) compared with other alpha subtypes.","interaction_type":"direct binding","direction_and_effect":"IFNA1 is an agonist of IFNAR2 in GtoPdb [DB:GtoPdb].","molecular_requirements":"IFNAR2 is one chain of the IFNAR1/IFNAR2 receptor [PMID:17174979]. Chain-level evidence.","affinity_potency":[{"value":"220 nM (IFN-alpha1)","assay":"binding affinity of isolated receptor chain","system":"human, isolated IFNAR2","cite":"PMID:21856167"},{"value":"0.4-5 nM (other alpha-IFNs)","assay":"as above","system":"human","cite":"PMID:21856167"}],"species_and_systems":"Human recombinant systems [PMID:21856167] [PMID:17174979]. A docking study used IFN-alpha 2 [PMID:11698684].","localisation_and_range":"IFNA1 is flagged secreted [flag].","caveats":"IFNA1 shows a substantial decrease in affinity for ifnar2 [PMID:17174979]. 11698684 is computational and studies IFN-alpha 2. Two papers are abstract only.","key_references":[{"PMID":"21856167","why":"Reports the 220 nM IFN-alpha1 outlier"},{"PMID":"17174979","why":"IFN\u03b11 reduced ifnar2 affinity"}],"covers":["LR000814","LR004266"]},"LR007272":{"pair":"IFNA17 -> IFNAR1:IFNAR2","headline":"IFNA17 to the IFNAR1:IFNAR2 heterodimer rests on class-wide binding data for each chain.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM and IFNAR2 at 0.4-5 nM [PMID:21856167]. GtoPdb lists IFNA17 as an agonist at both chains [DB:GtoPdb].","molecular_requirements":"Both chains are listed; each binds separately, IFNAR2 much more tightly [PMID:21856167]. Binding to the assembled heterodimer is not reported in our evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"},{"value":"0.4-5 nM","assay":"IFNAR2 chain affinity for human alpha-IFN subtypes (class-wide; IFN-alpha1 220 nM)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single verified paper, abstract only, class-wide values with no value for IFNA17; one further row was review only.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR007272"]},"LR011718":{"pair":"IFNA4 -> IFNA2:IFNAR1:IFNAR2","headline":"IFNA4 to the IFNA2:IFNAR1:IFNAR2 entry is supported only by database records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNA4 as agonist at IFNAR1 and IFNAR2 [DB:GtoPdb]. IntAct records co-immunoprecipitation associations from anti-tag pulldowns [DB:IntAct, PMID:28514442, PMID:33961781]; the partners in those records are not specified in our evidence.","molecular_requirements":"The receptor entry lists IFNA2, IFNAR1 and IFNAR2 together; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pair. Species and system of the database experiments are not reported in our evidence.","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"No paper row was verified for this complex (pending only). Support rests on database records.","key_references":[],"covers":["LR011718"]},"LR000819":{"pair":"IFNA4 -> IFNAR1","headline":"IFNA4 binds IFNAR1 only on class-wide evidence from one abstract; the chain is the weak-affinity subunit.","interaction_type":"direct binding","direction_and_effect":"Alpha-IFNs, as a class of 12 human subtypes, bind IFNAR1 at 0.5-5 \u03bcM [PMID:21856167]. GtoPdb lists IFNA4 as an agonist at IFNAR1 [DB:GtoPdb].","molecular_requirements":"IFNAR1 binds about 1000-fold more weakly than IFNAR2 per the curator's reading; IFNAR2 is the tighter chain [PMID:21856167]. Chain-only evidence.","affinity_potency":[{"value":"0.5-5 \u03bcM","assay":"IFNAR1 chain affinity for human alpha-IFN subtypes (class-wide; subtype not individually named in abstract)","system":"isolated human receptor chains","cite":"PMID:21856167"}],"species_and_systems":"Human alpha-IFN subtypes and human isolated receptor chains; affinity determination, abstract only [PMID:21856167].","localisation_and_range":"Ligand carries a secreted flag [flag]; range otherwise not reported in our evidence.","caveats":"Single paper, abstract only, no subtype-specific value for IFNA4. Binding is to the isolated chain, not the functional heterodimer.","key_references":[{"PMID":"21856167","why":"Class-wide affinities of 12 human alpha-IFN subtypes for IFNAR1 and IFNAR2 (abstract only)."}],"covers":["LR000819"]},"LR000828":{"pair":"IFNA8 -> IFNAR2","headline":"IFNA8 binds IFNAR2 as a type I interferon agonist; support is a class-wide binding study plus GtoPdb.","interaction_type":"direct binding","direction_and_effect":"IFNA8 acts as an agonist on the type I interferon receptor; the curator-verified study reports binding of human alpha-IFN subtypes to isolated receptor chains [PMID:21856167]. GtoPdb lists this as an agonist interaction with no affinity units [DB:GtoPdb].","molecular_requirements":"IFNAR2 is the tight-binding chain (0.4-5 nM) and IFNAR1 the weak one (0.5-5 \u03bcM) for alpha-IFNs [PMID:21856167]. Whether the pair needs both chains for signalling is not reported in our evidence beyond this binding comparison.","affinity_potency":[{"value":"0.4-5 nM","assay":"affinity and rate-constant determination, 12 human alpha-IFN subtypes collectively, isolated IFNAR2 chain","system":"human proteins","cite":"PMID:21856167"}],"species_and_systems":"Human ligand and human receptor chains, isolated recombinant chains (abstract-level reading) [PMID:21856167].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal.","caveats":"The affinity range is stated for 'Alpha-IFNs' as a class, not IFNA8 individually; only IFN-alpha1 (220 nM) is singled out as weaker, and the paper was read as an abstract only [PMID:21856167]. The second paper concerns IFN-beta engagement of IFNAR2.2 in Daudi cells and reports IFNAR2.2 was not detected with IFNAR1 after IFN-alpha stimulation [PMID:8969169]; the curator note says IFNA8 itself is not individually shown there, so it is weak support for this pair.","key_references":[{"PMID":"21856167","why":"binding of 12 human alpha-IFN subtypes to isolated IFNAR1 and IFNAR2"},{"PMID":"8969169","why":"IFNAR2.2 receptor-association phosphoprotein work in Daudi cells"}],"covers":["LR000828"]},"LR007281":{"pair":"IFNE -> IFNAR1:IFNAR2","headline":"IFNE signals through the IFNAR1:IFNAR2 heterodimer in mouse; functional evidence only.","interaction_type":"functional only","direction_and_effect":"IFN-\u03b5 signalled via Ifnar1 and Ifnar2 to induce IFN-regulated genes [PMID:23449591].","molecular_requirements":"Both Ifnar1 and Ifnar2 are named; the heterodimer is the receptor unit [PMID:23449591].","affinity_potency":[],"species_and_systems":"Mouse female reproductive tract epithelial cells and Ifn-\u03b5-deficient mice; the pair here is human, with no human experiment in our evidence [PMID:23449591].","localisation_and_range":"Ligand is flagged secreted and not transmembrane [flag], so it acts as a diffusible paracrine or endocrine signal. Constitutively expressed by reproductive tract epithelium and hormonally regulated [PMID:23449591].","caveats":"No binding data, no database records, abstract-only reading.","key_references":[{"PMID":"23449591","why":"IFN-\u03b5 signals via Ifnar1/Ifnar2"}],"covers":["LR007281"]},"LR008442":{"pair":"IFNG -> IFNGR2","headline":"IFN-gamma to IFNGR2 as a standalone binding pair is not supported; IFNGR2 is an accessory chain of the IFNGR1 receptor.","interaction_type":"conflicting","direction_and_effect":"IFN-gamma acts as an agonist on the receptor complex; GtoPdb lists Agonist for IFNG-IFNGR2 [DB:GtoPdb]. The single curated paper is a verified negative for this single-chain pair: it assigns ligand binding to IFNGR1 and calls IFNGR2 a transmembrane accessory factor necessary for signal transduction [PMID:7673114].","molecular_requirements":"IFNGR2 depends on IFNGR1: the same abstract reports an IFN-gamma R2:IFN-gamma cross-linked complex only in cells expressing both chains, with IFNGR2 closely associated with IFNGR1 [PMID:7673114]. UniProt says IFNGR2 associates with IFNGR1 to form the receptor [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human; reconstituted cell lines [PMID:7673114].","localisation_and_range":"IFNG is flagged secreted and non-transmembrane [flag], so it is expected to act at a distance (paracrine/endocrine); the receptor is flagged transmembrane [flag].","caveats":"Paper judged pair_absent; the evidence is abstract-only. Database records (BioGRID reconstituted complex, PDB 6E3K and 6E3L, Reactome) do list IFNG with IFNGR2, which may reflect complex membership [DB:PDB 6E3K]. Use the IFNG -> IFNGR1:IFNGR2 complex row instead.","key_references":[{"PMID":"7673114","why":"explicit negative for single-chain IFNGR2 binding; accessory role"}],"covers":["LR008442"]},"LR001854":{"pair":"IFNK -> IFNAR2","headline":"Recombinant human IFN-kappa binds IFNAR2 only weakly; this explains its low cellular potency.","interaction_type":"direct binding","direction_and_effect":"IFN-kappa is an agonist; GtoPdb lists Agonist [DB:GtoPdb]. Cellular potency was about 1000-fold lower than IFNalpha2 and IFNomega, consistent with weak affinity for the IFNAR2 chain [PMID:30171073].","molecular_requirements":"IFN-kappa signals through the IFNAR1/IFNAR2 complex; its IFNAR2 affinity is reduced while its IFNAR1 affinity is similar to other IFNs [PMID:30171073].","affinity_potency":[],"species_and_systems":"Recombinant human IFN-kappa, protein affinity characterisation [PMID:30171073]. Mouse pair is projected from human (ortholog inferred).","localisation_and_range":"IFNK is flagged secreted and non-transmembrane [flag].","caveats":"Abstract-only read; no numeric affinity in our evidence. The weak binding is measurable but low.","key_references":[{"PMID":"30171073","why":"IFN-kappa shows weak IFNAR2 affinity and low potency"}],"covers":["LR001854","LR005202"]},"LR011727":{"pair":"IFNL3 -> IFNL3:IFNLR1:IL10RB","headline":"IFN-lambda3 to a complex listing IFNL3, IFNLR1, IL10RB: no verified evidence, GtoPdb records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IFNL3-IFNLR1 and IFNL3-IL10RB as Agonist [DB:GtoPdb]. All three attached papers are still pending curation.","molecular_requirements":"The complex lists IFNL3 itself as a member [flag], so the composition is questionable; the true receptor subunits would be IFNLR1 and IL10RB, which is not reported for this row in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"IFNL3 is flagged secreted and non-transmembrane [flag].","caveats":"No papers were verified; support is from a database only.","key_references":[],"covers":["LR011727"]},"LR000837":{"pair":"IFNL3 -> IL10RB","headline":"IFN-lambda3 and IL10RB: IL10RB joins the IFNL3/IFNLR1 complex with very low affinity.","interaction_type":"functional only","direction_and_effect":"IFN-lambda3 is an agonist; GtoPdb lists Agonist for IFNL3-IL10RB [DB:GtoPdb]. IL-28 and IL-29 interact with a receptor of IL-10Rbeta and IL-28Ralpha [PMID:12469119].","molecular_requirements":"IL10RB does not bind IFN-lambda3 alone: binding was not detected to monomeric or tetrameric IL-10Rbeta without IFN-lambda R1 present [PMID:28329704]. It recognises the IFN-lambda3/IFN-lambda R1 binary complex with very low affinity [PMID:28329704].","affinity_potency":[{"value":"KD = 560 nM","assay":"surface plasmon resonance, IL-10Rbeta to engineered H11/IFN-lambda R1 complex (30-fold higher than wild-type complex)","system":"recombinant proteins","cite":"PMID:28329704"},{"value":"on-yeast KD of 200 nM","assay":"yeast display, H11 variant to IL-10Rbeta","system":"yeast-displayed IFN-lambda3 variant","cite":"PMID:28329704"}],"species_and_systems":"Human, human cells [PMID:12469119]; recombinant proteins and crystal structure [PMID:28329704].","localisation_and_range":"IFNL3 is flagged secreted and non-transmembrane [flag].","caveats":"Affinities are for the engineered H11 variant; the wild-type value is not stated in the excerpts. Abstract plus excerpts only.","key_references":[{"PMID":"28329704","why":"IL-10Rbeta recognition of the ligand/IFNLR1 complex"},{"PMID":"12469119","why":"receptor identification"}],"covers":["LR000837"]},"LR006813":{"pair":"IGF1 -> INSR","headline":"No paper in our evidence; support rests on structures and database annotations of IGF1 binding the insulin receptor.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IGF1 as an agonist of INSR [DB:GtoPdb]; UniProt states the insulin receptor can bind IGF-I and IGF-II [DB:UniProt].","molecular_requirements":"A UniProt entry notes hybrid IGF1R:INSR receptors (long or short INSR isoform) bind IGF1, with low affinity for insulin [DB:UniProt]. Structures of IGF-I with a hybrid INSR/IGF1R head region exist [DB:PDB 4XSS] [DB:PDB 7S0Q].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond structures (X-ray, cryo-EM) [DB:PDB 4XSS].","localisation_and_range":"IGF1 is flagged secreted and INSR transmembrane [flag].","caveats":"No curator-verified paper supports this pair; papers judged were abstract-insufficient, review-only or a different entity. Several structures are of hybrid receptors, so INSR-alone binding is not separated. A competition-binding record exists in IntAct but without values [DB:IntAct].","key_references":[],"covers":["LR006813"]},"LR004275":{"pair":"IGF2 -> INSR","headline":"Genetic mouse evidence that IGF-II signals partly through the insulin receptor; no direct binding paper in our evidence.","interaction_type":"functional only","direction_and_effect":"Mouse embryos lacking both Igf1r and Insr were as growth-retarded (30% of normal size at birth) as Igf1r/Igf2 double mutants, giving genetic evidence that IGF-II growth promotion is mediated in part by the insulin receptor [PMID:9281335]. Structures of IGF2 with INSR exist [DB:PDB 8U4C].","molecular_requirements":"Not reported in our evidence; IGF1R-null background was needed to reveal the INSR contribution [PMID:9281335].","affinity_potency":[],"species_and_systems":"In vivo knockout mice [PMID:9281335]; the human pair is ortholog-inferred from this mouse work.","localisation_and_range":"IGF2 is flagged secreted and INSR transmembrane [flag].","caveats":"Evidence is indirect genetics, read as abstract only, and does not show binding or isoform. No affinity is reported in our evidence.","key_references":[{"PMID":"9281335","why":"Igf1r/Insr double-null mouse genetics"}],"covers":["LR000843","LR004275"]},"LR002772":{"pair":"IGF2 -> ITGB4","headline":"Integrin alpha6beta4 binds IGF2 in one verified study; ITGB4 is the beta chain.","interaction_type":"direct binding","direction_and_effect":"IGF2 specifically bound integrins alphavbeta3 and alpha6beta4 and induced proliferation of IGF1R-positive CHO cells expressing either integrin [PMID:28873464]. Integrin-binding-defective IGF2 mutants (Arg to Glu at 24, 34, 37 and/or 38) suppressed wild-type IGF2 proliferation, suggesting dominant-negative IGF1R antagonism [PMID:28873464]. UniProt agrees [DB:UniProt].","molecular_requirements":"The alpha6beta4 heterodimer was tested; ITGB4 alone is not shown [PMID:28873464].","affinity_potency":[],"species_and_systems":"CHO cells expressing recombinant integrins, ELISA-type binding with soluble alphavbeta3, and adhesion assays; anchorage-independent conditions [PMID:28873464]. Mouse pair is ortholog-inferred.","localisation_and_range":"IGF2 is flagged secreted [flag].","caveats":"The single supporting paper is the same for several integrin chain rows; evidence concerns the heterodimer. No affinity is reported in our evidence.","key_references":[{"PMID":"28873464","why":"IGF2 binds alphavbeta3 and alpha6beta4; C-domain Arg mutants"}],"covers":["LR002772","LR006018"]},"LR010971":{"pair":"IGFBP6 -> IGF2","headline":"Database-supported IGFBP6-IGF2 binding with inhibitory label; no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"Annotated as inhibitory; Reactome lists an IGF:IGFBP6 complex [DB:Reactome].","molecular_requirements":"No subunit requirements reported.","affinity_potency":[],"species_and_systems":"Human only; BioGRID lists a reconstituted complex and IntAct an anti-tag co-immunoprecipitation [DB:BioGRID][DB:IntAct].","localisation_and_range":"IGF2 is annotated as secreted [flag]; IGFBP6 has no localisation flag.","caveats":"No curator-verified paper (three candidates judged as a different entity, one review only). Database records only; no affinity.","key_references":[],"covers":["LR010971"]},"LR000846":{"pair":"IGFL1 -> IGFLR1","headline":"IGFL1 binds IGFLR1 with high affinity (radioligand and SPR) in a full-text study.","interaction_type":"direct binding","direction_and_effect":"IGFL1 bound cells expressing IGFLR1 specifically, not the TNFR-family members NGFR or DR4; curator effect: agonist, but signalling outcome is not reported in our evidence [PMID:21454693].","molecular_requirements":"IGFLR1 was found by protein microarray as the top hit; no co-receptor reported [PMID:21454693].","affinity_potency":[{"value":"K 0.31 nDm (as printed)","assay":"radioligand binding, IGFL1 to IGFLR1-expressing cells","system":"IGFLR1-expressing cells","cite":"PMID:21454693"}],"species_and_systems":"Human IGFL1 and IGFLR1; recombinant IGFL1 mostly disulfide-linked dimer; HEK293T transfectants [PMID:21454693].","localisation_and_range":"IGFL1 is annotated as secreted and IGFLR1 as transmembrane [flag]; the paper says IGFLR1 is expressed primarily on mouse T-cell surfaces [PMID:21454693].","caveats":"The unit in the excerpt is printed 'nDm'; presumably nM but not stated. IntAct records come from the same paper [DB:IntAct].","key_references":[{"PMID":"21454693","why":"Protein microarray, cell binding, radioligand and SPR for IGFL1-IGFLR1"}],"covers":["LR000846"]},"LR002781":{"pair":"IGHG1 -> FCGR3B","headline":"Human IgG1 binds the Fc receptor CD16 in a crystal structure and in a binding screen; evidence is from abstracts only.","interaction_type":"direct binding","direction_and_effect":"IgG1 Fc binds the soluble receptor in a 1:1 complex, contacting both halves of the Fc at the C gamma2 domains and hinge [PMID:10917521]. IgG1 binds all human FcgammaRs including FcgammaRIIIB [PMID:19018092]. Signalling effect is not reported in our evidence.","molecular_requirements":"The receptor contacts both halves of the Fc fragment; the Fc opens asymmetrically on binding [PMID:10917521]. The structural paper names the receptor as FcgammaRIII (CD16) without separating FCGR3A from FCGR3B [PMID:10917521].","affinity_potency":[],"species_and_systems":"Human IgG1 Fc and human soluble receptor, crystallography [PMID:10917521]; recombinant binding across human FcgammaRs and variants [PMID:19018092]. PDB entries 1E4K, 1T83, 1T89 list IgG1 and the receptor chain [DB:PDB 1E4K].","localisation_and_range":"IGHG1 is flagged secreted [flag]; FCGR3B is flagged as a receptor [flag]. Range from annotation only.","caveats":"Both papers were read as abstracts only. The 3.2 A structure abstract does not resolve FCGR3A versus FCGR3B. Affinity values are not given in the abstracts.","key_references":[{"PMID":"10917521","why":"Crystal structure of IgG1 Fc with soluble FcgammaRIII"},{"PMID":"19018092","why":"IgG1 binds all human FcgammaRs including IIIB"}],"covers":["LR002781"]},"LR004284":{"pair":"IL10 -> IL10RB","headline":"IL10RB is an accessory signalling chain for IL-10; evidence is functional and from an abstract.","interaction_type":"functional only","direction_and_effect":"Co-expressing CRFB4 (IL10RB) with IL-10R1 makes hamster cells sensitive to IL-10, whereas IL-10R1 alone binds but does not signal [PMID:9312047]. The IL-10:CRFB4 complex was detected by cross-linking to labelled IL-10 [PMID:9312047]. GtoPdb lists IL-10 as an agonist for IL10RB [DB:GtoPdb].","molecular_requirements":"IL10RB works with IL10RA as an accessory chain essential for the active receptor [PMID:9312047]. Reactome shows IL10RB binding the IL10 dimer:IL10RA complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Human IL-10 and receptor chains in hamster cells and human PBMCs [PMID:9312047]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL10 is flagged secreted [flag]; range from annotation only.","caveats":"Abstract only; IL10RB is the second chain and does not bind IL-10 alone in the evidence shown. No affinity for IL10RB is reported.","key_references":[{"PMID":"9312047","why":"CRFB4 (IL10RB) is the IL-10R2 accessory chain"}],"covers":["LR000854","LR004284"]},"LR000855":{"pair":"IL11 -> IL11RA","headline":"IL-11 binds IL-11Ralpha directly; supported by mutagenesis, co-IP, binding data and structures, mostly from abstracts.","interaction_type":"direct binding","direction_and_effect":"IL-11 is the agonist ligand; GtoPdb lists it as an agonist [DB:GtoPdb]. Mutants R190E and L194D of human IL-11 failed to bind IL-11Ralpha [PMID:10504396]. In mouse, hepatocyte-specific Il11ra1 deletion protected against acetaminophen liver injury [PMID:34108253].","molecular_requirements":"Signalling needs gp130 (IL6ST) as well: multiple copies of IL-11, IL-11R and gp130 are present in the complex, proposed as a hexamer of two molecules each [PMID:10948192]. High-affinity binding appeared to require coexpression of NR1 (the murine IL-11Ralpha) and gp130 [PMID:7957045]. Membrane IL11RA gives 'classic' signalling; IL11 with soluble IL11RA gives 'trans-signaling' [DB:UniProt].","affinity_potency":[{"value":"Kd approximately 10 nM","assay":"low-affinity IL-11 binding to NR1 alone","system":"mouse NR1 in Ba/F3 cells","cite":"PMID:7957045"},{"value":"Kd = 300-800 pM","assay":"high-affinity IL-11 binding with NR1 plus gp130","system":"mouse NR1 and gp130 in Ba/F3 cells","cite":"PMID:7957045"}],"species_and_systems":"Binding work used human IL-11 mutants on HepG2 and Ba/F3-130-11alpha cells [PMID:10504396], tagged proteins in co-IP (species unspecified) [PMID:10948192], mouse receptor in Ba/F3 [PMID:7957045], and mouse liver in vivo [PMID:34108253]. Human structures 8DPS, 8DPT, 8DPU contain IL-11 and IL6ST chains [DB:PDB 8DPS].","localisation_and_range":"IL-11 is flagged secreted and the receptor a receptor [flag]; a soluble IL11RA form is described for trans-signalling [DB:UniProt].","caveats":"All four papers were read as abstracts only. The in vivo paper tests IL11RA1 loss, not binding. The structures list IL-11 with IL6ST chains, so they may show the full complex rather than IL11-IL11RA alone.","key_references":[{"PMID":"10504396","why":"mutants that fail to bind IL-11Ralpha"},{"PMID":"10948192","why":"co-IP showing hexameric IL-11/IL-11R/gp130 complex"},{"PMID":"7957045","why":"binding affinities and gp130 requirement"}],"covers":["LR000855"]},"LR004293":{"pair":"IL13 -> IL2RG","headline":"IL13 engages IL2RG only as part of an IL4R alpha/IL2R gamma heterodimer in one functional study; weak and chain-only.","interaction_type":"functional only","direction_and_effect":"IL13 mimics IL4 in inducing heterodimerization of IL2R gamma and IL4R alpha in cells expressing both, with marked JAK3 and STAT6 activation [PMID:8920992].","molecular_requirements":"Both IL4R alpha and IL2R gamma are required for JAK3 and proliferative responses in BA/F3 reconstitution [PMID:8920992]. IL2RG alone is not shown to bind IL13.","affinity_potency":[],"species_and_systems":"BA/F3 reconstituted cells; species of cells not reported in our evidence [PMID:8920992]. Mouse pair inferred from human.","localisation_and_range":"Not reported in our evidence.","caveats":"Functional readout, no direct binding. The abstract says the paper contradicts prior reports that IL13 does not use IL2R gamma [PMID:8920992]. Abstract only.","key_references":[{"PMID":"8920992","why":"IL13 induces IL2Rgamma/IL4Ralpha heterodimerization and JAK3/STAT6 activation"}],"covers":["LR000863","LR004293"]},"LR000864":{"pair":"IL13 -> IL4R","headline":"Weak: only a genetic association paper mentions IL13 and IL4R; databases assert the pairing.","interaction_type":"database-asserted only","direction_and_effect":"Binding of IL13 or IL4 to IL4R induces Th2 polarization is stated as background [PMID:11709756]. UniProt lists IL13 acting through the IL4R chain and IL13RA1 chain [DB:UniProt]; GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"IL4R works with IL13RA1 per UniProt [DB:UniProt]; direct IL13 binding to IL4R alone is not shown in our evidence.","affinity_potency":[],"species_and_systems":"Human asthma families genetic study [PMID:11709756].","localisation_and_range":"Not reported in our evidence.","caveats":"The only confirmed paper is a genetic association study in Dutch asthma families, not a binding study; the interaction statement is introductory background [PMID:11709756]. Direct binding of IL13 to IL4R alone is not supported.","key_references":[{"PMID":"11709756","why":"Gene-gene interaction IL4RA and IL13 in asthma (association only)"}],"covers":["LR000864"]},"LR008235":{"pair":"IL17A -> IL17RA:IL17RC","headline":"IL-17A signals through an IL-17RA:IL-17RC heteromeric receptor, with strong structural and affinity evidence, mostly for single chains.","interaction_type":"direct binding","direction_and_effect":"Agonist, via a heteromeric receptor [PMID:19838198]. Reactome and GtoPdb list the IL17RA:IL17RC:IL17A complex and agonist interactions [DB:Reactome, DB:GtoPdb]. UniProt notes IL17RC functions as a receptor for IL17A and IL17F homodimers in a heterodimeric complex with IL17RA [DB:UniProt].","molecular_requirements":"Both chains needed: both IL-17RA and IL-17RC can bind IL-17A independently but both are necessary for signalling, and overexpression of both without cytokine does not induce signalling [PMID:19838198]. After one receptor binds, the second site prefers a different receptor, favouring the heterodimer [PMID:19838198]. The crystal structure in this paper is with IL-17F, not IL-17A.","affinity_potency":[{"value":"2.8\u00b10.9 nM","assay":"SPR, IL-17A to IL-17RA","system":"soluble proteins","cite":"PMID:19838198"},{"value":"1.2\u00b10.1 nM","assay":"SPR, IL-17A to IL-17RC","system":"soluble proteins","cite":"PMID:19838198"},{"value":"3.1\u00b10.5 \u03bcM","assay":"SPR, second IL-17RA onto IL-17A already bound by IL-17RA","system":"soluble proteins","cite":"PMID:19838198"},{"value":"162\u00b129 nM","assay":"SPR, IL-17RA onto IL-17RC-IL-17A complex","system":"soluble proteins","cite":"PMID:19838198"}],"species_and_systems":"Human proteins, purified and recombinant [PMID:19838198]. 9367539 uses human cells; 25204502 used mice.","localisation_and_range":"Membrane receptor complex (entity annotated as transmembrane receptor [flag]); IL-17A annotated as secreted [flag]. Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"Abstract-only reads for two papers. The 1997 paper confirms the IL17RA chain only [PMID:9367539]. The mouse paper does not name the partner chain [PMID:25204502]. IL-17RC alone may bind IL-17A with high affinity without IL-17RA per a UniProt note [DB:UniProt].","key_references":[{"PMID":"19838198","why":"Structure and SPR affinities of IL-17 receptor chains and heterodimer formation"},{"PMID":"9367539","why":"Cloning of human IL-17R (IL17RA chain)"},{"PMID":"25204502","why":"Mouse evidence for IL-17RA as shared subunit"}],"covers":["LR008235"]},"LR000873":{"pair":"IL18 -> CD48","headline":"CD48 is reported to associate with the IL-18/IL-18Ralpha complex in human KG-1 cells; direct IL-18 binding to CD48 is not shown.","interaction_type":"functional only","direction_and_effect":"Co-receptor-like role. Anti-IL-18Ralpha antibody co-precipitated CD48 from IL-18-stimulated KG-1 cells, and soluble CD48 without GPI glycan bound IL-18Ralpha [PMID:15760905]. PI-PLC treatment inhibited tyrosine kinase phosphorylation and IL-18-dependent interferon-gamma production [PMID:15760905].","molecular_requirements":"The complex of IL-18, IL-18Ralpha and CD48 is proposed to involve both the CD48 peptide portion and its GPI glycan [PMID:15760905].","affinity_potency":[],"species_and_systems":"Human KG-1 cells and recombinant human CD48 [PMID:15760905]. Mouse pair is ortholog-inferred.","localisation_and_range":"CD48 is GPI-anchored, membrane-bound (annotated transmembrane receptor [flag]) in the paper's system [PMID:15760905].","caveats":"Abstract-only read. The binding shown is between CD48 and IL-18Ralpha, not IL-18 itself; the abstract text is truncated.","key_references":[{"PMID":"15760905","why":"CD48 associates with IL-18Ralpha via peptide and GPI glycan"}],"covers":["LR000873","LR004303"]},"LR002790":{"pair":"IL1B -> ITGAV","headline":"IL-1beta binds integrin alphaVbeta3 directly according to one abstract-level paper; UniProt repeats that paper.","interaction_type":"direct binding","direction_and_effect":"IL-1beta specifically bound integrins alphavbeta3 and alpha5beta1, and the authors propose this binding is primarily important for agonistic IL-1beta signalling [PMID:29030430]. Agonist direction is the curators' label.","molecular_requirements":"The integrin heterodimer is the binding unit named in the paper (integrin alphaVbeta3); this pair record is for one subunit only, and which subunit contacts IL-1beta is not reported in our evidence [PMID:29030430]. UniProt: ITGAV:ITGB3 binds to IL1B and this binding is essential for IL1B signaling [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human IL-1beta and human integrins in binding and signalling assays; the mouse pair is inferred from human evidence [PMID:29030430].","localisation_and_range":"IL1B is flagged secreted [flag]; the integrin is a membrane receptor, so ligand acts at the cell surface.","caveats":"Read as abstract only. The E128K mutation in the IL1R-binding site enhanced integrin binding, and Lys-to-Glu substitutions reduced but did not abolish agonistic action, so integrin binding is not the only route [PMID:29030430]. No affinity reported. UniProt support derives from the same paper.","key_references":[{"PMID":"29030430","why":"IL-1beta binds alphavbeta3 and alpha5beta1; role in agonism"}],"covers":["LR002790","LR006033"]},"LR011736":{"pair":"IL1RN -> IL1B:IL1R1:IL1RAP","headline":"Complex pair supported by database records only; no paper confirmed.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1RN-IL1R1 and IL1RN-IL1RAP as antagonist [DB:GtoPdb]. UniProt: binding of IL1RN to IL1R1 prevents its association with IL1R1 to form a signaling complex [DB:UniProt].","molecular_requirements":"The receptor entry is a three-member complex (IL1B:IL1R1:IL1RAP); the records support individual members, not this complex as a unit.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"IL1RN is flagged secreted [flag].","caveats":"Three papers are pending and none verified. Database records name pairs of members, not this complex, so the complex-level claim is an assembly.","key_references":[],"covers":["LR011736"]},"LR007308":{"pair":"IL1RN -> IL1R1:IL1RAP","headline":"Complex pair has database records for members only; no paper confirmed.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists IL1RN-IL1R1 and IL1RN-IL1RAP as antagonist [DB:GtoPdb]. UniProt: binding of IL1RN to IL1R1 prevents its association with IL1R1 to form a signaling complex [DB:UniProt].","molecular_requirements":"Complex of IL1R1 and IL1RAP; UniProt implies IL1RN blocks complex formation rather than binding the assembled complex.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"IL1RN is flagged secreted and the complex transmembrane [flag].","caveats":"The one paper judged was abstract_insufficient. Antagonism is via IL1R1 and the accessory chain is not itself shown to bind IL1RN.","key_references":[],"covers":["LR007308"]},"LR000891":{"pair":"IL21 -> IL2RG","headline":"IL-21 directly contacts the common gamma chain by cross-linking; chain-level evidence from one abstract, signalling needs IL-21R too.","interaction_type":"direct binding","direction_and_effect":"Chemical cross-linking shows direct binding of IL-21 to gamma(c) in gamma(c)-transfected cells [PMID:11418623]. GtoPdb lists an agonist [DB:GtoPdb].","molecular_requirements":"gamma(c) is an indispensable subunit of the IL-21 receptor complex, but IL-21 does not signal in gamma(c)-deficient cells that express IL-21R, so IL2RG acts with IL-21R rather than alone [PMID:11418623].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, transfected cell lines [PMID:11418623]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL-21 is flagged secreted [flag].","caveats":"Abstract-only, single paper. IL2RG is a shared chain for other cytokines per the abstract, so this row says little about IL-21 specificity [PMID:11418623]. BioGRID: Affinity Capture-Western [DB:BioGRID].","key_references":[{"PMID":"11418623","why":"cross-linking shows direct IL-21 binding to gamma(c)"}],"covers":["LR000891","LR004321"]},"LR007317":{"pair":"IL24 -> IL20RB:IL22RA1","headline":"IL-24 acts through the type II complex IL20RB:IL22RA1; one confirming paper read as abstract only plus Reactome records.","interaction_type":"direct binding","direction_and_effect":"mda-7 (IL-24) and IL-20, but not IL-19, bind the IL-22R plus IL-20Rbeta complex [PMID:11564763]. GtoPdb lists agonists [DB:GtoPdb].","molecular_requirements":"Both chains are part of the receptor; Reactome records IL24:IL22RA1:JAK1:IL20RB [DB:Reactome R-HSA-448735].","affinity_potency":[],"species_and_systems":"Receptor-transfected reporter cells, species not stated in the abstract [PMID:11564763].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"Only one confirmed paper, abstract only; two rows were review_only. A structure of IL24 with IL20RB exists [DB:PDB 6DF3].","key_references":[{"PMID":"11564763","why":"IL-24 binds type II IL-20R complex"}],"covers":["LR007317"]},"LR004329":{"pair":"IL24 -> IL22RA1","headline":"IL-24 uses IL22RA1 paired with IL20RB; consistent across papers, but chain-level and abstract-only.","interaction_type":"direct binding","direction_and_effect":"COS cells transfected with the IL-22R1/IL-20R2 heterodimer bind IL-24 [PMID:11706020]; mda-7 binds IL-22R plus IL-20Rbeta with STAT3 activation [PMID:11564763]; IL-24 can use IL-22R/IL-20RB [PMID:12351624]. Agonist [DB:GtoPdb].","molecular_requirements":"IL22RA1 acts with IL20RB; IL-24 can instead use IL20RA with IL20RB [PMID:11706020][DB:UniProt]. Structure with IL22RA1 chain exists [DB:PDB 6DF3].","affinity_potency":[],"species_and_systems":"Human receptors, COS and BHK cells, keratinocytes [PMID:11706020].","localisation_and_range":"IL-24 is flagged secreted [flag].","caveats":"All abstract-only; evidence is for the heterodimer, not IL22RA1 alone. One row was review_only.","key_references":[{"PMID":"11706020","why":"IL-24 binds IL-22R1/IL-20R2 transfectants"},{"PMID":"11564763","why":"IL-24 binds type II IL-20R"},{"PMID":"12351624","why":"IL-24 uses IL-22R/IL-20RB"}],"covers":["LR000899","LR004329"]},"LR000909":{"pair":"IL3 -> CSF2RB","headline":"IL-3 binds a high-affinity site that requires CSF2RB together with IL3RA; one abstract-level binding paper plus databases.","interaction_type":"direct binding","direction_and_effect":"A high-affinity IL-3-binding site was reconstituted by coexpressing the IL-3 receptor alpha (DUK-1) with hGMR beta in COS7 cells (agonist per GtoPdb) [PMID:1833064][DB:GtoPdb].","molecular_requirements":"CSF2RB alone is not shown to bind IL-3 in our evidence. It acts as the shared beta subunit with IL3RA: the alpha chain alone bound IL-3 with extremely low affinity [PMID:1833064]. Reactome lists IL3:IL3RA:IL3RB:JAK2 [DB:Reactome].","affinity_potency":[{"value":"Kd = 140 +/- 30 pM","assay":"125I-IL-3 binding, alpha plus beta reconstitution","system":"COS7 cells","cite":"PMID:1833064"},{"value":"Kd = 120 +/- 60 nM","assay":"125I-IL-3 binding, alpha chain alone","system":"COS7 cells","cite":"PMID:1833064"}],"species_and_systems":"Human proteins expressed in COS7 cells [PMID:1833064]. Structure 6NMY contains both chains [DB:PDB 6NMY]; BioGRID lists a reconstituted complex [DB:BioGRID].","localisation_and_range":"IL-3 is flagged secreted and non-transmembrane [flag].","caveats":"Abstract only. The paper's evidence is for the alpha plus beta complex, not for a direct IL-3-CSF2RB contact; the affinities belong to receptor combinations, not CSF2RB alone. Four other judged papers were abstract_insufficient.","key_references":[{"PMID":"1833064","why":"Expression cloning of IL3RA; high-affinity IL-3 binding needs the shared GM-CSF receptor beta subunit."}],"covers":["LR000909"]},"LR004338":{"pair":"Il3 -> Csf2rb2","headline":"Mouse IL-3 binds Csf2rb2 (AIC2A) directly in two older abstract-level papers.","interaction_type":"direct binding","direction_and_effect":"Only AIC2A, not its 91% identical paralog AIC2B, binds IL-3 [PMID:1730686]. AIC2A participates in forming the high-affinity IL-3 receptor, shown by ligand-affinity purification with biotin-IL-3 and Western blot [PMID:1777419].","molecular_requirements":"The external domain alone mediates binding: soluble AIC2A bound IL-3 with affinity similar to membrane-bound AIC2A. Neither of its two cytokine-receptor repeats alone bound IL-3, and the second repeat (hinge-region residues) is critical [PMID:1730686]. AIC2A is the low-affinity chain and takes part in the high-affinity receptor [PMID:1777419].","affinity_potency":[],"species_and_systems":"Mouse ligand and receptor [PMID:1730686][PMID:1777419]. Cell systems are not detailed in the abstracts.","localisation_and_range":"IL-3 is flagged secreted [flag]. A temperature shift changed the apparent size of AIC2A in cells [PMID:1777419].","caveats":"Both papers were read as abstract only. No affinity value is reported in our evidence. Paralog Csf2rb (AIC2B) does not bind IL-3, so confusion between the two genes matters when mapping symbols [PMID:1730686]. No database records.","key_references":[{"PMID":"1730686","why":"Only AIC2A, not AIC2B, binds IL-3; maps the critical second repeat."},{"PMID":"1777419","why":"Ligand-affinity purification shows AIC2A is in the high-affinity IL-3 receptor."}],"covers":["LR004338"]},"LR001863":{"pair":"IL34 -> PTPRZ1","headline":"IL-34 binds PTPRZ1 (PTP-zeta) in one paper using affinity chromatography and cell lysates; single abstract-level source.","interaction_type":"direct binding","direction_and_effect":"IL-34 bound PTP-zeta in CSF-1R-deficient U251 human glioblastoma lysates and inhibited proliferation, clonogenicity and motility in a PTP-zeta-dependent manner [PMID:23744080]. Reactome and BioGRID (reconstituted complex) agree [DB:Reactome][DB:BioGRID].","molecular_requirements":"Binding depended on PTP-zeta chondroitin sulfate moieties: chondroitinase ABC abrogated binding and CS competed with IL-34 [PMID:23744080].","affinity_potency":[],"species_and_systems":"Affinity chromatography of mouse brain membrane, then human U251 cells [PMID:23744080].","localisation_and_range":"IL-34 flagged secreted; PTPRZ1 flagged transmembrane (also flagged secreted) [flag]; the paper calls it a cell-surface proteoglycan [PMID:23744080].","caveats":"Only one paper, read as abstract. No affinity value. Binding is chondroitin sulfate dependent.","key_references":[{"PMID":"23744080","why":"IL-34 identified as PTP-zeta ligand"}],"covers":["LR001863","LR005208"]},"LR007326":{"pair":"IL37 -> IL18R1:SIGIRR","headline":"IL-37 forms a tripartite complex with IL-1R8 (SIGIRR) and IL-18Ralpha in human PBMC; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Silencing IL-1R8 or IL-18Ralpha impaired IL-37 anti-inflammatory activity; IL-1R8-deficient IL-37tg mice lost protection from endotoxemia [PMID:25729923].","molecular_requirements":"Both IL-18Ralpha and IL-1R8 are needed; the complex assembled on PBMC surface after LPS [PMID:25729923].","affinity_potency":[],"species_and_systems":"Human PBMC and mouse [PMID:25729923].","localisation_and_range":"Ligand annotated as secreted [flag]; receptor-side localisation not otherwise reported.","caveats":"Abstract only; no affinity. Curator effect label is antagonist but GtoPdb lists Agonist [DB:GtoPdb].","key_references":[{"PMID":"25729923","why":"Demonstrates the IL-37-IL-1R8-IL-18Ralpha complex"}],"covers":["LR007326"]},"LR002808":{"pair":"IL4 -> IL2RB","headline":"No paper support; database records concern the IL4 / IL4R / common gamma chain complex, not IL2RB.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence in our evidence; pair rests on database records alone.","molecular_requirements":"The cited structure 3BPL is the IL4-IL4R-common gamma ternary complex [DB:PDB 3BPL]; no IL2RB involvement is shown in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence (human pair is ortholog-inferred; mouse pair is listed directly, without curated experiments).","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Database records (IntAct, PDB, Reactome) describe IL4 with IL4R and the gamma chain rather than IL2RB [DB:IntAct]. Likely a mapping artefact; treat as unsupported.","key_references":[],"covers":["LR002808","LR006048"]},"LR006048":{"pair":"IL4 -> IL2RB","headline":"No paper support; database records concern the IL4 / IL4R / common gamma chain complex, not IL2RB.","interaction_type":"database-asserted only","direction_and_effect":"No paper evidence in our evidence; pair rests on database records alone.","molecular_requirements":"The cited structure 3BPL is the IL4-IL4R-common gamma ternary complex [DB:PDB 3BPL]; no IL2RB involvement is shown in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence (human pair is ortholog-inferred; mouse pair is listed directly, without curated experiments).","localisation_and_range":"IL4 is flagged secreted and non-transmembrane [flag], so it acts as a diffusible ligand on receptor-bearing cells; the receptor is flagged as a transmembrane receptor [flag].","caveats":"Database records (IntAct, PDB, Reactome) describe IL4 with IL4R and the gamma chain rather than IL2RB [DB:IntAct]. Likely a mapping artefact; treat as unsupported.","key_references":[],"covers":["LR002808","LR006048"]},"LR000918":{"pair":"IL6 -> IL6ST","headline":"IL6 reaches IL6ST only via IL6R; structural and domain-dissection evidence in human, abstracts only.","interaction_type":"direct binding","direction_and_effect":"IL-6 binds IL-6R and the IL-6:IL-6R complex associates with gp130 [PMID:9694899]; crystal structure and EM show a hexameric IL-6:IL-6Ralpha:gp130 complex [PMID:15895091]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL6R is required: the IL-6R D3 domain alone binds IL-6 but, complexed with IL-6, fails to associate with gp130; the second domain is implicated in gp130 complex formation [PMID:9694899]. UniProt: IL6ST does not interact with IL6 itself [DB:UniProt].","affinity_potency":[],"species_and_systems":"Human proteins; refolded bacterially expressed D3 domain, crystal structure and single-particle EM [PMID:9694899][PMID:15895091]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Not a direct IL6-IL6ST contact; the pair is mediated by IL6R. Both papers read as abstracts only; one paper note records a 2026-10-12 abstract confirmation.","key_references":[{"PMID":"15895091","why":"gp130:IL-6:IL-6Ralpha structure and EM of full extracellular complex"},{"PMID":"9694899","why":"IL-6R domain dissection: D3 binds IL-6, D2 needed for gp130"}],"covers":["LR000918","LR004346"]},"LR004347":{"pair":"IL7 -> IL2RG","headline":"IL2RG is a functional IL-7 receptor component, shown by cross-linking and antibodies; supporting chain, not a standalone receptor.","interaction_type":"direct binding","direction_and_effect":"IL-2R gamma was physically associated with the IL-7 receptor by chemical cross-linking [PMID:8266077]; antibodies show gamma participates in high-affinity IL-7 receptor complexes [PMID:8128231]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL2RG is a shared subunit that augments IL-7 binding affinity and internalization [PMID:8266077]; it works with the IL-7Ralpha chain [PMID:7522165]. IL2RG alone is not shown to bind IL-7 in our evidence.","affinity_potency":[],"species_and_systems":"Mouse for PMID:8266077; human for PMID:7522165; species of PMID:8128231 not reported in our evidence. Co-immunoprecipitation in IntAct [DB:IntAct].","localisation_and_range":"Secreted ligand [flag].","caveats":"Chain-only pair: the receptor is IL2RG without IL7R. Abstracts only; the PMID:7522165 paper mentions the gamma chain as background and its result concerns IL7R alpha.","key_references":[{"PMID":"8266077","why":"Cross-linking shows IL-2Rgamma associated with IL-7R"},{"PMID":"8128231","why":"Antibodies show gamma chain in IL-7 receptor complexes"}],"covers":["LR000919","LR004347"]},"LR000927":{"pair":"IL9 -> IL9R","headline":"IL9 to IL9R is supported by two functional human papers and databases; no direct binding measurement.","interaction_type":"functional only","direction_and_effect":"IL-9 signalling in bronchial epithelial cells was blocked by antibody to IL-9Ralpha [PMID:11588013]; IL-9 acts through IL-9R with JAK1/JAK3-STAT activation [PMID:9535918]. GtoPdb: agonist [DB:GtoPdb].","molecular_requirements":"IL-9Ralpha works with gammac; antibody to either blocked the response [PMID:11588013][PMID:9535918]; Tyr336 of IL-9Ralpha is crucial [PMID:9535918].","affinity_potency":[],"species_and_systems":"Human: primary and immortalized bronchial epithelial cells [PMID:11588013]; mast and T cell lines [PMID:9535918]. Mouse pair ortholog-inferred. BEAS-2B cells lacking the receptor did not respond [PMID:11588013].","localisation_and_range":"IL6/IL7/IL9 are flagged secreted [flag], so signalling is paracrine or endocrine; the receptor is flagged transmembrane [flag].","caveats":"Abstracts only; no binding assay. Two further papers are pending.","key_references":[{"PMID":"9535918","why":"IL-9R complex requirements and signalling"},{"PMID":"11588013","why":"Antibody blockade of IL-9 response in bronchial epithelium"}],"covers":["LR000927","LR004350"]},"LR007920":{"pair":"INHA -> ACVR1:ACVR2B","headline":"INHA on ACVR1 plus ACVR2B: database-asserted only; the type II receptor is the likely contact, no curated paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHA with the type II receptor as agonist [DB:GtoPdb]; UniProt says the ACVR2B type 2 receptor binds inhibin-A/INHA-INHBA [DB:UniProt]. Effect is stimulatory by annotation only.","molecular_requirements":"Type II chain ACVR2B carries the database evidence; the type I chain is not specifically evidenced in our evidence.","affinity_potency":[],"species_and_systems":"Species of database experiments not reported in our evidence.","localisation_and_range":"Secreted ligand [flag]; receptor complex transmembrane [flag].","caveats":"No paper evidence supports this pair; it rests on database records. Both judged papers were review_only. GtoPdb calls INHA an agonist, whereas related papers on other INHA pairs describe inhibin as competing with activin and BMPs.","key_references":[],"covers":["LR007920"]},"LR004356":{"pair":"INHBA -> ACVR2A","headline":"Activin A binds ACVR2A directly, with a crystal structure; five verified papers.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of ACVR2A with activin A; ACVR2A high-affinity growth factors are activin A, activin B and GDF11 [PMID:35643319]. Type II but not type I activin receptor binds activin when expressed alone, and activin induces type I-type II heteromer formation [PMID:9032295]. Agonist; signals through ActRIIA plus ALK4 [PMID:15196700].","molecular_requirements":"ACVR2A binds activin A; a type I receptor is required for signalling [PMID:9032295]. Binding uses a conserved hydrophobic hot spot [PMID:35643319].","affinity_potency":[],"species_and_systems":"Human proteins (structure, K562 cells) [PMID:35643319][PMID:9032295]; mouse reconstitution [PMID:15196700]; mouse pair projected.","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"Verified papers were read as abstract only (35643319 has full-text excerpts). Affinity values are not in our evidence. Three further papers were abstract_insufficient.","key_references":[{"PMID":"35643319","why":"ACVR2A-activin A crystal structure."},{"PMID":"9032295","why":"Type II receptor binds activin; type I needed for signalling."},{"PMID":"15196700","why":"ActRIIA plus ALK4 signalling in reconstitution."}],"covers":["LR000933","LR004356"]},"LR000936":{"pair":"INHBA -> TGFBR3","headline":"Inhibin A binds betaglycan (TGFBR3) with high affinity; activin A binding is not shown here.","interaction_type":"direct binding","direction_and_effect":"Betaglycan binds inhibin with high affinity and acts as an inhibin co-receptor with ActRII, enabling inhibin antagonism of activin [PMID:10746731]. Reactome lists inhibin-A binding to TGFBR3 [DB:Reactome].","molecular_requirements":"Betaglycan enhances binding in cells co-expressing ActRII and betaglycan [PMID:10746731].","affinity_potency":[],"species_and_systems":"Recombinant and endogenous complexes in cell lines; species not stated in our evidence [PMID:10746731].","localisation_and_range":"Ligand secreted flag, receptor transmembrane flag [flag].","caveats":"Evidence concerns inhibin, not activin A; the INHBA ligand symbol may stand for inhibin A (INHA:INHBA) rather than the activin A homodimer. Abstract only; no affinity value.","key_references":[{"PMID":"10746731","why":"Betaglycan is an inhibin co-receptor with ActRII."}],"covers":["LR000936","LR004359"]},"LR007263":{"pair":"INHBA:INHBB -> ACVR1C:ACVR2B","headline":"Activin A/B ligand complex to ACVR1C:ACVR2B; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists each activin subunit with each receptor chain as agonist interactions [DB:GtoPdb]. UniProt says ACVR1C signals with type II receptors like ACVR2A or BMPR2 [DB:UniProt].","molecular_requirements":"ACVR2B binding is supported by BioGRID records [PMID:9202237] [PMID:22267736] and a structure of activin A with an ActRIIB-Alk4 fusion [DB:PDB 7OLY]. No record here shows activin A or B acting through ACVR1C.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"No paper-level evidence is held for this pair (only review-only or abstract-insufficient rows), so it rests on database records alone.","key_references":[],"covers":["LR007263"]},"LR008271":{"pair":"INHBB -> ACVR1B:ACVR2A","headline":"Activin B to ACVR1B:ACVR2A; supported by database records only.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists INHBB with each receptor chain as agonist [DB:GtoPdb]. Reactome describes activin A, AB and B binding ACVR2A,B:ACVR1B [DB:Reactome]. BioGRID records INHBB with ACVR2A [PMID:9202237]; UniProt says ACVR2A is a receptor for activin A, activin B and inhibin A [DB:UniProt].","molecular_requirements":"Chain-level records only; whether both subunits are needed is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond human database records.","localisation_and_range":"Ligand is flagged secreted [flag], so likely paracrine/endocrine; receptor is flagged transmembrane [flag].","caveats":"Only abstract-insufficient rows exist, so no curator-verified paper supports this pair; records are per chain, not for the assembled complex.","key_references":[],"covers":["LR008271"]},"LR004365":{"pair":"INHBC -> ACVR2A","headline":"Activin C reported to bind ACVR2A and antagonise activin A signalling; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Activin-C acts as an activin-A antagonist by binding activin receptor subunits IIA and IIB and modulating canonical Smad signalling [PMID:25180271]. The database-style effect label is Stimulatory, which differs from this antagonist reading.","molecular_requirements":"Type II receptor subunit binding only; a type I partner is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human granulosa cell line and human gonadal/adrenal cancer tissue [PMID:25180271]. Mouse pair is projected from human evidence (ortholog inferred).","localisation_and_range":"Ligand is flagged secreted [flag].","caveats":"Single paper, read as abstract only; binding method not stated in the abstract. Two confirmed rows are counted but one paper is shown; one other row was review-only and one abstract-insufficient.","key_references":[{"PMID":"25180271","why":"Activin-C binds ActRIIA/IIB and antagonises activin A in human gonadal/adrenal cancer settings"}],"covers":["LR000942","LR004365"]},"LR004374":{"pair":"Ins1 -> Lrp2","headline":"Mouse Ins1 to Lrp2 is a projection of the insulin-megalin finding; no mouse-specific experiment shown.","interaction_type":"direct binding","direction_and_effect":"The cited paper identifies megalin as an endocytic insulin receptor in renal microvillar membranes by cross-linking and immunoprecipitation, and shows internalisation [PMID:9773776].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species of the experiments is not stated in the abstract [PMID:9773776]; the mouse pair is ortholog-inferred.","localisation_and_range":"Apical surface of proximal tubule cells in clathrin-coated pits [PMID:9773776]. Ligand is flagged secreted [flag].","caveats":"The paper refers to insulin generally; Ins1 versus Ins2 is not distinguished. Abstract only, no affinity.","key_references":[{"PMID":"9773776","why":"Megalin as an endocytic insulin receptor"}],"covers":["LR004374"]},"LR002826":{"pair":"ITGB1 -> ADGRE5","headline":"Integrin alpha5beta1 is reported as a high-affinity counterreceptor for CD97; the ITGB1 row inherits this abstract-level evidence.","interaction_type":"direct binding","direction_and_effect":"Soluble CD97 drives integrin-dependent HUVEC migration [PMID:15576472].","molecular_requirements":"Evidence is for the alpha5beta1 heterodimer, not ITGB1 alone [PMID:15576472].","affinity_potency":[],"species_and_systems":"Human HUVEC and in vivo angiogenesis assay [PMID:15576472]; mouse pair is orthology-projected.","localisation_and_range":"ADGRE5 flagged secreted [flag].","caveats":"Abstract only; no affinity values; chain-only attribution.","key_references":[{"PMID":"15576472","why":"Alpha5beta1 as counterreceptor for CD97"}],"covers":["LR002826","LR006064"]},"LR006066":{"pair":"ITGB2 -> ICAM1","headline":"Mac-1 binds ICAM-1 in cell and purified-protein assays; ITGB2 row inherits Mac-1 heterodimer evidence.","interaction_type":"direct binding","direction_and_effect":"ICAM-1 is a counter-receptor for Mac-1 and contributes to neutrophil-endothelial adhesion [PMID:1980124].","molecular_requirements":"The evidence is for Mac-1 (alphaMbeta2); binding differed from LFA-1 in temperature sensitivity, avidity and antibody profile [PMID:1980124].","affinity_potency":[],"species_and_systems":"Human cells and purified proteins, transfected murine L and monkey COS cells [PMID:1980124]. Mouse pair orthology-projected.","localisation_and_range":"Membrane-bound adhesion molecules [PMID:1980124].","caveats":"Abstract read; no affinity values; chain-only attribution.","key_references":[{"PMID":"1980124","why":"ICAM-1 as a Mac-1 counter-receptor"}],"covers":["LR002829","LR006066"]},"LR000954":{"pair":"JAG1 -> NOTCH3","headline":"Jagged1 binds Notch3 and drives its signalling; supported by binding, mutation and functional papers.","interaction_type":"direct binding","direction_and_effect":"Soluble Notch3 extracellular protein bound JAG1 directly in solid-phase assays [PMID:11006133]. Jagged1-induced RBP/JK reporter activity of Notch3 was reduced by two CADASIL mutants; C428S lost Jagged1 binding while C542Y kept binding but had impaired surface presentation [PMID:14714274]. Murine Notch3 signalled in response to Jagged 1 [PMID:12482954]. TSP2 augmented the Notch3-Jagged1 interaction [PMID:19147503]. Annotation: stimulatory.","molecular_requirements":"Ca2+ dependent binding [PMID:11006133]. The ligand-binding domain lies in EGF repeats 10-11 of Notch3 [PMID:14714274].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:11006133][PMID:14714274][PMID:19147503]; murine Notch3 stable cell lines [PMID:12482954].","localisation_and_range":"JAG1 is flagged as transmembrane [flag]. TSP2 is an extracellular facilitator [PMID:19147503].","caveats":"All papers abstract-only. The TSP2 paper treats the pair as background and its finding concerns facilitation. The murine CADASIL paper does not measure binding [PMID:12482954]. Database records exist [DB:BioGRID][DB:IntAct][DB:Reactome].","key_references":[{"PMID":"11006133","why":"Direct binding"},{"PMID":"14714274","why":"Binding-domain mutants and Jagged1-induced signalling"},{"PMID":"19147503","why":"TSP2 potentiates the pair"}],"covers":["LR000954","LR004377"]},"LR008334":{"pair":"JAM2 -> JAM2","headline":"No verified paper; homodimerisation is asserted by databases only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a protein array record [DB:IntAct]; Reactome lists JAM2 dimerisation [DB:Reactome].","localisation_and_range":"JAM2 flagged as not secreted, transmembrane [flag].","caveats":"Judged papers were abstract_insufficient or different_entity. UniProt text concerns alpha4/beta1 binding, not homodimerisation [DB:UniProt].","key_references":[],"covers":["LR008334"]},"LR002835":{"pair":"JAM3 -> ITGB2","headline":"JAM3 binds beta2-integrin Mac-1 directly in human systems, but evidence is for the Mac-1 heterodimer rather than ITGB2 alone.","interaction_type":"direct binding","direction_and_effect":"JAM-3 is a counterreceptor for Mac-1: JAM-3 directly bound purified Mac-1 in a saturable, dose-dependent way inhibited by anti-Mac-1 or anti-JAM-3 antibody, and purified JAM-3 inhibited neutrophil binding to adherent platelets [PMID:12208882]. JAM-C availability also regulates alphaMbeta2-dependent leukocyte adhesion [PMID:16093349].","molecular_requirements":"Evidence is for the Mac-1 heterodimer (alphaMbeta2); ITGB2 inherits it at complex level. Adhesion was blocked by anti-beta2 antibody; binding was strong for Mac-1, weaker for p150.95 and absent for LFA-1, which shares the beta2 chain, so beta2 alone is not sufficient [PMID:12208882].","affinity_potency":[],"species_and_systems":"Human platelets, U937 and K562 cells, CHO transfectants, purified proteins [PMID:12208882]; species not specified in the second paper [PMID:16093349]. Dossier includes human and mouse entries; experiments shown are human.","localisation_and_range":"JAM-3 is a type I transmembrane glycoprotein [PMID:12208882], so signalling is contact-dependent (juxtacrine); the entity flags also mark JAM3 as secreted [flag], which the papers do not support.","caveats":"Evidence is complex-level; the specificity panel shows LFA-1 (also beta2) does not bind, so ITGB2 is not the determining chain [PMID:12208882]. Second paper read as abstract only [PMID:16093349]. No affinity reported.","key_references":[{"PMID":"12208882","why":"Direct Mac-1 binding with integrin specificity panel"},{"PMID":"16093349","why":"JAM-C and alphaMbeta2-dependent leukocyte adhesion"}],"covers":["LR002835","LR006072"]},"LR006075":{"pair":"KISS1 -> NPFFR2","headline":"Kisspeptin-10 binds and activates NPFFR2 in one 2011 study; the pair is ortholog-projected from that evidence.","interaction_type":"direct binding","direction_and_effect":"Kisspeptin-10 showed potent binding and activation of NPFFR2, whereas short GPR54-selective peptide agonists bound with much lower affinity [PMID:24900254]. Reported NPFFR ligands showed negligible affinity for GPR54, i.e. cross-reactivity runs one way [PMID:24900254].","molecular_requirements":"Kisspeptin-10 form specifically; short synthetic agonists were weak at NPFFRs [PMID:24900254].","affinity_potency":[],"species_and_systems":"Human and mouse entries are both ortholog-inferred; the paper's experiment species are labelled human by the curators; abstract-only read [PMID:24900254].","localisation_and_range":"KISS1 is flagged secreted [flag]; the paper suggests secondary kisspeptin targets may lie in the median eminence [PMID:24900254].","caveats":"Single paper, abstract only, with no numbers in the dossier. The canonical kisspeptin receptor is GPR54, so this is a cross-reactivity finding [PMID:24900254]. Not present in any database.","key_references":[{"PMID":"24900254","why":"Kisspeptin-10 binds and activates NPFFR1 and NPFFR2"}],"covers":["LR002839","LR006075"]},"LR004383":{"pair":"Kitl -> Kit","headline":"Mouse SCF (Kitl) is the ligand of Kit, supported by the original 1990 identification and two soluble-receptor studies.","interaction_type":"direct binding","direction_and_effect":"The 1990 study provided biological and physical evidence that SCF is a ligand for c-kit, and in vivo SCF reversed macrocytic anaemia and repaired mast cell deficiency in Sl/Sld mice [PMID:1698556]. A soluble Kit ectodomain (Kit-X, 90 kDa) retained high-affinity SCF binding, dimerised with ligand and acted as a stoichiometric antagonist of SCF on cells overexpressing the receptor [PMID:1375232].","molecular_requirements":"The isolated ectodomain alone binds SCF and dimerises with it [PMID:1375232]; the SCF binding site lies in the amino-terminal half of the ectodomain, with the third Ig-like domain contributing to affinity [PMID:7680037].","affinity_potency":[],"species_and_systems":"Mouse SCF and Sl mutants [PMID:1698556]; recombinant Kit-X from CHO cells [PMID:1375232]; murine antibodies and human megakaryocytes [PMID:7680037]. All abstract-only reads. This dossier covers the mouse entry only.","localisation_and_range":"SCF is flagged secreted [flag]; the ectodomain work shows a soluble Kit form can act as a decoy [PMID:1375232].","caveats":"All three papers read as abstracts only. Affinity values are not reported in the abstracts.","key_references":[{"PMID":"1698556","why":"Original identification of SCF as c-kit ligand"},{"PMID":"1375232","why":"Soluble Kit ectodomain binds SCF and antagonises it"},{"PMID":"7680037","why":"Maps SCF binding to the Kit amino-terminal Ig domains"}],"covers":["LR004383"]},"LR010845":{"pair":"KL -> FGFR3","headline":"Klotho engages FGFR3 as part of an FGF23 co-receptor complex; one structural paper (abstract) plus a PDB record.","interaction_type":"direct binding","direction_and_effect":"Klotho co-receptors simultaneously engage FGF hormones and their cognate FGFRs, stabilising the complex; the structure includes FGFR3c [PMID:37286607].","molecular_requirements":"Heparan sulfate proteoglycan is an additional required coreceptor for dimerisation/activation. The structure is a 1:2:1:1 FGF23-FGFR-alphaKlotho-heparan sulfate complex, and alphaKlotho does not directly recruit the secondary receptor [PMID:37286607].","affinity_potency":[],"species_and_systems":"Human proteins, cryo-EM structure with cell-based complementation experiments [PMID:37286607]. PDB 7YSU has KL and FGFR3 chains [DB:PDB 7YSU].","localisation_and_range":"Klotho is flagged as a receptor itself [flag]; membrane or shed form not distinguished in this dossier.","caveats":"Abstract only. The signalling ligand is FGF23 and KL is a co-receptor, so this is not a stand-alone ligand-receptor pair. No affinity reported in our evidence.","key_references":[{"PMID":"37286607","why":"Cryo-EM structure of FGF23-FGFR-alphaKlotho-heparan sulfate complexes"}],"covers":["LR010845"]},"LR001872":{"pair":"KLRB1 -> CLEC2D","headline":"CD161-LLT1 is a physical interaction in database records; the one curated paper is functional and assigns CD161 as ligand.","interaction_type":"direct binding","direction_and_effect":"UniProt describes CLEC2D as a receptor for KLRB1 that protects target cells against NK-mediated lysis [DB:UniProt]. The confirmed paper treats LLT1 as the signalling receptor on germinal-centre B cells with CD161 on follicular dendritic cells as ligand; LLT1 triggering supported B cell activation and CXCR4 downregulation [PMID:26829983].","molecular_requirements":"Reactome lists a CLEC2D dimer:KLRB1 dimer complex [DB:Reactome].","affinity_potency":[{"value":"Kd of 48 \u03bcM","assay":"described as a weak binding strength; cited background, not measured in this paper","system":"LLT1-CD161","cite":"PMID:26829983"}],"species_and_systems":"Human tonsil B cells and tissue sections; recombinant CD161 and blocking antibodies [PMID:26829983]. Database support: surface plasmon resonance, solid phase assay, PDB 5MGT [DB:IntAct][DB:PDB 5MGT].","localisation_and_range":"Both are membrane proteins [flag]; interaction is by cell-cell contact.","caveats":"The Kd value appears in the paper's text next to a citation, so it is background, not this paper's result. The paper's direction (CD161 ligand, LLT1 receptor) is opposite to UniProt's (CLEC2D receptor for KLRB1) in role naming; the site pair has KLRB1 as ligand. The evidence sentence concerns CD161 expression on FDCs, not binding. One further paper was review-only.","key_references":[{"PMID":"26829983","why":"LLT1-CD161 in human germinal centre B cells"}],"covers":["LR001872"]},"LR000963":{"pair":"KNG1 -> BDKRB2","headline":"Kininogen-derived bradykinin and kallidin activate B2R, shown by several structures; the active ligand is a kinin peptide.","interaction_type":"direct binding","direction_and_effect":"Bradykinin and kallidin are endogenous peptide agonists of B2R, acting as vasodilators [PMID:35132089]. Complex structures of human B2R with bradykinin are reported [PMID:34518695]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The acting ligands are kinins derived from KNG1; B2R is coupled to Gq in the structures [PMID:35132089]. Intact KNG1 as ligand is not tested in our evidence.","affinity_potency":[{"value":"pIC50 7.0-9.3","assay":"GtoPdb full agonist record","system":"not specified in dossier","cite":"PMID:8302267"}],"species_and_systems":"Human B2R-Gq cryo-EM structures at 3.0 and 2.9 angstrom resolution, expressed in insect cells [PMID:35132089]; human structures also in [PMID:34518695]. PDB 7F2O, 7F6H, 7F6I [DB:PDB 7F2O].","localisation_and_range":"KNG1 is secreted [flag]; endocrine or paracrine kinin action at a membrane GPCR.","caveats":"The second paper's abstract is truncated at source. Three papers were abstract_insufficient and one pending. The precursor-versus-kinin distinction matters for expression-based scoring.","key_references":[{"PMID":"34518695","why":"B1R and B2R structures"},{"PMID":"35132089","why":"Cryo-EM B2R-Gq with bradykinin and kallidin"}],"covers":["LR000963","LR004385"]},"LR010854":{"pair":"KRTAP4-12 -> PDGFRB","headline":"Only a yeast two-hybrid IntAct record; no evidence that this is a ligand-receptor interaction.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a two-hybrid physical association from a large-scale screen; species and system not reported in our evidence [DB:IntAct].","localisation_and_range":"Not reported in our evidence.","caveats":"The only judged paper was review_only, so no curator-verified evidence exists. A two-hybrid hit does not show a ligand-receptor relationship, and KRTAP4-12 is a keratin-associated protein, so this is likely a screening artefact.","key_references":[],"covers":["LR010854"]},"LR004392":{"pair":"L1CAM -> EGFR","headline":"Co-IP in transfected HEK293 cells and Drosophila S2 evidence for L1CAM-EGFR association and EGFR activation; not seen in brain.","interaction_type":"direct binding","direction_and_effect":"Reciprocal co-IP in HEK293 cells (human L1CAM and human EGFR) showed physical interaction [PMID:22815787]. L1CAM-mediated adhesion between Drosophila S2 cells activated human EGF kinase at contact sites, and EGFR physically interacted with L1-CAM [PMID:14718570]. L1CAM binding to erbB enhances the response to neuregulins [PMID:22815787]; effect labelled agonist.","molecular_requirements":"Different Ig-like domains of L1CAM can support erbB binding [PMID:22815787]. Reactome describes an L1-EGFR trans-heterodimer [DB:Reactome R-HSA-445016]; the PLoS One paper reports a cis interaction for erbB3.","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 and Drosophila S2 cells [PMID:22815787][PMID:14718570]; Drosophila genetics also used [PMID:14718570]. Mouse pair is ortholog-inferred.","localisation_and_range":"Membrane proteins acting at cell contact sites (homophilic L1 adhesion triggers activation) [PMID:14718570]; L1CAM also flagged secreted [flag].","caveats":"The 2012 study could not detect L1CAM-EGFR co-IP from brain extracts ('not shown'), while erbB2 and erbB3 were detected [PMID:22815787]. 2004 paper read as abstract only; the 2012 paper's text is partly excerpted. Non-quantitative assay; no affinity.","key_references":[{"PMID":"22815787","why":"Co-IP of L1CAM with erbB receptors, human proteins"},{"PMID":"14718570","why":"L1 adhesion activates EGFR kinase in S2 cells"}],"covers":["LR000970","LR004392"]},"LR000972":{"pair":"L1CAM -> ERBB3","headline":"Strongest of the erbB set: reciprocal co-IP, endogenous brain co-IP and in situ proximity ligation support L1CAM-erbB3.","interaction_type":"direct binding","direction_and_effect":"Reciprocal co-IP in HEK293 cells, a proximity ligation assay, and co-IP of endogenous proteins from rat brain support physical L1CAM-erbB3 interaction [PMID:22815787]. Binding enhances the response to neuregulins [PMID:22815787].","molecular_requirements":"The Ig-like domains of L1CAM support the interaction; a DeltaIg construct was tested [PMID:22815787]. The PLA signal appeared in cells not in contact, so the interaction occurs in cis [PMID:22815787].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293; rat P2 brain and mouse E14 brain for endogenous evidence [PMID:22815787]. Mouse pair is ortholog-inferred. BioGRID lists Affinity Capture-Western and Co-localization [DB:BioGRID].","localisation_and_range":"Cis interaction at the cell surface in growing axons [PMID:22815787].","caveats":"One paper only; no affinity; co-IP and PLA show proximity, not necessarily direct contact.","key_references":[{"PMID":"22815787","why":"Co-IP, PLA and brain evidence for L1CAM-erbB3"}],"covers":["LR000972","LR004394"]},"LR007047":{"pair":"L1CAM -> EZR:L1CAM","headline":"Database-asserted only; no curated paper; the receptor is an EZR:L1CAM complex, ezrin being cytoplasmic.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper; support comes from database records. BioGRID lists L1CAM-EZR Reconstituted Complex and Affinity Capture-Western, and an L1CAM-L1CAM two-hybrid [DB:BioGRID]; IntAct lists an L1CAM homodimer solid phase assay [DB:IntAct]; Reactome lists an L1 trans-homodimer [DB:Reactome R-HSA-191438]. Direction and effect are not reported in our evidence.","molecular_requirements":"The receptor is a complex of EZR and L1CAM [flag]; the records describe L1 homodimer and L1-ezrin association, not an extracellular ligand-receptor event.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"The receptor members' annotations are mostly empty [flag]; localisation not reported.","caveats":"Judged papers were all different_entity or abstract_insufficient. The pair likely mixes an L1 homophilic interaction with an intracellular L1-ezrin link.","key_references":[],"covers":["LR007047"]},"LR002844":{"pair":"L1CAM -> FGFR1","headline":"Surface plasmon resonance shows direct L1 FN3-FGFR1 Ig II-III binding with receptor activation; abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Direct interaction of L1 FN3 modules I-V with FGFR1 Ig modules II and III by surface plasmon resonance; L1-FN3 modules activated FGFR1 (phosphorylation) and induced neurite outgrowth in primary neurons [PMID:18222703]. Agonist-like effect.","molecular_requirements":"L1 FN3 I-V and FGFR1 Ig II-III are the mapped regions; binding was enhanced by ATP, AMP-PCP and GTP, but not AMP [PMID:18222703]. Reactome lists L1:FGFR1 [DB:Reactome R-HSA-443643].","affinity_potency":[],"species_and_systems":"Recombinant protein fragments by SPR; species not specified in dossier; primary neurons for function [PMID:18222703]. The mouse pair is listed as a separate non-inferred record.","localisation_and_range":"Reactome describes L1-FGFR cis-heterodimerization [DB:Reactome R-HSA-437230]; FGFR1 not flagged secreted [flag].","caveats":"Abstract only; no affinity values; species unspecified.","key_references":[{"PMID":"18222703","why":"SPR binding of L1 FN3 to FGFR1 plus activation"}],"covers":["LR002844","LR006079"]},"LR006084":{"pair":"L1CAM -> L1CAM","headline":"Homophilic L1 interaction: one functional adhesion paper plus database records; other judged papers abstract_insufficient.","interaction_type":"functional only","direction_and_effect":"Breast cancer cell adhesion to activated endothelium was via ALCAM or L1 itself, identified by blocking antibodies and recombinant-protein flow assays [PMID:22983139]. Databases list trans-homodimer [DB:Reactome R-HSA-191438], two-hybrid [DB:BioGRID] and solid phase assay [DB:IntAct].","molecular_requirements":"Reactome describes an L1 trans-homodimer at the plasma membrane [DB:Reactome R-HSA-191438].","affinity_potency":[],"species_and_systems":"Human breast cancer cells and endothelial cells [PMID:22983139]. Mouse pair is ortholog-inferred.","localisation_and_range":"Trans (cell-contact) homophilic binding [DB:Reactome]; L1CAM also flagged secreted [flag].","caveats":"Paper is abstract only and 'potential binding partners'; ALCAM versus L1 not resolved. Seven judged papers insufficient, one pending.","key_references":[{"PMID":"22983139","why":"L1 on endothelium as potential partner"}],"covers":["LR002849","LR006084"]},"LR011376":{"pair":"LAMA1 -> ITGA3:ITGB1","headline":"No curator-confirmed paper; only a BioGRID ITGB1 record is linked to this complex.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Only a BioGRID reconstituted-complex record (LAMA1 with ITGB1) is available [DB:BioGRID].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Two papers were abstract_insufficient. The BioGRID record concerns ITGB1, not ITGA3 specifically, from a paper whose abstract names alpha1beta1 and alpha2beta1 [DB:BioGRID 315221].","key_references":[],"covers":["LR011376"]},"LR000981":{"pair":"LAMA1 -> ITGB4","headline":"Alpha6beta4 is reported as a receptor for laminin isoforms including laminin 1; abstract-only, heterotrimer-level.","interaction_type":"direct binding","direction_and_effect":"Radioligand-binding and cell-adhesion assays showed alpha6beta4 is a receptor for several laminin isoforms including laminin 1 [PMID:7721947]. Alpha6beta4-positive cells attach to and roll on laminin under flow [PMID:7699012].","molecular_requirements":"The receptor is the alpha6beta4 heterodimer; laminin fragment E8 supported attachment [PMID:7699012].","affinity_potency":[],"species_and_systems":"804G bladder epithelial cells (the curator infers rat) with laminin of unstated origin [PMID:7721947]; cell lines in a flow assay [PMID:7699012].","localisation_and_range":"Ligand flagged secreted [flag]; matrix ligand.","caveats":"Both papers are abstract-only and concern the laminin-1 heterotrimer rather than LAMA1; species is ambiguous. Two review-only rows and one abstract_insufficient row are not shown.","key_references":[{"PMID":"7721947","why":"Radioligand binding of alpha6beta4 to laminin 1"},{"PMID":"7699012","why":"Dynamic adhesion to laminin via alpha6beta4"}],"covers":["LR000981","LR004402"]},"LR009306":{"pair":"LAMA1 -> NT5E","headline":"Weak: a background statement that CD73 binds laminin, in an immunohistochemistry paper.","interaction_type":"functional only","direction_and_effect":"The abstract states the enzyme binds laminin and fibronectin [PMID:10470109]. Direction and effect not reported.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"The paper's own experiment is immunohistochemistry of glioblastoma tissue; binding statement is background [PMID:10470109].","localisation_and_range":"Ligand flagged secreted [flag]; CD73 is an ectoenzyme on plasma membranes [PMID:10470109].","caveats":"This is background, not a result of the paper, and 'laminin' does not resolve to the LAMA1 chain. No other support.","key_references":[{"PMID":"10470109","why":"Mentions CD73 binding laminin (background only)"}],"covers":["LR009306"]},"LR002853":{"pair":"LAMA2 -> ADGRG6","headline":"Laminin-211 binds the GPR126 N-terminal fragment by co-IP, including in vivo and lost in Lama2-null nerve; full text.","interaction_type":"direct binding","direction_and_effect":"Laminin-211 binds GPR126-NTF and can either suppress or promote Stachel-mediated activation of GPR126-CTF [PMID:25695270].","molecular_requirements":"The N-terminal fragment (NTF) binds laminin-211; the NTF is necessary and sufficient for radial sorting while the CTF raises cAMP [PMID:25695270]. LAMA2 is inferred as laminin-211's defining chain.","affinity_potency":[],"species_and_systems":"GPR126-NTF-hFc co-immunoprecipitated with mouse-derived laminin-211, confirmed in P4 mouse sciatic nerve lysate and lost in Lama2-null mice; zebrafish genetics also used [PMID:25695270]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted and non-transmembrane; receptor transmembrane [flag]; matrix ligand acting on the receptor's extracellular fragment.","caveats":"The ligand is the laminin-211 trimer. Two review-only rows are not shown. No affinity reported.","key_references":[{"PMID":"25695270","why":"Co-IP of GPR126-NTF with laminin-211, absent in Lama2-null nerve"}],"covers":["LR002853","LR006087"]},"LR006093":{"pair":"LAMA4 -> DAG1","headline":"Recombinant laminin alpha4 G-domain modules bind alpha-dystroglycan only weakly; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant alpha4LG1-3 and alpha4LG4-5 had only a low affinity for alpha-dystroglycan compared with laminin alpha1 and alpha2 G domains [PMID:10934193].","molecular_requirements":"G-domain fragments were tested, not full-length laminin alpha4 chain or laminin-8 [PMID:10934193].","affinity_potency":[],"species_and_systems":"Species not specified in our evidence; human and mouse pairs are both ortholog-inferred [PMID:10934193].","localisation_and_range":"LAMA4 flagged secreted; DAG1 flagged transmembrane [flag].","caveats":"Evidence is a low-affinity, comparative result, not a quantified Kd; abstract only. Two papers were abstract-insufficient.","key_references":[{"PMID":"10934193","why":"Low-affinity alpha-dystroglycan binding of alpha4 G domain"}],"covers":["LR002859","LR006093"]},"LR000990":{"pair":"LAMA4 -> ITGA3","headline":"The laminin alpha4 G domain binds integrin alpha3beta1 with high affinity (recombinant fragment); abstract-level read.","interaction_type":"direct binding","direction_and_effect":"Recombinant G(919-1207) of laminin alpha4 bound alpha3beta1 with high affinity, and endothelial adhesion to it was blocked by integrin antibodies [PMID:12454288]. Interaction record lists a Stimulatory effect [flag].","molecular_requirements":"Receptor tested is the alpha3beta1 heterodimer; the ligand is a G-domain fragment, not full chain [PMID:12454288].","affinity_potency":[{"value":"half-maximal at 1.4 nM","assay":"endothelial cell adhesion to recombinant G(919-1207) (adhesion, not binding Kd)","system":"endothelial cells","cite":"PMID:12454288"}],"species_and_systems":"Endothelial cells and recombinant protein; species not stated in the abstract [PMID:12454288].","localisation_and_range":"LAMA4 flagged secreted [flag]; component of vessel basement membrane [PMID:12454288].","caveats":"Abstract only; no binding Kd quoted, the 1.4 nM value is an adhesion half-maximum. One further paper was review-only.","key_references":[{"PMID":"12454288","why":"alpha3beta1 and alphavbeta3 bind alpha4 G domain"}],"covers":["LR000990","LR004409"]},"LR002862":{"pair":"LAMA5 -> DAG1","headline":"Laminin-10 (alpha5) binds alpha-dystroglycan via LG4 in deletion studies; a curator-verified negative on the same paper conflicts.","interaction_type":"conflicting","direction_and_effect":"Deleting the LG4-5 modules of recombinant laminin-10 abolished binding to alpha-dystroglycan, and LG4 alone bound it [PMID:14701821]. Laminin-10/11 preferentially bound brain alpha-dystroglycan over skeletal muscle alpha-dystroglycan [PMID:16709410].","molecular_requirements":"Ligand tested as laminin-10/11 trimers; LG4 module is the dystroglycan site [PMID:14701821].","affinity_potency":[],"species_and_systems":"Recombinant human laminin-10 [PMID:14701821]; mammalian tissue alpha-dystroglycan [PMID:16709410]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LAMA5 flagged secreted; DAG1 transmembrane [flag].","caveats":"A pair_absent row exists for PMID 14701821, but the same paper is also confirmed; the negative was auto-matched. Both are abstract-only reads. BioGRID and IntAct also list records [DB:BioGRID][DB:IntAct].","key_references":[{"PMID":"14701821","why":"LG4 of laminin-10 binds alpha-dystroglycan"},{"PMID":"16709410","why":"Laminin-10/11 prefers brain alpha-dystroglycan"}],"covers":["LR002862","LR006096"]},"LR011079":{"pair":"LAMA5 -> ITGA9:ITGB1","headline":"Complex row for laminin alpha5 and integrin alpha9beta1; only a PDB record.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect not reported in our evidence. A PDB entry has a chain of O15230 and a chain of P05556 [DB:PDB 7CEC].","molecular_requirements":"Receptor is the ITGA9:ITGB1 heterodimer per the entity record.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"LAMA5 is flagged secreted [flag] and ITGA9:ITGB1 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"No papers judged (one abstract_insufficient). The PDB chains listed are LAMA5 and ITGB1, not ITGA9 [DB:PDB 7CEC].","key_references":[],"covers":["LR011079"]},"LR004419":{"pair":"LAMB1 -> ITGA6","headline":"Laminin beta1-containing laminins engage integrin alpha6 (alpha6beta1, alpha6beta4) in adhesion assays; abstract-only functional evidence.","interaction_type":"functional only","direction_and_effect":"Human platelet adhesion to purified platelet laminin was largely inhibited by antibodies to beta1 and alpha6 integrin chains [PMID:10585296]. Laminin supported alpha6beta4-positive cell attachment under shear stress, and an anti-alpha6 antibody inhibited it [PMID:7699012]. Annotated stimulatory.","molecular_requirements":"The alpha6 chain pairs with beta1 or beta4 in these papers; the ligand is the whole laminin heterotrimer, so LAMB1 is inferred [PMID:7699012]. A PDB entry has chains P07942 and P23229 [DB:PDB 7CEC].","affinity_potency":[],"species_and_systems":"Human platelets [PMID:10585296]; cell species not reported in our evidence for the flow assay [PMID:7699012]. Mouse pair ortholog-inferred.","localisation_and_range":"LAMB1 is flagged secreted [flag] and ITGA6 is flagged as a receptor [flag]; beyond these annotation flags, range is not reported in our evidence.","caveats":"Both papers are abstract-only, antibody-blocking or adhesion readouts without a direct binding measurement. Another paper was review_only.","key_references":[{"PMID":"10585296","why":"Platelet adhesion to laminin blocked by anti-alpha6/beta1"},{"PMID":"7699012","why":"alpha6beta4 adhesion to laminin under flow"}],"covers":["LR001000","LR004419"]},"LR011394":{"pair":"LAMB2 -> ITGA7:ITGB1","headline":"No paper verifies LAMB2 with ITGA7:ITGB1; support is a PDB record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P05556 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Complex flagged transmembrane and ligand secreted [flag]; range otherwise not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Two papers were abstract_insufficient. The related ITGA7 chain-level row has a recombinant binding paper, but it is not credited to this complex row.","key_references":[],"covers":["LR011394"]},"LR002871":{"pair":"LAMC1 -> DAG1","headline":"LAMC1 (in laminin-10/11) preferentially binds brain alpha-dystroglycan; one abstract-level report.","interaction_type":"direct binding","direction_and_effect":"Laminin-10/11 preferentially bound brain alpha-dystroglycan compared with skeletal-muscle alpha-dystroglycan, suggesting tissue-specific glycosylation modifies laminin binding [PMID:16709410]. Annotated effect is Stimulatory [flag].","molecular_requirements":"The ligand is the laminin-10/11 heterotrimer, so LAMC1 acts as one chain; glycosylation of alpha-dystroglycan affects binding [PMID:16709410].","affinity_potency":[],"species_and_systems":"Mammalian brain and skeletal-muscle alpha-dystroglycan; the species is not stated in our evidence [PMID:16709410].","localisation_and_range":"Ligand flagged secreted [flag]; receptor DAG1 is flagged secreted, receptor and transmembrane [flag]. Range otherwise not reported.","caveats":"Only an abstract was read. The assay cannot isolate LAMC1 from the other chains. No affinity is reported. A second confirmed row has no paper shown.","key_references":[{"PMID":"16709410","why":"Laminin-10/11 binds brain alpha-dystroglycan, abstract only"}],"covers":["LR002871","LR006105"]},"LR004428":{"pair":"LAMC1 -> ITGA6","headline":"LAMC1 (in laminin-511/521 and other laminins) binds integrin alpha6 at Kd 0.73 nM, with adhesion studies in platelets and cells.","interaction_type":"direct binding","direction_and_effect":"Laminin-511/521 bound recombinant alpha6beta1 in solid-phase assays [PMID:16413178]. Platelet adhesion to purified platelet laminin was largely inhibited by antibodies to beta1 and alpha6 [PMID:10585296]. Laminar-flow assays showed alpha6beta4-positive cells attach to laminin, blocked by anti-alpha6 antibody [PMID:7699012]. Annotated effect is Stimulatory [flag].","molecular_requirements":"Ligands are assembled heterotrimers (laminin-511/521; laminin-8 in platelets; laminin LAMA1/LAMB1/LAMC1 in the flow study), so LAMC1 acts as one chain. Binder is alpha6beta1 or alpha6beta4 depending on the paper. PDB 7CEC lists chains of P11047 and P23229 [DB:PDB 7CEC].","affinity_potency":[{"value":"Kd 0.73 nM","assay":"solid-phase saturation binding, recombinant integrin ectodomain to purified laminin isoform; alpha6beta1 vs laminin-511/521","system":"recombinant human integrin, purified laminin","cite":"PMID:16413178"}],"species_and_systems":"Recombinant human proteins [PMID:16413178]; human platelets [PMID:10585296]; cell lines of unstated species in the flow study [PMID:7699012]. Mouse pair is projected from human.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"Kd values are for the whole laminin heterotrimer, not the single chain. The two other papers were read as abstract only and are functional (antibody blocking), not direct binding.","key_references":[{"PMID":"16413178","why":"Kd for alpha6beta1 vs laminin-511/521"},{"PMID":"10585296","why":"Platelet adhesion to laminin blocked by anti-alpha6, abstract only"},{"PMID":"7699012","why":"alpha6beta4 dynamic adhesion to laminin under flow, abstract only"}],"covers":["LR001010","LR004428"]},"LR007056":{"pair":"LAMC1 -> ITGA7:ITGB1","headline":"LAMC1 with ITGA7:ITGB1 has only a PDB record; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"PDB record shows a structure with chains of P11047 and P05556 [DB:PDB 7CEC]; subunit requirements are not reported.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag]; the receptor is annotated as a receptor [flag]. Matrix versus soluble range is not reported in our evidence.","caveats":"No paper in our evidence verifies this pair as listed; support rests on the database record alone. Five papers were abstract_insufficient and one different_entity. The PDB entry lists no ITGA7 chain.","key_references":[],"covers":["LR007056"]},"LR004437":{"pair":"LCN2 -> LRP2","headline":"Megalin (LRP2) binds NGAL/LCN2 with high affinity by surface plasmon resonance and mediates its uptake.","interaction_type":"direct binding","direction_and_effect":"Megalin bound NGAL with high affinity by surface plasmon resonance, and a rat yolk sac cell line endocytosed NGAL by a mechanism completely blocked by an anti-megalin antibody [PMID:15670845]. It acts as an uptake receptor.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human NGAL with rat megalin-expressing yolk sac cells [PMID:15670845]; mouse pair is ortholog-projected.","localisation_and_range":"LCN2 flagged secreted [flag]; megalin described as expressed in polarized epithelia [PMID:15670845].","caveats":"Abstract only; the numeric affinity is not given in the abstract.","key_references":[{"PMID":"15670845","why":"SPR binding and uptake of NGAL by megalin"}],"covers":["LR001019","LR004437"]},"LR002880":{"pair":"LGALS3 -> CDH5","headline":"VE-cadherin (CDH5) was one of four endothelial glycoproteins pulled down by galectin-3; weak support, CD146 was the functional partner.","interaction_type":"functional only","direction_and_effect":"Affinity purification with galectin-3 extracted VE-cadherin (CD144) among four endothelial membrane glycoproteins; CD146 was the major binder and its knockdown abolished galectin-3-induced IL-6 and G-CSF secretion [PMID:28364041]. Effect through CDH5 not reported in our evidence.","molecular_requirements":"Galectin-3 bound N-linked glycans on CD146; whether the same applies to CDH5 is not reported in our evidence [PMID:28364041].","affinity_potency":[],"species_and_systems":"Human vascular endothelial cells [PMID:28364041]. Mouse pair is ortholog-inferred.","localisation_and_range":"Galectin-3 flagged secreted; CDH5 flagged transmembrane [flag]. Circulating galectin-3 acts on endothelium [PMID:28364041].","caveats":"Only co-purification, no CDH5-specific validation; possible indirect pull-down via CD146 complexes. Abstract-only read.","key_references":[{"PMID":"28364041","why":"Galectin-3 affinity purification lists CD144/VE-cadherin"}],"covers":["LR002880","LR006114"]},"LR006129":{"pair":"LGALS8 -> ITGA6","headline":"Galectin-8 binds alpha3beta1 integrin; ITGA6 is only inferred from the same paper, which does not name it in the abstract shown.","interaction_type":"functional only","direction_and_effect":"Galectin-8 inhibited adhesion of human 1299 carcinoma cells to plates coated with integrin ligands and induced apoptosis (antagonist of adhesion); effects were not mimicked by galectin-1 or galectin-3, and Mn2+ abolished the inhibition [PMID:10852818].","molecular_requirements":"The identified binder is the alpha3beta1 integrin; alpha6 is not named in the abstract shown [PMID:10852818].","affinity_potency":[],"species_and_systems":"Human 1299 carcinoma cells; alpha3beta1 also from HeLa and human endothelial cells; mouse pair is ortholog-inferred [PMID:10852818].","localisation_and_range":"Galectin-8 is a secreted protein (secreted flag [flag]); endogenous galectin-8 secreted from 1299 cells forms complexes with surface alpha3beta1 integrin [PMID:10852818].","caveats":"ITGA6 is not named in the shown abstract; the human pair is ortholog-inferred rather than directly tested, so support here is indirect. Abstract only; glycan-mediated binding. No affinity reported.","key_references":[{"PMID":"10852818","why":"Galectin-8 binding to alpha3beta1 integrin inhibits adhesion and induces apoptosis"}],"covers":["LR002899","LR006129"]},"LR001881":{"pair":"LGALS9 -> CD44","headline":"Galectin-9 reported to bind CD44 on induced Treg cells; one abstract-only paper, plus a UniProt note.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 increased iTreg stability and function by directly binding CD44, which formed a complex with TGF-betaRI and activated Smad3; curator labels it agonist [PMID:25065622]. UniProt notes LGALS9 interaction activates LCK, ERK and MAPK signalling in NK cells [DB:UniProt].","molecular_requirements":"CD44 forms a complex with TGF-betaRI; galectin-9 acts synergistically with TGF-beta [PMID:25065622]. Extra receptor components beyond this are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator labels both partners human, but the full-text excerpts describe Lgals9-deficient mice and in vitro T-cell differentiation [PMID:25065622]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"Galectin-9 is flagged secreted and CD44 flagged transmembrane [flag]; range not further reported in our evidence.","caveats":"Only one paper, read as abstract only for the curator call. Binding was inferred from the abstract wording; excerpts show carbohydrate-dependence (lactose inhibited iTreg generation) [PMID:25065622]. UniProt evidence is functional [DB:UniProt].","key_references":[{"PMID":"25065622","why":"iTreg stability via galectin-9/CD44/TGF-betaRI/Smad3"}],"covers":["LR001881","LR005223"]},"LR002907":{"pair":"LGALS9 -> IGHM","headline":"Galectin-9 reported to bind IgM-BCR on B cells and inhibit BCR signalling; one paper, abstract-only.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 is identified as a ligand for IgM-BCR; it merges and immobilises IgM-BCR nanoclusters and relocalises them with inhibitory CD45/CD22 [PMID:30120235]. Abstract states exogenous recombinant galectin-9 nearly completely abolishes BCR signalling [PMID:30120235].","molecular_requirements":"Relocalisation with CD45 and CD22 is part of the mechanism; whether the BCR heavy chain alone suffices is not reported in our evidence [PMID:30120235].","affinity_potency":[],"species_and_systems":"Super-resolution imaging and single-particle tracking in B cells; excerpts mention C57BL/6 and Lgals9 knockout mice, so the work is mouse [PMID:30120235]. The human pair is ortholog-inferred.","localisation_and_range":"Galectin-9 flagged secreted [flag]; it is found bound to the surface of primary naive B cells [PMID:30120235].","caveats":"Single paper, read as abstract only for the curator judgement; no affinity reported. Direction is inhibitory on BCR signalling, not a classical agonist.","key_references":[{"PMID":"30120235","why":"Galectin-9 binds IgM-BCR, inhibits BCR signalling"}],"covers":["LR002907","LR006134"]},"LR007218":{"pair":"LGALS9 -> P4HB","headline":"Galectin-9 binds cell-surface protein disulfide isomerase on Th2 cells; supported by one abstract and BioGRID.","interaction_type":"direct binding","direction_and_effect":"Galectin-9 binds cell-surface PDI, regulating its residency time on the plasma membrane [PMID:21670307]. UniProt says the interaction retains P4HB at the Th2 cell surface, increasing disulfide reductase activity, altering redox state and enhancing cell migration [DB:UniProt]. Agonist or antagonist label is not reported in our evidence.","molecular_requirements":"Curator note says the binding is glycan-mediated, via PDI N-glycans [PMID:21670307]. Other requirements not reported.","affinity_potency":[],"species_and_systems":"Th2 T-helper cells; curator labels both partners human, species not otherwise stated in the abstract [PMID:21670307]. BioGRID record is a reconstituted complex [DB:BioGRID].","localisation_and_range":"Galectin-9 flagged secreted; P4HB is flagged non-receptor and non-transmembrane [flag], and is normally an ER enzyme, so it is a surface pool here [PMID:21670307].","caveats":"One paper, abstract only. P4HB is not a classical receptor, and binding is carbohydrate-mediated rather than protein-protein.","key_references":[{"PMID":"21670307","why":"Galectin-9 binds cell-surface PDI on Th2 cells"}],"covers":["LR007218"]},"LR005229":{"pair":"LGI2 -> ADAM22","headline":"LGI2 co-precipitates with Adam22 from rat brain; one full-text paper, with Reactome support.","interaction_type":"direct binding","direction_and_effect":"Both Adam22 and Adam23 antibodies co-precipitated Lgi2 from rat brain [PMID:21829378]. The paper's section title states Lgi2 K518X truncation prevents LGI2 secretion and action on neuronal ADAM receptors [PMID:21829378]. Reactome lists LGI2 binding ADAM22,23 [DB:Reactome].","molecular_requirements":"Reactome lists a complex LGI2:ADAM22,23 at the plasma membrane [DB:Reactome].","affinity_potency":[],"species_and_systems":"Rat brain co-IP and cell-surface binding assay; excerpts include Lagotto Romagnolo dogs, so curator's human label does not match [PMID:21829378]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"LGI family are neuronally secreted proteins [PMID:21829378]; Reactome places the complex at the plasma membrane [DB:Reactome].","caveats":"A co-IP shows association, not direct binding; effect direction and affinity are not reported in our evidence. Reactome is the only database.","key_references":[{"PMID":"21829378","why":"Lgi2 co-IPs with Adam22/23; truncation blocks secretion"}],"covers":["LR001887","LR005229"]},"LR001890":{"pair":"LGI3 -> ADAM23","headline":"LGI3 binds ADAM23 in three papers (adipocytes, brain proteomics); binding shown by pull-down and affinity purification, two papers read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"LGI3 associates with ADAM23 in adipose tissue and 3T3-L1 cells; LGI3 treatment attenuates adipogenesis and this is reversed by ADAM23 knockdown, so it acts as an antagonist of adipogenesis through ADAM23 [PMID:22405860]. In mouse brain LGI3 uses ADAM23 as a receptor [PMID:38194969].","molecular_requirements":"ADAM23 had the highest recovery among ADAM family members in LGI3 pull-downs, but ADAM22 and ADAM11 were also recovered, so ADAM23 is a predominant rather than sole partner [PMID:38194969]. LGI3 also co-assembles with Kv1 channels (Kv1.1, Kv1.2) [PMID:38194969]. A 60-kDa LGI3 form is the major secreted form in 3T3-L1 cells [PMID:22405860].","affinity_potency":[],"species_and_systems":"Adipocyte work used 3T3-L1 cells and ob/ob mouse adipose tissue [PMID:22405860]; the brain work used Lgi3 knock-in mice [PMID:38194969]. The human pair is ortholog-inferred; the mouse pair is directly supported.","localisation_and_range":"LGI3 is secreted (entity flag [flag]); in brain it is secreted from oligodendrocytes and accumulates at juxtaparanodes of myelinated axons [PMID:38194969]. ADAM23 is flagged as secreted and receptor [flag].","caveats":"Two of three papers were read as abstracts only [PMID:22405860][PMID:38194969]. A third paper's statement that LGI3 binds ADAM22/ADAM23 is a browser-read, unverified sentence from a paper about Lgi4 [PMID:20220021]. Reactome records binding of LGI3 to ADAM22, ADAM23 and syntaxin1 [DB:Reactome].","key_references":[{"PMID":"38194969","why":"LGI3 uses ADAM23 as receptor in vivo (affinity purification, Lgi3 knock-in mice)"},{"PMID":"22405860","why":"LGI3 associates with ADAM23 and suppresses adipogenesis through it"}],"covers":["LR001890","LR005232"]},"LR010638":{"pair":"LIN7C -> HTR2C","headline":"Database records only (BioGRID complex, IntAct holdup); no curated paper support.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a reconstituted complex and IntAct a direct holdup interaction [DB:BioGRID][DB:IntAct].","localisation_and_range":"No localisation flags in dossier.","caveats":"Database support only; one paper was judged a different entity. Likely an intracellular scaffold-receptor tail interaction rather than ligand signalling.","key_references":[],"covers":["LR010638"]},"LR006138":{"pair":"LINGO1 -> LINGO1","headline":"LINGO-1 ectodomain binds full-length LINGO-1 in trans and inhibits oligodendrocyte differentiation; one abstract-read paper plus IntAct.","interaction_type":"direct binding","direction_and_effect":"Soluble LINGO-1 ectodomain interacts with itself in trans by binding CHO cells expressing full-length LINGO-1; antagonist of oligodendrocyte differentiation and myelination [PMID:22514275]. The abstract states this activates RhoA per curator note.","molecular_requirements":"Homophilic: one protein is both ligand and receptor. No other subunits are reported.","affinity_potency":[],"species_and_systems":"Mouse; recombinant ectodomain and CHO cells, oligodendrocyte precursor and DRG cocultures [PMID:22514275]. Human pair is ortholog-inferred. IntAct has an anti-tag coimmunoprecipitation for the human self-pair [DB:IntAct].","localisation_and_range":"Membrane-bound with trans (cell-contact) action; soluble ectodomain also acts [PMID:22514275]. Neither entity is flagged secreted [flag].","caveats":"One paper read from abstract only. No affinity reported. Homodimer pairs complicate CCC scoring.","key_references":[{"PMID":"22514275","why":"LINGO-1 ectodomain self-interacts in trans and inhibits OPC differentiation"}],"covers":["LR002912","LR006138"]},"LR004446":{"pair":"LPL -> LRP1","headline":"LPL binds LRP1 with nanomolar affinity in three abstract-only papers; LRP1 acts as a clearance receptor.","interaction_type":"direct binding","direction_and_effect":"LPL competed with activated alpha2-macroglobulin and RAP for LRP binding, and an anti-LRP antibody blocked cellular degradation of 125I-LPL, so LRP mediates LPL uptake [PMID:1281473]. A carboxyl-terminal LPL fragment (residues 378-448) bound LRP and inhibited lipase-mediated lipoprotein uptake, acting as an antagonist of that uptake [PMID:7989348].","molecular_requirements":"The LRP-binding region lies in the C-terminal domain of LPL, residues 313-448, which lacks the catalytic site [PMID:7510694]. Mutating Lys407 to Ala reduced affinity about 10-fold; Trp393/Trp394 mutations abolished lipoprotein binding but had little effect on LRP interaction [PMID:7510694]. Binding of the fragment was blocked by heparin [PMID:7989348].","affinity_potency":[{"value":"KD 18 nM","assay":"125I-LPL binding to purified LRP, solid-phase","system":"bovine milk LPL, human LRP","cite":"PMID:1281473"},{"value":"Ki 6.8 nM","assay":"competition with alpha2M* on LDL-receptor-deficient fibroblasts","system":"bovine milk LPL","cite":"PMID:1281473"},{"value":"KD 2.8 nM","assay":"purified LRP binding to LPL-coated wells","system":"human LPL, human LRP","cite":"PMID:7510694"},{"value":"KD 5 nM","assay":"purified LRP binding to LPLC-coated wells","system":"human LPL C-terminal fragment","cite":"PMID:7510694"}],"species_and_systems":"Purified protein and cultured fibroblast systems; ligand was bovine milk LPL in one paper and human LPL fragments in the others [PMID:1281473][PMID:7510694].","localisation_and_range":"LPL is annotated secreted [flag]. The binding promotes cellular uptake and degradation [PMID:1281473].","caveats":"All three papers read as abstracts only. LRP1 is a catabolic receptor here, not a signalling receptor [PMID:1281473]. Much evidence uses fragments rather than full-length LPL [PMID:7510694][PMID:7989348].","key_references":[{"PMID":"7510694","why":"Maps LRP binding to LPL C-terminal domain; KD 2.8 nM"},{"PMID":"1281473","why":"LPL binds LRP with KD 18 nM and is internalised"},{"PMID":"7989348","why":"C-terminal fragment binds LRP and inhibits lipase-mediated uptake"}],"covers":["LR001032","LR004446"]},"LR002916":{"pair":"LRFN4 -> PTPRS","headline":"LRFN4 (SALM3) binds LAR-family RPTPs including PTPRS in a splice-dependent trans-synaptic interaction; one paper, plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SALM3 interacts with and requires all three LAR-RPTPs (LAR, PTP-sigma, PTP-delta) for presynaptic differentiation [PMID:26321637]. The interaction needs the mini-exon B insert in the LAR-RPTP [PMID:26321637]. Reactome lists SALM3 binding LAR-RPTP [DB:Reactome].","molecular_requirements":"LAR-RPTPs containing meB alone bound SALM3, those with only meA or neither did not; adding meA to meB increased binding. Ig1-3 domains of PTP-delta were sufficient [PMID:26321637].","affinity_potency":[],"species_and_systems":"Paper reports mouse SALM3 and mouse PTP-delta in its assays; dossier species fields say human and the mouse pair is ortholog-inferred [PMID:26321637]. Cell-binding and co-culture assays, plus Salm3 knockout mice [PMID:26321637].","localisation_and_range":"Both flagged transmembrane for the pair, so contact-dependent trans-synaptic adhesion [flag][PMID:26321637].","caveats":"Evidence is family-level for all LAR-RPTPs; pair-specific data for PTPRS are not separated in our evidence. Paper's text names PTP-sigma only in the statement covering all three RPTPs. Affinity not reported in our evidence.","key_references":[{"PMID":"26321637","why":"SALM3 binds LAR-RPTPs in a meB-dependent manner"}],"covers":["LR002916","LR006141"]},"LR006147":{"pair":"LRIG2 -> EGFR","headline":"LRIG2 and its ectodomain co-immunoprecipitate with EGFR and enhance EGFR/Akt signalling in glioblastoma cells; one paper plus two interaction database records.","interaction_type":"direct binding","direction_and_effect":"Full-length LRIG2 and LRIG2 ectodomain physically interact with EGFR and enhance EGFR activation and downstream PI3K/Akt signalling [PMID:25353163]. Curators label the effect agonist [PMID:25353163]. Gefitinib (10 uM) abrogated the Akt activation effect, and the authors suggest LRIG2 stabilises EGFR [PMID:25353163].","molecular_requirements":"The ectodomain alone was sufficient to co-precipitate EGFR, which the authors take to mean the ectodomains mediate recognition [PMID:25353163].","affinity_potency":[],"species_and_systems":"Human glioblastoma cell lines (U87, U251) with overexpressed Flag-tagged LRIG2 [PMID:25353163]. The mouse pair is ortholog-inferred. BioGRID and IntAct list the same co-IP from this paper [DB:BioGRID] [DB:IntAct].","localisation_and_range":"LRIG2 is flagged as non-secreted, but the paper reports that the soluble ectodomain is released from glioblastoma cells [PMID:25353163]. Cell-surface and intracellular colocalisation were seen [PMID:25353163].","caveats":"Evidence is co-IP and colocalisation in overexpressing cells, which does not show direct binding. Both database records cite the same paper, so they are not independent support. Abstract text was truncated; details come from excerpts.","key_references":[{"PMID":"25353163","why":"Co-IP of LRIG2 and its ectodomain with EGFR; enhanced EGFR/Akt activation"}],"covers":["LR002922","LR006147"]},"LR002925":{"pair":"LRRC4 -> NTNG2","headline":"Netrin-G2 and its ligand bind with about 2.5 nM affinity, and mouse knockouts of either share an auditory startle phenotype; crystal structure record present.","interaction_type":"direct binding","direction_and_effect":"Curators label the effect agonist [PMID:17973922]. Genetic inhibition of either netrin-G2 or netrin-G2 ligand gave nearly identical loss of acoustic startle with normal ABR, so they act in the same pathway [PMID:17973922].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Kd 2.5 nM","assay":"binding affinity, method not given in abstract","system":"mouse proteins","cite":"PMID:17973922"}],"species_and_systems":"Mouse proteins and mouse knockouts [PMID:17973922]. The human pair is ortholog-inferred, while the mouse pair is not. Databases hold a co-crystal structure [DB:PDB 3ZYI], BioGRID [DB:BioGRID] and IntAct SPR [DB:IntAct].","localisation_and_range":"Both partners are flagged non-secreted [flag]. Range not reported in our evidence.","caveats":"Abstract only, and the assay behind 2.5 nM is not stated. The paper uses the names netrin-G2 ligand; mapping to LRRC4 comes from the curators.","key_references":[{"PMID":"17973922","why":"About 2.5 nM affinity and matching knockout phenotypes"}],"covers":["LR002925","LR006150"]},"LR005238":{"pair":"LRRC4B -> PTPRD","headline":"NGL-3 (LRRC4B) interacts with PTPdelta via its first two FNIII domains and drives presynaptic differentiation only; one confirming paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"PTPdelta interacts with NGL-3 via its first two FNIII domains; this interaction instructs only presynaptic differentiation, unidirectionally [PMID:20139422]. Curators label it agonist [PMID:20139422].","molecular_requirements":"The first two FNIII domains of PTPdelta are the interacting region [PMID:20139422]. NGL-3 also binds LAR and PTPsigma, so the three LAR-family receptors compete as partners [PMID:20139422].","affinity_potency":[],"species_and_systems":"Human and rodent systems not distinguished in our evidence; curator species listed human [PMID:20139422]. Reactome lists the LRRC4B:PTPRF,PTPRS,PTPRD complex [DB:Reactome]. Both listed species are ortholog-inferred.","localisation_and_range":"Membrane-bound, contact-dependent trans-synaptic adhesion (annotation [flag]).","caveats":"Abstract only, no affinity, and two other judged papers were abstract_insufficient and four review_only. PTPRD is a paralog of PTPRF and PTPRS, which bind the same ligand, so subunit specificity is limited.","key_references":[{"PMID":"20139422","why":"NGL-3 interactions with LAR, PTPdelta and PTPsigma and their synaptic effects"}],"covers":["LR001896","LR005238"]},"LR006156":{"pair":"LRRTM2 -> NRXN2","headline":"LRRTM2 is reported to bind neurexin-2 lacking the S4 insert; support is two abstract-level papers, one only indirect.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 binds neurexins 1, 2 and 3 alpha and beta variants specifically lacking an insert at splice site 4 [PMID:20519524]. A truncating NRXN2 mutation produced a protein that failed to bind LRRTM2 or NLGN2 in cell binding assays [PMID:21424692].","molecular_requirements":"Neurexin must lack the S4 insert [PMID:20519524].","affinity_potency":[],"species_and_systems":"Both papers were read as abstract only; the curator lists human for both partners in the 2011 paper [PMID:21424692]. Pair projected to mouse by orthology. No database records.","localisation_and_range":"Both partners flagged transmembrane [flag].","caveats":"The 2010 paper's evidence sentence names neurexin-1beta; NRXN2 is covered only by the general statement. The 2011 abstract says truncating mutations in NRXN1 and NRXN2 fail to bind, but which protein was tested for LRRTM2 binding is not clear from the abstract. No affinity reported.","key_references":[{"PMID":"20519524","why":"LRRTM2 binds neurexins 1, 2, 3 lacking S4"},{"PMID":"21424692","why":"truncated NRXN proteins fail to bind LRRTM2"}],"covers":["LR002931","LR006156"]},"LR002934":{"pair":"LRRTM4 -> GPC1","headline":"LRRTM4 binds glypicans in a heparan sulfate-dependent manner, with GPC1 covered by a class-level result; one paper, mouse glypicans in HEK293T.","interaction_type":"direct binding","direction_and_effect":"Glypican binds LRRTM4, but not LRRTM2, in an HS-dependent manner [PMID:23911103]. LRRTM4-Fc strongly bound all glypican isoforms tested, and GPC1 and GPC3-6 were detected in the LRRTM4-Fc sample [PMID:23911103].","molecular_requirements":"Heparan sulfate on the glypican is required for binding [PMID:23911103]. Whether the core protein alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Cell surface binding used HA-tagged mouse glypican cDNAs in HEK293T cells; proteomics used rat brain [PMID:23911103]. Human and mouse pairs are orthology-projected. No database records.","localisation_and_range":"Glypican is described as a GPI-anchored HSPG [PMID:23911103]; GPC4 and LRRTM4 localise to pre- and postsynaptic membranes of excitatory synapses [PMID:23911103]. Annotation flag for GPC1 says secreted [flag].","caveats":"Only one paper, read as abstract with excerpts. The curator notes the abstract names glypican generically, but the excerpts cover this paralog. No affinity reported.","key_references":[{"PMID":"23911103","why":"unbiased proteomics identifying glypican as LRRTM4 receptor"}],"covers":["LR002934","LR006159"]},"LR006165":{"pair":"LRRTM4 -> PTPRS","headline":"PTPRS acts as presynaptic receptor in a glypican-4/LRRTM4 complex; direct LRRTM4-PTPRS binding is not shown.","interaction_type":"functional only","direction_and_effect":"Knockdown of PTPsigma, but not LAR, in cultured neurons significantly reduced the synaptogenic activity of LRRTM4 in heterologous synapse-formation assays, and PTPsigma is called a presynaptic receptor for the GPC-4/LRRTM4 complex [PMID:25624497].","molecular_requirements":"PTPsigma bound only proteolytically cleaved GPC-4 in an HS-dependent way and formed an additional complex with LRRTM4 in rat brains [PMID:25624497]. LRRTM4 engagement therefore appears to run through glypican-4.","affinity_potency":[],"species_and_systems":"Rat brain and cultured neurons [PMID:25624497]; BioGRID lists affinity capture-western [DB:BioGRID]. The nanomolar affinity in the abstract is for GPC-4 with PTPsigma, not LRRTM4.","localisation_and_range":"PTPRS is flagged both secreted and transmembrane [flag]; the paper presents it as a presynaptic receptor acting across the synapse [PMID:25624497].","caveats":"Paper read as abstract only; curator quote is a Discussion sentence marked spot-check pending. No direct LRRTM4-PTPsigma binding is reported; the interaction is glypican-bridged.","key_references":[{"PMID":"25624497","why":"PTPsigma as presynaptic receptor for GPC-4/LRRTM4"}],"covers":["LR002940","LR006165"]},"LR002943":{"pair":"LUM -> MMP14","headline":"Lumican directly inhibits MMP-14 activity with moderate affinity (KD about 275 nM); one paper.","interaction_type":"direct binding","direction_and_effect":"The glycosylated form of lumican significantly decreased MMP-14 activity in B16F1 melanoma cells, acting as a competitive inhibitor that completely blocked activity [PMID:25304424]. Curator labels antagonist.","molecular_requirements":"Lumican binds the catalytic domain of MMP-14; decorin did not have this effect [PMID:25304424]. The glycosylated form of lumican is the active form.","affinity_potency":[{"value":"KD ~275 nM","assay":"binding to MMP-14 catalytic domain (SPR per IntAct)","system":"B16F1 melanoma study","cite":"PMID:25304424"}],"species_and_systems":"Human proteins per curator labels; cell system B16F1 melanoma; IntAct lists surface plasmon resonance for this paper [DB:IntAct] [PMID:25304424]. Mouse pair is ortholog-inferred.","localisation_and_range":"Lumican flagged secreted; MMP14 is a membrane protease, not secreted [flag]. Matrix-proximal inhibition [PMID:25304424].","caveats":"Abstract-only. Binding to catalytic domain is a substrate-site interaction, so MMP-14 acts as an enzyme target rather than a signalling receptor. BioGRID lists biochemical activity [DB:BioGRID].","key_references":[{"PMID":"25304424","why":"Lumican competitively inhibits MMP-14, KD about 275 nM"}],"covers":["LR002943","LR006168"]},"LR004464":{"pair":"MATN1 -> ITGA1","headline":"Matrilin-1 associates with the integrin alpha1 subunit in one abstract-only paper; support is thin.","interaction_type":"direct binding","direction_and_effect":"Antibody to integrin alpha1 co-precipitated 125I-CMP (matrilin-1) from MRC5 cell lysates and unlabeled CMP competed, indicating association with alpha1; antibody to alpha1 or beta1 abolished CMP-induced adhesion and spreading [PMID:10196235].","molecular_requirements":"Alpha1beta1 is implicated: alpha1 and beta1 antibodies blocked adhesion, while antibodies to alpha2, alpha3, alpha5, beta2, alpha5beta1 or alphaVbeta5 had little effect [PMID:10196235].","affinity_potency":[],"species_and_systems":"Rabbit chondrocytes and fibroblasts, human epiphyseal chondrocytes and MRC5 fibroblasts; binding shown in human MRC5 lysates [PMID:10196235]. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"MATN1 is flagged secreted [flag]; used as a coating substrate, matrix-type adhesion.","caveats":"Single paper, abstract only; co-precipitation from lysate does not exclude indirect association. A BioGRID reconstituted-complex record cites the same paper [DB:BioGRID].","key_references":[{"PMID":"10196235","why":"matrilin-1 (CMP) adhesion and alpha1 co-precipitation"}],"covers":["LR001051","LR004464"]},"LR004473":{"pair":"MDK -> PTPRZ1","headline":"Midkine binds PTPRZ1 with high affinity in a solid-phase assay; a single abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Midkine binds PTPzeta (PTPRZ1) in a solid-phase binding assay, and the authors conclude PTPzeta is a common receptor for midkine and pleiotrophin [PMID:10212223]. Midkine's C-terminal half is fully active for binding; Arg78 mutation lost high-affinity binding and reduced neuronal migration induction [PMID:10212223].","molecular_requirements":"High-affinity binding depends on Arg78 of midkine, which is proposed to contact the chondroitin sulfate portion of PTPzeta; chondroitinase ABC-treated PTPzeta shows only low-affinity binding [PMID:10212223]. Reactome lists (PTN,MDK):PTPRZ complexes [DB:Reactome].","affinity_potency":[{"value":"Kd 0.58 nM (high-affinity site); 3.0 nM (low-affinity site)","assay":"solid-phase binding, Scatchard analysis","system":"human midkine, rat PTPzeta","cite":"PMID:10212223"}],"species_and_systems":"Human midkine with rat PTPzeta, recombinant/purified in vitro [PMID:10212223]. Human and mouse pairs are both projected from this evidence.","localisation_and_range":"PTPRZ1 is flagged both secreted and transmembrane, and midkine as secreted [flag]; range is not tested in our evidence.","caveats":"Only one paper, read as abstract only. Binding relies on chondroitin sulfate chains of the receptor, so core-protein-only binding is not shown. BioGRID lists a reconstituted complex [DB:BioGRID] and UniProt cites the same paper [DB:UniProt].","key_references":[{"PMID":"10212223","why":"Solid-phase binding with Scatchard Kd values and Arg78 requirement"}],"covers":["LR001060","LR004473"]},"LR006174":{"pair":"MDK -> RNF167","headline":"Midkine binding to the RNF167 ectodomain was seen by SPR in a CRISPRa orphan-receptor screen; single full-text paper.","interaction_type":"direct binding","direction_and_effect":"Midkine ectodomain captured on sensors bound RNF167 ectodomain by SPR; RNF128 (negative control) showed no binding [PMID:36178190]. Functional effect on RNF167 is not reported in our evidence.","molecular_requirements":"RNF167 is a transmembrane PA-TM-RING E3 ligase; the SPR used its ECD [PMID:36178190]. No co-receptor requirement reported.","affinity_potency":[],"species_and_systems":"Human proteins, recombinant ectodomains by SPR, after a cell-based CRISPRa screen [PMID:36178190]. Mouse pair is ortholog-inferred.","localisation_and_range":"Midkine is flagged secreted [flag]; RNF167 is a membrane protein per the paper [PMID:36178190], so a secreted ligand acting on a membrane receptor is plausible but not shown in cells.","caveats":"Only SPR on purified ectodomains; no affinity value reported in our excerpts. Midkine did not bind MFRP or ROR1 in the same study, showing selectivity [PMID:36178190]. RNF167 is an E3 ligase, so physiological signalling direction is unclear.","key_references":[{"PMID":"36178190","why":"SPR binding of MDK and PTN to RNF167-ECD with negative controls"}],"covers":["LR002949","LR006174"]},"LR002952":{"pair":"MFGE8 -> ITGB1","headline":"Human beta1 evidence comes only via alpha8beta1 adhesion to MFGE8; one full-text paper.","interaction_type":"direct binding","direction_and_effect":"alpha8-transfected human SW480 cells adhered to Mfge8, blocked by an alpha8 antibody; ligation of alpha8beta1 by Mfge8 reduced antral smooth muscle contraction through PTEN-dependent RhoA inhibition [PMID:27092791].","molecular_requirements":"beta1 is implicated only as the partner of alpha8 (alpha8beta1); beta1 alone was not tested separately in our evidence [PMID:27092791].","affinity_potency":[],"species_and_systems":"Human SW480 cells; mouse in vivo [PMID:27092791]. Human pair is ortholog-inferred.","localisation_and_range":"Mfge8 is flagged secreted [flag].","caveats":"Two further papers were judged abstract_insufficient and are not shown. The evidence is really for ITGA8; ITGB1 support is subunit-level, which matters for complex scoring.","key_references":[{"PMID":"27092791","why":"alpha8beta1 engagement by Mfge8"}],"covers":["LR002952","LR006177"]},"LR004482":{"pair":"Mfge8 -> Itgb3","headline":"Mouse functional evidence that Mfge8 acts via alphavbeta3 in fatty acid uptake; abstract-level, ortholog-inferred.","interaction_type":"functional only","direction_and_effect":"Mfge8 coordinated fatty acid uptake via alphavbeta3- and alphavbeta5-dependent Akt phosphorylation by PI3K and mTORC2, driving Cd36 and Fatp1 translocation [PMID:24441829].","molecular_requirements":"beta3 acts with alphav; beta5 is an alternative partner [PMID:24441829].","affinity_potency":[],"species_and_systems":"Mfge8-deficient mice and cells [PMID:24441829]. The pair is projected as mouse.","localisation_and_range":"Mfge8 is flagged secreted [flag].","caveats":"Abstract-level only; no direct binding assay for beta3 in our evidence; effect on beta3 cannot be separated from beta5.","key_references":[{"PMID":"24441829","why":"Mfge8 signals via alphavbeta3/beta5 to Akt"}],"covers":["LR004482"]},"LR006183":{"pair":"MIF -> EGFR","headline":"Secreted, O-GlcNAcylated MIF binds the EGFR extracellular domain and acts as an antagonist; one full-text paper plus interaction records.","interaction_type":"direct binding","direction_and_effect":"MIF antagonizes EGFR: it blocked EGF binding and EGF-induced EGFR, ERK and c-Jun phosphorylation, invasion, proliferation and brain tumour formation. EGFR activation induces MMP13, which degrades extracellular MIF [PMID:26280537].","molecular_requirements":"MIF must be O-GlcNAcylated at Ser112/Thr113; bacterially expressed His-MIF did not block EGFR activation, whereas Flag-MIF from mammalian cells did. MIF bound the EGFR extracellular domain directly [PMID:26280537].","affinity_potency":[],"species_and_systems":"Human cells (A431, U87 and others) and purified proteins [PMID:26280537]. Mouse pair is ortholog-inferred.","localisation_and_range":"MIF is naturally secreted and acts on EGFR extracellularly [PMID:26280537]; secreted flag [flag].","caveats":"Single paper; no affinity reported. Activity depends on the modification, so recombinant bacterial MIF is not equivalent [PMID:26280537]. BioGRID and IntAct records exist [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"26280537","why":"O-GlcNAcylated MIF binds EGFR and inhibits its activation"}],"covers":["LR002958","LR006183"]},"LR005247":{"pair":"MMRN2 -> CD248","headline":"MMRN2 directly binds CD248 at a region distinct from the CLEC14A/CD93 site; one paper, with a data caveat in the full text.","interaction_type":"direct binding","direction_and_effect":"CD248 directly binds MMRN2; thrombomodulin does not [PMID:28671670]. CD248 binds a distinct, non-competing MMRN2 region, so CLEC14A and CD248 can bind MMRN2 simultaneously, seen at the endothelium-pericyte interface in human pancreatic cancer [PMID:28671670]. UniProt lists the interaction [DB:UniProt].","molecular_requirements":"Binding depends on a predicted long-loop region of the C-type lectin domain [PMID:28671670]. A CD248 chimera in CLEC14A bound MMRN2FL in far western blotting [PMID:28671670].","affinity_potency":[],"species_and_systems":"Human proteins; HEK293T lysates and human pancreatic cancer tissue [PMID:28671670]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMRN2 is a secreted extracellular matrix protein [flag][PMID:28671670]; CD248 is a transmembrane receptor on fibroblasts and pericytes [flag][PMID:28671670].","caveats":"The CD248-GFP fusion was most likely misfolded, so whole-protein binding could not be shown in that experiment; support came from CTLD chimeras [PMID:28671670]. Abstract read only.","key_references":[{"PMID":"28671670","why":"MMRN2 binding to CLEC14A, CD93 and CD248"}],"covers":["LR001907","LR005247"]},"LR001908":{"pair":"MMRN2 -> CD93","headline":"MMRN2 is a direct ligand for CD93, shown in two independent papers with domain and residue mapping.","interaction_type":"direct binding","direction_and_effect":"MMRN2 is a specific ligand for CD93 [PMID:28912033]; disrupting the interaction reduced endothelial adhesion and migration [PMID:28912033]. CD93 and MMRN2 co-immunoprecipitated in HUVEC lysates [PMID:28671670]. UniProt describes MMRN2 as a CD93 ligand [DB:UniProt]; BioGRID lists co-localisation and reconstituted complex [DB:BioGRID].","molecular_requirements":"CD93 and CLEC14A bind the same non-glycosylated coiled-coil region of MMRN2 [PMID:28671670]. The CD93 C-type lectin domain is needed, and F238 of CD93 engages the MMRN2 coiled-coil domain [PMID:28912033].","affinity_potency":[],"species_and_systems":"Human proteins; HUVEC lysates and human tumour vessels [PMID:28671670][PMID:28912033]. The mouse pair is ortholog-inferred.","localisation_and_range":"MMRN2 is a secreted ECM protein [flag]; CD93 is a transmembrane receptor [flag].","caveats":"Both curator rows were read as abstract only (full-text excerpts for one). Affinity is not reported in our evidence. Mapping relies on docking models and mutagenesis [PMID:28912033].","key_references":[{"PMID":"28912033","why":"Identifies MMRN2 as a CD93 ligand with mutagenesis mapping"},{"PMID":"28671670","why":"Family-wide MMRN2 binding and shared coiled-coil region"}],"covers":["LR001908","LR005248"]},"LR006192":{"pair":"MRC1 -> SIGLEC1","headline":"MRC1 cysteine-rich domain binds sialoadhesin (SIGLEC1) glycoforms; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"CR-Fc bound selectively to sialoadhesin purified from spleen and lymph nodes [PMID:10575006].","molecular_requirements":"Binding is glycoform-specific: only the CR-Fc-binding form of sialoadhesin, with sialidase-resistant charged glycans, is recognised [PMID:10575006].","affinity_potency":[],"species_and_systems":"Mouse spleen and lymph node lysates, ligand blots with an Fc chimera [PMID:10575006].","localisation_and_range":"Both membrane proteins [flag]; SIGLEC1 also carries a secreted flag [flag].","caveats":"Abstract only; glycoform-conditional; single paper; direction (which partner is ligand) follows the curated assignment rather than the paper.","key_references":[{"PMID":"10575006","why":"Identifies sialoadhesin as CR-Fc counter-receptor"}],"covers":["LR002967","LR006192"]},"LR004491":{"pair":"MST1 -> MST1R","headline":"MSP binds and activates RON; well supported by binding, functional and structural records.","interaction_type":"direct binding","direction_and_effect":"MSP binds RON and induces its autophosphorylation, increasing ciliary beat frequency [PMID:9045873]. MSP induces tyrosine phosphorylation of p185RON; HGF does not activate RON and MSP does not activate the HGF receptor [PMID:8062829].","molecular_requirements":"RON is a disulfide-linked alpha/beta heterodimer (p185RON) at the cell surface; a recombinant protein with only MSP's N-terminal two kringles also activates it [PMID:8062829].","affinity_potency":[{"value":"Kd = 0.5 nM","assay":"binding to RON","system":"normal human bronchial epithelial cells","cite":"PMID:9045873"}],"species_and_systems":"Human cells and tissue (bronchial epithelium, nasal cilia) [PMID:9045873]; mouse pair is ortholog-inferred.","localisation_and_range":"MSP is secreted [flag] and found in the bronchoalveolar space; RON sits on the apical surface of ciliated epithelia [PMID:9045873].","caveats":"Both papers read as abstracts only. Records also include PDB 4QT8, IntAct SPR and Reactome [DB:PDB 4QT8][DB:IntAct]. GtoPdb lists no type or action [DB:GtoPdb].","key_references":[{"PMID":"9045873","why":"Kd 0.5 nM binding and ciliary function"},{"PMID":"8062829","why":"Identifies MSP as RON activator"}],"covers":["LR001079","LR004491"]},"LR002970":{"pair":"MSTN -> TGFBR1","headline":"TGFBR1 (ALK5) inferred as myostatin type I receptor from one functional abstract.","interaction_type":"functional only","direction_and_effect":"GDF8 reduced PTX3 with SMAD2/3 phosphorylation; this was abolished by the ALK4/5/7 inhibitor SB431542 and ALK5 knockdown [PMID:25641196].","molecular_requirements":"Acts with type II receptors ACVR2A/ACVR2B per companion rows [PMID:25641196].","affinity_potency":[],"species_and_systems":"Human granulosa cell lines and primary granulosa-lutein cells [PMID:25641196]; mouse pair ortholog-inferred.","localisation_and_range":"Myostatin is secreted [flag].","caveats":"Abstract only; no direct binding of myostatin to TGFBR1 shown; inhibitor is not selective for ALK5.","key_references":[{"PMID":"25641196","why":"SB431542 and ALK5 knockdown in human granulosa cells"}],"covers":["LR002970","LR006195"]},"LR001089":{"pair":"NCAM1 -> ROBO1","headline":"Abstract of a Robo3 paper says Robo3 binds Robo1 and NCAM; it does not describe NCAM-Robo1.","interaction_type":"functional only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms; mouse pair is ortholog-inferred [PMID:16226035].","localisation_and_range":"Not reported in our evidence.","caveats":"The cited sentence is about Robo3 binding Robo1 and NCAM, so NCAM-Robo1 is not itself shown [PMID:16226035]. Abstract only.","key_references":[{"PMID":"16226035","why":"Robo3 binds Robo1 and NCAM heterophilically"}],"covers":["LR001089","LR004500"]},"LR001917":{"pair":"NECTIN1 -> NECTIN1","headline":"Nectin-1 homophilic trans-interaction is measured with a KD of 1 microM; weak compared with heterophilic partners.","interaction_type":"direct binding","direction_and_effect":"Nectin-1 homophilic trans-interaction is mediated by V-to-V domain contacts, with C domains raising affinity [PMID:12011057]. Reactome lists trans and cis homodimers [DB:Reactome].","molecular_requirements":"Nectin-3 and anti-V-domain antibodies compete, mapping the site to the nectin-1 V domain [PMID:12011057].","affinity_potency":[{"value":"KD 1 microM","assay":"homophilic trans-interaction","system":"nectin-1 ectodomain, human","cite":"PMID:12011057"}],"species_and_systems":"Human nectins in the 2002 study [PMID:12011057]; the mouse row is ortholog-inferred.","localisation_and_range":"Membrane adhesion molecule acting in trans at cell-cell junctions [PMID:12011057].","caveats":"Weakest of three nectin-1 interactions; nectin-3 outcompetes it where co-expressed [PMID:12011057]. The ligand and receptor roles are arbitrary. Abstract only.","key_references":[{"PMID":"12011057","why":"Affinity comparison of nectin-1 trans-interactions"}],"covers":["LR001917","LR005256"]},"LR005256":{"pair":"NECTIN1 -> NECTIN1","headline":"Nectin-1 homophilic trans-interaction is measured with a KD of 1 microM; weak compared with heterophilic partners.","interaction_type":"direct binding","direction_and_effect":"Nectin-1 homophilic trans-interaction is mediated by V-to-V domain contacts, with C domains raising affinity [PMID:12011057]. Reactome lists trans and cis homodimers [DB:Reactome].","molecular_requirements":"Nectin-3 and anti-V-domain antibodies compete, mapping the site to the nectin-1 V domain [PMID:12011057].","affinity_potency":[{"value":"KD 1 microM","assay":"homophilic trans-interaction","system":"nectin-1 ectodomain, human","cite":"PMID:12011057"}],"species_and_systems":"Human nectins in the 2002 study [PMID:12011057]; the mouse row is ortholog-inferred.","localisation_and_range":"Membrane adhesion molecule acting in trans at cell-cell junctions [PMID:12011057].","caveats":"Weakest of three nectin-1 interactions; nectin-3 outcompetes it where co-expressed [PMID:12011057]. The ligand and receptor roles are arbitrary. Abstract only.","key_references":[{"PMID":"12011057","why":"Affinity comparison of nectin-1 trans-interactions"}],"covers":["LR001917","LR005256"]},"LR007353":{"pair":"NECTIN3 -> PVR","headline":"Heterophilic trans-interaction between nectin-3 and PVR (Necl-5) shown by two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Tage4 (PVR/Necl-5) heterophilically trans-interacted with nectin-3 but not homophilically [PMID:12740392]; soluble Fc chimeric ectodomains identified nectin3 as a PVR ligand [PMID:11544254]. UniProt notes that trans-interaction with PVR activates CDC42 and RAC [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Curator recorded human; the abstracts do not state species [PMID:12740392] [PMID:11544254].","localisation_and_range":"Membrane-bound, trans at cell junctions [DB:Reactome]; PVR carries a secreted flag [flag].","caveats":"Abstracts only; one further paper was abstract-insufficient. The evidence sentence of PMID 12740392 is generic. BioGRID, IntAct and Reactome records agree [DB:BioGRID].","key_references":[{"PMID":"11544254","why":"Fc-chimera trans-interaction identifying nectin3 as PVR ligand"},{"PMID":"12740392","why":"Tage4/PVR trans-interacts with nectin-3"}],"covers":["LR007353"]},"LR001926":{"pair":"NELL2 -> ROBO3","headline":"Secreted NELL2 acts as a repulsive ligand for ROBO3 on mouse commissural axons; one abstract-only paper plus database records.","interaction_type":"functional only","direction_and_effect":"NELL2 repels mouse commissural axons through Robo3 and helps steer them to the midline; the curator labels it antagonist [PMID:26586761]. UniProt describes it as a repulsive axon guidance cue acting via ROBO3 [DB:UniProt].","molecular_requirements":"Robo3 is reported not to bind Slits or Netrins [PMID:26586761]. Subunit or co-receptor requirements for NELL2 are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were on mouse commissural axons; the paper was read as an abstract only [PMID:26586761]. Database records of a physical complex exist: IntAct surface plasmon resonance [DB:IntAct], PDB 6POG structure [DB:PDB 6POG], Reactome complex [DB:Reactome]. The human pair is listed and the mouse pair is ortholog-inferred.","localisation_and_range":"NELL2 is annotated secreted and ROBO3 transmembrane [flag]; the paper calls NELL2 secreted [PMID:26586761].","caveats":"Only one paper, read as abstract, and its binding is not described in the abstract; binding support comes from the databases.","key_references":[{"PMID":"26586761","why":"Identifies NELL2 as a secreted Robo3 ligand repelling mouse commissural axons"}],"covers":["LR001926","LR005265"]},"LR005265":{"pair":"NELL2 -> ROBO3","headline":"Secreted NELL2 acts as a repulsive ligand for ROBO3 on mouse commissural axons; one abstract-only paper plus database records.","interaction_type":"functional only","direction_and_effect":"NELL2 repels mouse commissural axons through Robo3 and helps steer them to the midline; the curator labels it antagonist [PMID:26586761]. UniProt describes it as a repulsive axon guidance cue acting via ROBO3 [DB:UniProt].","molecular_requirements":"Robo3 is reported not to bind Slits or Netrins [PMID:26586761]. Subunit or co-receptor requirements for NELL2 are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments were on mouse commissural axons; the paper was read as an abstract only [PMID:26586761]. Database records of a physical complex exist: IntAct surface plasmon resonance [DB:IntAct], PDB 6POG structure [DB:PDB 6POG], Reactome complex [DB:Reactome]. The human pair is listed and the mouse pair is ortholog-inferred.","localisation_and_range":"NELL2 is annotated secreted and ROBO3 transmembrane [flag]; the paper calls NELL2 secreted [PMID:26586761].","caveats":"Only one paper, read as abstract, and its binding is not described in the abstract; binding support comes from the databases.","key_references":[{"PMID":"26586761","why":"Identifies NELL2 as a secreted Robo3 ligand repelling mouse commissural axons"}],"covers":["LR001926","LR005265"]},"LR010944":{"pair":"NGFR -> NTRK1","headline":"Receptor-receptor association: p75NTR co-precipitates with TrkA in co-transfected cells; the curated paper is an abstract-only report.","interaction_type":"direct binding","direction_and_effect":"p75NTR was co-precipitated with trkA, trkB and trkC in cells transfected with both receptors [PMID:9927421]. This is a receptor-receptor association, not a ligand-receptor interaction; effect direction is not reported for TrkA specifically.","molecular_requirements":"Deletion mapping was done on trkB and p75NTR, with both extracellular and intracellular domains contributing [PMID:9927421]. UniProt says SQSTM1 bridges NGFR to NTRK1 through TRAF6 [DB:UniProt].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation in doubly transfected cells; species not reported in our evidence; abstract only [PMID:9927421]. BioGRID lists affinity capture-western records [DB:BioGRID].","localisation_and_range":"Both are membrane receptors in the same cell membrane, in close proximity [PMID:9927421].","caveats":"Interaction is co-IP in transfected cells and may be indirect; the mapping was on trkB, not trkA. Nineteen other papers were abstract-insufficient.","key_references":[{"PMID":"9927421","why":"p75NTR co-precipitates with trkA, trkB and trkC"}],"covers":["LR010944"]},"LR001098":{"pair":"NID1 -> ITGB1","headline":"Beta1 integrin (as alpha3beta1) is the entactin receptor in PC-3 cells; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"The entactin receptor isolated by affinity chromatography was identified as integrin alpha 3 beta 1; purified alpha 3 beta 1 bound entactin [PMID:1527019].","molecular_requirements":"Beta1 acts as part of the alpha3beta1 heterodimer; binding was divalent cation-dependent, not eluted by RGD peptides, and alpha 2 beta 1 liposomes did not bind [PMID:1527019].","affinity_potency":[],"species_and_systems":"Human PC-3 prostate carcinoma cells with mouse recombinant entactin-Sepharose; abstract only [PMID:1527019]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Entactin is a basement-membrane glycoprotein; NID1 is annotated secreted [flag].","caveats":"Abstract-only and beta1 specificity is inferred from alpha3beta1 identification; one judged paper was review only.","key_references":[{"PMID":"1527019","why":"Alpha3beta1 identified as entactin receptor"}],"covers":["LR001098","LR004509"]},"LR004509":{"pair":"NID1 -> ITGB1","headline":"Beta1 integrin (as alpha3beta1) is the entactin receptor in PC-3 cells; abstract-level evidence from one paper.","interaction_type":"direct binding","direction_and_effect":"The entactin receptor isolated by affinity chromatography was identified as integrin alpha 3 beta 1; purified alpha 3 beta 1 bound entactin [PMID:1527019].","molecular_requirements":"Beta1 acts as part of the alpha3beta1 heterodimer; binding was divalent cation-dependent, not eluted by RGD peptides, and alpha 2 beta 1 liposomes did not bind [PMID:1527019].","affinity_potency":[],"species_and_systems":"Human PC-3 prostate carcinoma cells with mouse recombinant entactin-Sepharose; abstract only [PMID:1527019]. Both human and mouse pairs are ortholog-inferred.","localisation_and_range":"Entactin is a basement-membrane glycoprotein; NID1 is annotated secreted [flag].","caveats":"Abstract-only and beta1 specificity is inferred from alpha3beta1 identification; one judged paper was review only.","key_references":[{"PMID":"1527019","why":"Alpha3beta1 identified as entactin receptor"}],"covers":["LR001098","LR004509"]},"LR004518":{"pair":"NLGN2 -> NRXN3","headline":"Only a general neuroligin-neurexin paper plus a BioGRID record; NRXN3 and NLGN2 not individually resolved.","interaction_type":"database-asserted only","direction_and_effect":"Neuroligins 2 and 3 were characterised for neurexin binding alongside neuroligin 1 [PMID:8576240]; effect on NRXN3 is not reported in our evidence.","molecular_requirements":"Tight binding needs beta-neurexins lacking a splice site 4 insert [PMID:8576240].","affinity_potency":[],"species_and_systems":"Rat binding assays (curator-listed) [PMID:8576240]; mouse and human pairs are ortholog-projected.","localisation_and_range":"Neither partner is secreted; both carry transmembrane flags [flag], so this is a membrane-bound, contact-dependent (trans-synaptic) pair. BioGRID lists a reconstituted complex [DB:BioGRID].","caveats":"The visible abstract does not resolve which neurexin paralogue binds NLGN2; the cited sentence is descriptive. Abstract only. No affinity.","key_references":[{"PMID":"8576240","why":"General neuroligin-neurexin binding"}],"covers":["LR001107","LR004518"]},"LR004527":{"pair":"NMU -> NMUR2","headline":"Strongly supported direct agonist-receptor pair: radioligand binding, calcium and signalling assays in recombinant human cells, and Reactome, BioGRID, GtoPdb and PDB records.","interaction_type":"direct binding","direction_and_effect":"NMU is an agonist of NMU2R; it raises intracellular Ca2+ and inositol phosphate and inhibits forskolin-stimulated cAMP in HEK-293 cells [PMID:15292653]. The receptor couples to Galpha(q/11) and Galpha(i) [PMID:15331768]. NMU elevates acidification, arachidonic acid metabolite release and Ca2+ in CHO cells expressing TGR-1 [PMID:10887190]. Radiolabeled NMU binds with high affinity to membranes of these cells [PMID:10887190].","molecular_requirements":"Single receptor chain is sufficient in recombinant cells; no co-receptor reported. Binding to the receptor is described as essentially irreversible, followed by internalisation [PMID:15331768].","affinity_potency":[{"value":"EC50 0.50 nM","assay":"intracellular Ca2+ release (stated in abstract for NmU isopeptides)","system":"human NmU1R/NmU2R in HEK-293 cells","cite":"PMID:15292653"},{"value":"EC50 1.50 nM","assay":"inositol phosphate formation","system":"human recombinant receptor in HEK-293 cells","cite":"PMID:15292653"},{"value":"IC50 0.80 nM","assay":"inhibition of forskolin-stimulated cAMP","system":"human NmU2R in HEK-293 cells","cite":"PMID:15292653"}],"species_and_systems":"Human recombinant receptors in HEK-293 cells [PMID:15292653][PMID:15331768]; TGR-1 in CHO cells from rat cDNA [PMID:10887190]; endogenous receptors in isolated rat smooth muscle cells [PMID:15331768]. The mouse pair is inferred from human by orthology.","localisation_and_range":"NMU is flagged secreted and the receptor transmembrane [flag]; the papers do not address range.","caveats":"Almost all papers were read as abstracts only. PMID:10899166 does not state species. PMID:10894543 names no specific binding assay or affinity.","key_references":[{"PMID":"10887190","why":"TGR-1 (NMUR2) activated by NMU with high-affinity radioligand binding in CHO cells"},{"PMID":"15292653","why":"Radioligand binding and signalling of both human receptors"},{"PMID":"15331768","why":"G protein coupling and near-irreversible binding"}],"covers":["LR001116","LR004527"]},"LR007371":{"pair":"NODAL -> ACVR1C:ACVR2B:TDGF1","headline":"Nodal signals through ALK7 (ACVR1C) in human trophoblasts; ACVR2B and TDGF1 parts are not evidenced by the curated paper.","interaction_type":"functional only","direction_and_effect":"Nodal overexpression decreased viable trophoblast cell number and induced apoptosis; the effect was mimicked by constitutively active ALK7 and blocked by kinase-deficient ALK7 and by dominant-negative Smad2/3, so Nodal acts as an agonist via ALK7 and Smad2/3 [PMID:15150278].","molecular_requirements":"ACVR1C (ALK7) is the only chain supported by the paper. The type II chain ACVR2B and the co-receptor TDGF1 are not named in the abstract [PMID:15150278]. BioGRID lists reconstituted complexes for TDGF1-NODAL and ACVR2B-NODAL [DB:BioGRID, PMID:28126904].","affinity_potency":[],"species_and_systems":"Human trophoblast cells (HTR8/SVneo and choriocarcinoma lines), overexpression; paper read as abstract only [PMID:15150278].","localisation_and_range":"Nodal is flagged secreted [flag]; TDGF1 is flagged transmembrane [flag].","caveats":"Complex only partly evidenced: one chain from a functional paper read as abstract only, the rest from BioGRID. The CFC co-receptor requirement is not tested in this paper.","key_references":[{"PMID":"15150278","why":"Nodal and ALK7 inhibit proliferation and induce apoptosis in human trophoblast cells"}],"covers":["LR007371"]},"LR006219":{"pair":"NPDC1 -> PILRA","headline":"NPDC1 is a novel PILR-alpha binding partner; binding needs sialylated O-glycans and a conserved Arg; one paper.","interaction_type":"direct binding","direction_and_effect":"NPDC1 was identified as a PILR-alpha binding partner, with PILR-alpha described as an inhibitory receptor [PMID:22396535].","molecular_requirements":"Sialylated O-glycans on ligands are compulsory for PILR-alpha binding, and Arg-133 (mouse) or Arg-126 (human) of PILR-alpha is required [PMID:22396535]. IntAct lists SPR [DB:IntAct, PMID:22396535].","affinity_potency":[],"species_and_systems":"Mouse and human PILR-alpha mutagenesis; experiment system for NPDC1 not detailed in our evidence [PMID:22396535].","localisation_and_range":"NPDC1 is flagged non-secreted [flag]; PILRA is flagged both secreted and transmembrane [flag].","caveats":"Abstract only. Binding depends on ligand glycosylation, so recombinant or non-glycosylated forms may not bind.","key_references":[{"PMID":"22396535","why":"Sialylation-dependent PILR-alpha ligands including NPDC1"}],"covers":["LR002995","LR006219"]},"LR004536":{"pair":"NPNT -> ITGA8","headline":"Nephronectin binds integrin alpha8beta1 in an RGD-dependent manner; one mouse study with strong binding evidence.","interaction_type":"direct binding","direction_and_effect":"Soluble alpha8beta1-alkaline phosphatase probe binds nephronectin, and the two form a complex in vivo [PMID:11470831]. Binding was abolished by GRGDSP peptide but not GRGESP [PMID:11470831]. Effect on signalling is not reported in our evidence beyond the Stimulatory annotation.","molecular_requirements":"ITGA8 acts as the alpha8beta1 heterodimer with ITGB1 [PMID:11470831]; Reactome lists an NPNT:ITGA8:ITGB1 complex [DB:Reactome]. Binding maps to nephronectin residues 382-561, likely including the RGD, which the paper says was not proven by mutation [PMID:11470831].","affinity_potency":[],"species_and_systems":"Mouse (newborn kidney extracts, mouse nephronectin) with recombinant probe and fusion proteins [PMID:11470831]. The human pair is ortholog-inferred.","localisation_and_range":"Nephronectin is an extracellular matrix protein with a signal peptide and no transmembrane region [PMID:11470831]; ligand-expressing ureteric bud and receptor-expressing mesenchyme are adjacent [PMID:11470831].","caveats":"Single paper. Several other RGD-binding integrins also bind nephronectin [PMID:11470831], so the pair is not exclusive. BioGRID records come from the same paper [DB:BioGRID].","key_references":[{"PMID":"11470831","why":"Identifies nephronectin as alpha8beta1 ligand with RGD-dependent binding"}],"covers":["LR001126","LR004536"]},"LR004545":{"pair":"NPS -> NPSR1","headline":"Neuropeptide S activates NPSR1 as a full agonist with Ca2+ mobilisation; supported by functional papers and databases.","interaction_type":"functional only","direction_and_effect":"NPS activates NPSR and mobilises intracellular Ca2+ [PMID:15312648]; GtoPdb lists full agonist [DB:GtoPdb]. NPS-NPSR1 signalling increased expression of cholecystokinin, VIP, PYY and somatostatin in NPSR1-transfected HEK293 cells [PMID:19732772]. UniProt says NPSR1 signals via Gq/GNAQ-dependent phospholipase C [DB:UniProt].","molecular_requirements":"Receptor-only; no co-receptor reported.","affinity_potency":[{"value":"pEC50 8.0","assay":"Ca2+ mobilisation","system":"receptor-activation assay","cite":"PMID:15312648"}],"species_and_systems":"Ca2+ assay plus mouse and rat in vivo behaviour [PMID:15312648]; human NPSR1-transfected HEK293 cells [PMID:19732772]. Both pairs are ortholog-inferred.","localisation_and_range":"NPS annotated secreted and NPSR1 transmembrane [flag].","caveats":"Abstract-only reading. Effects in the physiology papers are downstream and do not measure binding.","key_references":[{"PMID":"15312648","why":"NPS activates NPSR; in vivo arousal and anxiety effects"},{"PMID":"19732772","why":"NPS-NPSR1 signalling in enteroendocrine context"}],"covers":["LR001135","LR004545"]},"LR004554":{"pair":"NPY -> PRLHR","headline":"NPY binds PRLHR1 only at micromolar levels and blocks PRLH signalling; a weak antagonist from a single abstract.","interaction_type":"direct binding","direction_and_effect":"A micromolar level of NPY bound and completely inhibited the PRLH-evoked response in PRLHR1-expressing cells, so NPY acts as an antagonist here, not an agonist [PMID:15885496][DB:GtoPdb].","molecular_requirements":"Single receptor chain (PRLHR1 subtype); no co-receptor reported.","affinity_potency":[{"value":"pKi 5.4","assay":"curator-recorded affinity; NPY inhibition of PRLH response","system":"PRLHR1-expressing cells","cite":"PMID:15885496"}],"species_and_systems":"Cells expressing vertebrate PRLHR1; the dossier lists human ligand and receptor [PMID:15885496]. Mouse pair is projected from human.","localisation_and_range":"NPY is flagged secreted, PRLHR transmembrane [flag].","caveats":"Single paper, read as abstract only. The effect is weak (micromolar) and is likely an evolutionary cross-reactivity rather than physiological signalling. The pKi is curator-recorded.","key_references":[{"PMID":"15885496","why":"Micromolar NPY inhibits PRLH response at PRLHR1"}],"covers":["LR001145","LR004554"]},"LR006228":{"pair":"NRG1 -> ITGA6","headline":"Single abstract-level report that NRG1 binds integrin alpha6 (ITGA6); one paper, stored per subunit, not the dimer.","interaction_type":"direct binding","direction_and_effect":"NRG1 (isolated EGF-like domain or native multi-domain form) binds integrins; Lys-to-Glu mutants suppressed integrin binding and ErbB3 phosphorylation, so integrin binding appears to support NRG1-ErbB3 signalling [PMID:20682778]. UniProt states this binding is essential for NRG1-ERBB signalling [DB:UniProt].","molecular_requirements":"NRG1 binds the integrin heterodimers alphavbeta3 and alpha6beta4; the dossier stores them per subunit [PMID:20682778]. alpha6beta4 was functionally dominant for forming the integrin-NRG1-ErbB3 ternary complex [PMID:20682778]. A UniProt record says the ternary complex includes ERBB3 [DB:UniProt]. This row names only one chain; the evidence concerns the heterodimer.","affinity_potency":[{"value":"KD 136 nM (1.36 x 10(-7) m), to alphavbeta3","assay":"direct binding","system":"purified integrins","cite":"PMID:20682778"}],"species_and_systems":"Human ligand and human receptor, purified proteins; the mouse pair is projected from human evidence [PMID:20682778].","localisation_and_range":"NRG1 is flagged both secreted and transmembrane [flag]; range not addressed in the paper text we have.","caveats":"Only one paper, read as abstract only. The KD is for alphavbeta3, not for this individual chain. Chain-only row for a heterodimeric receptor; the integrin dimer should be the unit scored.","key_references":[{"PMID":"20682778","why":"Direct NRG1-integrin binding and integrin-NRG1-ErbB3 ternary complex"}],"covers":["LR003004","LR006228"]},"LR004563":{"pair":"NRTN -> GFRA2","headline":"NRTN is a preferred ligand for GFRA2, supported by binding, signalling, structure and UniProt records.","interaction_type":"direct binding","direction_and_effect":"GFRA2 mediates NTN signalling through Ret, and TrnR2-Ret cells are more sensitive to NTN than to GDNF [PMID:9182803]. UniProt calls GFRA2 the receptor for neurturin [DB:UniProt].","molecular_requirements":"GFRA2 acts with Ret; GFRA2 is GPI-linked [PMID:9182803]. Binding of 125I-ligand to human GFRalpha1/2 was studied with and without cRET [PMID:10829012]. PDB entries contain chains of NRTN and GFRA2 [DB:PDB 5MR4].","affinity_potency":[{"value":"approximately 30-fold more sensitive to NTN than to GDNF","assay":"Ret phosphorylation, relative sensitivity of TrnR2-Ret cells","system":"fibroblasts expressing TrnR2 and Ret","cite":"PMID:9182803"}],"species_and_systems":"Human receptors, fibroblasts and 125I-ligand binding to human GFRalpha2 [PMID:10829012][PMID:9182803].","localisation_and_range":"NRTN annotated secreted [flag]; GFRA2 GPI-anchored [PMID:9182803].","caveats":"Papers read as abstracts only; affinity values from PMID 10829012 are not in our abstract text. Review-only and pending papers not counted.","key_references":[{"PMID":"9182803","why":"TrnR2 (GFRA2) mediates NTN signalling via Ret"},{"PMID":"10829012","why":"Ligand binding to human GFRalpha1/2 with and without cRET"}],"covers":["LR001154","LR004563"]},"LR006237":{"pair":"NRTN -> SDC3","headline":"Direct binding of matrix-immobilised NRTN to the heparan sulfate chains of syndecan-3, with RET-independent cell effects; one paper.","interaction_type":"direct binding","direction_and_effect":"Immobilised NRTN induced adherence and spreading of SHEP cells in an HSPG-dependent way; these cells do not express RET, so the effect is RET-independent [PMID:21200028]. Syndecan-3 may transduce GFL signals directly or act as a co-receptor presenting GFLs to RET [PMID:21200028].","molecular_requirements":"Binding is via the heparan sulfate chains of syndecan-3; heparinase III treatment inhibited GDNF-syndecan-3 binding and reduced cell adherence [PMID:21200028]. Src-family kinase activation is involved in spreading.","affinity_potency":[{"value":"Kd 10-50 nM","assay":"surface plasmon resonance, immobilised GFLs vs syndecan-3 ectodomain (reported for GDNF, NRTN, ARTN together)","system":"syndecan-3 purified from rat brain","cite":"PMID:21200028"}],"species_and_systems":"Rat brain syndecan-3 ectodomain by SPR; SHEP cell assays; human/mouse labels in the dossier come from curation. Mouse pair is ortholog-inferred.","localisation_and_range":"Syndecan-3 is a transmembrane proteoglycan; NRTN acted when matrix-immobilised, not soluble [PMID:21200028]. NRTN is flagged secreted [flag].","caveats":"Single paper, read as abstract by curators though full text was available. The effect applies to immobilised, not soluble, ligand. It is a heparan sulfate interaction, which may be shared with other HS-binding proteins.","key_references":[{"PMID":"21200028","why":"NRTN, GDNF and ARTN bind syndecan-3 HS chains; RET-independent cell spreading"}],"covers":["LR003013","LR006237"]},"LR006246":{"pair":"NRXN1 -> NLGN1","headline":"Classic direct binding of neurexin-1beta to neuroligin-1, Ca2+-dependent, supported by a cell-aggregation paper and BioGRID.","interaction_type":"direct binding","direction_and_effect":"Cells expressing neurexin 1beta aggregate only with cells expressing neuroligin 1; the two function as heterophilic cell adhesion molecules [PMID:9325340].","molecular_requirements":"Binding needs Ca2+ (half-maximal at 1-3 microM free Ca2+) and only neurexin 1beta lacking an insert in splice site 4 binds; aggregation was inhibited by soluble neurexin 1beta lacking the insert [PMID:9325340].","affinity_potency":[],"species_and_systems":"Detergent-solubilised neuroligins and transfected cell lines; species not stated in dossier. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"Both are transmembrane [flag]; trans-cellular adhesion. BioGRID lists reconstituted complexes [DB:BioGRID].","caveats":"Abstract-only read. No affinity value in our evidence.","key_references":[{"PMID":"9325340","why":"neurexin 1beta-neuroligin 1 Ca2+-dependent cell aggregation"}],"covers":["LR003022","LR006246"]},"LR006255":{"pair":"NRXN3 -> LRRTM2","headline":"LRRTM2 binds alpha- and beta-neurexins directly; the paper treats neurexins generically, so NRXN3 is inferred.","interaction_type":"direct binding","direction_and_effect":"LRRTM2 directly binds alpha- and beta-neurexins and forms a trans cell-adhesion junction [PMID:20064387].","molecular_requirements":"Binding needs neurexins lacking an insert in splice site #4 and is Ca2+ dependent; all three alpha-neurexins appeared in the LRRTM2 affinity purification and all three beta-neurexins bound per the curator note [PMID:20064387].","affinity_potency":[],"species_and_systems":"Recombinant Ig-fusions in HEK293/HEK293T cells and rat brain affinity chromatography [PMID:20064387]. Both species rows are ortholog-inferred.","localisation_and_range":"Both partners are flagged as transmembrane, non-secreted [flag], so contact-dependent (juxtacrine/trans-synaptic) signalling is implied; the paper shows trans cell adhesion [PMID:20064387].","caveats":"Evidence sentence names neurexins generically; two other judged rows were a different entity.","key_references":[{"PMID":"20064387","why":"LRRTM2 binds alpha/beta-neurexins, trans adhesion"}],"covers":["LR003031","LR006255"]},"LR004572":{"pair":"NTN1 -> DCC","headline":"Well-supported direct binding of netrin-1 to DCC, with structural, binding and functional evidence; netrin-1 acts as an attractive agonist.","interaction_type":"direct binding","direction_and_effect":"Netrin-1 binds DCC and acts as an agonist: an anti-DCC antibody blocks netrin-1-dependent commissural axon outgrowth in vitro [PMID:8861902]. Netrin-1 engages DCC through its EGF-3 domain [PMID:29503192].","molecular_requirements":"Netrin-1 binds the fifth fibronectin type III repeat of DCC, with 1:1 stoichiometry in solution [PMID:12810718]. APP acts as a co-receptor in the DCC complex and enhances netrin-1-driven MAPK signalling [PMID:22782894]. Draxin tethers netrin-1 to DCC [PMID:29503192]. Binding in one cell-surface study appeared to depend on a coreceptor or accessory proteins [PMID:9950216].","affinity_potency":[],"species_and_systems":"Experiments in the dossier used human proteins [PMID:12810718][PMID:29503192]; commissural axon outgrowth in vitro [PMID:8861902]; rat commissural axons and Xenopus spinal axons [PMID:11239160]. Mouse pair is ortholog-inferred. Also recorded in BioGRID, IntAct, PDB 4URT and Reactome [DB:PDB 4URT][DB:Reactome].","localisation_and_range":"Netrin-1 is secreted and DCC is transmembrane [flag]; DCC is described as expressed on commissural axons [PMID:8861902].","caveats":"Most papers were read as abstracts only. In one study netrin-1 could be cross-linked to DCC on the cell surface but did not immunoprecipitate without cross-linking and failed to bind a soluble DCC ectodomain fusion [PMID:9950216]. One retracted row is not shown.","key_references":[{"PMID":"8861902","why":"Identifies DCC as a netrin-1-binding receptor on commissural axons"},{"PMID":"12810718","why":"Maps netrin binding to DCC fifth fibronectin repeat"},{"PMID":"29503192","why":"Crystal structures with Draxin; netrin-1 uses EGF-3 domain"}],"covers":["LR001163","LR004572"]},"LR006264":{"pair":"NTN4 -> ITGB1","headline":"Netrin-4 binds alpha6beta1 integrin dose-dependently in endothelial cells; one abstract-only paper, no chain-specific data.","interaction_type":"direct binding","direction_and_effect":"Alpha6beta1 integrin binds netrin-4 in a dose-dependent manner; inhibiting alpha6 or beta1 suppresses netrin-4-induced endothelial migration, adhesion, focal adhesion contact and Src-family phosphorylation [PMID:21799154].","molecular_requirements":"The binding is to the alpha6beta1 heterodimer; both the alpha6 and beta1 subunits are needed for the functional effects [PMID:21799154]. Chain-specific binding is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Endothelial and lymphatic endothelial cells; species is not stated in the curation record [PMID:21799154]. Pair is ortholog-inferred for both species.","localisation_and_range":"Netrin-4 is flagged secreted [flag].","caveats":"Abstract only. The ITGB1 pair is a subunit of the complex; CCC tools scoring complexes need both integrin chains.","key_references":[{"PMID":"21799154","why":"Netrin-4 binds and activates endothelial alpha6beta1 integrin"}],"covers":["LR003040","LR006264"]},"LR004581":{"pair":"NTNG1 -> LRRC4C","headline":"Netrin-G1 binds NGL-1 (LRRC4C): binding, structure and KO mouse data support a real trans-synaptic pair.","interaction_type":"direct binding","direction_and_effect":"NGL-1 interacts specifically with netrin-G1 through its LRR region [PMID:14595443]. Surface-bound NGL-1 stimulates, but soluble NGL-1 disrupts, thalamic axon growth [PMID:14595443]. Netrin-G1 and NGL1 specify excitatory synapses in the hippocampal temporoammonic pathway [PMID:25411505].","molecular_requirements":"Not reported in our evidence beyond the LRR region of NGL-1 [PMID:14595443].","affinity_potency":[],"species_and_systems":"Human NGL-1 with mouse thalamic axons [PMID:14595443]; netrin-G and NGL knockout mice [PMID:25411505]. Database records: BioGRID co-crystal structure, IntAct surface plasmon resonance and PDB 3ZYJ [DB:PDB 3ZYJ][DB:BioGRID][DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Netrin-G1 is a lipid-anchored protein [PMID:14595443]; NGL-1 is a transmembrane protein [PMID:14595443]. Trans-synaptic or contact-mediated.","caveats":"Abstracts only; no affinity numbers in our evidence. The 2014 paper states the pairing as background rather than testing it directly. One abstract_insufficient row is not shown.","key_references":[{"PMID":"14595443","why":"Identifies NGL-1 as netrin-G1 ligand"},{"PMID":"25411505","why":"Netrin-G1/NGL1 knockout mouse synapse specificity"}],"covers":["LR001172","LR004581"]},"LR001179":{"pair":"NXPH3 -> NRXN1","headline":"Neurexophilin-3 binds neurexin LNS2, shown by recombinant binding in mouse and a 2019 study; one more paper is pending.","interaction_type":"direct binding","direction_and_effect":"Neurexophilins 1 and 3 but not 4 bind the second LNS domain in all three alpha-neurexins [PMID:9856994]. The 2019 study tested binding of Nxph1 and Nxph3 to Nrxn1-3 LNS2SS2- and reports reduced binding affinity for both with I401Q mutants [PMID:31566781].","molecular_requirements":"LNS2 domain is required, all splice variants bind in the 1998 study [PMID:9856994]. The I401Q mutation weakens binding [PMID:31566781].","affinity_potency":[],"species_and_systems":"Recombinant mouse proteins and knockout mice [PMID:9856994]; recombinant structure-based assays [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; membrane neurexin [flag].","caveats":"The NXPH3 evidence in [PMID:31566781] is a figure-legend sentence and no affinity numbers are in our excerpts. [PMID:9856994] read as abstract only. One more paper is pending.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001179","LR004588"]},"LR004590":{"pair":"NXPH3 -> NRXN3","headline":"Neurexophilin-3 binds neurexin-3 LNS2 per a 2019 full-text study and a 1998 recombinant study.","interaction_type":"direct binding","direction_and_effect":"Nxph3 binding to Nrxn1-3 LNS2SS2- was tested [PMID:31566781], and neurexophilins 1 and 3 bind the second LNS domain of all three alpha-neurexins [PMID:9856994].","molecular_requirements":"LNS2 is the binding domain [PMID:9856994]. The equivalent I401Q mutation in Nrxn3 decreased Nxph1 binding from the nanomolar to the millimolar range; Nxph3 values are not stated in our excerpts [PMID:31566781].","affinity_potency":[],"species_and_systems":"Recombinant mouse proteins [PMID:9856994]; recombinant LNS2 constructs [PMID:31566781]. Both species pairs are ortholog-inferred.","localisation_and_range":"Secreted ligand [flag]; membrane neurexin [flag].","caveats":"The quoted NXPH3 sentence is a lead-in, not a result. No Nxph3 affinity in our evidence. The 1998 paper was abstract only.","key_references":[{"PMID":"31566781","why":"Structures of Nxph1 with Nrxn LNS2 and isoform specificity"},{"PMID":"9856994","why":"NXPH1 and NXPH3 bind LNS2 of all three alpha-neurexins"}],"covers":["LR001181","LR004590"]},"LR010836":{"pair":"OLFM2 -> ROBO2","headline":"No verified evidence: only a two-hybrid pooling record in IntAct and a review-only paper judgement.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct lists a physical association detected by two-hybrid pooling [DB:IntAct]; species not stated.","localisation_and_range":"ROBO2 carries both secreted and transmembrane flags [flag]; ligand localisation not annotated.","caveats":"No curator-confirmed paper; the single judged paper was review-only. Rests on a high-throughput yeast two-hybrid record alone, which does not show a direct or functional interaction.","key_references":[],"covers":["LR010836"]},"LR001188":{"pair":"OSM -> OSMR","headline":"OSM signals through OSMR (OSMRbeta) paired with gp130; functional and structural-mapping evidence, no direct binding data.","interaction_type":"functional only","direction_and_effect":"OSMRbeta forms a gp130-OSMRbeta complex activated by OSM but not LIF [PMID:8999038]. The OSM site 3 motif (Phe160/Lys163) is responsible for LIFR and OSMR binding [PMID:10997905]. GtoPdb lists OSM as agonist of OSMR [DB:GtoPdb].","molecular_requirements":"OSMR acts with gp130 as a heterodimer [PMID:8999038]; OSMR on its own is not tested in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins, abstract-level; mouse pair is ortholog-inferred, not tested.","localisation_and_range":"OSM is flagged secreted [flag]; OSMR carries a receptor flag only [flag].","caveats":"Both papers abstract only; the structure is of OSM alone [PMID:10997905]. No binding affinity. One further paper is still pending and not shown.","key_references":[{"PMID":"8999038","why":"Cloning of OSMRbeta; OSM-specific gp130 complex"},{"PMID":"10997905","why":"OSM site 3 epitope for OSMR"}],"covers":["LR001188","LR004597"]},"LR006273":{"pair":"PCDHA7 -> PCDHA7","headline":"PCDHA7 binds itself homophilically in trans by SPR with interface mutagenesis; mouse data, human by orthology.","interaction_type":"direct binding","direction_and_effect":"Mutations designed to disrupt the alpha7 trans interface inhibited homophilic binding, showing binding occurs via the trans interface [PMID:35253643]. Self-binding, so no distinct ligand and receptor.","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse clustered protocadherin EC1-4 fragments by SPR [PMID:35253643]; the human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Heterophilic binding of close paralogs was not detected, with an estimated lower limit KD of ~200 \u03bcM [PMID:35253643]. Only mouse fragments were tested; alpha isoforms need cis partners for surface delivery in cells, per a curator note.","key_references":[{"PMID":"35253643","why":"SPR plus trans-interface mutagenesis"}],"covers":["LR003049","LR006273"]},"LR003069":{"pair":"PCDHGA3 -> PCDHGA3","headline":"Mouse Pcdhga3 is a well-established homophilic adhesion molecule in K562 assays; used as a positive control.","interaction_type":"direct binding","direction_and_effect":"Two K562 cell populations each transfected with murine PCDHGA3 adhered strongly [PMID:27068704], and \u03b3-Pcdh isoform A3 showed strict homophily [PMID:20679223].","molecular_requirements":"Clustered protocadherin trans interaction is homophilic and isoform-specific; cis multimers with other isoforms may form the actual cell-surface unit, so one isoform alone may not reproduce the interface.","affinity_potency":[],"species_and_systems":"Mouse PCDHGA3 expressed in human K562 cells [PMID:27068704]; mouse isoforms [PMID:20679223]. Human pair is ortholog-inferred.","localisation_and_range":"Membrane-bound cell-adhesion molecule; trans homophilic contact between cells (juxtacrine), not secreted [flag].","caveats":"Cell aggregation only, no affinity. In PMID:27068704 PCDHGA3 served as a control, not the main subject. PMID:20679223 was browser-read and unverified. Paralogs are not interchangeable.","key_references":[{"PMID":"20679223","why":"strict homophily of gamma-Pcdh isoforms"},{"PMID":"27068704","why":"PCDHGA3 homophilic adhesion as control"}],"covers":["LR003069","LR006292"]},"LR006309":{"pair":"PDCD1 -> CD274","headline":"PD-1/PD-L1 binding is well established in databases; the one curated paper shows PD-1 binding triggers PD-L1 intracellular signalling.","interaction_type":"direct binding","direction_and_effect":"In HNSCC models PD-1 binding enhanced PD-L1-driven clonogenicity, motility and invasiveness via ILF2-ILF3 and STAT3; this is signalling into the PD-L1 cell [PMID:37389416]. UniProt describes PDCD1 as delivering inhibitory signals on binding CD274 [DB:UniProt].","molecular_requirements":"Deleting the PD-L1 intracellular domain (delta260-290) disrupted signalling [PMID:37389416]. PD-L1 co-immunoprecipitated with ILF3 but not ILF2 [PMID:37389416].","affinity_potency":[],"species_and_systems":"Human HNSCC cell models and humanized in vivo models with recombinant PD-1 [PMID:37389416]; mouse pair is ortholog-inferred. Structures and binding assays in databases [DB:PDB 4ZQK][DB:IntAct].","localisation_and_range":"PD-L1 is annotated secreted and transmembrane, PD-1 transmembrane [flag]; binding is between membrane proteins (contact).","caveats":"The curated paper is abstract-level support and does not measure binding itself; physical binding rests on databases [DB:BioGRID][DB:Reactome]. Pair is written PD-1 as ligand, PD-L1 as receptor; the paper's bidirectional signalling concerns the PD-L1 side.","key_references":[{"PMID":"37389416","why":"PD-1 binding triggers PD-L1 intracellular signalling in HNSCC."}],"covers":["LR003086","LR006309"]},"LR003087":{"pair":"PDCD1 -> PDCD1LG2","headline":"PD-1 binds PD-L2 with measured SPR kinetics; PD-L2 shows 2-6-fold higher affinity than PD-L1.","interaction_type":"direct binding","direction_and_effect":"B7-DC (PD-L2)/PD-1 exhibited a 2-6-fold higher affinity and different association/dissociation kinetics compared with B7-H1/PD-1 [PMID:12893276]. UniProt: PDCD1 delivers inhibitory signals on ligand binding [DB:UniProt].","molecular_requirements":"Not reported in our evidence beyond soluble Ig fusion proteins of the extracellular parts [PMID:12893276].","affinity_potency":[{"value":"2-6-fold higher affinity than B7-H1/PD-1","assay":"surface plasmon resonance, soluble Ig fusion proteins","system":"human","cite":"PMID:12893276"}],"species_and_systems":"Human recombinant Ig fusions, flow cytometry and SPR [PMID:12893276]; mouse pair ortholog-inferred.","localisation_and_range":"PD-L2 annotated secreted, PD-1 annotated non-secreted [flag]; membrane-bound pair (contact).","caveats":"Abstract only; no absolute affinity in our evidence. Direction listed with PD-1 as ligand; the reverse-direction dossier is G03623.","key_references":[{"PMID":"12893276","why":"SPR comparison of PD-L2 and PD-L1 binding to PD-1."}],"covers":["LR003087","LR006310"]},"LR001197":{"pair":"PDGFB -> PDGFRB","headline":"PDGFB binds and activates PDGFRB; supported by human receptor binding data and database structure and binding records.","interaction_type":"direct binding","direction_and_effect":"PDGF receptor cloned from human cDNA bound PDGF-BB and, less, PDGF-AB, but not PDGF-AA [PMID:2850496]. A soluble PDGFRB decoy reduced PDGF-BB-induced glycosaminoglycan synthesis in fetal lung fibroblasts, consistent with receptor-mediated stimulation [PMID:11903042]. UniProt: PDGFB homodimer interacts with PDGFRB homodimers [DB:UniProt].","molecular_requirements":"The ligand acts as a dimer (PDGFB homodimer; PDGFA:PDGFB heterodimers also bind PDGFRB) [DB:UniProt]. Single receptor chain suffices in the CHO expression assay [PMID:2850496].","affinity_potency":[],"species_and_systems":"Human receptor expressed in CHO cells [PMID:2850496]; human fetal lung fibroblasts [PMID:11903042]. Both papers read as abstracts only. A PDB structure (3MJG) and IntAct and BioGRID binding records exist [DB:PDB 3MJG][DB:IntAct].","localisation_and_range":"PDGFB flagged secreted, PDGFRB transmembrane [flag]; soluble paracrine ligand acting on a cell-surface receptor.","caveats":"Both papers read as abstracts only. The second paper is an indirect functional (decoy) readout. The mouse pair is ortholog-inferred from human evidence. No affinity reported in our evidence.","key_references":[{"PMID":"2850496","why":"Receptor cloned and shown to bind PDGF-BB, not PDGF-AA"},{"PMID":"11903042","why":"Soluble PDGFRB decoy blocks PDGF-BB response in fibroblasts"}],"covers":["LR001197","LR004606"]},"LR004608":{"pair":"PDGFC -> PDGFRB","headline":"PDGFC -> PDGFRB is supported only by database records; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states PDGFC interacts with PDGFRA homodimers and with PDGFRA:PDGFRB heterodimers, not PDGFRB homodimers [DB:UniProt]. An IntAct cross-linking record exists for PDGFC and PDGFRB [DB:IntAct].","molecular_requirements":"Evidence points to the PDGFRA:PDGFRB heterodimer rather than PDGFRB alone [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence beyond the database records.","localisation_and_range":"PDGFC flagged secreted and transmembrane; PDGFRB transmembrane [flag].","caveats":"No verified papers (two abstract-insufficient, one review-only). A standalone PDGFRB homodimer interaction is not supported by the UniProt record. Mouse pair is ortholog-inferred.","key_references":[],"covers":["LR001199","LR004608"]},"LR001935":{"pair":"PECAM1 -> CD38","headline":"CD31 (PECAM1) was identified as a CD38 counter-receptor in 1998 and signals in sperm via soluble CD38.","interaction_type":"functional only","direction_and_effect":"Moon-1 antibody-recognised ligand on HUVEC was shown to be CD31; CD31-CD38 interactions modulate heterotypic adhesion, calcium fluxes and cytokine messages [PMID:9551996]. Soluble CD38 increases sperm capacitation via interaction with CD31 on sperm, with Src phosphorylation of CD31 and Erk1/2 activation [PMID:26407101].","molecular_requirements":"Not reported in our evidence beyond CD31 and CD38 themselves.","affinity_potency":[],"species_and_systems":"Human cells: HUVEC and CD31 transfectants [PMID:9551996]; human sperm with a proximity ligation assay [PMID:26407101]. Abstracts plus some full text.","localisation_and_range":"CD38 is soluble in seminal plasma in one paper [PMID:26407101]; membrane-mediated adhesion in the other [PMID:9551996]. Secreted flag on CD38 is an annotation flag [flag].","caveats":"The first paper identifies CD31 by antibody cross-inhibition and precipitation, not a purified-protein binding assay; no affinity in our evidence. Mouse pair is ortholog-inferred.","key_references":[{"PMID":"9551996","why":"Identifies CD31 as counter-receptor of CD38"},{"PMID":"26407101","why":"Soluble CD38 signals through CD31 on human sperm"}],"covers":["LR001935","LR005273"]},"LR004617":{"pair":"PENK -> OPRM1","headline":"No verified paper; support rests on GtoPdb and IntAct records.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists a partial agonist [DB:GtoPdb]. IntAct reports a scintillation proximity assay between P35372 and P01210 [DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system of the underlying assays not reported in our evidence.","localisation_and_range":"PENK is flagged secreted [flag].","caveats":"No curator-verified paper; all 12 judged rows were abstract_insufficient and one was a different entity. GtoPdb affinity unit pKi has no value in the dossier [DB:GtoPdb].","key_references":[],"covers":["LR001208","LR004617"]},"LR003096":{"pair":"PF4 -> LRP1","headline":"LRP1 blockade or knockdown reverses PF4 inhibition of megakaryocyte colony growth; one abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"RAP or anti-LRP1 antibodies reversed PF4's inhibition of megakaryocyte colony growth; shRNA knockdown restored colony formation in bone marrow from hPF4-overexpressing mice [PMID:19605848].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human megakaryocyte cultures and hPF4-overexpressing mice; infusion of RAP in mice raised platelet counts [PMID:19605848]. Species of human and mouse pairs both non-inferred.","localisation_and_range":"PF4 is flagged secreted [flag]. LRP1 expression is on large polyploid megakaryocytes [PMID:19605848].","caveats":"No binding evidence; RAP is a general antagonist of LDL-receptor family members, so specificity relies on antibodies and shRNA. Abstract only; no database records.","key_references":[{"PMID":"19605848","why":"LRP1 mediates PF4 inhibition of megakaryopoiesis"}],"covers":["LR003096","LR006318"]},"LR006318":{"pair":"PF4 -> LRP1","headline":"LRP1 blockade or knockdown reverses PF4 inhibition of megakaryocyte colony growth; one abstract-only functional paper.","interaction_type":"functional only","direction_and_effect":"RAP or anti-LRP1 antibodies reversed PF4's inhibition of megakaryocyte colony growth; shRNA knockdown restored colony formation in bone marrow from hPF4-overexpressing mice [PMID:19605848].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human megakaryocyte cultures and hPF4-overexpressing mice; infusion of RAP in mice raised platelet counts [PMID:19605848]. Species of human and mouse pairs both non-inferred.","localisation_and_range":"PF4 is flagged secreted [flag]. LRP1 expression is on large polyploid megakaryocytes [PMID:19605848].","caveats":"No binding evidence; RAP is a general antagonist of LDL-receptor family members, so specificity relies on antibodies and shRNA. Abstract only; no database records.","key_references":[{"PMID":"19605848","why":"LRP1 mediates PF4 inhibition of megakaryopoiesis"}],"covers":["LR003096","LR006318"]},"LR005274":{"pair":"PGLYRP1 -> TREM1","headline":"PGLYRP1-peptidoglycan complexes bind and activate TREM-1; one abstract-only paper plus UniProt.","interaction_type":"direct binding","direction_and_effect":"PGLYRP1 with peptidoglycan forms a potent TREM-1 ligand inducing known TREM-1 functions; multimerized PGLYRP1 alone also activates [PMID:25595774]. UniProt cites the interaction [DB:UniProt].","molecular_requirements":"The ligand is normally a PGLYRP1-peptidoglycan complex; multimerization bypasses the peptidoglycan need [PMID:25595774].","affinity_potency":[],"species_and_systems":"Human and mouse recorded in the pair; the abstract does not name the experimental systems [PMID:25595774].","localisation_and_range":"PGLYRP1 is flagged secreted [flag].","caveats":"Abstract only; adaptor TYROBP/DAP12 is part of TREM1 signalling per UniProt [DB:UniProt]. No affinities reported in our evidence.","key_references":[{"PMID":"25595774","why":"PGLYRP1-peptidoglycan complexes bind TREM-1"}],"covers":["LR001937","LR005274"]},"LR006327":{"pair":"PLA2G2A -> ERBB3","headline":"sPLA2-IIa co-immunoprecipitates with HER3 in human cancer cells; one abstract-only paper plus BioGRID.","interaction_type":"direct binding","direction_and_effect":"sPLA2-IIa binds EGFR and HER3 by co-immunoprecipitation, suggesting it functions as a ligand for both [PMID:28440478]. Curated direction: agonist, with HER/ERBB-elicited signalling supporting cancer stem cell properties [PMID:28440478]. BioGRID lists Affinity Capture-Western [DB:BioGRID 2524054].","molecular_requirements":"Not reported in our evidence; HER2 association is indirect [PMID:28440478].","affinity_potency":[],"species_and_systems":"Human lung (A549, H1975) and prostate (22Rv1) cancer cells; nude mouse xenografts [PMID:28440478]. Mouse pair ortholog-inferred.","localisation_and_range":"Secreted, from the PLA2G2A flag [flag] and elevated tumour interstitial fluid levels [PMID:28440478].","caveats":"Abstract only; co-IP does not exclude intermediaries; no affinity reported [PMID:28440478].","key_references":[{"PMID":"28440478","why":"sPLA2-IIa binds EGFR and HER3 by co-IP"}],"covers":["LR003106","LR006327"]},"LR007083":{"pair":"PLA2G2A -> ITGA4:ITGB1","headline":"Complex entry for sPLA2-IIA binding alpha4beta1; no curated papers, supported by IntAct and UniProt records.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states ITGA4:ITGB1 binds PLA2G2A via site 2, distinct from the classical site 1, inducing integrin conformational changes and enhanced ligand binding to site 1 [DB:UniProt P13612]. IntAct lists an ELISA record [DB:IntAct P05556-P14555].","molecular_requirements":"Requires the alpha4:beta1 heterodimer as the unit; the UniProt statements cite two papers whose evidence is judged on the sibling subunit rows [DB:UniProt P05556].","affinity_potency":[],"species_and_systems":"Human, per the database records; no papers judged under this entry.","localisation_and_range":"Secreted ligand, from the PLA2G2A flag [flag]; integrin on the cell surface.","caveats":"No papers were judged under this complex entry; evidence is database records only [DB:UniProt P05556].","key_references":[],"covers":["LR007083"]},"LR004626":{"pair":"PLAU -> LRP1","headline":"LRP binds the uPAR:uPA:PAI-1 complex and affects myogenic cell motility; complex-level, functional evidence only.","interaction_type":"functional only","direction_and_effect":"Interference with [uPAR:uPA:PAI-1] complex formation, or with LRP binding to it, decreased myogenic cell motility [PMID:10896774]. UniProt says LRP1 interacts with uPA/PLAU alone or in complex with SERPINE1 [DB:UniProt Q07954].","molecular_requirements":"The bound unit is the complex of uPAR, uPA and PAI-1 [PMID:10896774]; uPA alone as a LRP1 ligand: not reported in our evidence in the paper.","affinity_potency":[],"species_and_systems":"Human myogenic cells in vitro [PMID:10896774]. Mouse pair listed as non-inferred in our data but with no mouse evidence shown.","localisation_and_range":"Secreted uPA per flag [flag]; receptor-bound uPA and matrix-bound PAI-1 per the abstract [PMID:10896774].","caveats":"Abstract only; no binding measurement. Three other judged papers were abstract_insufficient and one was review_only.","key_references":[{"PMID":"10896774","why":"LRP interaction with uPAR:uPA:PAI-1 supports myogenic cell motility"}],"covers":["LR001223","LR004626"]},"LR006336":{"pair":"PLAUR -> ITGB3","headline":"Direct cell-based binding of soluble uPAR to beta3 (ITGB3) integrin chain in one paper; no affinity.","interaction_type":"direct binding","direction_and_effect":"Soluble uPAR (suPAR D2D3) bound integrin-transfected CHO cells in a cation-dependent manner, blocked by anti-integrin and anti-uPAR antibodies [PMID:11053440]. It acts as a ligand, signalling consequence not reported in our evidence.","molecular_requirements":"Evidence is for the heterodimer; the integrin chain alone was not tested separately [PMID:11053440]. Binding was to alphavbeta3 [PMID:11053440].","affinity_potency":[],"species_and_systems":"Human uPAR on hamster (CHO) cells [PMID:11053440].","localisation_and_range":"uPAR is described as a GPI-anchored protein lacking a transmembrane structure that acts as an integrin ligand, in trans between apposed cells, as well as an associated protein in cis [PMID:11053440]. Cell-cell contact range.","caveats":"Single paper (full text); no affinity.","key_references":[{"PMID":"11053440","why":"uPAR binds integrins alpha4beta1, alpha6beta1, alpha9beta1, alphavbeta3 on CHO cells"}],"covers":["LR003115","LR006336"]},"LR004635":{"pair":"PLG -> PLGRKT","headline":"Plg-RKT is reported as a plasminogen receptor promoting surface activation; direct binding not in the judged paper.","interaction_type":"functional only","direction_and_effect":"Plg-RKT markedly promoted cell-surface plasminogen activation, was a differentiation-induced integral membrane protein with a C-terminal lysine, and colocalised with uPAR [PMID:19897580]. Role is agonist/promoter of activation.","molecular_requirements":"A C-terminal lysine exposed on the surface is described; cooperates with uPAR and apparently tPA [PMID:19897580].","affinity_potency":[],"species_and_systems":"Human proteins and cells; abstract only [PMID:19897580]. IntAct lists an ELISA record [DB:IntAct]. Human pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; receptor integral membrane [PMID:19897580].","caveats":"Abstract only; the evidence sentence is functional. One additional row was review-only.","key_references":[{"PMID":"19897580","why":"Plg-RKT discovery and surface plasminogen activation"}],"covers":["LR001232","LR004635"]},"LR004644":{"pair":"POMC -> MC4R","headline":"POMC-derived peptides bind and activate MC4R, shown in abstract-level binding studies; evidence relies on analogues and a mutant fusion protein.","interaction_type":"direct binding","direction_and_effect":"NDP-MSH, a synthetic alpha-MSH analogue, binds and activates human MC4R, with TM3 and TM6 residues needed for affinity [PMID:11101306]. A mutant beta-MSH/beta-endorphin fusion protein binds hMC4R with affinity similar to its natural ligands but activates it much less [PMID:12165561]. Rat MC4R responds to melanocortin agonists [PMID:10493100]. GtoPdb records agonist action [DB:GtoPdb].","molecular_requirements":"Receptor residues D122, D126, F261 and H264 contribute to NDP-MSH binding in hMC4R [PMID:11101306]. Other requirements not reported in our evidence.","affinity_potency":[{"value":"pKi 7.4-8.0","assay":"GtoPdb affinity range","system":"not specified","cite":"PMID:10493100"}],"species_and_systems":"Human MC4R [PMID:11101306][PMID:12165561]; rat MC4R [PMID:10493100]. Mouse pair is ortholog-inferred. All read as abstracts only.","localisation_and_range":"POMC flagged secreted, MC4R transmembrane [flag]; range not tested.","caveats":"No paper tests native full-length POMC or a single native peptide. NDP-MSH is a stabilised analogue [PMID:11101306]; the fusion protein from a disease mutation is a partial agonist-like variant, so binding and activation dissociate [PMID:12165561].","key_references":[{"PMID":"11101306","why":"hMC4R mutagenesis defining ligand-binding residues"},{"PMID":"12165561","why":"POMC variant fusion protein binds hMC4R but activates poorly"},{"PMID":"10493100","why":"Rat MC3R/MC4R pharmacology"}],"covers":["LR001242","LR004644"]},"LR006345":{"pair":"POSTN -> ITGAV","headline":"Periostin is a ligand for alpha-V integrins, with binding shown for alphaVbeta3/beta5 and in vivo support in mouse haematopoietic stem cells.","interaction_type":"direct binding","direction_and_effect":"Secreted periostin is a ligand for alpha(V)beta(3) and alpha(V)beta(5) integrins and promotes ovarian cancer cell motility [PMID:12235007]. Postn acting through Itgav regulates HSC proliferation; Postn loss raises phenotypic HSC numbers, so the axis restrains proliferation [PMID:27905395].","molecular_requirements":"alphaV pairs with a beta chain; alphaVbeta3 and alphaVbeta5 are named [PMID:12235007]. The HSC paper notes Itgav (CD51) and Itgb3 (CD61) form a heterodimer known to bind Postn [PMID:27905395].","affinity_potency":[],"species_and_systems":"Human ovarian carcinoma cells [PMID:12235007]; mouse bone-marrow HSC in vivo [PMID:27905395]. Both read as abstracts, the second with full-text excerpts.","localisation_and_range":"Periostin is flagged secreted [flag]; matrix and paracrine range not tested beyond the papers.","caveats":"Neither paper reports affinity. The in vivo paper shows a functional link, and the excerpts shown do not themselves demonstrate direct binding [PMID:27905395]. Complex requirement: alphaV needs a beta partner, so score as heterodimer.","key_references":[{"PMID":"12235007","why":"Periostin is a ligand for alphaVbeta3 and alphaVbeta5"},{"PMID":"27905395","why":"Postn-Itgav axis regulates HSC in vivo"}],"covers":["LR003124","LR006345"]},"LR004653":{"pair":"PPY -> NPY5R","headline":"Database-asserted only: GtoPdb lists PP as a full agonist at Y5; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists PP as a full agonist at NPY5R, with affinity in pKi [DB:GtoPdb]; no paper in our evidence shows the effect directly.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence; the GtoPdb record cites PMID 8824284 but no paper was verified. Mouse pair is projected from human.","localisation_and_range":"PPY is flagged secreted and NPY5R transmembrane [flag].","caveats":"No verified papers: seven candidates were abstract_insufficient and one concerned a different entity. Reactome only records that NPY receptors bind NPY-related peptides in general [DB:Reactome]. No affinity value is given in our evidence.","key_references":[],"covers":["LR001252","LR004653"]},"LR001944":{"pair":"PRG4 -> TLR4","headline":"Direct binding of PRG4 to TLR4 by ELISA with inhibitory effect on TLR4 activation; one paper, human recombinant system.","interaction_type":"direct binding","direction_and_effect":"Recombinant and native human PRG4 showed concentration-dependent binding to TLR4 by ELISA, and nhPRG4 inhibited TLR4 activation by its agonist and by OA and RA synovial fluid; the paper classes PRG4 as an antagonist [PMID:26643105]. Depleting PRG4 from synovial fluid did not significantly change TLR4 activation [PMID:26643105].","molecular_requirements":"Not reported in our evidence; binding used immobilised receptor protein, and activity was read in receptor-expressing HEK cells [PMID:26643105].","affinity_potency":[],"species_and_systems":"Human recombinant and native PRG4, TLR-overexpressing HEK cells and patient OA/RA synovial fluid [PMID:26643105]. Mouse pair is projected.","localisation_and_range":"PRG4 is flagged secreted [flag] and described as secreted by synovial fibroblasts and chondrocytes [PMID:26643105].","caveats":"One paper only; no affinity value reported in our evidence. The TLR4 binding is shown, but endogenous PRG4 depletion had no significant effect on TLR4 in synovial fluid, so physiological relevance is weaker than for TLR2 [PMID:26643105].","key_references":[{"PMID":"26643105","why":"PRG4 binds TLR2 and TLR4 and reduces their activation"}],"covers":["LR001944","LR005281"]},"LR006354":{"pair":"PRNP -> ADGRG6","headline":"Functional agonism of ADGRG6 (Gpr126) by the PrP amino-terminal flexible tail, with in vivo zebrafish support; one paper.","interaction_type":"functional only","direction_and_effect":"The PrP(C) flexible tail (residues 23-120) triggered a concentration-dependent cAMP increase in Schwann cells and Adgrg6-overexpressing HEK293T cells; ablating Gpr126 abolished the response [PMID:27501152]. The excerpts also report co-precipitation and increased binding of FT23-50 to Gpr126-expressing cells [PMID:27501152].","molecular_requirements":"The N-terminal flexible tail acts; a KKRPKPG cluster peptide (FT23-50) sufficed, and alanine substitution abolished activity [PMID:27501152].","affinity_potency":[],"species_and_systems":"Mouse Schwann cells and SW10 line, HEK293T cells with human Gpr126, mice and zebrafish [PMID:27501152]; the curator labels species as human.","localisation_and_range":"PRNP is flagged non-secreted and ADGRG6 transmembrane [flag]. The paper proposes PrP(C) acts in trans on Schwann cells [PMID:27501152].","caveats":"Evidence is mostly functional cAMP data with a fragment peptide; full-length PrP binding affinity is not reported. A third paper was review_only. Agonism is by the flexible tail, not shown for intact PrP.","key_references":[{"PMID":"27501152","why":"PrP flexible tail activates Gpr126 cAMP signalling"}],"covers":["LR003133","LR006354"]},"LR004662":{"pair":"PROS1 -> TYRO3","headline":"Protein S is a long-standing agonist ligand of TYRO3 (Dtk); support from 1995-96 and 2014 abstract-only papers.","interaction_type":"functional only","direction_and_effect":"Protein S was identified as a ligand for Tyro 3 [PMID:7867073]; Dtk (Tyro3) was reported to bind protein S [PMID:8641360]. In reporter cells, TYRO3 had its own interaction and activation pattern with PROS1, modulated by apoptotic cells, phosphatidylserine vesicles and virus [PMID:25074926]. GtoPdb lists the record without type or affinity [DB:GtoPdb].","molecular_requirements":"Gamma-carboxylation of ligands is essential for full TAM activation [PMID:25074926].","affinity_potency":[],"species_and_systems":"Human proteins and cells in all three papers [PMID:7867073][PMID:8641360][PMID:25074926]; mouse pair listed as not ortholog-inferred but its experiments are not described.","localisation_and_range":"PROS1 flagged secreted [flag]; context-dependent phosphatidylserine presentation affects activation [PMID:25074926].","caveats":"All papers abstract-only; no affinity reported. PMID 8641360 is mainly an expression study in hematopoiesis and its binding statement is background [PMID:8641360]. Two review-only rows and one different-entity row were excluded.","key_references":[{"PMID":"7867073","why":"First identification of protein S as Tyro3/Axl ligand."},{"PMID":"25074926","why":"Reporter-cell study with PROS1 and TYRO3 activation context."},{"PMID":"8641360","why":"Dtk binds protein S; expression in hematopoiesis."}],"covers":["LR001262","LR004662"]},"LR006363":{"pair":"PSAP -> MRC1","headline":"Mannose receptor takes up prosaposin precursor in mice in vivo; one paper, abstract-level, no direct binding shown.","interaction_type":"functional only","direction_and_effect":"In mice the mannose receptor system on macrophages participates in SAP precursor internalisation, and it removed intravenously injected precursor from blood into liver [PMID:9707421].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In vivo experiments in mice; curator notes browser-read Discussion with spot-check pending [PMID:9707421].","localisation_and_range":"Ligand is flagged secreted and receptor transmembrane [flag]; precursor clearance is endocytic uptake.","caveats":"No direct binding measurement in the dossier; the quote is a curator browser read not yet spot-checked; paper abstract only in our record. Endocytic clearance, not signalling.","key_references":[{"PMID":"9707421","why":"In vivo mouse clearance of SAP precursor via mannose receptor."}],"covers":["LR003142","LR006363"]},"LR008307":{"pair":"PSG9 -> DSCAM","headline":"SPR in a large human cell-surface interactome screen showed PSG9 binding DSCAM; single paper, binding only.","interaction_type":"direct binding","direction_and_effect":"The paper reports SPR binding of DSCAM to PSG9; no effect or signalling is reported [PMID:32822567].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Recombinant human ectodomain proteins, SPR with 2-fold analyte dilutions of 16-2,048 nM; no cell system [PMID:32822567].","localisation_and_range":"Receptor flagged transmembrane [flag]; PSGs are described as secreted proteins in placenta context, DCC is expressed in human placenta [PMID:32822567].","caveats":"Binding of recombinant proteins only, no functional readout, no affinity value in our evidence; in vivo relevance unknown. A single screen paper.","key_references":[{"PMID":"32822567","why":"Interactome screen with SPR validation of PSG-DCC/DSCAM binding."}],"covers":["LR008307"]},"LR001269":{"pair":"PTH2 -> PTH1R","headline":"TIP39 binds PTH1R with weak-to-moderate affinity without activating it, acting as an antagonist.","interaction_type":"conflicting","direction_and_effect":"TIP-(1-39) binds PTH1R without cAMP stimulation, and TIP(9-39) inhibits PTH and PTHrP agonists [PMID:11159842]. Another paper says TIP39 does not appreciably activate PTH1R [PMID:10854439]; GtoPdb lists an antagonist record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"243 +/- 52 nM","assay":"radioreceptor binding competition with 125I-rPTH","system":"LLCPK1 cells stably expressing PTH1R","cite":"PMID:11159842"},{"value":"210 +/- 64 nM","assay":"radioreceptor binding with 125I-PTHrP-(1-36)","system":"LLCPK1 cells stably expressing PTH1R","cite":"PMID:11159842"},{"value":"59 nm","assay":"binding affinity","system":"PTH1R, human","cite":"PMID:10854439"}],"species_and_systems":"Human TIP39 on pig LLCPK1 cells expressing PTH1R [PMID:11159842]; human ligand and receptor in a second study [PMID:10854439].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Affinities differ between papers (59 nM vs 210-243 nM). Both abstract only. GtoPdb lists pIC50 6.6 to 7.2 [DB:GtoPdb]. One row abstract_insufficient. Not an agonist pair despite a Ligand-Receptor class label.","key_references":[{"PMID":"10854439","why":"TIP39 binds PTH1R at 59 nM without activation."},{"PMID":"11159842","why":"TIP39 binds PTH1R weakly, antagonist behaviour."}],"covers":["LR001269","LR004669"]},"LR004671":{"pair":"PTHLH -> PTH1R","headline":"PTHrP is a classical PTH1R agonist with structural and binding database records; papers here are mostly indirect.","interaction_type":"direct binding","direction_and_effect":"PTHrP is an agonist of PTH1R. A [Trp23]hPTHrP-(1-36) analogue was a full agonist at the PTH/PTHrP receptor [PMID:8702701]. In intestinal epithelial cells, neutralising PTH1R and antagonising PTHLH prevented TGF-beta1-induced EMT, and PTHLH-PTH1R signals through PKA-Runx2 [PMID:29577935]. UniProt describes PTH1R as a receptor for PTH and PTHLH [DB:UniProt].","molecular_requirements":"Receptor residues 173-189, at the C-terminal end of the N-terminal extracellular domain, contact a PTH agonist photoprobe [PMID:9108031]. Subunit or co-receptor requirements are not reported in our evidence.","affinity_potency":[{"value":"pIC50 6.5","assay":"binding/activity of a PTHrP-derived analogue (value as recorded)","system":"human PTH-2 receptor study; recorded against PTH1R row","cite":"PMID:8702701"}],"species_and_systems":"Human ligand and receptor in recombinant HEK-293 cells [PMID:9108031], and human intestinal tissue plus mice [PMID:29577935]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTHLH is flagged as secreted and PTH1R as transmembrane [flag]; paracrine or endocrine.","caveats":"All papers were read as abstracts. PMID 9108031 maps the contact site with a PTH photoprobe, not PTHrP itself. PMID 8702701 used a modified PTHrP analogue and studied mainly PTH2R. The EMT paper is a functional readout. Structures and BioGRID/IntAct records support direct binding [DB:PDB 3H3G] [DB:BioGRID] [DB:IntAct].","key_references":[{"PMID":"8702701","why":"Residue-23-modified PTHrP is a full agonist at PTH1R"},{"PMID":"9108031","why":"Photoaffinity mapping of receptor contact domain"},{"PMID":"29577935","why":"PTHLH-PTH1R axis drives EMT via PKA-Runx2"}],"covers":["LR001271","LR004671"]},"LR006372":{"pair":"PTN -> NRP1","headline":"PTN binds NRP1 directly and needs it for signalling and migration in human cells.","interaction_type":"direct binding","direction_and_effect":"NRP-1 is needed for PTN-induced MAPK and focal adhesion kinase signalling, HUVEC migration and tumour-cell invasion; NRP-1 silencing or blocking antibody inhibited them [PMID:26408254]. PTN binding stimulated NRP-1 internalisation and recycling [PMID:26408254].","molecular_requirements":"PTN interacts via its thrombospondin type-I repeat (TSR-I) domains [PMID:26408254]. PTN bound immobilised recombinant NRP-1 in an ELISA, and NRP-1 co-immunoprecipitated with PTN in PC3, MDA-MB231 and HUVEC cells [PMID:26408254]. PTN may also bind cells through ALK and RPTPbeta/zeta [PMID:26408254].","affinity_potency":[],"species_and_systems":"Human carcinoma cells and HUVEC; CHO cells lack NRP-1 [PMID:26408254]. Mouse pair is ortholog-inferred.","localisation_and_range":"PTN is flagged as secreted [flag], so signalling would be paracrine. NRP1 is flagged as transmembrane [flag].","caveats":"Single paper, no affinity reported. Co-immunoprecipitation could reflect indirect interaction, but the ELISA supports direct binding [PMID:26408254].","key_references":[{"PMID":"26408254","why":"PTN-NRP-1 direct binding and role in PTN signalling"}],"covers":["LR003151","LR006372"]},"LR001278":{"pair":"PTN -> SDC1","headline":"Binding of PTN to syndecan-1 glycosaminoglycan chains by BIAcore; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"PTN bound both heparan sulfate and chondroitin sulfate chains of syndecan-1 and syndecan-4, more strongly to the CS chains of syndecan-4; the core protein of syndecan-1 also contributed to binding [PMID:15226297]. Removing CS chains lowered association and dissociation rates, suggesting a ternary complex [PMID:15226297].","molecular_requirements":"Binding depends on glycosaminoglycan chains (HS and CS), not a protein-only epitope [PMID:15226297]. Whether syndecan-1 alone transduces a PTN signal is not reported in our evidence.","affinity_potency":[],"species_and_systems":"BIAcore with syndecan ectodomains from normal murine mammary gland epithelial cells [PMID:15226297]; the dossier labels species human, which conflicts with the abstract. Both species interactions here are ortholog-inferred.","localisation_and_range":"SDC1 carries a secreted flag and a transmembrane flag [flag]; the ectodomain was used in vitro.","caveats":"Abstract only; no affinity values; binding is glycan-mediated and shared with other heparin-binding growth factors; no receptor activation shown.","key_references":[{"PMID":"15226297","why":"BIAcore comparison of PTN binding to syndecan-1 and -4 chains"}],"covers":["LR001278","LR004678"]},"LR005283":{"pair":"PTPRC -> CD22","headline":"Real but very low-affinity, glycan-mediated binding of CD22 to CD45 sialic acid; not a protein-specific signalling pair.","interaction_type":"direct binding","direction_and_effect":"CD22 binds alpha2-6-linked sialic acid on N-glycans of CD45; soluble CD22-Ig engagement of CD45 modulated early T-cell antigen receptor signals [PMID:7537381]. Sialylating CD22 abrogated its interactions with ligands [PMID:7537381].","molecular_requirements":"Binding requires alpha2-6-linked sialic acid; CD22 bound sialylated CD4 and a synthetic sialoglycoconjugate with similar affinity, so CD45 preference reflects multiple glycan copies [PMID:12115612].","affinity_potency":[{"value":"Kd 130 microM","assay":"surface plasmon resonance, 25 degrees C","system":"CD22 binding native CD45","cite":"PMID:12115612"}],"species_and_systems":"Human experiments [PMID:12115612, PMID:7537381] per curator fields; mouse pair is a separate record.","localisation_and_range":"CD45 and CD22 are both flagged transmembrane [flag]; membrane-bound, contact-dependent.","caveats":"Fast kinetics (koff >=18 s-1) indicate transient contact [PMID:12115612]. Databases list CD22-PTPRC co-IP/capture records [DB:BioGRID, DB:IntAct]. Both papers read as abstracts.","key_references":[{"PMID":"12115612","why":"SPR Kd of CD22 for CD45"},{"PMID":"7537381","why":"soluble CD22 modulates T-cell signalling via CD45"}],"covers":["LR001947","LR005283"]},"LR003159":{"pair":"PTPRD -> NLGN3","headline":"Direct non-canonical NLGN3-PTPdelta interaction reported in one paper with structure and mouse behaviour.","interaction_type":"direct binding","direction_and_effect":"NLGN3 binds PTPdelta splice variants in a non-canonical interaction that competes with neurexin binding [PMID:33758193]. Impairing NLGN3-PTPdelta in mice reduced social behavior and enhanced motor learning [PMID:33758193].","molecular_requirements":"Splicing-dependent: PTPdelta variants lacking the meB peptide act as selective ligands; NLGN3 identified on PTPdelta-bound beads [PMID:33758193].","affinity_potency":[],"species_and_systems":"Mouse and cultured neurons; complex structure [PMID:33758193].","localisation_and_range":"Both flagged transmembrane [flag]; trans-synaptic.","caveats":"Single paper, abstract-level curation plus excerpts; no affinity in our evidence.","key_references":[{"PMID":"33758193","why":"NLGN3-PTPdelta non-canonical interaction competes with neurexin"}],"covers":["LR003159","LR006380"]},"LR006381":{"pair":"PTPRD -> SLITRK1","headline":"PTPRD and SLITRK1 aggregate cells in a mouse assay and have a co-crystal structure in databases; one primary paper.","interaction_type":"direct binding","direction_and_effect":"Slitrk1-expressing L cells specifically aggregated with PTP-delta-expressing L cells; the paper concludes Slitrks need LAR-RPTP family members to trigger synapse formation, with PTP-delta needed for inhibitory synapse differentiation [PMID:23345436]. Agonist or antagonist effect on PTPRD is not reported in our evidence.","molecular_requirements":"Not reported for single subunits; the databases hold a co-crystal structure and a reconstituted complex of SLITRK1 and PTPRD [DB:BioGRID] [DB:PDB 4RCA].","affinity_potency":[],"species_and_systems":"Mouse proteins in mouse L cells, plus rat brain data in the abstract [PMID:23345436]. Human and mouse pairs are both listed; the mouse pair is projected from human (ortholog-inferred).","localisation_and_range":"Both proteins are flagged transmembrane (SLITRK1 is also flagged secreted) [flag]; adhesion between cells implies contact-dependent (juxtacrine) action [PMID:23345436].","caveats":"Evidence is one cell-adhesion assay (aggregation), not a measured binding; the paper's abstract-level result is that Slitrks need distinct LAR-RPTP members for synapse formation [PMID:23345436]. The curation note says the quote is unverifiable pending spot-check. The BioGRID/PDB records cite PMID 25394468, which is not among the judged papers.","key_references":[{"PMID":"23345436","why":"Cell-aggregation assay between Slitrk and PTP-delta cells"}],"covers":["LR003160","LR006381"]},"LR003168":{"pair":"PTPRS -> LRRC4B","headline":"PTPRS (PTP-sigma) binds NGL-3 (LRRC4B) through its first two FNIII domains; one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"PTP-sigma interacts with NGL-3 via its first two FNIII domains, and the PTPsigma-NGL-3 interaction promotes synapse formation in a bidirectional manner [PMID:20139422]; curated direction agonist.","molecular_requirements":"PTP-sigma uses its first two FNIII domains [PMID:20139422]. Reactome lists a complex of LRRC4B with PTPRF, PTPRS and PTPRD [DB:Reactome].","affinity_potency":[],"species_and_systems":"Curated as human proteins; paper read as abstract only; both listed pairs are ortholog-inferred [PMID:20139422].","localisation_and_range":"Both flagged transmembrane (PTPRS also flagged secreted) [flag]; trans-synaptic adhesion indicates contact-dependent action [PMID:20139422].","caveats":"Only abstract-level evidence; the curated row is the reciprocal of an NGL-3 -> PTPsigma row. No affinity reported. Two further judged rows were abstract_insufficient.","key_references":[{"PMID":"20139422","why":"NGL-3 interacts with PTP-sigma via FNIII 1-2"}],"covers":["LR003168","LR006389"]},"LR006390":{"pair":"PTPRS -> NTRK3","headline":"All TrkC isoforms bind PTP-sigma directly in trans with high affinity; postsynaptic TrkC and presynaptic PTP-sigma form a synaptic organising complex.","interaction_type":"direct binding","direction_and_effect":"All TrkC isoforms, but not TrkA or TrkB, function in excitatory synaptic adhesion through neurotrophin-independent high-affinity trans binding to axonal PTP-sigma; PTP-sigma triggers and TrkC mediates postsynaptic clustering, so organising signals run both ways [PMID:21262467].","molecular_requirements":"Noncatalytic TrkC isoforms also work, so the kinase domain is not needed for adhesion [PMID:21262467]. No further subunit requirements are reported in our evidence.","affinity_potency":[],"species_and_systems":"Hippocampal neuron-fibroblast coculture, a TrkC-neutralising antibody that blocks TrkC-PTP-sigma interaction, TrkC knockdown in culture and in vivo [PMID:21262467]. Human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"Membrane-bound trans interaction across the synapse; PTPRS is also flagged secreted [flag] [PMID:21262467].","caveats":"Abstract-only read; no numeric affinity is reported in our evidence ('high-affinity' only). Reactome, BioGRID and UniProt also list the pair [DB:Reactome] [DB:UniProt].","key_references":[{"PMID":"21262467","why":"TrkC-PTP-sigma bidirectional synaptic organising complex"}],"covers":["LR003169","LR006390"]},"LR001953":{"pair":"PVR -> NECTIN3","headline":"PVR-nectin3 trans-binding is stated in one paper's abstract (as prior work) and supported by database records; no new primary data in our evidence.","interaction_type":"direct binding","direction_and_effect":"Nectin3 is described as binding PVR in a trans-hetero-interaction network of nectins [PMID:12011057]. UniProt notes that trans-interaction with PVR activates CDC42 and RAC [DB:UniProt].","molecular_requirements":"Not reported in our evidence for this pair; the paper mapped nectin3 binding on a nectin1 V domain using PVR chimeras, not PVR-nectin3 binding itself [PMID:12011057].","affinity_potency":[],"species_and_systems":"Human proteins [PMID:12011057]. Mouse pair is projected from human evidence (ortholog inferred). Database records include surface plasmon resonance and solid phase assay (IntAct), a reconstituted complex (BioGRID) and Reactome trans-heterodimer [DB:IntAct][DB:BioGRID][DB:Reactome].","localisation_and_range":"Nectins are adhesion molecules at adherens junctions, with trans-interactions between ectodomains of adjacent cells [PMID:12011057]. PVR is also flagged secreted [flag].","caveats":"The only paper restates the authors' earlier network and read as abstract only; curators noted PVR is only a scaffold there. Affinity for PVR-nectin3 not reported. Direction (which partner is ligand) is not defined in the evidence; the interaction is trans-homophilic-style adhesion.","key_references":[{"PMID":"12011057","why":"States the nectin3-PVR interaction (background to the study); abstract only"}],"covers":["LR001953","LR005289"]},"LR004680":{"pair":"PYY -> NPY1R","headline":"PYY-NPY1R rests only on database records; no paper in our evidence confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"GtoPdb lists PYY as an agonist of NPY1R [DB:GtoPdb]. UniProt describes NPY1R as a receptor for NPY and PYY [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"IntAct records physical association by scintillation proximity assay [DB:IntAct]. Species of experiments not reported in our evidence; human and mouse pairs are projected from other evidence (ortholog inferred).","localisation_and_range":"PYY is flagged as secreted and not transmembrane; NPY1R as a transmembrane receptor [flag].","caveats":"No curator-verified paper: three abstracts were insufficient and one was review only. Reactome and UniProt statements are generic to NPY-family peptides. No affinity value in our evidence.","key_references":[],"covers":["LR001280","LR004680"]},"LR003177":{"pair":"QRFP -> NPFFR1","headline":"QRFP (26RFa) binds and activates human NPFFR1 in one full-text paper, as part of an RF-amide panel; cross-reactivity, not the cognate pair.","interaction_type":"direct binding","direction_and_effect":"RF-amide peptides including 26RFa bound NPFFR in radioligand competition and activated it in [35S]GTPgammaS and cAMP assays [PMID:23911743]. In mice, effects of the RF-amide peptides were antagonised by RF9, supporting direct NPFF receptor activation [PMID:23911743].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.1-10 nM","assay":"radioligand competition on membranes, whole peptide panel (not QRFP alone)","system":"CHO cells expressing human receptor","cite":"PMID:23911743"}],"species_and_systems":"Human receptor in CHO membranes; in vivo pain tests in mice with peptides given i.c.v. [PMID:23911743].","localisation_and_range":"QRFP is flagged secreted [flag]; mouse effects were by central injection.","caveats":"The Ki range covers all peptides, not QRFP specifically. The paper reports GPR103 as selective for its cognate ligand, so NPFF receptors are secondary targets. Mouse pair is projected.","key_references":[{"PMID":"23911743","why":"Systematic RF-amide peptide binding and activation of NPFF1/NPFF2"}],"covers":["LR003177","LR006397"]},"LR007335":{"pair":"RAET1L -> HCST:KLRK1","headline":"Complex-level pair supported only by database records (IntAct, PDB, UniProt); no curator-verified paper for the complex.","interaction_type":"database-asserted only","direction_and_effect":"UniProt describes the ligand as binding and activating the KLRK1/NKG2D receptor, mediating natural killer cell cytotoxicity [DB:UniProt].","molecular_requirements":"Structural and binding records involve the KLRK1 chain only: PDB 4S0U contains a chain of Q5VY80 and a chain of P26718 (NKG2D with ULBP6) [DB:PDB 4S0U]. The HCST partner is not addressed in our evidence.","affinity_potency":[],"species_and_systems":"Records include surface plasmon resonance, X-ray crystallography and FACS [DB:IntAct]; species of the experiments is not reported in our evidence.","localisation_and_range":"RAET1L is flagged transmembrane, not secreted [flag].","caveats":"No papers were judged for this complex; the one paper row is review_only. Support for HCST involvement is not shown; the individual KLRK1 pair is better evidenced (see RAET1L -> KLRK1).","key_references":[],"covers":["LR007335"]},"LR001287":{"pair":"RARRES2 -> CMKLR1","headline":"Chemerin is a well-supported agonist of CMKLR1, with binding, signaling and vascular functional data, plus GtoPdb and PDB records.","interaction_type":"direct binding","direction_and_effect":"Chemerin activates CMKLR1 (ChemR23): calcium release, inhibition of cAMP accumulation and p42-p44 MAPK phosphorylation through Gi proteins, with chemotaxis of immature dendritic cells and macrophages [PMID:14530373]. Chemerin and chemerin-9 activate Galphai and Galphao subtypes and recruit beta-arrestin1/2 at CMKLR1 [PMID:27716822]. In human vessels, chemerin acts at CMKLR1, not GPR1, to cause vasoconstriction [PMID:27742615]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"The proform has low activity; proteolytic removal of the C-terminal domain gives a potent agonist, the circulating form being residues 21 to 154 [PMID:14530373, PMID:14675762]. Chemerin-9 (149-157) retains most activity; Tyr149, Phe150, Gly152, Phe154, Phe156 are key [PMID:14701797]. Single GPCR chain, no co-receptor reported.","affinity_potency":[{"value":"KD of respectively 0.88 nM","assay":"saturation binding, [125I]-chemerin","system":"CHO-K1 cells expressing human CMKLR1","cite":"PMID:27716822"},{"value":"KD=0.28\u00b10.07 nmol/L","assay":"radiolabeled chemerin-9 binding","system":"CHO-K1 cells expressing human CMKLR1","cite":"PMID:27742615"},{"value":"pD2=8.45\u00b10.10","assay":"inhibition of forskolin-evoked cAMP accumulation, full-length chemerin","system":"CMKLR1 cell-based assay","cite":"PMID:27742615"}],"species_and_systems":"Human proteins in recombinant cells, primary human cells and human vessels; the mouse pair is inferred from human evidence (ortholog_inferred).","localisation_and_range":"Chemerin is flagged secreted, so paracrine/endocrine; CMKLR1 is transmembrane [flag]. Chemerin was abundant in human inflammatory fluids [PMID:14530373].","caveats":"Four rows are pending. Chemerin-9 is biased toward cAMP inhibition over beta-arrestin recruitment at CMKLR1, so readout matters [PMID:27742615]. Some papers read as abstract only. The mouse pair has no direct mouse evidence here.","key_references":[{"PMID":"14530373","why":"Chemerin characterized as processed ChemR23 agonist"},{"PMID":"14701797","why":"Chemerin-9 minimal agonist, residue mapping"},{"PMID":"27716822","why":"Binding and signaling of three chemerin receptors"}],"covers":["LR001287","LR004686"]},"LR003186":{"pair":"RGMA -> TFR2","headline":"Evidence is that RGMA can substitute for HJV in the HFE-TfR2 complex; direct RGMA-TFR2 binding is not shown.","interaction_type":"functional only","direction_and_effect":"RGMA, a CNS HJV homolog, can substitute for HJV within the HFE-TfR2-HJV complex and promote hepcidin transcription [PMID:22728873].","molecular_requirements":"The same TfR2 residues (120-139) that matter for HFE/HJV binding are implicated; the complex includes HFE and HJV architecture [PMID:22728873].","affinity_potency":[],"species_and_systems":"Species not stated beyond the curator's human entry; the mouse pair is ortholog-inferred [PMID:22728873].","localisation_and_range":"RGMA is flagged secreted and TFR2 transmembrane [flag]; a membrane complex is described [PMID:22728873].","caveats":"Abstract-only; the sentence concerns functional substitution, not binding to TFR2 itself; single paper.","key_references":[{"PMID":"22728873","why":"RGMA substitutes for HJV in the HFE-TfR2 complex"}],"covers":["LR003186","LR006406"]},"LR001296":{"pair":"RGMB -> NEO1","headline":"RGMB physically interacts with neogenin and inhibits migration of dentate precursors; supported by a dedicated paper and a generic RGM paper.","interaction_type":"direct binding","direction_and_effect":"Co-immunoprecipitation and binding assays indicate a strong physical interaction; RGMb abolished in vitro and in vivo migration of dentate neuroepithelial cells and reduced cell adhesion (antagonist) [PMID:19944164]. A PDB structure with RGMB and NEO1 chains is recorded [DB:PDB 4UI2].","molecular_requirements":"Not reported in our evidence beyond the two partners.","affinity_potency":[{"value":"sub-nanomolar","assay":"expression cloning binding (RGM generically)","system":"chick","cite":"PMID:15258590"}],"species_and_systems":"Developing dentate gyrus, organotypic slices and in utero electroporation [PMID:19944164]; chick retina for the generic RGM paper [PMID:15258590].","localisation_and_range":"RGMB is not flagged secreted [flag]; contact-mediated reduction of adhesion between neogenin and RGMb cells [PMID:19944164].","caveats":"Both abstract-only. The second paper refers to RGM generically, not RGMB specifically [PMID:15258590].","key_references":[{"PMID":"19944164","why":"Neogenin-RGMb interaction and migration inhibition"},{"PMID":"15258590","why":"Neogenin as an RGM receptor (generic RGM)"}],"covers":["LR001296","LR004695"]},"LR006408":{"pair":"RGMB -> PDCD1LG2","headline":"PD-L2 binds RGMb at a site distinct from BMP; one paper, mouse respiratory tolerance model.","interaction_type":"direct binding","direction_and_effect":"PD-L2 binds RGMb and the two bind distinct sites from BMP-2/4; blocking the RGMb-PD-L2 interaction impaired respiratory tolerance by reducing initial T-cell expansion [PMID:24752301].","molecular_requirements":"PD-L2 and BMP-2/4 bind non-overlapping sites on RGMb [PMID:24752301].","affinity_potency":[],"species_and_systems":"Lung tissue and mouse tolerance model; curator lists human; the human pair is ortholog-inferred, the mouse pair is not [PMID:24752301].","localisation_and_range":"RGMb is not flagged secreted and PDCD1LG2 is transmembrane [flag].","caveats":"Abstract-only; no affinity; the paper frames PD-L2 as ligand and RGMb as receptor, opposite to the pair's written direction.","key_references":[{"PMID":"24752301","why":"PD-L2 binds RGMb; role in respiratory tolerance"}],"covers":["LR003188","LR006408"]},"LR012375":{"pair":"RNF43 -> FZD4:LRP6","headline":"RNF43 -> FZD4:LRP6 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"Reactome lists a binding reaction in which ZNRF3 and RNF43 bind the FZD:LRP5/6 receptor complex [DB:Reactome]. Direction and effect are not reported in our evidence.","molecular_requirements":"Receptor is a FZD plus LRP complex; the Reactome record is generic for the FZD:LRP5/6 complex, not specific to this paralog combination, and which subunit RNF43 contacts is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: abstract_insufficient 3). ","key_references":[],"covers":["LR012375"]},"LR012159":{"pair":"RNF43 -> FZD8:LRP5","headline":"RNF43 -> FZD8:LRP5 is supported only by database records; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists RNF43-FZD8 affinity-capture or PCA records [DB:BioGRID]. Direction and effect are not reported in our evidence.","molecular_requirements":"Only the FZD8 chain has database support; the LRP co-receptor part has none in our evidence.","affinity_potency":[],"species_and_systems":"Human; experimental systems not reported in our evidence.","localisation_and_range":"Not reported in our evidence (no secreted or membrane flag given).","caveats":"No paper confirmed this pair (outcomes: different_entity 2, abstract_insufficient 1). Some judged rows were a different entity.","key_references":[],"covers":["LR012159"]},"LR005292":{"pair":"ROBO2 -> ROBO2","headline":"ROBO2 homophilic ectodomain interaction, from one abstract-only paper plus an IntAct record.","interaction_type":"direct binding","direction_and_effect":"Robo2 extracellular domain is a homophilic adhesion molecule [PMID:12504588]; the interaction is symmetric and no agonist or antagonist effect is reported.","molecular_requirements":"Blocked by antibody to the first Ig domain of Robo1/2 or soluble Robo-Fc [PMID:12504588]; stoichiometry not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human Robo2 in transfected 3T3 cells with primary neurons [PMID:12504588]. Mouse pair is projected.","localisation_and_range":"Robo2 carries both secreted and membrane flags [flag]; trans adhesion per the paper [PMID:12504588].","caveats":"Abstract only. IntAct 'polymerization' record cites the same paper [DB:IntAct]. A self-pair, so ligand and receptor roles are not distinguishable.","key_references":[{"PMID":"12504588","why":"Homophilic Robo2 adhesion"}],"covers":["LR001959","LR005292"]},"LR003195":{"pair":"ROBO3 -> ROBO3","headline":"ROBO3 homophilic binding from an abstract-only paper; UniProt notes oligomerization linked to midline axon repulsion.","interaction_type":"direct binding","direction_and_effect":"Robo3 can bind homophilically [PMID:16226035]. UniProt says this interaction promotes oligomerization of ROBO3, resulting in repulsion of commissural axons at the midline [DB:UniProt].","molecular_requirements":"Robo3A/Robo3B isoforms differ by a 26-residue N-terminal insertion; which one self-associates is not reported in our evidence [PMID:16226035].","affinity_potency":[],"species_and_systems":"Human Robo3 isoforms [PMID:16226035]; the UniProt statement cites PMID 32198364, which is not among our judged papers [DB:UniProt].","localisation_and_range":"Membrane-bound per flag [flag]; midline repulsion implies contact-dependent action [DB:UniProt].","caveats":"Abstract only for the primary paper. Self-pair, so ligand and receptor roles are indistinguishable.","key_references":[{"PMID":"16226035","why":"Robo3 homophilic binding"}],"covers":["LR003195","LR006415"]},"LR004707":{"pair":"RSPO1 -> LRP6","headline":"RSPO1 -> LRP6: only family-level abstract evidence of ectodomain interaction plus a UniProt regulation note.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins physically interacted with the LRP6 and Fzd8 ectodomains in vivo and in vitro and activated TCF reporter and beta-catenin stabilisation [PMID:16543246]. UniProt describes RSPO1 acting through Kremen to block LRP6 internalization, not direct LRP6 binding [DB:UniProt].","molecular_requirements":"R-spondin did not form a ternary complex with both LRP6 and Fzd8 [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse cristin/R-spondin proteins [PMID:16543246]; human pair ortholog-inferred.","localisation_and_range":"RSPO1 secreted per flag [flag].","caveats":"Abstract only; family-level not RSPO1-specific. Two abstract-insufficient papers. UniProt-cited work says RSpo1 does not directly activate LRP6 [DB:UniProt].","key_references":[{"PMID":"16543246","why":"R-spondin family binds LRP6 and Fzd8 ectodomains"}],"covers":["LR001310","LR004707"]},"LR004716":{"pair":"RSPO3 -> LRP6","headline":"Cristin/R-spondin proteins bind the LRP6 ectodomain in one abstract-only paper; RSPO3 is covered only as a family member.","interaction_type":"direct binding","direction_and_effect":"Cristin/R-spondin proteins act as LRP6 ligands and induce canonical Wnt/beta-catenin signalling with TCF reporter activity [PMID:16543246].","molecular_requirements":"They interacted with the extracellular domains of LRP6 and Fzd8 in vivo and in vitro, but did not form a ternary complex with both [PMID:16543246].","affinity_potency":[],"species_and_systems":"Mouse Cristin/R-spondin proteins per the title; both human and mouse pairs in the dossier are ortholog-inferred.","localisation_and_range":"RSPO3 is flagged secreted and LRP6 transmembrane [flag].","caveats":"Family-level result without paralogue resolution. Abstract only. No database records support this pair.","key_references":[{"PMID":"16543246","why":"Cristin/R-spondin family binds LRP6 and Fzd8 ectodomains"}],"covers":["LR001319","LR004716"]},"LR006417":{"pair":"RTN2 -> RTN4R","headline":"RTN2 binds NgR1 (RTN4R) with nanomolar affinity in a single biophysical mapping paper, read as abstract only.","interaction_type":"direct binding","direction_and_effect":"The paper reports novel nanomolar interactions of RTN2 and RTN3 with NgR1; effect on signalling is not reported in our evidence [PMID:17189258].","molecular_requirements":"Not reported for this pair; the abstract describes NgR1 mapping to the concave face of its leucine-rich-repeat domain [PMID:17189258].","affinity_potency":[],"species_and_systems":"Recombinant biophysical mapping across reticulon and NgR families; curators record human ligand and receptor. The human pair is ortholog-inferred [PMID:17189258].","localisation_and_range":"RTN4R is flagged transmembrane [flag]; RTN2 is a reticulon, typically intracellular, and its extracellular availability is not reported in our evidence.","caveats":"The exact affinity value is not in the abstract. The curator assay_class is direct_binding but the paper is abstract-only. Effect direction \"agonist\" is not stated in the abstract. No database records.","key_references":[{"PMID":"17189258","why":"Systematic mapping of reticulon-NgR interactions; RTN2/RTN3 bind NgR1"}],"covers":["LR003197","LR006417"]},"LR004725":{"pair":"RTN4 -> TNFRSF19","headline":"TAJ (TNFRSF19) binds NgR1 and joins the Nogo receptor complex; direct Nogo-TAJ binding is not shown.","interaction_type":"functional only","direction_and_effect":"TAJ replaces p75 in the p75/NgR1/LINGO-1 complex to activate RhoA in the presence of myelin inhibitors; exogenous TAJ reversed MAIF-induced neurite outgrowth inhibition, and Taj-deficient mouse neurons were more resistant [PMID:15694322].","molecular_requirements":"TAJ needs NgR1 and LINGO-1 in the complex [PMID:15694322].","affinity_potency":[],"species_and_systems":"Neurons including Taj-deficient mouse neurons, in vitro [PMID:15694322]; curators record human ligand and receptor.","localisation_and_range":"RTN4 flagged non-secreted [flag]; the complex acts at the neuronal surface.","caveats":"TAJ is shown to bind NgR1, not Nogo/RTN4 directly; this pair is the complex-level interpretation. Abstract only. No database records.","key_references":[{"PMID":"15694322","why":"TAJ binds NgR1 and replaces p75 in the Nogo receptor complex"}],"covers":["LR001328","LR004725"]},"LR008433":{"pair":"RYK -> FZD8","headline":"Receptor-receptor (co-receptor) interaction: the Frizzled-8 CRD pulled down the Ryk extracellular domain in one full-text paper.","interaction_type":"direct binding","direction_and_effect":"Ryk functions as a coreceptor with Frizzled for Wnt ligands, and acts through Dishevelled to activate the canonical Wnt pathway [PMID:15454084]. The pair is annotated as Receptor-Receptor with a stimulatory modulatory effect. It is not a classic ligand-receptor pair.","molecular_requirements":"The cysteine-rich domain (CRD) of Frizzled-8 binds the Ryk extracellular domain, even without Wnt-1; the CRD also binds Wnt in the absence of Ryk [PMID:15454084]. Ternary complex with Wnt-1 is concluded by the curator note [PMID:15454084].","affinity_potency":[],"species_and_systems":"Co-immunoprecipitation of recombinant Frizzled-8 CRD-Fc with Ryk extracellular domain; species of constructs is not stated in the excerpts. Functional work included Ryk siRNA transgenic mice and neurite outgrowth [PMID:15454084].","localisation_and_range":"Both are membrane receptors acting in the same cell or contact; RYK has no secreted flag and FZD8 is flagged non-secreted [flag].","caveats":"Single paper; a second record was judged review-only. Evidence is one co-IP of an extracellular fragment, no affinity. Co-receptor binding is not ligand signalling direction.","key_references":[{"PMID":"15454084","why":"Ryk as Wnt coreceptor binding the Frizzled CRD"}],"covers":["LR008433"]},"LR006426":{"pair":"S100A1 -> TLR4","headline":"Functional evidence in cardiac fibroblasts that S100A1 signals through TLR4/MyD88; direct binding is not shown and the receptor role is indirect.","interaction_type":"functional only","direction_and_effect":"Extracellular S100A1 activates MAPK/SAPK and NF-kB (p65) in cardiac fibroblasts in a TLR4- and MyD88-dependent manner, independent of RAGE [PMID:24833748]. Antibody-mediated S100A1 neutralization enlarged infarct size and worsened left ventricular function post-MI, and CFs adopt an anti-fibrotic phenotype [PMID:24833748]. Reactome asserts S100A1 binds TLR4:LY96 [DB:Reactome R-HSA-6805943].","molecular_requirements":"TLR4 and MyD88 are needed for ERK1/2 activation; RAGE is not. S100A1 is internalized independent of TLR4 but routed to endolysosomes in a TLR4-dependent way, and signalling may arise from an endolysosomal TLR4/MyD88 complex [PMID:24833748]. LY96 (MD-2) requirement is only from Reactome [DB:Reactome R-HSA-6805997].","affinity_potency":[],"species_and_systems":"Human S100A1 in mouse cells: WT, RAGE-/-, TLR4-/- and MyD88-/- fibroblasts, mouse MI model, and patient serum [PMID:24833748].","localisation_and_range":"Released from damaged cardiomyocytes and acts on neighbouring cardiac fibroblasts (paracrine); S100A1 has a secreted flag [PMID:24833748][flag].","caveats":"Binding to TLR4 is inferred from knockout dependence and a proximity ligation colocalisation (supplementary); no Kd or purified binding is in our evidence. Other cell types did not respond. Only the abstract was formally read by the curator. Reactome support rests partly on this same paper.","key_references":[{"PMID":"24833748","why":"TLR4/MyD88-dependent S100A1 signalling in cardiac fibroblasts"}],"covers":["LR003206","LR006426"]},"LR006435":{"pair":"S100A4 -> EGFR","headline":"SPR shows direct S100A4-EGFR binding with Kd 21.4 nM, but EGFR blockade did not affect neuroprotection.","interaction_type":"direct binding","direction_and_effect":"S100A4 binds ErbB1 (EGFR) in label-transfer and SPR; two EGFR inhibitors and anti-EGFR antibody did not significantly affect S100A4-induced neuroprotection, which depends mainly on ErbB4 [PMID:30083275].","molecular_requirements":"ErbB2 did not bind S100A4 but its knockdown abolished neuroprotection, suggesting it signals as a partner [PMID:30083275].","affinity_potency":[{"value":"Kd 21.4 \u00b1 5.5 nM","assay":"surface plasmon resonance, S100A4 on immobilized ErbB1","system":"recombinant proteins","cite":"PMID:30083275"}],"species_and_systems":"Cultured hippocampal neurons and dopaminergic cell models; species of cells not stated in excerpts [PMID:30083275]. BioGRID and IntAct list further assays [DB:BioGRID][DB:IntAct].","localisation_and_range":"S100A4 is flagged secreted and EGFR transmembrane [flag].","caveats":"Binding is shown but functional contribution of EGFR is not supported: inhibitors had no effect. The Kd is apparent, from binding kinetics. Curator read abstract only.","key_references":[{"PMID":"30083275","why":"SPR and label-transfer binding of S100A4 to ErbB1/3/4"}],"covers":["LR003217","LR006435"]},"LR006444":{"pair":"S100A8 -> CD69","headline":"Binding of the S100A8/S100A9 complex to CD69 supported by one abstract-only paper; S100A8 acts as part of the complex.","interaction_type":"direct binding","direction_and_effect":"The S100A8/S100A9 complex was identified as the natural ligand of CD69 in human PBMCs; the association was confirmed by in vitro binding and competition assay, and CD69-S100A8/S100A9 association was required for SOCS3 up-regulation and inhibited STAT3 signalling, supporting Treg differentiation [PMID:26296369]. Agonist-like. UniProt also records the interaction [DB:UniProt].","molecular_requirements":"The ligand is the S100A8/S100A9 complex, not S100A8 alone; the paper does not test S100A8 separately in our evidence [PMID:26296369]. Binding depends on CD69 glycosylation: peptide-N-glycosidase treatment significantly abolished it [PMID:26296369].","affinity_potency":[],"species_and_systems":"Human PBMCs and in vitro binding with human proteins; mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Ligand flagged as secreted [flag]; secreted, so paracrine/endocrine range is plausible. CD69 is flagged as a receptor [flag].","caveats":"Abstract only was read. Complex-level evidence; S100A8 contribution alone is not reported in our evidence. UniProt entries cite the same paper, so they are not independent.","key_references":[{"PMID":"26296369","why":"Identifies S100A8/S100A9 as CD69 ligand, glycosylation-dependent"}],"covers":["LR003227","LR006444"]},"LR006453":{"pair":"S100A9 -> CD36","headline":"S100A8/A9-arachidonic acid complex interacts with CD36 in vitro; evidence is about arachidonate uptake (abstract-only, 2001).","interaction_type":"direct binding","direction_and_effect":"Arachidonate uptake by HUVEC in the presence of S100A8/A9 was largely mediated by FAT/CD36, and kinetic studies indicated an interaction between the transporter and the S100A8/A9-AA complex, confirmed by an in vitro protein-protein interaction assay [PMID:11141076].","molecular_requirements":"The interacting species is the S100A8/A9-arachidonic acid complex, not S100A9 alone [PMID:11141076].","affinity_potency":[],"species_and_systems":"Human umbilical vein endothelial cells, CD36-transfected COS-7 cells and an in vitro assay; species of the proteins in the assay is not stated in the abstract [PMID:11141076].","localisation_and_range":"Ligand secreted [flag]; CD36 transmembrane [flag].","caveats":"Abstract only. This is a transport/uptake context rather than a classical signalling receptor interaction; the effect on S100A8/A9 signalling is not reported. No affinity reported.","key_references":[{"PMID":"11141076","why":"S100A8/A9-AA complex interaction with FAT/CD36"}],"covers":["LR003237","LR006453"]},"LR001962":{"pair":"SAA1 -> CD36","headline":"CD36 reported as a SAA receptor mediating proinflammatory activity (abstract-only); transfected cells and cd36-/- rat cells.","interaction_type":"functional only","direction_and_effect":"CD36 functions as a novel SAA receptor: SAA uptake rose 5-10-fold in CD36-transfected HeLa cells, SAA induced a 10-50-fold increase of IL-8 secretion in CD36-overexpressing HEK293 cells, and cd36(-/-) rat macrophages and Kupffer cells showed up to 60-75% reduction in SAA-induced cytokine secretion [PMID:20075072]. Agonist.","molecular_requirements":"SAA activation was blocked by a CD36 peptide based on the hexarelin-binding site but not the thrombospondin-1-binding site; JNK and to a lesser extent ERK1/2 mediate signalling [PMID:20075072].","affinity_potency":[],"species_and_systems":"Transfected HeLa and HEK293 cells and rat macrophages/Kupffer cells; SAA preparation species not stated in the abstract [PMID:20075072].","localisation_and_range":"SAA1 flagged secreted [flag]; CD36 transmembrane [flag]. Association with HDL neutralized SAA effects [PMID:20075072].","caveats":"Abstract only; curator label direct_binding but no binding assay or affinity is described, only uptake and signalling. SAA1 versus other SAA isoforms is not distinguished in our evidence.","key_references":[{"PMID":"20075072","why":"CD36 as SAA receptor mediating inflammatory signalling"}],"covers":["LR001962"]},"LR003249":{"pair":"SCRG1 -> CD36","headline":"SCRG1 binds CD36 on the cell surface in a CRISPRa screen with flow-cytometry validation; one paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"SCRG1 was a top-scoring CD36 hit in the CRISPRa screen, and tetramerised SCRG1 (400 nM) stained CD36-transfected cells by flow cytometry [PMID:36178190]. Functional effect on CD36 is not reported in our evidence.","molecular_requirements":"Full-length CD36 was expressed; no co-receptor requirement is reported in our evidence [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human proteins; CD36-transfected 293F cells versus control cells, with SPRC tetramers as a negative control [PMID:36178190]. Mouse pair is projected from human.","localisation_and_range":"SCRG1 is flagged secreted and CD36 transmembrane [flag]; the assay used soluble multimerised ligand on cell-surface receptor [PMID:36178190].","caveats":"Single paper, tetramer cell staining only (no SPR or affinity). The paper notes SCRG1 is only to some extent related in sequence to the other CD36 ligands, and the CD36-enriched ligands cluster in brain where CD36 mRNA is low [PMID:36178190]. CD36 is described as multifunctional and binding several secreted ligands, so specificity is a question.","key_references":[{"PMID":"36178190","why":"CRISPRa screen and flow-cytometry binding of SCRG1 to CD36"}],"covers":["LR003249","LR006465"]},"LR006471":{"pair":"Sectm1a -> Tnfrsf18","headline":"Mouse Sectm1a is reported to bind GITR on macrophages and activate PI3K-Akt; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Sectm1a binds GITR on macrophage surfaces and activates PI3K-Akt; knockout mice show suppressed phagocytosis and worse sepsis outcome, rSectm1a improves survival, and its effects are lost in GITR knockout [PMID:32769121].","molecular_requirements":"Not reported in our evidence beyond GITR and PI3K-Akt dependence [PMID:32769121].","affinity_potency":[],"species_and_systems":"Mouse knockout models and macrophages [PMID:32769121].","localisation_and_range":"Sectm1a is flagged secreted [flag]; recombinant secreted protein was used [PMID:32769121].","caveats":"One paper, abstract only; binding method and affinity not reported in our evidence.","key_references":[{"PMID":"32769121","why":"Sectm1a as a GITR ligand in macrophages and sepsis"}],"covers":["LR006471"]},"LR003258":{"pair":"SELENOP -> LRP6","headline":"SELENOP co-immunoprecipitates with LRP6 and amplifies WNT signalling; single full-text paper, best evidence of the LRP5/6 pair.","interaction_type":"direct binding","direction_and_effect":"SELENOP co-immunoprecipitated with FLAG-LRP6 in 293T cells and decreased cell-surface LRP6, interpreted as promoting LRP6 internalization and amplifying WNT signalling [PMID:37166989].","molecular_requirements":"Truncation before the fourth selenocysteine and deletion of U258-U299 uncoupled the interaction [PMID:37166989]. Heparin prevented the SELENOP-LRP6 co-IP while sodium chlorate (HSPG synthesis inhibition) enhanced it, so HSPGs may sequester SELENOP [PMID:37166989].","affinity_potency":[],"species_and_systems":"Endogenous FLAG-tagged LRP6 in human 293T cells, plus mouse constructs for proximity ligation and mapping; mouse Apc-deletion model for phenotype [PMID:37166989].","localisation_and_range":"SELENOP is annotated secreted [flag]; the authors speculate LRP6 may mediate SELENOP uptake in gut [PMID:37166989].","caveats":"Co-IP and proximity ligation only, no affinity. The paper's own discussion says the gut SELENOP receptor remains unidentified [PMID:37166989]. No database records.","key_references":[{"PMID":"37166989","why":"co-IP and mapping of SELENOP-LRP6 interaction"}],"covers":["LR003258","LR006474"]},"LR008613":{"pair":"SELL -> SELPLG","headline":"L-selectin binding to PSGL-1 carrying the NK cell PEN5 epitope; one abstract-only paper, with database records for selectin-PSGL-1 binding.","interaction_type":"direct binding","direction_and_effect":"PEN5, a lactosamine modification of PSGL-1, creates a binding site for L-selectin on PSGL-1 that is independent of PSGL-1 tyrosine sulfation [PMID:10725346].","molecular_requirements":"Requires the PEN5 post-translational modification on PSGL-1 (NK cell restricted) [PMID:10725346].","affinity_potency":[],"species_and_systems":"NK cells; species not stated in the abstract [PMID:10725346]; curators record human.","localisation_and_range":"Both annotated membrane-bound [flag]; contact-dependent.","caveats":"Paper read as abstract only and assay detail is just 'NK cells'. IntAct has a solid-phase record for the pair [DB:IntAct]; the Reactome examples refer to P-selectin binding, not L-selectin [DB:Reactome].","key_references":[{"PMID":"10725346","why":"PEN5-modified PSGL-1 as an L-selectin ligand"}],"covers":["LR008613"]},"LR008640":{"pair":"SELPLG -> ESAM","headline":"No verified evidence; only Reactome P-selectin/PSGL-1 binding records, which do not concern ESAM.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Both annotated membrane-bound [flag].","caveats":"Judged rows were review_only, abstract_insufficient and different_entity, with no confirmed paper. The Reactome examples describe P-selectin binding P-selectin ligand and do not name ESAM [DB:Reactome]. Treat as unsupported.","key_references":[],"covers":["LR008640"]},"LR004734":{"pair":"SELPLG -> SELL","headline":"L-selectin binding to PSGL-1 is supported by several binding and adhesion papers, but one is glycan-conditional and most were read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"L-selectin binds PSGL-1 on leukocytes, at lower levels than P-selectin; binding was blocked by antibodies to either protein [PMID:8892633]. Neutrophil-neutrophil adhesion was inhibited by anti-PSGL-1 or anti-L-selectin antibodies [PMID:8896607]. Binding is a lectin-domain interaction with a PSGL-1 glycosulfopeptide site [PMID:18250165]. Effect direction is not reported in our evidence.","molecular_requirements":"Binding required appropriate glycosylation of PSGL-1 and Ca2+ [PMID:8892633]. On NK cells, a PEN5 lactosamine modification of PSGL-1 creates an L-selectin binding site independent of tyrosine sulfation [PMID:10725346], so binding may depend on cell type glycosylation.","affinity_potency":[],"species_and_systems":"All confirmed experiments are labelled human (cells, recombinant chimeras and glycosulfopeptide) [PMID:8892633][PMID:8896607][PMID:18250165][PMID:10725346]. The mouse pair is projected from human evidence (ortholog_inferred).","localisation_and_range":"Both partners are flagged membrane-bound [flag], so this is a juxtacrine, cell-contact interaction.","caveats":"Three of four shown papers were read as abstracts only. No affinity value is reported for L-selectin with PSGL-1. The NK-cell PEN5 result is conditional on a cell-restricted glycan [PMID:10725346]. Database records shown (Reactome, IntAct) concern P-selectin binding PSGL-1, not L-selectin [DB:Reactome R-HSA-202724] [DB:IntAct P14151-Q14242].","key_references":[{"PMID":"8892633","why":"L-selectin binds PSGL-1 on leukocytes; glycosylation and Ca2+ dependent"},{"PMID":"8896607","why":"Full-text neutrophil adhesion blocked by anti-PSGL-1 or anti-L-selectin"},{"PMID":"18250165","why":"L-selectin lectin domain binding to PSGL-1 glycosulfopeptide"}],"covers":["LR001338","LR004734"]},"LR004743":{"pair":"Sema3b -> Nrp2","headline":"SemA-AP binds NP-2a in a single 1998 AP-fusion binding study; mouse pair inferred from this.","interaction_type":"direct binding","direction_and_effect":"SemA-AP and SemE-AP (1 nM) both bind to NP-2a [PMID:10196546].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"AP-fusion binding with rat NP-2a (receptor written NP-2a) [PMID:10196546]; mouse pair is ortholog-inferred [flag].","localisation_and_range":"Sema3b is flagged secreted [flag].","caveats":"One paper, quote browser-read with spot-check pending; old SemA nomenclature; no affinity or functional effect on NRP2 reported in our evidence.","key_references":[{"PMID":"10196546","why":"SemA-AP binds NP-2a"}],"covers":["LR004743"]},"LR008028":{"pair":"SEMA3B -> NRP2:PLXNA2:PLXNA4","headline":"Functional silencing data (abstract only) imply a Sema3B receptor complex of plexin-A2, plexin-A4 and one neuropilin; NRP2 variant.","interaction_type":"functional only","direction_and_effect":"Plexin-A2 silencing completely abolished Sema3B signalling, which also required plexin-A4 and one of the two neuropilins [PMID:25335892]. Effect agonist.","molecular_requirements":"Requires plexin-A2 and plexin-A4 plus either NRP1 or NRP2; this row is the NRP2 variant and the abstract does not say which is preferred [PMID:25335892].","affinity_potency":[],"species_and_systems":"Endothelial and glioblastoma cells, labelled human in the dossier [PMID:25335892].","localisation_and_range":"Sema3B is flagged secreted [flag]; receptor is a membrane complex.","caveats":"Single abstract-only paper; NRP2 involvement is not specifically shown, only 'one of the two neuropilins'.","key_references":[{"PMID":"25335892","why":"Sema3B requires plexin-A2, plexin-A4 and one neuropilin"}],"covers":["LR008028"]},"LR006480":{"pair":"SEMA3B -> PLXNA2","headline":"Plexin-A2 is non-substitutably required for Sema3B signalling in cell silencing experiments (abstract only).","interaction_type":"functional only","direction_and_effect":"Plexin-A2 silencing completely abolished Sema3B signalling, unlike Sema3A signalling [PMID:25335892]. Plexin-A4 overexpression failed to restore Sema3B signalling in plexin-A2-silenced cells [PMID:25335892]. Effect agonist.","molecular_requirements":"Also requires plexin-A4 and one of the two neuropilins [PMID:25335892].","affinity_potency":[],"species_and_systems":"Endothelial and glioblastoma cells (labelled human) [PMID:25335892]; mouse pair is ortholog-inferred [flag].","localisation_and_range":"Sema3B is flagged secreted [flag].","caveats":"Single paper read as abstract only; functional dependence, not binding.","key_references":[{"PMID":"25335892","why":"Plexin-A2 silencing abolishes Sema3B signalling"}],"covers":["LR003264","LR006480"]},"LR003267":{"pair":"SEMA3C -> PLXNB1","headline":"SEMA3C:Fc binds Plexin B1 in a proximity ligation assay in DU145 cells, with full-text support.","interaction_type":"direct binding","direction_and_effect":"SEMA3C drives activation of EGFR, ErbB2 and MET via Plexin B1 and promotes prostate cancer cell growth [PMID:29348142]. Plexin B1 sema-domain Fc fusion proteins suppressed RTK signaling and cell growth, acting as a decoy [PMID:29348142].","molecular_requirements":"Binding was seen with Plexin B1 and tested alongside NRP1 in the same assay; whether NRP1 is needed is not reported in our evidence [PMID:29348142].","affinity_potency":[],"species_and_systems":"Human recombinant SEMA3C:Fc in human DU145 cells; xenografts of LNCaP in vivo for the decoy [PMID:29348142]. Mouse pair is ortholog-inferred.","localisation_and_range":"SEMA3C is annotated as secreted [flag], so signalling is expected to be paracrine or autocrine. PLXNB1 is annotated transmembrane [flag].","caveats":"Binding evidence is proximity ligation (close proximity in cells), not purified-protein binding; no affinity reported [PMID:29348142].","key_references":[{"PMID":"29348142","why":"PLA binding of SEMA3C:Fc to Plexin B1 and RTK transactivation"}],"covers":["LR003267","LR006483"]},"LR004752":{"pair":"SEMA3F -> PLXNA3","headline":"SEMA3F signalling via NRP2 is mediated principally by Plexin-A3 in mouse genetic studies; coreceptor evidence, both read as abstracts.","interaction_type":"functional only","direction_and_effect":"Neurons from Plexin-A3/A4 double-mutant mice were insensitive to Sema3F in vitro, with axon defects in vivo resembling Neuropilin-2 mutants [PMID:15721238]. Sema3F-Fc induced spine retraction in wild-type cortical neurons but not NrCAM-null ones [PMID:25143608].","molecular_requirements":"Signalling via NRP2 is mediated principally by Plexin-A3 [PMID:15721238]. NrCAM forms a complex with NRP2 and PlexA3 in brain and is required for Sema3F spine retraction [PMID:25143608].","affinity_potency":[],"species_and_systems":"Mouse neurons and brain [PMID:15721238][PMID:25143608]. The human pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence beyond SEMA3F being flagged secreted [flag].","caveats":"Both papers read as abstracts only. Evidence is genetic and complex-level, not direct SEMA3F-PlexA3 binding.","key_references":[{"PMID":"15721238","why":"Plexin-A3 principally mediates NRP2/Sema3F responses"},{"PMID":"25143608","why":"NrCAM-NRP2-PlexA3 complex mediates Sema3F spine retraction"}],"covers":["LR001356","LR004752"]},"LR003276":{"pair":"SEMA4A -> NRP1","headline":"Sema4a-Nrp1 interaction reported in Treg cells in one abstract-level paper; human pair is ortholog-inferred.","interaction_type":"direct binding","direction_and_effect":"Sema4a on immune cells and Nrp1 on Treg cells interact in vitro, potentiating Treg function and survival, and in vivo at inflammatory sites [PMID:23913274]. Ligation restrains Akt phosphorylation via PTEN [PMID:23913274].","molecular_requirements":"Nrp1 on Tregs; Sema4a-Ig beads were sufficient to potentiate suppression [PMID:23913274]. Plexin involvement is not reported in our evidence.","affinity_potency":[],"species_and_systems":"The experiments are in mouse Treg cells (Treg-restricted Nrp1 deletion), though the curator tagged human [PMID:23913274]. Human pair is ortholog-inferred.","localisation_and_range":"Sema4a is expressed on Tconv cells and DCs and contacts Tregs, apparently contact-dependent or as Ig fusion [PMID:23913274].","caveats":"Read as abstract with partial excerpts; direct binding assay is not itself shown in the text we have.","key_references":[{"PMID":"23913274","why":"Sema4a-Nrp1 interaction potentiates Treg function"}],"covers":["LR003276","LR006492"]},"LR001359":{"pair":"SEMA4B -> DCBLD2","headline":"SEMA4B-DCBLD2 (CLCP1) rests on one abstract-only paper using phage display and co-immunoprecipitation in a lung cancer line.","interaction_type":"direct binding","direction_and_effect":"A phage clone resembling the SEMA4B Sema domain interacted with LNM35 lung cancer cells, and immunoprecipitation confirmed CLCP1 interaction with SEMA4B; SEMA4B enhanced CLCP1 ubiquitination and proteasomal degradation, so the effect is labelled antagonist [PMID:17213806].","molecular_requirements":"DCBLD2 (CLCP1) alone is reported; no co-receptor in our evidence.","affinity_potency":[],"species_and_systems":"Human lung cancer cell line LNM35; mouse pair is ortholog-inferred [PMID:17213806].","localisation_and_range":"SEMA4B is not flagged secreted [flag]; range not stated in the paper abstract.","caveats":"One paper, abstract only, no affinity. Physiological role was described by the authors as remaining to be investigated [PMID:17213806]. No database support.","key_references":[{"PMID":"17213806","why":"CLCP1-SEMA4B interaction and CLCP1 degradation"}],"covers":["LR001359","LR004755"]},"LR004761":{"pair":"SEMA5A -> PLXNB3","headline":"Plexin-B3 is reported as a high-affinity, Sema5A-specific receptor; evidence is one abstract-only paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"Plexin-B3 is described as a high-affinity receptor specific for Sema5A, and Sema5A activation of plexin-B3 mediates functional responses in plexin-B3-expressing fibroblasts, epithelial and primary endothelial cells (agonist) [PMID:15218527]. Sema5A also triggers Met signalling when Met is complexed with plexin-B3 [PMID:15218527].","molecular_requirements":"Met associated with plexin-B3 is needed for the Met transactivation response [PMID:15218527]; whether plexin-B3 alone suffices for other responses is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human cells per the curator fields; the mouse pair is not ortholog-inferred in the dossier, but no mouse experiment is shown.","localisation_and_range":"Ligand is flagged membrane-bound and receptor transmembrane [flag]. Reactome lists the SEMA5A:PLXNB3 complex at the plasma membrane [DB:Reactome].","caveats":"Abstract only; no affinity value is given in our evidence. Database support is Reactome, citing the same paper [DB:Reactome].","key_references":[{"PMID":"15218527","why":"Identifies plexin-B3 as the high-affinity Sema5A receptor"}],"covers":["LR001365","LR004761"]},"LR003285":{"pair":"SEMA6D -> NRCAM","headline":"Nr-CAM is reported as a receptor for Sema6D at the optic chiasm, with full-text excerpts describing binding.","interaction_type":"direct binding","direction_and_effect":"Nr-CAM functions as a receptor for Sema6D; Sema6D with Nr-CAM and Plexin-A1 converts repulsion of contralateral RGCs to growth promotion, and all three are required for efficient decussation [PMID:22632726]. Nr-CAM-Sema6D binding was perturbed by anti-Sema6D treatment [PMID:22632726].","molecular_requirements":"Nr-CAM acts together with Plexin-A1 in the signalling context [PMID:22632726].","affinity_potency":[],"species_and_systems":"Optic chiasm cultures and mouse in vivo per curator fields; the human pair is ortholog-inferred and the mouse pair is not.","localisation_and_range":"Sema6D and Nr-CAM are expressed on midline radial glia while Plexin-A1 is on chiasm neurons, so cell-to-cell contact signalling [PMID:22632726].","caveats":"Single paper; binding rests on one assay shown in excerpts and no affinity is reported. Receptor carries secreted and transmembrane flags [flag].","key_references":[{"PMID":"22632726","why":"Nr-CAM as Sema6D receptor in RGC decussation"}],"covers":["LR003285","LR006501"]},"LR001368":{"pair":"SEMA6D -> PLXNA1","headline":"Well supported by three confirmed papers across chick and mouse: Plexin-A1 is a major Sema6D receptor, with co-receptor-dependent effects.","interaction_type":"direct binding","direction_and_effect":"Plexin-A1 is the major Sema6D-binding receptor in chick heart, where VEGFR2 or Off-track as co-receptor gives opposite migration outcomes [PMID:14977921]. PlexinA1 mediates sema6D signalling for proprioceptive axon segregation in mouse [PMID:17145500]. Sema6D with Nr-CAM and Plexin-A1 promotes contralateral RGC projection (agonist) [PMID:22632726].","molecular_requirements":"Co-receptors VEGFR2, Off-track [PMID:14977921], Nr-CAM [PMID:22632726]; Reactome lists a SEMA6D:PLXNA1:TREM2:DAP12 complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Chick [PMID:14977921], mouse [PMID:17145500] and optic chiasm cultures [PMID:22632726].","localisation_and_range":"Sema6D is flagged membrane-bound; the optic chiasm paper separates ligand-expressing radial glia from receptor-expressing neurons [flag][PMID:22632726].","caveats":"All three papers abstract only (the last has excerpts); no affinity reported. The sign of effect depends on co-receptor.","key_references":[{"PMID":"14977921","why":"Plexin-A1 major Sema6D receptor; co-receptor-dependent outcome"},{"PMID":"17145500","why":"PlexinA1 receptor for sema6D in mouse axon segregation"},{"PMID":"22632726","why":"Trans Sema6D, Plexin-A1, Nr-CAM at chiasm"}],"covers":["LR001368","LR004764"]},"LR004770":{"pair":"SERPINE1 -> LRP2","headline":"PAI-1 complexes bind and are endocytosed by LRP2 (gp330); binding measured for uPA:PAI-1, Kd about 0.8 nM.","interaction_type":"direct binding","direction_and_effect":"Affinity-purified gp330 from rabbit renal cortex bound uPA:PAI-1 complexes, and binding was inhibited by RAP [PMID:8344937]. Type II pneumocytes internalised and degraded PAI-1, pro-uPA and uPA:PAI-1, blocked by RAP and partly by anti-gp330 antibodies [PMID:7673355]. Thrombin-PAI-1 endocytosis was blocked by LRP-2 antibodies and RAP [PMID:8626514].","molecular_requirements":"The bound species is the uPA:PAI-1 complex; binding was calcium-dependent [PMID:8344937]. Vitronectin promotes thrombin-PAI-1 clearance [PMID:8626514].","affinity_potency":[{"value":"Kd about 0.8 nM","assay":"binding of uPA.PAI-1 complexes to affinity-purified gp330 at 4 degrees C","system":"rabbit renal cortex","cite":"PMID:8344937"}],"species_and_systems":"Rabbit renal gp330 and tubules [PMID:8344937]; rat type II pneumocytes [PMID:7673355]; dossier labels all as human. Mouse pair is ortholog-projected.","localisation_and_range":"Apical endocytosis in kidney proximal tubules [PMID:8344937]; LRP2 is flagged as a receptor [flag].","caveats":"All three papers abstract only. Partly shared with LRP1 in cell assays, so LRP2-specific contribution is not isolated [PMID:7673355, PMID:8626514].","key_references":[{"PMID":"8344937","why":"Direct binding of uPA:PAI-1 to gp330, Kd about 0.8 nM"},{"PMID":"7673355","why":"gp330-dependent endocytosis of PAI-1 and uPA:PAI-1"},{"PMID":"8626514","why":"LRP2 and LRP1 mediate thrombin-PAI-1 endocytosis"}],"covers":["LR001375","LR004770"]},"LR001377":{"pair":"SERPINE2 -> LRP1","headline":"Thrombin-protease nexin 1 complexes bind recombinant LRP1 regions; free SERPINE2 not shown.","interaction_type":"direct binding","direction_and_effect":"All three LRP1 homology regions (sLRP2, sLRP3, sLRP4) bound thrombin-protease nexin 1 complexes in solution-binding experiments [PMID:14596620].","molecular_requirements":"The ligand is the thrombin-protease nexin 1 complex, not free SERPINE2 [PMID:14596620].","affinity_potency":[],"species_and_systems":"Recombinant human LRP homology regions expressed in Pichia pastoris [PMID:14596620]. Mouse pair is ortholog-projected.","localisation_and_range":"SERPINE2 is flagged secreted [flag]; localisation not otherwise reported.","caveats":"Both confirmed rows come from the same abstract-only paper listing many ligands; not all ligand binding was RAP-competable [PMID:14596620].","key_references":[{"PMID":"14596620","why":"sLRP regions bind thrombin-protease nexin 1"}],"covers":["LR001377","LR004772"]},"LR001971":{"pair":"SERPINF1 -> PLXDC1","headline":"PEDF binds the extracellular domain of PLXDC1 and PLXDC1 mediates cell-type-specific PEDF responses.","interaction_type":"direct binding","direction_and_effect":"PLXDC1 and PLXDC2 were identified as cell-surface receptors for PEDF; knockdown of either decreased PEDF response in RAW267.4 cells [PMID:25535841]. PEDF is reported to dissociate basal receptor homooligomers to activate them [PMID:25535841].","molecular_requirements":"Binding needs the extracellular domain: biotinylated PEDF bound HEK293 cells expressing PLXDC1, with the extracellular-domain deleted form tested as a control [PMID:25535841]. PLXDC1 and PLXDC2 have cell-type-specific roles [PMID:25535841].","affinity_potency":[],"species_and_systems":"Transfected HEK293 cells, and macrophage RAW267.4 and endothelial SVEC4-10 cells (mouse lines named in the excerpts) [PMID:25535841]; dossier labels species human. Mouse pair is ortholog-projected from human.","localisation_and_range":"PEDF is flagged secreted [flag]; PLXDC1 is a transmembrane cell-surface receptor in the paper [PMID:25535841].","caveats":"Single paper; no affinity reported; PLXDC1 and PLXDC2 are not separated in some functional experiments.","key_references":[{"PMID":"25535841","why":"Identifies PLXDC1 and PLXDC2 as PEDF receptors"}],"covers":["LR001971","LR005301"]},"LR006507":{"pair":"SERPINF1 -> PNPLA2","headline":"PEDF co-immunoprecipitates with ATGL and lowers hepatocyte triglyceride in an ATGL-dependent way; supported by databases too.","interaction_type":"direct binding","direction_and_effect":"PEDF co-immunoprecipitated with ATGL in hepatic and HCC lysates; rPEDF decreased triglyceride in PEDF-null hepatocytes and this depended on ATGL, blocked by the inhibitor (R)-bromoenol lactone [PMID:18191271]. GtoPdb lists an Activator, Binding record [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence beyond ATGL dependence of the effect [PMID:18191271].","affinity_potency":[],"species_and_systems":"PEDF-null and control hepatocytes and liver, and HCC lysates; the abstract does not state the species, and the dossier labels it human [PMID:18191271]. BioGRID lists reconstituted-complex and two-hybrid records [DB:BioGRID].","localisation_and_range":"ATGL is an intracellular lipase localised to adiposomes in hepatocytes [PMID:18191271]; PEDF is flagged secreted [flag]. How secreted PEDF reaches ATGL is not reported in our evidence.","caveats":"Co-immunoprecipitation does not prove direct binding; abstract-only read; one further row is pending. An intracellular lipase as a receptor for a secreted ligand is unusual for cell-cell communication scoring.","key_references":[{"PMID":"18191271","why":"PEDF-ATGL co-IP and ATGL-dependent triglyceride lowering"}],"covers":["LR003291","LR006507"]},"LR008424":{"pair":"SFRP1 -> FZD6","headline":"Co-immunoprecipitation records and one 2026 pituitary-tumour study support SFRP1-FZD6.","interaction_type":"functional only","direction_and_effect":"The 2026 study inferred macrophage-initiated SFRP1-FZD6 signalling in non-functioning pituitary adenoma and reports experimental validation, linked to CCND1, CDK6, SGK1 and TGFBR2 [PMID:41844162]. BioGRID and IntAct list affinity-capture-western and coimmunoprecipitation records [DB:BioGRID, DB:IntAct].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human pituitary adenoma single-nucleus data; the validation assay is not described in our evidence [PMID:41844162]. Database records cite PMID:10347172 [DB:BioGRID].","localisation_and_range":"SFRP1 is flagged secreted [flag]; macrophage-to-tumour paracrine signalling is proposed [PMID:41844162].","caveats":"Abstract-only read; the validation method is unspecified. The database records rest on a paper not in the dossier's papers. Direction of effect is not established.","key_references":[{"PMID":"41844162","why":"Predicted and validated macrophage SFRP1 to tumour FZD6 axis"}],"covers":["LR008424"]},"LR010953":{"pair":"SFRP2 -> WNT3A","headline":"SFRP2 physically binds WNT3A and blocks its canonical signalling; ligand-ligand inhibition from one abstract-level paper plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SFRP2 acts as an inhibitor of WNT3A: it attenuated Wnt3a-induced caspase activity and inhibited beta-catenin/TCF transcriptional activity [PMID:19109969]. This is a ligand-ligand (decoy-like) pair, not a ligand-receptor pair.","molecular_requirements":"Not reported in our evidence beyond the two partners. Reactome lists a WNT3A:sFRP complex [DB:Reactome].","affinity_potency":[],"species_and_systems":"Solid phase binding assay for the physical interaction; functional work in rat cardiomyoblasts under hypoxia reoxygenation [PMID:19109969].","localisation_and_range":"Both partners are flagged secreted [flag]; Reactome places the complex in the extracellular region [DB:Reactome].","caveats":"Only one paper confirmed, read as abstract only; two other abstracts were insufficient and one concerned a different entity. Binding was shown in vitro and species of the binding proteins is not stated.","key_references":[{"PMID":"19109969","why":"Solid phase binding of Sfrp2 to Wnt3a and inhibition of Wnt3a effects"}],"covers":["LR010953"]},"LR008415":{"pair":"SFRP2 -> WNT4","headline":"Database-only ligand-ligand record from one BioGRID affinity-capture entry; no curated paper confirms it.","interaction_type":"database-asserted only","direction_and_effect":"Class is Ligand-Ligand with an inhibitory modulatory effect, but no paper in our evidence shows direction or effect.","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Single BioGRID record, Affinity Capture-Western [DB:BioGRID]; species and system not reported in our evidence.","localisation_and_range":"Both partners are flagged secreted [flag].","caveats":"Rests on one database record alone; the one judged paper row was assigned to a different entity.","key_references":[],"covers":["LR008415"]},"LR011790":{"pair":"SFRP5 -> WNT3","headline":"SFRP5-WNT3 is supported only by a docking study; no experimental evidence in our dossier.","interaction_type":"functional only","direction_and_effect":"SFRP family members are described as Wnt antagonists; the docking result indicated SFRP3 has the highest binding affinity to Wnt3, while SFRP1 and SFRP5 have the lowest [PMID:40372458].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Computational docking only; no experimental system [PMID:40372458].","localisation_and_range":"WNT3 is flagged secreted [flag]; SFRP5 secretion flag is not set in the dossier.","caveats":"Purely computational, abstract only. SFRP5 is reported with the lowest docking affinity for Wnt3, so this is weak support.","key_references":[{"PMID":"40372458","why":"Docking comparison of SFRP family binding to Wnt3"}],"covers":["LR011790"]},"LR003294":{"pair":"SFTPA1 -> LY96","headline":"SP-A binds MD-2 directly and antagonises LPS signalling; supported by one paper with several binding assays plus Reactome.","interaction_type":"direct binding","direction_and_effect":"SP-A binding to TLR4/MD-2 is antagonist: it attenuated smooth-LPS cell-surface binding and NF-kappaB activation in TLR4/MD-2-expressing cells [PMID:16754682].","molecular_requirements":"Binding to MD-2 was Ca2+-dependent and involves the carbohydrate recognition domain; supratrimeric oligomerisation matters, because the trimeric CRF fragment had approximately 600- and 155-fold higher KD for TLR4 and MD-2 than SP-A [PMID:16754682]. Reactome lists the TLR4:LY96 complex as the binder [DB:Reactome].","affinity_potency":[{"value":"600-fold higher KD (CRF vs full SP-A), TLR4","assay":"BIAcore/solid-phase binding","system":"recombinant soluble TLR4","cite":"PMID:16754682"},{"value":"155-fold higher KD (CRF vs full SP-A), MD-2","assay":"BIAcore/solid-phase binding","system":"recombinant soluble MD-2","cite":"PMID:16754682"}],"species_and_systems":"Recombinant soluble human TLR4 and MD-2 with SP-A; cell assays in TLR4/MD-2-expressing cells. Mouse pair is ortholog-inferred [PMID:16754682].","localisation_and_range":"SP-A is flagged secreted [flag].","caveats":"One paper, abstract only; absolute KD values are not given, only fold differences. The paper concerns SP-A generally.","key_references":[{"PMID":"16754682","why":"Direct SP-A binding to TLR4 and MD-2 with oligomerisation dependence"}],"covers":["LR003294","LR006510"]},"LR010935":{"pair":"SHANK1 -> ADGRB2","headline":"Database-only protein-protein interaction record; SHANK1 is not a secreted ligand, so a ligand-receptor reading is doubtful.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence; the only support is two-hybrid records [DB:BioGRID] [DB:IntAct].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system: two-hybrid records [DB:BioGRID] [DB:IntAct]. Species is human per the pair record.","localisation_and_range":"SHANK1 has no secreted flag in the dossier; localisation as a ligand is not reported in our evidence.","caveats":"Rests on database records only; the judged paper rows were assigned to a different entity.","key_references":[],"covers":["LR010935"]},"LR006516":{"pair":"SHBG -> GPRC6A","headline":"SHBG binds GPRC6A and competes with osteocalcin; two abstract-level papers, agonist peptide shown.","interaction_type":"direct binding","direction_and_effect":"Agonist: SHBG141-161 peptide stimulates testosterone and insulin secretion in MA-10 Leydig and beta-TC6 cells, and anti-GPRC6A IgG abolishes the response [PMID:31857654]. Unliganded SHBG bound GPRC6A-transfected membranes and was displaced by ucOC at 100-fold molar excess [PMID:27673554].","molecular_requirements":"The SHBG 141-161 domain is implicated in binding [PMID:31857654]; docking suggested a shared extracellular Venus-flytrap region for SHBG, SHBG141-161 and ucOCN [PMID:31857654].","affinity_potency":[{"value":"100-fold molar excess ucOC displaced SHBG","assay":"competitive displacement","system":"HEK-293 cells transfected with GPRC6A","cite":"PMID:27673554"}],"species_and_systems":"HEK-293 cells expressing human GPRC6A, MA-10 and beta-TC6 mouse cell lines; the dossier lists the pair as human with mouse ortholog-inferred.","localisation_and_range":"SHBG is flagged secreted [flag].","caveats":"Both papers abstract-level, same research group per the curator notes; the peptide response is not full-length SHBG.","key_references":[{"PMID":"27673554","why":"SHBG binds GPRC6A and is displaced by ucOC"},{"PMID":"31857654","why":"SHBG141-161 peptide binds and activates GPRC6A"}],"covers":["LR003302","LR006516"]},"LR007407":{"pair":"SHH -> BOC:PTCH1","headline":"Complex BOC:PTCH1 is supported only by database records for SHH-PTCH1 binding; no curator-verified paper for this complex.","interaction_type":"database-asserted only","direction_and_effect":"SHH binds PTCH1 as a receptor and is described as relieving PTCH1 inhibition of smoothened [DB:UniProt]. Reactome lists a Hh-Npp:BOC:PTCH1 complex [DB:Reactome].","molecular_requirements":"Structures of the human PTCH1-ShhN complex are deposited ([DB:PDB 6DMY], [DB:PDB 6E1H]); UniProt notes two PTCH1 molecules engage one hedgehog molecule [DB:UniProt]. Whether BOC is needed in addition to PTCH1 is not reported in our evidence; the structural and interaction records concern PTCH1 and SHH only [DB:IntAct] [DB:PDB 6DMY].","affinity_potency":[],"species_and_systems":"Records are for human proteins; BioGRID lists a reconstituted complex for SHH-PTCH1 [DB:BioGRID]. No papers were confirmed for this pair.","localisation_and_range":"SHH is flagged secreted [flag]; the receptor is flagged transmembrane [flag], so signalling is paracrine to a membrane receptor.","caveats":"No curator-verified paper (two papers were judged abstract-insufficient). Direct evidence concerns SHH-PTCH1, not the BOC:PTCH1 complex as a unit; a scorer using the least-expressed subunit assumes BOC is required, which is not shown here.","key_references":[],"covers":["LR007407"]},"LR001386":{"pair":"SHH -> CDON","headline":"SHH binds CDON directly, shown by several binding papers; CDON acts as a positive co-receptor.","interaction_type":"direct binding","direction_and_effect":"Cdo and Boc bind Shh through a high-affinity interaction with a specific fibronectin repeat that is essential for activity; they enhance Shh signalling in its target field [PMID:16647304]. CDON binds SHH and positively regulates Hh signaling [PMID:20519495]. Ectopic expression can also sequester Shh non-cell-autonomously [PMID:16647304].","molecular_requirements":"CDON alone is shown to bind; a specific fibronectin repeat is required [PMID:16647304]. Co-receptor with PTCH: Reactome lists Hh-Npp:CDON:PTCH [DB:Reactome]. Crystal structures of Hh proteins with CDON and BOC active domains show all mammalian Hh proteins bind in the same manner [PMID:20519495].","affinity_potency":[],"species_and_systems":"Mouse neural tube, with Shh-dependent ventral cell fates [PMID:16647304]; the second paper used mouse Boc knockout and rat commissural axons, but is for BOC/CDON jointly [PMID:17086203]. Affinity is described only as high-affinity or micromolar, with no value given in the dossier [PMID:16647304] [PMID:20519495].","localisation_and_range":"Membrane protein on the receiving cell; SHH is flagged secreted [flag]. Binding to the receptor occurs in the target field [PMID:16647304].","caveats":"All three papers read as abstracts only. The axon-guidance paper names Boc as the receptor and CDON only as a binder [PMID:17086203]; the abstract of [PMID:20519495] is truncated.","key_references":[{"PMID":"16647304","why":"Cdo and Boc bind Shh; role in Shh signalling feedback"},{"PMID":"20519495","why":"All mammalian Hh proteins bind CDO and BOC; structures"},{"PMID":"17086203","why":"Boc and Cdon bind Shh; axon guidance"}],"covers":["LR001386","LR004781"]},"LR001980":{"pair":"SIRPG -> CD47","headline":"SIRPgamma binds CD47 with low affinity (Kd approximately 23 microM) in one abstract-only paper plus database records.","interaction_type":"direct binding","direction_and_effect":"Soluble SIRPgamma extracellular region binds CD47, like SIRPalpha but more weakly; the authors suggest signalling via CD47 only, as SIRPgamma lacks known signalling motifs [PMID:15294972]. UniProt says interaction with SIRPG mediates cell-cell adhesion and costimulates T-cell activation [DB:UniProt].","molecular_requirements":"SIRPgamma is expressed without DAP12 and lacks the lysine required for DAP12 interaction [PMID:15294972].","affinity_potency":[{"value":"Kd approximately 23 microM","assay":"soluble SIRPgamma extracellular region binding CD47","system":"recombinant human proteins","cite":"PMID:15294972"}],"species_and_systems":"Human; soluble SIRPgamma ectodomain and T/B cells [PMID:15294972].","localisation_and_range":"Transmembrane [flag]; expressed on most T cells and some B cells, not myeloid cells [PMID:15294972]. Contact-dependent.","caveats":"Abstract only. Affinity is about 11-fold weaker than SIRPalpha (Kd approximately 2 microM). Unidirectional signalling is a suggestion by the authors. IntAct assay records exist [DB:IntAct].","key_references":[{"PMID":"15294972","why":"SIRPgamma ectodomain binds CD47, Kd approximately 23 microM"}],"covers":["LR001980"]},"LR001395":{"pair":"SLIT2 -> ROBO1","headline":"SLIT2 binds ROBO1, a canonical repulsive-guidance pair with cell-overlay binding, a crystal structure and database support.","interaction_type":"direct binding","direction_and_effect":"Slit2 binds Robo proteins with specific, high-affinity binding and repels embryonic spinal motor axons in culture [PMID:10102268]. UniProt lists ROBO1 as a receptor for SLIT1 and SLIT2 [DB:UniProt].","molecular_requirements":"Conditioned medium contained mixed N-terminal, C-terminal and full-length hSlit2; which fragment binds ROBO1 is not resolved here [PMID:10102268].","affinity_potency":[],"species_and_systems":"Human Slit2 on COS cells expressing rat Robo1 (overlay binding) [PMID:10102268]. Dossier covers human and mouse pairs, both ortholog-inferred.","localisation_and_range":"ROBO1 flagged transmembrane, SLIT2 secreted [flag].","caveats":"The paper's 'high-affinity' claim has no number in our evidence. Supporting records: PDB 2V9T structure [DB:PDB 2V9T], IntAct surface plasmon resonance [DB:IntAct], Reactome [DB:Reactome]. One review-only row not shown.","key_references":[{"PMID":"10102268","why":"Slit2 binds Robo1/2 in overlay assay"}],"covers":["LR001395","LR004790"]},"LR005319":{"pair":"SLITRK2 -> PTPRD","headline":"SLITRK2-PTPdelta has a crystal structure of the trans-synaptic complex plus cell aggregation evidence.","interaction_type":"direct binding","direction_and_effect":"Crystal structure of a synaptogenic trans-synaptic adhesion complex between Slitrk2 and PTPdelta, with mutagenesis defining splicing-dependent adhesion [PMID:25989451]. Slitrk2-expressing L cells aggregated with PTPdelta cells [PMID:23345436].","molecular_requirements":"Binding is splicing-dependent between Slitrks and type IIa RPTPs [PMID:25989451].","affinity_potency":[],"species_and_systems":"Structure abstract does not state species in our evidence [PMID:25989451]; mouse L cells [PMID:23345436].","localisation_and_range":"Trans-synaptic adhesion between pre- and postsynaptic membranes; SLITRK2 flagged transmembrane [flag][PMID:25989451].","caveats":"Structure paper is abstract only; no affinity reported. PMID:23345436 is a family-level assay. Four review-only rows not shown.","key_references":[{"PMID":"25989451","why":"Slitrk2-PTPdelta crystal structure"},{"PMID":"23345436","why":"Slitrk2 L-cell aggregation with PTPdelta"}],"covers":["LR001990","LR005319"]},"LR010764":{"pair":"SLURP1 -> CHRNA10","headline":"Synthetic SLURP-1 inhibits alpha9alpha10 nAChRs in functional assays; no direct binding shown for this subunit.","interaction_type":"functional only","direction_and_effect":"Synthetic SLURP-1 robustly inhibits human and rat alpha9alpha10 nAChRs, and inhibition was accentuated at higher ACh concentrations, which the authors read as an allosteric mechanism. [PMID:29192197]","molecular_requirements":"Tested as the alpha9alpha10 heteromer; alpha10 alone is not reported in our evidence [PMID:29192197].","affinity_potency":[],"species_and_systems":"Human receptors expressed heterologously (two-electrode voltage clamp), synthetic human SLURP-1 tested at 10 uM [PMID:29192197].","localisation_and_range":"SLURP1 is flagged secreted [flag]; the paper describes it as a secreted protein that co-localizes with nAChRs [PMID:29192197]. CHRNA10 has no receptor flag in the entity record.","caveats":"Curator read abstract level only. The evidence is inhibition of ACh-evoked currents, not binding. Synthetic SLURP-1 did not compete with alpha-bungarotoxin at human alpha7 or muscle-type nAChRs and did not inhibit alpha7 currents without PNU120596; earlier recombinant SLURP-1 with extensions gave conflicting results [PMID:29192197].","key_references":[{"PMID":"29192197","why":"Chemically synthesized human SLURP-1 inhibits alpha9alpha10 nAChRs"}],"covers":["LR010764"]},"LR010827":{"pair":"SLURP1 -> CHRNB2","headline":"Synthetic SLURP-1 inhibits alpha3beta2 nAChRs in functional assays; no direct binding shown for this subunit.","interaction_type":"functional only","direction_and_effect":"Synthetic SLURP-1 inhibits human alpha3beta2 nAChRs (antagonist). [PMID:29192197]","molecular_requirements":"Tested as heteromers with alpha subunits; beta2 alone is not reported in our evidence [PMID:29192197].","affinity_potency":[],"species_and_systems":"Human receptors expressed heterologously (two-electrode voltage clamp), synthetic human SLURP-1 tested at 10 uM [PMID:29192197].","localisation_and_range":"SLURP1 is flagged secreted [flag]; the paper describes it as a secreted protein that co-localizes with nAChRs [PMID:29192197]. ","caveats":"Curator read abstract level only. The evidence is inhibition of ACh-evoked currents, not binding. Synthetic SLURP-1 did not compete with alpha-bungarotoxin at human alpha7 or muscle-type nAChRs and did not inhibit alpha7 currents without PNU120596; earlier recombinant SLURP-1 with extensions gave conflicting results [PMID:29192197].","key_references":[{"PMID":"29192197","why":"Chemically synthesized human SLURP-1 tested on nAChR subtypes"}],"covers":["LR010827"]},"LR005328":{"pair":"SOST -> LRP4","headline":"Sclerostin binds Lrp4 in cell-free and cell-based pulldowns; Lrp4-deficient mice show bone defects.","interaction_type":"direct binding","direction_and_effect":"Sclerostin binds Lrp4 in vitro by pulldown and a cell-free assay with Lrp4 ectodomain-Fc [PMID:19936252]. Lrp4-deficient mice have reduced bone mass and density and raised turnover markers; Lrp4 may be an additional regulatory node beyond Lrp5/6, per the curator note [PMID:19936252]. The effect on signalling through Lrp4 is not shown in our evidence.","molecular_requirements":"Lrp4 ectodomain is sufficient for binding in the cell-free assay [PMID:19936252]. Other co-receptors are not reported.","affinity_potency":[],"species_and_systems":"HEK293A cells overexpressing Lrp4 and a cell-free assay; knockout mice for bone phenotype [PMID:19936252]. Human and mouse pairs are both ortholog-inferred. IntAct lists ELISA and SPR records from PMID 21471202 [DB:IntAct].","localisation_and_range":"SOST is flagged secreted and LRP4 as a receptor [flag]. Sclerostin is described as an osteocyte-secreted protein acting on osteoblasts [PMID:19936252].","caveats":"Paper read as abstract and excerpts. No affinity in the paper excerpts. The genetic phenotype is not specific to sclerostin binding. Both pairs are ortholog-inferred.","key_references":[{"PMID":"19936252","why":"Lrp4 binds Dkk1 and sclerostin; Lrp4 mutant bone phenotype"}],"covers":["LR002000","LR005328"]},"LR006534":{"pair":"SPARC -> ENG","headline":"SPARC directly binds endoglin and reduces its interaction with alphaV integrin; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"SPARC interacted directly with endoglin and reduced endoglin interaction with alphaV integrin, lowering TGF-beta1 activity and promoting pericyte migration [PMID:21708981]. Antagonist-like dampening of an accessory receptor, not a conventional agonist.","molecular_requirements":"Endoglin is a TGF-beta1 accessory receptor; endoglin and alphaV integrin were both needed for TGF-beta inhibition of migration [PMID:21708981].","affinity_potency":[],"species_and_systems":"Mouse pericytes and 10T1/2 cells: SPARC coprecipitated with endoglin, and solid-phase binding assays were used with SPARC and endoglin [PMID:21708981]. Human pair is ortholog-inferred.","localisation_and_range":"SPARC is flagged secreted [flag]; acts on the cell surface of pericytes.","caveats":"Single paper; no affinity reported; the excerpts do not say whether the solid-phase proteins were human or mouse. No database records.","key_references":[{"PMID":"21708981","why":"SPARC binds endoglin, reduces alphaV integrin association"}],"covers":["LR003327","LR006534"]},"LR008226":{"pair":"SPP1 -> ITGA8:ITGB1","headline":"Osteopontin binds integrin alpha8beta1 in solid-phase assays; one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Osteopontin was identified as a ligand for alpha8beta1; purified OPN binds specifically to alpha8beta1-AP in a solid-phase binding assay [PMID:9614184].","molecular_requirements":"Receptor was the soluble mouse alpha8/beta1 extracellular heterodimer; K562 cells expressing alpha8beta1 were used for adhesion assays [PMID:9614184].","affinity_potency":[],"species_and_systems":"Mouse alpha8 and beta1 extracellular domains with alkaline phosphatase; mouse embryo sections; purified OPN [PMID:9614184]. The dossier labels both species human.","localisation_and_range":"SPP1 is flagged secreted and not transmembrane [flag]; ITGA8 not given; ligand localisation overlapped developing bone and kidney [PMID:9614184].","caveats":"One paper, abstract truncated. The listed evidence sentence is about other ligands. Species labels disagree with the abstract. BioGRID and Reactome records exist for ITGB1 and alpha8beta1 [DB:BioGRID][DB:Reactome].","key_references":[{"PMID":"9614184","why":"Osteopontin identified as alpha8beta1 ligand by solid-phase binding"}],"covers":["LR008226"]},"LR005337":{"pair":"SPP1 -> ITGB3","headline":"Osteopontin is reported to engage integrin alphavbeta3 (RGD-dependent); our own evidence is thin and abstract-level.","interaction_type":"direct binding","direction_and_effect":"Osteopontin is a ligand for alphavbeta3 [PMID:16005200]; alphavbeta3 is described as a previously known OPN-binding integrin [PMID:7592829]. Effect direction is not reported in our evidence.","molecular_requirements":"alphavbeta3 binds the RGD site of osteopontin; thrombin cleavage is not required for optimal adhesion [PMID:16005200]. The heterodimer, not ITGB3 alone, is the binding unit.","affinity_potency":[],"species_and_systems":"Experimental species unspecified [PMID:16005200]; human GST-OPN with HEK293 cells in the background paper, where alphavbeta3 was not the new finding [PMID:7592829].","localisation_and_range":"SPP1 is flagged secreted [flag]; OPN is called an extracellular matrix protein [PMID:7592829].","caveats":"Both papers were read as abstracts only and neither mainly tests alphavbeta3. The mouse pair is ortholog-inferred. Reactome has an alphaVbeta3:SPP1 complex [DB:Reactome]. One further paper was judged abstract-insufficient.","key_references":[{"PMID":"16005200","why":"Compares RGD dependence across five OPN integrins"},{"PMID":"7592829","why":"States alphavbeta3 as known OPN receptor"}],"covers":["LR002009","LR005337"]},"LR004806":{"pair":"SST -> SSTR2","headline":"Somatostatin binds SSTR2 with high affinity in recombinant cells; multiple abstract-level binding papers.","interaction_type":"direct binding","direction_and_effect":"Somatostatin is an agonist; SSTR1 and SSTR2 bind SRIF and SRIF 28 with high affinity [PMID:8702767]. SRIF14 equals SRIF28 in rank order at sst2 [PMID:9652348]. GtoPdb gives pKi 8.9-10.5 [DB:GtoPdb].","molecular_requirements":"SSTR2 alone suffices in transfected cells. Synthetic hexapeptide/octapeptide analogs bind SSTR2 selectively; residues 294-297 (FDFV) in TM7 of murine SSTR2 determine analog affinity [PMID:8702767].","affinity_potency":[{"value":"pKd 9.89","assay":"[125I][Tyr3]octreotide saturation binding","system":"human sst2 in CCL39 cells","cite":"PMID:9652348"},{"value":"pKi 8.9-10.5","assay":"GtoPdb curated range","system":"not reported","cite":"PMID:7988476"}],"species_and_systems":"Human SSTR2 in CHO or CCL39 cells; murine SSTR2 mutagenesis [PMID:1346068][PMID:9652348][PMID:8702767]. Mouse pair is ortholog-inferred.","localisation_and_range":"SST flagged secreted [flag].","caveats":"All abstract-only. The pKd 9.89 is for the octreotide analogue radioligand, not native somatostatin. Several rows concern analogs or comparisons.","key_references":[{"PMID":"1346068","why":"Cloning of SSTR2; somatostatin binding"},{"PMID":"9652348","why":"sst2 pharmacology, SRIF14 = SRIF28"},{"PMID":"8702767","why":"SSTR2 selectivity determinants"}],"covers":["LR001411","LR004806"]},"LR006543":{"pair":"SVEP1 -> ITGA9","headline":"SVEP1 (polydom) is a direct ligand of integrin alpha9beta1, supported by two papers and databases.","interaction_type":"direct binding","direction_and_effect":"Polydom/SVEP1 binds directly to recombinant integrin alpha9beta1 and mediates alpha9beta1-dependent cell adhesion [PMID:22654117]. In vascular smooth muscle, inhibiting SVEP1/alpha4beta1/alpha9beta1 enhanced intracellular calcium to Gq/11 vasoconstrictors, so the axis restrains contraction [PMID:35802072][DB:UniProt].","molecular_requirements":"Receptor is the alpha9beta1 heterodimer; ITGB1 is needed in addition to ITGA9 [PMID:22654117][DB:UniProt]. Polydom mapped integrin-binding site with N-terminal deletion constructs (site not detailed in our evidence) [PMID:22654117].","affinity_potency":[],"species_and_systems":"Recombinant integrin and cell adhesion assays (species not stated in dossier) [PMID:22654117]; human iPSC-derived VSMCs and Svep1+/- mouse vessels [PMID:35802072].","localisation_and_range":"SVEP1 is flagged secreted [flag]; described as an extracellular matrix protein [PMID:22654117].","caveats":"Both papers read as abstracts only. The abstract says the affinity far exceeds that of other alpha9beta1 ligands but no value is given in our evidence [PMID:22654117]. GtoPdb records binding with no affinity [DB:GtoPdb].","key_references":[{"PMID":"22654117","why":"polydom/SVEP1 binds integrin alpha9beta1 directly"},{"PMID":"35802072","why":"SVEP1-integrin axis in vasoregulation"}],"covers":["LR003336","LR006543"]},"LR004815":{"pair":"Tac2 -> Tacr3","headline":"Neurokinin B (Tac2) acts on NK3 receptor (Tacr3); supported by human-receptor binding and Ca2+ papers, abstract only, projected to mouse.","interaction_type":"direct binding","direction_and_effect":"Agonist. NKB is the natural ligand with Ki = 0.8 nM at human NK-3 in the antagonist paper [PMID:9190866]; NKB inhibition is also seen in an NK-3 homolog line [PMID:8990205]. GtoPdb lists a full agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[{"value":"Ki 0.8 nM","assay":"NKB affinity, [125I][MePhe7]NKB binding","system":"CHO cells expressing human NK-3","cite":"PMID:9190866"},{"value":"Kd 39 nM","assay":"[3H]senktide binding","system":"CHO cells expressing NK-3 receptor homolog","cite":"PMID:8990205"},{"value":"pKi 7.7-9.2","assay":"curated agonist affinity range","system":"GtoPdb record","cite":"DB:GtoPdb"}],"species_and_systems":"Human receptor in CHO and HEK 293 cells [PMID:9190866] [PMID:8990205]; the mouse pair is ortholog-inferred.","localisation_and_range":"Tac2 flagged secreted and Tacr3 as a receptor [flag].","caveats":"Both papers are abstract only and use human receptors, so mouse is inferred. The 39 nM Kd is for the senktide radioligand, not NKB [PMID:8990205]. PMID 9190866 is mainly an antagonist (SB 223412) study.","key_references":[{"PMID":"9190866","why":"NKB affinity at human NK-3 and NKB-induced Ca2+ mobilisation"},{"PMID":"8990205","why":"NK-3 homolog binds senktide and [125I-MePhe7]NKB"}],"covers":["LR004815"]},"LR003348":{"pair":"TAFA2 -> KIR3DL3","headline":"TAFA2 tetramers stain KIR3DL3-expressing cells; weak direct binding from one screening paper.","interaction_type":"direct binding","direction_and_effect":"Cell-surface staining with TAFA2 tetramers (200 nM) showed concentration-dependent binding to K562 cells expressing KIR3DL3 [PMID:36178190]. The paper calls TAFA-2 selective for inhibitory KIRs; functional effect on KIR3DL3 signalling is not reported in our evidence.","molecular_requirements":"Binding was higher to KIRs with a D0 domain (KIR3s, KIR2DL5A) than to KIR2DL2, which lacks D0 [PMID:36178190].","affinity_potency":[],"species_and_systems":"Human TAFA2 and human KIR3DL3 (FLAG-tagged, lentivirally expressed in K562 cells); recombinant tetramers, flow cytometry [PMID:36178190].","localisation_and_range":"TAFA2 is annotated as secreted [flag]; KIR3DL3 is annotated as a receptor [flag].","caveats":"By SPR, binding to KIR3DL3 was at the limit of detection and did not saturate, whereas KIR3DL1 gave a KD of ~1.7 \u00b5M [PMID:36178190]. Support is a single screening paper; no independent confirmation.","key_references":[{"PMID":"36178190","why":"CRISPRa screen hit confirmed by cell-surface staining of KIR3DL3 cells"}],"covers":["LR003348"]},"LR006552":{"pair":"TAFA2 -> NRXN1","headline":"TAFA2 (FAM19A2) binds neurexins, including NRXN1, by disulfide linkage; one paper, mouse and HEK293T systems.","interaction_type":"direct binding","direction_and_effect":"FAM19A/TAFA proteins interact with all neurexins except neurexin-1\u03b3 [PMID:32706374]. FAM19A1 and FAM19A2 were isolated in a complex with neurexins from brain homogenates using multiple neurexin antibodies [PMID:32706374]. Rather than activating a receptor, FAM19A1 expression decreased neurexin O-glycosylation and heparan sulfate modification in hippocampal cultures [PMID:32706374].","molecular_requirements":"FAM19A1-A4 bind the cysteine-loop domain of neurexins by forming intermolecular disulfide bonds; both the cysteines and an adjacent neurexin sequence were required [PMID:32706374]. FAM19A5 does not bind [PMID:32706374].","affinity_potency":[],"species_and_systems":"Endogenous complexes from mouse brain; recombinant coIP in HEK293T cells with Nrxn1\u03b2-ECD; hippocampal cultures [PMID:32706374]. The human pair and the mouse pair are both listed, the human one projected from mouse-type evidence [flag].","localisation_and_range":"TAFA2 is annotated secreted and NRXN1 as transmembrane [flag]. Binding occurs within the secretory pathway and needs cis co-expression [PMID:32706374].","caveats":"Supported by one paper read as an abstract plus full-text excerpts; the abstract states that neurexin-1\u03b3 is the exception [PMID:32706374]. Binding is covalent and forms during transit through the secretory pathway, which is unusual for a ligand-receptor pair.","key_references":[{"PMID":"32706374","why":"Identifies FAM19A1-A4 as pan-neurexin ligands with disulfide-linked binding"}],"covers":["LR003349","LR006552"]},"LR007416":{"pair":"TENM1 -> ADGRL1","headline":"Teneurin-1 was identified among proteins pulled down by the latrophilin-1 extracellular domain; direct pair-specific evidence is thin.","interaction_type":"direct binding","direction_and_effect":"Affinity chromatography of rat brain extract on latrophilin-1 (Lphn1) ectodomain columns followed by mass spectrometry identified teneurin-1, -3 and -4 for IgLp1ECD, and all four teneurins for IgLp1LEC [PMID:24273166]. The abstract states that teneurin binds latrophilins with nanomolar affinity and mediates cell adhesion, without isoform detail visible here [PMID:24273166].","molecular_requirements":"Binding is via the lectin-like domain of latrophilins; alternative splicing in latrophilin-1 modulates teneurin binding but not FLRT3 binding [PMID:24273166].","affinity_potency":[],"species_and_systems":"Rat brain extract, mass spectrometry, Lphn1-Ig fusion proteins [PMID:24273166].","localisation_and_range":"Both are annotated transmembrane [flag]; the paper proposes trans-synaptic, cell-contact interaction [PMID:24273166].","caveats":"Only a co-purification identification supports TENM1 specifically; the other evidence is review_only or abstract_insufficient. A mass spectrometry hit is not a direct binding test.","key_references":[{"PMID":"24273166","why":"Identifies teneurins as latrophilin lectin-domain interactors"}],"covers":["LR007416"]},"LR003357":{"pair":"TENM2 -> ADGRL1","headline":"Well-supported adhesion pair: teneurin-2 (Lasso) and latrophilin-1 co-purify, bind and attract cells; rat brain and HEK293T data.","interaction_type":"direct binding","direction_and_effect":"LPH1 and Lasso (a teneurin-2 splice variant) interact strongly and specifically and are always co-purified from rat brain extracts [PMID:21724987]. Co-culturing LPH1 and Lasso cells led to mutual attraction and junction formation; a C-terminal Lasso fragment induced Ca2+ signals in presynaptic boutons [PMID:21724987]. Pulldown showed Ten2 and Ten4, but not Ten1, binding all Lphn1 constructs [PMID:24273166].","molecular_requirements":"Lectin-like domain of latrophilins is the teneurin-binding region; Lphn1 splicing modulates teneurin binding but not FLRT3 binding [PMID:24273166]. Lasso is a teneurin-2 splice variant [PMID:21724987].","affinity_potency":[],"species_and_systems":"Rat brain purification, cell cocultures, hippocampal neurons [PMID:21724987]; HEK293T-derived teneurin ectodomains and Lphn1-Ig [PMID:24273166]. Human and mouse pairs are ortholog-inferred. UniProt records the ligand role [DB:UniProt].","localisation_and_range":"Both transmembrane [flag]; LPH1 is presynaptic and Lasso postsynaptic, a trans-synaptic contact interaction [PMID:21724987].","caveats":"One key paper was read as abstract only [PMID:21724987]. Affinity values not in our excerpts.","key_references":[{"PMID":"21724987","why":"Purifies Lasso/teneurin-2 as the LPH1 ligand"},{"PMID":"24273166","why":"Pulldowns show Ten2 binding to Lphn1 lectin domain"}],"covers":["LR003357","LR006560"]},"LR006561":{"pair":"TENM2 -> ADGRL2","headline":"Cell-adhesion evidence that teneurin-2 engages latrophilin-expressing cells including Lphn2; one paper, indirect.","interaction_type":"functional only","direction_and_effect":"Mixing HEK293T cells expressing Lphn1/2/3 with cells expressing Ten2 or Ten4 produced large cell aggregates indicating intercellular adhesion [PMID:24273166].","molecular_requirements":"Not reported separately for ADGRL2 in our evidence.","affinity_potency":[],"species_and_systems":"HEK293T cell aggregation assay [PMID:24273166]. Both listed pairs are ortholog-inferred.","localisation_and_range":"Both annotated transmembrane receptors [flag]; interaction is cell-contact (trans) adhesion [PMID:24273166].","caveats":"Aggregation does not isolate ADGRL2 from the other latrophilins in our excerpt, and no ADGRL2-specific affinity is reported. Other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"24273166","why":"Cell aggregation of Lphn-expressing cells with Ten2 cells"}],"covers":["LR003358","LR006561"]},"LR003366":{"pair":"TFF3 -> LINGO2","headline":"LINGO2 pulls down with TFF3, co-localizes at the membrane and is required for TFF3 function in one paper.","interaction_type":"direct binding","direction_and_effect":"TFF3-LINGO2 interaction disrupts inhibitory EGFR-LINGO2 complexes, enhancing EGFR signalling and allowing TFF3 to block apoptosis [PMID:31562318]. Anti-LINGO2 antibody at high doses blocked TFF3-induced IL-10 production in U937 cells [PMID:31562318].","molecular_requirements":"The LINGO2 extracellular LRR region is needed: an N-terminal truncation (delta 350 AA) abrogated co-localization with TFF3 [PMID:31562318].","affinity_potency":[],"species_and_systems":"Human U937 and HEK293 cells, murine MC38 cells and Lingo2-deficient mice; co-immunoprecipitation used murine TFF3-Fc with Flag-tagged LINGO2 [PMID:31562318]. The human pair is ortholog-inferred; the mouse pair is not.","localisation_and_range":"TFF3 is annotated secreted [flag]; localisation of LINGO2 binding is on the epithelial cell membrane, within 40 nm by proximity ligation [PMID:31562318].","caveats":"Evidence is co-IP and co-localization, with no affinity reported. Only the abstract plus excerpts were read. The same paper found no membrane co-localization of TFF3 with CXCR4 in HEK293 cells [PMID:31562318].","key_references":[{"PMID":"31562318","why":"LINGO2 as TFF3 receptor and EGFR derepression"}],"covers":["LR003366","LR006567"]},"LR004833":{"pair":"TGFB1 -> ACVRL1","headline":"TGF-beta1 binds ALK1 (ACVRL1) in endothelial cells, with TbetaR-II; one abstract-only mouse paper.","interaction_type":"direct binding","direction_and_effect":"ALK1 binds TGF-beta1 and TbetaR-II in endothelial cells; ALK1 signalling can inhibit TGF-beta1 transcriptional activation mediated by ALK5 [PMID:10716993].","molecular_requirements":"Binds together with TbetaR-II [PMID:10716993]; other requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse experiments (ligand and receptor both mouse), endothelial cells and ALK1-knockout mice [PMID:10716993]. Human pair is ortholog-inferred.","localisation_and_range":"TGFB1 is flagged secreted [flag]. Receptor localisation not reported in our evidence.","caveats":"Single paper read as abstract only. The binding details (assay, affinity) are not reported in our evidence. No database records.","key_references":[{"PMID":"10716993","why":"ALK1 binds TGF-beta1 and TbetaR-II in endothelial cells; ALK1 null mice"}],"covers":["LR001438","LR004833"]},"LR006570":{"pair":"TGFB1 -> ITGA8","headline":"Integrin alpha8beta1 adheres to LAP-TGFbeta1 in cell assays; adhesion evidence only.","interaction_type":"functional only","direction_and_effect":"alpha8-transfected cell lines spread on and adhere to recombinant LAP-TGFbeta1 better than mock cells [PMID:12415008].","molecular_requirements":"The binder assayed is the alpha8 subunit with beta1 (alpha8beta1); the ligand is LAP-TGFbeta1, the latent form [PMID:12415008]. Adhesion was RGD-dependent and enhanced by Mn2+ or activating antibody 8A2 per curator notes [PMID:12415008].","affinity_potency":[],"species_and_systems":"Recombinant LAP-TGFbeta1 and transfected cell lines; species not reported in our evidence [PMID:12415008].","localisation_and_range":"TGFB1 is flagged secreted [flag]. Matrix-like adhesion of latent complex to a cell integrin; no further range data.","caveats":"Adhesion assay is not direct binding; read as abstract only. Ligand is the latent form, not mature TGF-beta1. No database records.","key_references":[{"PMID":"12415008","why":"alpha8beta1-mediated adhesion to LAP-TGFbeta1"}],"covers":["LR003369","LR006570"]},"LR005346":{"pair":"TGFB1 -> VASN","headline":"TGF-beta1 binds vasorin directly and vasorin dampens its signalling; vasorin acts as a TGF-beta binding modulator, not a classic receptor.","interaction_type":"direct binding","direction_and_effect":"Vasorin directly binds TGF-beta and attenuates TGF-beta signalling in vitro; restoring vasorin in vivo reduced injury-induced vascular lesions, partly via TGF-beta inhibition, an antagonist/decoy-like role [PMID:15247411]. Desialylation of VASN enhanced TGF-beta1 binding 2- to 3-fold and dampened TGF-beta1 signalling and angiogenesis [PMID:30252131].","molecular_requirements":"Not reported in our evidence beyond VASN being the binding partner. Full text reports binding fold to TGF-beta1 of 3.2x without alpha2,3-sialic acid and 1.45x without N-glycan [PMID:30252131].","affinity_potency":[],"species_and_systems":"Human VASN and TGF-beta1 in the 2018 work (MCF7 secreted VASN, HUVEC readouts); in vivo arterial injury model in the 2004 paper [PMID:30252131][PMID:15247411]. Mouse pair is ortholog-projected.","localisation_and_range":"Vasorin is a type I membrane protein [PMID:15247411]; a secreted form (sVASN, 93 kDa) occurs in MCF7 medium [PMID:30252131]. Our receptor flag marks it non-transmembrane [flag].","caveats":"Both papers were judged on abstracts, the second with full-text excerpts. Glycosylation modulates binding, so affinity depends on the VASN form. BioGRID and UniProt also list the interaction [DB:BioGRID][DB:UniProt].","key_references":[{"PMID":"15247411","why":"Direct TGF-beta binding by vasorin, antagonism in vitro and in vivo"},{"PMID":"30252131","why":"Sialylation of VASN changes TGF-beta1 binding 2- to 3-fold"}],"covers":["LR002018","LR005346"]},"LR004842":{"pair":"TGFB2 -> TGFBR2","headline":"TGF-beta2 binds a TGFBR2 splice variant (TbetaRII-B) and signals through Smad in the absence of betaglycan.","interaction_type":"direct binding","direction_and_effect":"TbetaRII-B restores TGF-beta2 sensitivity in L6 cells lacking TbetaRIII and TbetaRII-B, signalling via the Smad pathway [PMID:11157754]. Annotated stimulatory [flag].","molecular_requirements":"Works without a type III receptor; the evidence concerns the TbetaRII-B isoform specifically [PMID:11157754].","affinity_potency":[],"species_and_systems":"L6 cells in a transfection rescue assay; the species of the cells and constructs is not reported in our evidence. Human pair, mouse ortholog-projected.","localisation_and_range":"Ligand secreted [flag]; BioGRID, GtoPdb, PDB and Reactome also hold records [DB:BioGRID][DB:GtoPdb][DB:PDB 5TX4].","caveats":"Abstract-only; evidence is for the alternatively spliced isoform, not necessarily the main TGFBR2 form.","key_references":[{"PMID":"11157754","why":"TbetaRII-B as a TGF-beta2 binding receptor"}],"covers":["LR001447","LR004842"]},"LR008280":{"pair":"TGFB3 -> ACVR1:TGFBR1","headline":"TGF-beta3 does not bind ACVR1 in a verified negative; ACVR1 engagement is described for TGF-beta1 only.","interaction_type":"conflicting","direction_and_effect":"The full text states that engineered TGF-beta3 WW does not bind ACVR1, and by inference neither does TGF-beta3 WD [PMID:29376829]. The same paper shows TGF-beta-induced SMAD1/5 phosphorylation needs TGFBR1 and ACVR1, with TGFBR1 phosphorylating ACVR1 [PMID:29376829].","molecular_requirements":"The paper's model has TGFBR1 activate ACVR1, which phosphorylates SMAD1/5 [PMID:29376829].","affinity_potency":[],"species_and_systems":"Biochemical assay with engineered TGF-beta3 constructs; species not detailed in our evidence.","localisation_and_range":"Ligand secreted, annotated transmembrane [flag]. Structure of TGF-beta3 with TGFBR1 chain [DB:PDB 2PJY].","caveats":"The negative uses engineered constructs. GtoPdb and PDB records concern TGFBR1 and TGFBR2, not ACVR1 [DB:GtoPdb].","key_references":[{"PMID":"29376829","why":"Explicit TGF-beta3 / ACVR1 negative, ACVR1 role in SMAD1/5"}],"covers":["LR008280"]},"LR001449":{"pair":"TGFB3 -> ACVRL1","headline":"TGF-beta3 activates a chimeric ALK-1 (ACVRL1) receptor in a signalling assay; binding was not measured.","interaction_type":"functional only","direction_and_effect":"TGF-beta1 and TGF-beta3 activated chimeric ALK-1; the interaction is mediated by the type II TGF-beta receptor [PMID:10187774].","molecular_requirements":"Type II TGF-beta receptor needed; endoglin's role is discussed but not reported here [PMID:10187774].","affinity_potency":[],"species_and_systems":"Chimeric ALK-1 with kinase domain swapped for TGFBR1 or ActRIB; species unspecified [PMID:10187774].","localisation_and_range":"Ligand secreted [flag]; ligand also flagged transmembrane [flag].","caveats":"Abstract-only; chimeric receptor, not native; two other papers abstract-insufficient.","key_references":[{"PMID":"10187774","why":"TGF-beta3 activates chimeric ALK-1 via type II receptor"}],"covers":["LR001449","LR004844"]},"LR007434":{"pair":"TGFB3 -> ITGAV:ITGB8","headline":"alphaVbeta8 complex row for TGF-beta3 is supported by an electron microscopy structure only; no verified paper.","interaction_type":"database-asserted only","direction_and_effect":"PDB 8VS6 is an EM structure titled L-TGF-b3/avb8 [DB:PDB 8VS6].","molecular_requirements":"Both chains named in the record [DB:PDB 8VS6].","affinity_potency":[],"species_and_systems":"No curator-judged papers; three pending.","localisation_and_range":"Annotated secreted ligand, transmembrane complex [flag].","caveats":"Not curator-verified; latent form is implied by the structure title.","key_references":[],"covers":["LR007434"]},"LR003375":{"pair":"TGFB3 -> ITGB6","headline":"Integrin beta6 (as alphaVbeta6) binds the TGF-beta3 prodomain, with structural evidence; chain-only row.","interaction_type":"direct binding","direction_and_effect":"alphaVbeta6 binds RGDLXXL/I in TGF-beta1 and TGF-beta3 prodomains with high affinity [PMID:25383667], and binds and activates latent TGFbeta3 [PMID:11821050]. A PDB structure exists [DB:PDB 4UM9].","molecular_requirements":"The LXXL/I helix binds a hydrophobic pocket in the beta6 subunit; heterodimer needed [PMID:25383667].","affinity_potency":[],"species_and_systems":"Structure and peptide affinity (species not stated); 2002 work in unspecified species [PMID:11821050].","localisation_and_range":"Ligand secreted, annotated transmembrane [flag].","caveats":"The bound species is the latency-associated peptide (LAP) complex, not mature TGF-beta. Integrin activates latent TGF-beta; abstract-only.","key_references":[{"PMID":"25383667","why":"Crystal structure of alphaVbeta6 with prodomain motif"},{"PMID":"11821050","why":"alphaVbeta6 binds and activates latent TGFbeta3"}],"covers":["LR003375","LR006576"]},"LR004851":{"pair":"TGM2 -> ITGA9","headline":"tTG is a ligand for integrin alpha9beta1 by cell adhesion in two cell systems; functional support from one paper.","interaction_type":"functional only","direction_and_effect":"G-361 cells use alpha(9)beta(1) to adhere to tTG, and SW480 cells transfected with alpha(9)beta(1), but not mock transfectants, adhered to tTG [PMID:10816592].","molecular_requirements":"Functional receptor is alpha9beta1, so ITGB1 is also required [PMID:10816592].","affinity_potency":[],"species_and_systems":"Human G-361 melanoma and SW480 colon cancer cells [PMID:10816592]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; adhesion to tTG as substrate [PMID:10816592].","caveats":"Adhesion assays only, no direct binding or affinity; abstract-level read; one paper.","key_references":[{"PMID":"10816592","why":"tTG, FXIII and pp-vWF as ligands for alpha9beta1"}],"covers":["LR001456","LR004851"]},"LR001458":{"pair":"TGM2 -> ITGB3","headline":"TG2 binds integrin beta3 in co-IP and macrophage studies; supported by two papers.","interaction_type":"direct binding","direction_and_effect":"TG2 interacts directly with beta1 and beta3 integrins but not beta2 [PMID:10684262]. TG2 binds integrin beta3 and MFG-E8 to build phagocytic portals; integrin beta3 signalling is impaired in TG2-null macrophages [PMID:19643138].","molecular_requirements":"TG2 stabilises accumulated integrin beta3 at the phagocytic cup; beta3 over-expression partially corrected the defect [PMID:19643138]. Association is noncovalent and independent of cross-linking activity [PMID:10684262].","affinity_potency":[],"species_and_systems":"Mouse macrophages for [PMID:19643138]; cultured cells with human tTG for [PMID:10684262]. The mouse pair is ortholog-inferred.","localisation_and_range":"TGM2 is flagged secreted [flag]; cell-surface and phagocytic cup contexts [PMID:19643138].","caveats":"Both papers were read as abstracts only for this pair. The beta3 partner alpha chain is not reported in our evidence.","key_references":[{"PMID":"10684262","why":"tTG interacts with beta1 and beta3 integrins"},{"PMID":"19643138","why":"TG2 binds integrin beta3 in macrophage phagocytosis"}],"covers":["LR001458","LR004853"]},"LR004860":{"pair":"THBS1 -> ITGA3","headline":"Functional evidence that alpha3beta1 mediates breast carcinoma cell adhesion and chemotaxis to THBS1; no direct binding data.","interaction_type":"functional only","direction_and_effect":"The integrin alpha3beta1 is the major mediator of breast carcinoma cell adhesion and chemotaxis to TSP1 (stimulatory). TSP1 binding activity of alpha3beta1 was not stimulated by CD47-binding peptides from TSP1 [PMID:10196234]. Reactome lists THBS1 binding integrin alpha3beta1, alpha4beta1 [DB:Reactome].","molecular_requirements":"Acts as the alpha3beta1 heterodimer; activation state matters, as the integrin is partially active in MDA-MB-435 but mostly inactive in MDA-MB-231 and MCF-7, which need beta1 activation to spread on TSP1 [PMID:10196234]. IGF-1 and CD98 ligation increase its activity [PMID:10196234].","affinity_potency":[],"species_and_systems":"Breast carcinoma cell lines (species recorded as unspecified in this row) [PMID:10196234]. Mouse pair is ortholog-inferred.","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"One paper, read as abstract only; the readout is cell adhesion and chemotaxis, not physical binding. No affinity reported.","key_references":[{"PMID":"10196234","why":"alpha3beta1 is the major mediator of breast carcinoma adhesion/chemotaxis to TSP1"}],"covers":["LR001465","LR004860"]},"LR001467":{"pair":"THBS1 -> ITGA6","headline":"Reasonable evidence that alpha6beta1 recognizes the THBS1 N-terminal module, plus a co-IP in osteosarcoma cells.","interaction_type":"direct binding","direction_and_effect":"The THBS1 N-terminal pentraxin module is a ligand for alpha6beta1, which mediates adhesion and chemotaxis (stimulatory) of microvascular endothelial and HT-1080 cells; the peptide LALERKDHSG was identified as an alpha6beta1-binding sequence [PMID:12909644]. Co-IP confirmed THBS1 interacts with ITGA6 in human osteosarcoma cells [PMID:40083708].","molecular_requirements":"Acts as alpha6beta1; in microvascular cells activation by the anti-beta1 antibody TS2/16 is needed, and Glu90 of THBS1 was required for alpha6beta1 but not alpha4beta1 recognition [PMID:12909644].","affinity_potency":[],"species_and_systems":"Human endothelial and HT-1080 cells [PMID:12909644]; human 143B and MG-63 osteosarcoma lines [PMID:40083708].","localisation_and_range":"THBS1 is flagged secreted [flag], so it likely acts as a soluble or matrix-associated ligand; range is not reported in our evidence beyond that.","caveats":"The 2003 paper was read as abstract only; its evidence is cell adhesion with a peptide, and the osteosarcoma co-IP does not prove direct binding. Activation-state dependent. No affinity reported.","key_references":[{"PMID":"12909644","why":"alpha6beta1 recognizes THBS1 N-terminal module; LALERKDHSG peptide"},{"PMID":"40083708","why":"Co-IP of THBS1 with ITGA6 (full text)"}],"covers":["LR001467","LR004862"]},"LR003384":{"pair":"THBS1 -> TGFBR1","headline":"One 2024 abstract reports THBS1 interacting with TbetaRI and ITGAV in prostate cancer cells; other details not available.","interaction_type":"direct binding","direction_and_effect":"THBS1 mediates cell migration by interacting with ITGAV and TbetaRI; deletion of TbetaRI or THBS1 prevents migration and invasion [PMID:39304722]. Curation labels agonist, but this is not shown by the abstract.","molecular_requirements":"THBS1 interacts with both ITGAV and TbetaRI in this paper [PMID:39304722]; whether either alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Castration-resistant prostate cancer cells (human), CRISPR/siRNA, xenograft [PMID:39304722].","localisation_and_range":"THBS1 is flagged secreted [flag]; TGFbeta induces its production [PMID:39304722].","caveats":"Abstract only; the interaction techniques are not named in the dossier. Interaction direction is odd for a ligand-receptor pair as TbetaRI normally binds TGFb1 [PMID:39304722].","key_references":[{"PMID":"39304722","why":"TbetaRI/ITGAV and THBS1 in prostate cancer migration"}],"covers":["LR003384","LR006585"]},"LR001476":{"pair":"THPO -> MPL","headline":"Well supported agonist pair with a cryo-EM structure of the TPO-MPL extracellular complex plus functional and database evidence.","interaction_type":"direct binding","direction_and_effect":"Agonist: TPO bridges two MPL chains and drives homodimeric MPL activation [PMID:37633268]; TPO-stimulated Mpl activation is proposed to occur through receptor homodimerisation [PMID:8521814]. GtoPdb lists the interaction as Agonist [DB:GtoPdb].","molecular_requirements":"Two MPL chains per TPO. TPO binds via a high-affinity site 1 and a low-affinity site 2; MPL CRM1 recognises TPO and CRM2 brings transmembrane and intracellular domains together [PMID:37633268].","affinity_potency":[],"species_and_systems":"Cryo-EM at 3.4 \u00c5 resolution using human TPO and human MPL; SPR with human MPL ectodomain; also mouse and in vitro cell work with TPO variants [PMID:37633268]. The 1995 study used mutant Mpl in FDC-P1 and Ba/F3 cells (abstract only) [PMID:8521814]. PDB 8G04 [DB:PDB 8G04].","localisation_and_range":"TPO is flagged secreted and MPL transmembrane [flag]; endocrine/paracrine cytokine acting on membrane receptor.","caveats":"Engineered TPO variants span neutral antagonists to partial and super-agonists [PMID:37633268]. The 1995 paper was read as abstract only and shows TPO action only indirectly [PMID:8521814]. No numeric affinity in our evidence.","key_references":[{"PMID":"37633268","why":"Cryo-EM structure of TPO-MPL complex and biased agonists"},{"PMID":"8521814","why":"Mpl dimer interface and TPO-stimulated homodimerisation"}],"covers":["LR001476","LR004871"]},"LR003393":{"pair":"THY1 -> ITGAM","headline":"Thy-1 binds Mac-1 (alphaM-beta2) and the isolated alphaM I-domain; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Thy-1 on endothelium mediates leukocyte adhesion and transendothelial migration via Mac-1 [PMID:15004192]. alphaM I-domain also binds Thy-1, with roughly half the affinity of alphaX [PMID:15850796].","molecular_requirements":"Evidence at the Mac-1 (CD11b/CD18, alphaMbeta2) heterodimer level; the alphaM I-domain alone binds Thy-1 [PMID:15004192][PMID:15850796].","affinity_potency":[],"species_and_systems":"Human: monocytes, PMNs, Thy-1 transfectants, dermal microvascular endothelial cells, purified proteins [PMID:15004192]; recombinant I-domain binding [PMID:15850796].","localisation_and_range":"Membrane-bound on both sides [flag]; juxtacrine leukocyte-endothelium contact [PMID:15004192].","caveats":"Both papers abstract only; alphaM affinity is given only relative to alphaX and no absolute value is reported for alphaM [PMID:15850796]. Beta2 chain involvement is not separated here.","key_references":[{"PMID":"15004192","why":"Thy-1 identified as Mac-1 counterreceptor"},{"PMID":"15850796","why":"alphaM I-domain affinity relative to alphaX"}],"covers":["LR003393","LR006594"]},"LR007425":{"pair":"THY1 -> ITGAV:ITGB3","headline":"THY1 binds the alphavbeta3 complex by SPR and force spectroscopy; two abstract-only papers.","interaction_type":"direct binding","direction_and_effect":"Thy-1/alphavbeta3 interactions stimulate astrocyte migration and retraction of neuronal prolongations [PMID:29212879]; signalling to astrocytes depended on the Thy-1-integrin interaction [PMID:18346467].","molecular_requirements":"alphav forms an alphavbeta3 heterodimer in DI TNC1 astrocytes and both subunits were required for neuron-astrocyte association [PMID:18346467].","affinity_potency":[],"species_and_systems":"Thy-1-Fc with nonpurified alphavbeta3-Fc in optical tweezers, force accelerates dissociation (slip bond) [PMID:29212879]; DI TNC1 astrocytes, noted in curator notes as a rat line while the row is human [PMID:18346467].","localisation_and_range":"Membrane-bound neuron-to-astrocyte contact [PMID:18346467].","caveats":"Abstract only for both; no affinity values; the species of the astrocyte work differs from the human pair.","key_references":[{"PMID":"18346467","why":"SPR binding of Thy-1 to alphavbeta3"},{"PMID":"29212879","why":"Force-dependent dissociation"}],"covers":["LR007425"]},"LR006606":{"pair":"TIMP3 -> ITGA7","headline":"ITGA7 binds TIMP3 in prostate cancer cells with growth-suppressing signalling; one abstract-read paper.","interaction_type":"direct binding","direction_and_effect":"ITGA7 bound TIMP3 in prostate cancer cells, lowering TNF-alpha, causing cytoplasmic NF-kappaB translocation and cyclin D1 down-regulation, with G0/G1 accumulation and growth suppression; TIMP3 knockdown or interfering with ITGA7/TIMP3 binding largely abrogated this, and a mutant ITGA7 lacking TIMP3 binding had no tumour-suppressor activity [PMID:23830872].","molecular_requirements":"Knocking down laminin beta1 (ITGA7's canonical ligand) enhanced ITGA7-TIMP3 signalling [PMID:23830872]. Partner integrin beta chain is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human prostate cancer cells [PMID:23830872]; mouse pair is ortholog-inferred.","localisation_and_range":"TIMP3 is flagged secreted; ITGA7 flagged receptor [flag].","caveats":"Single abstract-read paper; no affinity reported.","key_references":[{"PMID":"23830872","why":"ITGA7-TIMP3 binding and tumour-suppressive signalling"}],"covers":["LR003405","LR006606"]},"LR008541":{"pair":"TLN1 -> ITGB3","headline":"Database-asserted binding between TLN1 and integrin beta3; no curated paper, only a review.","interaction_type":"database-asserted only","direction_and_effect":"BioGRID lists reconstituted-complex and protein-peptide records and IntAct lists fluorescence polarization, saturation binding and ELISA records for TLN1-ITGB3 [DB:BioGRID][DB:IntAct]. The interaction is annotated as stimulatory in the dossier [flag].","molecular_requirements":"not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species and system not reported in our evidence.","localisation_and_range":"TLN1 has no secretion annotation and ITGB3 is flagged non-secreted receptor [flag].","caveats":"The only judged paper was review_only, so no primary paper is confirmed. Binding evidence is in vitro database records only.","key_references":[],"covers":["LR008541"]},"LR001485":{"pair":"TNC -> ITGA7","headline":"Alpha7beta1 integrin associates with tenascin-C peptides in human-derived binding assays and mediates neurite outgrowth; abstract-only.","interaction_type":"direct binding","direction_and_effect":"Function-blocking antibodies to alpha7 and beta1 abolished VFDNFVLK-mediated process extension from cerebellar granule neurons, and alpha7beta1 associated biochemically with peptides containing VFDNFVLK [PMID:14715956].","molecular_requirements":"Both alpha7 and beta1 were needed for the response [PMID:14715956]. The site lies in the alternatively spliced fibronectin type III repeat D of tenascin-C [PMID:14715956].","affinity_potency":[],"species_and_systems":"Human tenascin-C peptides; cerebellar granule neurons [PMID:14715956].","localisation_and_range":"Ligand flagged as secreted, non-transmembrane [flag]; presented as extracellular matrix, so acts locally on adjacent cells.","caveats":"Abstract-only read. Evidence concerns a peptide motif from a spliced repeat, not full-length TNC. The mutant peptide VSPNGSLK did not bind [PMID:14715956].","key_references":[{"PMID":"14715956","why":"alpha7beta1 binds VFDNFVLK of tenascin-C fnD"}],"covers":["LR001485","LR004880"]},"LR008532":{"pair":"TNC -> ITGA9:ITGB1","headline":"UniProt and Reactome record alpha9beta1 binding TNC; no verified paper in our dossier.","interaction_type":"database-asserted only","direction_and_effect":"No curator-verified paper (outcomes: abstract_insufficient, different_entity, review_only) [outcome_counts]. UniProt states ITGA9:ITGB1 interacts with TNC via its 3rd fibronectin type III domain [DB:UniProt]; Reactome lists an alpha9beta1:tenascin-C hexamer [DB:Reactome].","molecular_requirements":"Complex ITGA9:ITGB1 [flag]; TNC third fibronectin type III domain involved [DB:UniProt].","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Database-only here; no paper-level evidence for the heterodimer row in our evidence.","key_references":[],"covers":["LR008532"]},"LR006615":{"pair":"TNFRSF1B -> IL17RD","headline":"TNFR2 forms a signalling heteromer with IL-17RD in one abstract-level paper; receptor-receptor, not a classic ligand-receptor pair.","interaction_type":"functional only","direction_and_effect":"TNFR2 but not TNFR1 forms a heteromer with IL-17RD (Sef). The association causes mutual receptor aggregation and TRAF2 recruitment and activates NF-kappaB; IL-17RD depletion impaired TNFR2-mediated NF-kappaB activation [PMID:25378394].","molecular_requirements":"TNFR1 does not form this heteromer [PMID:25378394]. TRAF2 recruitment is part of the signalling cascade [PMID:25378394].","affinity_potency":[],"species_and_systems":"Human proteins as recorded; the abstract also reports increased IL-17RD and a strong TNFR2-IL-17RD interaction in renal epithelia of nephritis rats [PMID:25378394]. The mouse pair is projected from human evidence.","localisation_and_range":"TNFR2 is flagged secreted and transmembrane [flag]; IL-17RD has no localisation flag in the dossier.","caveats":"Single paper, read as an abstract only; no database records. The abstract does not name a binding assay, and which partner acts as ligand is not reported in our evidence [PMID:25378394].","key_references":[{"PMID":"25378394","why":"TNFR2-IL-17RD heteromer and NF-kappaB activation"}],"covers":["LR003414","LR006615"]},"LR001494":{"pair":"TNFSF10 -> TNFRSF10C","headline":"TRAIL-R3 (TNFRSF10C) binds TRAIL with high affinity but lacks a death domain; it acts as a decoy.","interaction_type":"direct binding","direction_and_effect":"Quantitative binding studies show TRAIL-R3 is a plasma membrane protein capable of high-affinity interaction with TRAIL; it does not induce apoptosis on overexpression [PMID:9314565]. By competing for TRAIL it can inhibit TRAIL-induced apoptosis, so it may be an antagonistic decoy receptor [PMID:9325248].","molecular_requirements":"TRAIL-R3 lacks a cytoplasmic domain and appears to be GPI-linked [PMID:9314565]. Co-receptor requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human proteins; transient expression in cells [PMID:9314565]. Database records: IntAct surface plasmon resonance and solid phase assay [DB:IntAct], UniProt [DB:UniProt]. Expression is restricted to peripheral blood lymphocytes and spleen in the transcripts studied [PMID:9314565].","localisation_and_range":"Membrane-bound (GPI-linked, per paper) [PMID:9314565]; TRAIL is flagged secreted and transmembrane [flag].","caveats":"The affinity is described as high but no value appears in our evidence. Both papers were read as abstracts, and the decoy function is stated as a suggestion [PMID:9325248].","key_references":[{"PMID":"9314565","why":"Cloning and TRAIL binding of TRAIL-R3"},{"PMID":"9325248","why":"Describes TRAIL-R3 as an antagonistic decoy"}],"covers":["LR001494"]},"LR009036":{"pair":"TREM2 -> SEMA6D","headline":"Database-asserted only: Reactome has SEMA6D binding a PLXNA1:TREM2:DAP12 complex; no curated paper evidence and the direction is reversed.","interaction_type":"database-asserted only","direction_and_effect":"Reactome has SEMA6D binding to the PLXNA1:TREM2:DAP12 complex [DB:Reactome R-HSA-416725]. UniProt says SEMA6D signals through TYROBP in dendritic cells with PLEXNA1 as coreceptor, upregulating CCR7 and promoting maturation and survival [DB:UniProt].","molecular_requirements":"PLXNA1 and TREM2 with DAP12 (TYROBP) in the complex [DB:Reactome R-HSA-416720]; TREM2 alone not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experimental system not reported in our evidence beyond dendritic cells in the UniProt text.","localisation_and_range":"SEMA6D is flagged transmembrane and not secreted [flag]; TREM2 flagged secreted and receptor [flag].","caveats":"No papers were judged (both rows pending). In the database SEMA6D is the ligand and TREM2 part of the receptor, opposite to this pair's stated direction.","key_references":[],"covers":["LR009036"]},"LR004905":{"pair":"TRH -> TRHR","headline":"TRH activates the TRH receptor in expression cloning, COS-1, and HEK293 assays; multiple papers, a classic agonist GPCR pair.","interaction_type":"direct binding","direction_and_effect":"Agonist: TRH stimulated inositol phosphate formation in COS-1 cells expressing the cloned receptor [PMID:2175902]; in HEK293 cells TRHR-Timer gave an 11-fold increase in inositol phosphate formation, increased intracellular free calcium and internalization of 75% of bound [3H][N3-methyl-His2]TRH within 10 min [PMID:15117874]. The TRH-TRHR complex and G11alpha both internalise in clathrin-coated vesicles [PMID:9794253].","molecular_requirements":"Single GPCR; couples to Gq/11, with G11alpha co-internalised [PMID:9794253].","affinity_potency":[],"species_and_systems":"Mouse pituitary receptor cDNA in Xenopus oocytes and COS-1 cells [PMID:2175902]; HEK293 cells [PMID:15117874]; cell system for the third paper not stated in the abstract. Human and mouse pairs are ortholog-inferred.","localisation_and_range":"TRH flagged secreted and not transmembrane; TRHR transmembrane [flag]; secreted peptide acting on a cell surface receptor.","caveats":"All three papers were read as abstracts. The oocyte paper reports 'appropriate affinities' without a value [PMID:2175902]. Two papers concern receptor trafficking rather than binding.","key_references":[{"PMID":"2175902","why":"Expression cloning of the mouse TRH receptor"},{"PMID":"15117874","why":"TRH-induced inositol phosphate, calcium and internalisation in HEK293"},{"PMID":"9794253","why":"Co-internalisation of TRH-TRHR and G11alpha"}],"covers":["LR001515","LR004905"]},"LR006624":{"pair":"TSKU -> FZD4","headline":"Tsukushi binds the cysteine-rich domain of Fzd4 with 2.3 x 10-10 M and competes with Wnt2b; well supported inhibitor.","interaction_type":"direct binding","direction_and_effect":"Antagonist/Wnt inhibitor: TSK binds directly to the cysteine-rich domain of Fzd4 and competes with Wnt2b; TSK overexpression antagonized Wnt2b signaling in chicken embryonic retinal cells and repressed Wnt-dependent peripheral eye fates; TSK knockout mice had ciliary body expansion and up-regulated Wnt2b and Fzd4 [PMID:21856951]. UniProt agrees [DB:UniProt].","molecular_requirements":"Fzd4 cysteine-rich domain is the binding site [PMID:21856951]; LRP5/6 requirement not reported in our evidence.","affinity_potency":[{"value":"2.3 x 10-10 M","assay":"direct binding to Fzd4 cysteine-rich domain","system":"not specified in abstract","cite":"PMID:21856951"}],"species_and_systems":"Chick eye in vivo and in vitro, mouse knockout [PMID:21856951]. Human pair is ortholog-inferred.","localisation_and_range":"Secreted protein expressed in the ciliary/iris epithelium acting on the adjacent optic vesicle rim, so short-range paracrine [PMID:21856951].","caveats":"Abstract read only; assay system for the Kd is not specified.","key_references":[{"PMID":"21856951","why":"TSK-Fzd4 binding and Wnt2b competition in eye development"}],"covers":["LR003423","LR006624"]},"LR005355":{"pair":"TSLP -> CRLF2","headline":"TSLP binds CRLF2 as a heterodimer with IL7R (background statement); supported by GtoPdb, PDB and Reactome.","interaction_type":"direct binding","direction_and_effect":"Agonist: CRLF2 binds TSLP as a heterodimer with IL7R [PMID:22915648]; GtoPdb lists Agonist [DB:GtoPdb]. The paper's own results concern CRLF2 mutant signalling in B-ALL, not ligand binding.","molecular_requirements":"IL7R is a partner; CRLF2 signalling needs the box1 domain and tryptophan W286, and Y368 for the CRLF2 F232C mutant [PMID:22915648]. PDB structures show TSLP, TSLPR and IL-7Ralpha complexes [DB:PDB 5J11].","affinity_potency":[],"species_and_systems":"B-cell acute lymphoblastic leukemia cell models [PMID:22915648]; structures [DB:PDB 5J11].","localisation_and_range":"TSLP is flagged secreted, CRLF2 transmembrane [flag]; TSLP is a secreted cytokine.","caveats":"The curated sentence is a background statement of the paper, not a new result. Abstract-level evidence; one further paper was review_only. CRLF2 alone binding strength not reported in our evidence.","key_references":[{"PMID":"22915648","why":"CRLF2 signalling requirements in B-ALL; TSLP heterodimer receptor stated"}],"covers":["LR002027","LR005355"]},"LR011844":{"pair":"TSLP -> CRLF2:IL7R:TSLP","headline":"Database-asserted only: Reactome, PDB and UniProt describe a TSLP:CRLF2:IL7R ternary complex; the receptor here already contains TSLP.","interaction_type":"database-asserted only","direction_and_effect":"Reactome has the IL7R:TSLP:CRLF2 complex at the plasma membrane [DB:Reactome R-HSA-8982872]; GtoPdb lists TSLP-CRLF2 and TSLP-IL7R as Agonist [DB:GtoPdb]. UniProt: CRLF2 is a receptor for TSLP [DB:UniProt].","molecular_requirements":"CRLF2, IL7R and TSLP together form the complex; a structure of human TSLP with TSLPR and IL-7Ralpha is deposited [DB:PDB 5J11].","affinity_potency":[],"species_and_systems":"X-ray structures, one with mouse IL-7Ralpha [DB:PDB 5J12]; no curated papers.","localisation_and_range":"TSLP flagged secreted [flag].","caveats":"No papers judged (pending). The 'receptor' entity includes the ligand itself, so it is a ternary complex, not a receptor.","key_references":[],"covers":["LR011844"]},"LR003429":{"pair":"UNC5A -> FLRT1","headline":"UNC5A and FLRT1 bind strongly in a high-throughput extracellular screen; direction and signalling effect for this pair are not shown.","interaction_type":"direct binding","direction_and_effect":"Direction is not determined: binding is reciprocal between proteins that are both cell-surface, and the paper reports neurite attraction/repulsion for FLRT1 stripes (16% attractive, 5% repulsive of 375) but not for UNC5A [PMID:26633812].","molecular_requirements":"Not reported in our evidence beyond the pairing itself; all 12 FLRT1-3 and Unc5A-D combinations bound in the screen [PMID:26633812].","affinity_potency":[],"species_and_systems":"Extracellular biochemical screen with purified proteins in an ELISA format (mean Abs650nm value = 2.14, near saturation) and mouse retina context; species of recombinant proteins not reported in the excerpts [PMID:26633812]. The mouse pair is direct; the human pair is ortholog-inferred.","localisation_and_range":"Both partners are annotated transmembrane [flag]; the paper tested trans interaction between opposing cell surfaces in aggregation assays [PMID:26633812]. FLRT1 also carries a secreted flag [flag].","caveats":"Single paper, full text. Binding is semi-quantitative with a saturated signal; no Kd is given in our evidence. Prior literature described some FLRT-Unc5 pairs, but this pair was among the eight reported as new [PMID:26633812].","key_references":[{"PMID":"26633812","why":"Screen reporting binding of all FLRT-Unc5 pairs"}],"covers":["LR003429","LR006630"]},"LR003438":{"pair":"UNC5C -> FLRT3","headline":"Extracellular binding of UNC5C and FLRT3 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5C is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5C stripes repelled 11% of neurons (n=45/396), but FLRT3 was not expressed by Unc5C-repelled neurons in the data shown [PMID:26633812]. UniProt records the extracellular-domain interaction by similarity [DB:UniProt].","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003438","LR006639"]},"LR006642":{"pair":"UNC5D -> FLRT3","headline":"Extracellular binding of UNC5D and FLRT3 shown in a mouse-protein screen; one full-text paper, no affinity.","interaction_type":"direct binding","direction_and_effect":"Binding was seen in an ELISA-based screen with AP/Fc-tagged extracellular domains, with every FLRT1-3 x Unc5A-D pair reported at or near saturation (mean Abs650nm value = 2.14) [PMID:26633812]. Titration with purified protein and CHO.K1 cell aggregation confirmed the family pairs [PMID:26633812]. In this paper Unc5-expressing neurons are repelled by FLRT, so FLRT acts as ligand and Unc5 as receptor, the reverse of the listed direction [PMID:26633812]. ","molecular_requirements":"Extracellular domains of both partners are used; no co-receptor or extra subunit is reported in our evidence.","affinity_potency":[],"species_and_systems":"Mouse proteins in recombinant ELISA and cell-aggregation assays; the human pair is ortholog-inferred and the mouse pair is the direct one [PMID:26633812].","localisation_and_range":"UNC5D is annotated as a transmembrane receptor and FLRT3 as both secreted and transmembrane [flag]; contact-mediated signalling is likely, but this is not tested here.","caveats":"The binding statement is family-wide rather than specific to this pair. Pair-specific functional data are absent. Unc5D stripes repelled 12% of neurons (n=49/407) [PMID:26633812]. UniProt records the extracellular-domain interaction [DB:UniProt]. The 2011 EMBO J abstract in the sibling dossier describes Unc5D as binding specifically to FLRT2, which sits in some tension with this pair.","key_references":[{"PMID":"26633812","why":"Extracellular screen and titration binding of all FLRT x Unc5 pairs, mouse proteins"}],"covers":["LR003441","LR006642"]},"LR004914":{"pair":"UTS2B -> UTS2R","headline":"URP (UTS2B) binds and activates the UT receptor; three curator-confirmed papers, all read as abstracts only.","interaction_type":"direct binding","direction_and_effect":"URP is an agonist: it binds and activates human or rat UII receptors (GPR14) and lowers blood pressure in anaesthetised rats [PMID:14550283][PMID:17628210]. In mouse, URP and UII(17) were equally potent in calcium mobilisation at the UT receptor [PMID:18710417]. GtoPdb lists it as a full agonist [DB:GtoPdb].","molecular_requirements":"Single receptor chain (UT receptor/GPR14); no co-receptor or subunit requirement reported in our evidence.","affinity_potency":[{"value":"pIC50 8.6","assay":"curator-recorded affinity; abstract does not state the value","system":"URP on human/rat UII receptors","cite":"PMID:14550283"},{"value":"pKd 9.6","assay":"curator-recorded affinity; abstract does not state the value","system":"human UT receptor","cite":"PMID:17628210"}],"species_and_systems":"Rat-derived URP on human or rat receptors, with in vivo rat blood pressure [PMID:14550283]; human ligand and receptor [PMID:17628210]; mouse calcium assays [PMID:18710417]. The mouse pair is ortholog-inferred from human evidence.","localisation_and_range":"Secreted peptide acting on a transmembrane receptor (entity flags) [flag]; tissue expression of URP and UT mRNA reported in mouse [PMID:18710417].","caveats":"All three papers were read as abstracts only. Affinity values are curator-recorded and not seen in abstract text. BioGRID lists a reconstituted complex [DB:BioGRID].","key_references":[{"PMID":"14550283","why":"URP isolated from rat brain; binds and activates UII receptors"},{"PMID":"17628210","why":"URP binds and activates human UT receptor"},{"PMID":"18710417","why":"UII and URP equipotent at mouse UT receptor"}],"covers":["LR001525","LR004914"]},"LR004923":{"pair":"VCAN -> ITGB1","headline":"Beta1 integrin pulled down with the versican C-terminal domain in glioma cells; one abstract-level paper.","interaction_type":"direct binding","direction_and_effect":"beta(1)-integrin bound the C-terminal domain of PG-M/versican; the interaction activated focal adhesion kinase, enhanced integrin expression and promoted cell adhesion [PMID:11805102].","molecular_requirements":"Calcium- and manganese-dependent; the used peptide has no RGD motif; alpha partner not reported in our evidence [PMID:11805102].","affinity_potency":[],"species_and_systems":"Pull-down, immunoprecipitation and cell-surface binding in glioma cells; species not stated in the curated row [PMID:11805102]. Mouse pair is ortholog-inferred.","localisation_and_range":"Versican flagged secreted [flag].","caveats":"Abstract only; only the C-terminal domain was tested, not full-length versican. No database records.","key_references":[{"PMID":"11805102","why":"beta1 integrin binds versican C-terminal domain"}],"covers":["LR001534","LR004923"]},"LR001539":{"pair":"VEGFA -> ITGA9","headline":"VEGF-A is a direct ligand of integrin alpha9beta1, supported by one abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Adhesion and migration of human endothelial cells on VEGF-A depend on alpha9beta1, and an alpha9beta1-blocking antibody inhibited VEGF-A165- or -121-induced angiogenesis [PMID:17363377].","molecular_requirements":"Cooperative input from alpha9beta1 and VEGF-R2 is needed for adhesion and migration; the beta1 partner is part of the receptor. Unlike alpha3beta1 or alphavbeta3, alpha9beta1 also binds the 121 isoform [PMID:17363377].","affinity_potency":[],"species_and_systems":"Human endothelial cells and human VEGF-A [PMID:17363377].","localisation_and_range":"Not reported in our evidence.","caveats":"Single paper read as abstract only; no affinity reported. Function requires VEGFR-2 as well [PMID:17363377].","key_references":[{"PMID":"17363377","why":"VEGF-A direct ligand of alpha9beta1"}],"covers":["LR001539","LR004928"]},"LR004932":{"pair":"VEGFA -> NRP2","headline":"VEGF165 binds neuropilin-2 with high affinity in a heparin-dependent way; NRP2 also complexes with VEGFR-2.","interaction_type":"direct binding","direction_and_effect":"Both np-2 splice forms bind VEGF165 but not VEGF121 [PMID:10748121]. VEGF-A induces NRP2 interaction with VEGFR-2, enhancing VEGFR-2 phosphorylation and cell survival [PMID:16621967].","molecular_requirements":"Heparin is needed for high-affinity VEGF165 binding to np-2 [PMID:10748121]; VEGFR-2 forms a complex with NRP2 [PMID:16621967].","affinity_potency":[{"value":"KD 1.3 x 10(-10) M","assay":"binding of VEGF165 to np-2 in presence of heparin","system":"HUVEC-expressed np-2 a17/a22 splice forms","cite":"PMID:10748121"}],"species_and_systems":"Human endothelial cells [PMID:10748121, PMID:16621967]; a PDB structure exists [DB:PDB 5DN2].","localisation_and_range":"Not reported in our evidence.","caveats":"Two shown papers, abstract-level; the binding paper also reports VEGF145 with KD 7e-10 M. VEGF121 does not bind.","key_references":[{"PMID":"10748121","why":"VEGF165 binding and KD for neuropilin-2"},{"PMID":"16621967","why":"VEGF-A induced NRP2/VEGFR-2 interaction"}],"covers":["LR001543","LR004932"]},"LR007443":{"pair":"VEGFB -> FLT1:KDR","headline":"Complex-level row with no paper support; evidence is database records for FLT1 alone.","interaction_type":"database-asserted only","direction_and_effect":"No papers support this complex row. Database records describe VEGFB binding FLT1, and UniProt states that KDR interacts with VEGFA, VEGFB and PGF [DB:UniProt].","molecular_requirements":"The row requires both FLT1 and KDR as a complex. Our evidence shows VEGFB with FLT1 only [DB:BioGRID] [DB:PDB 2XAC]; a heterodimer requirement is not shown. Both members are flagged receptors and transmembrane [flag].","affinity_potency":[],"species_and_systems":"Species and experimental systems not reported in our evidence beyond the human database records. Curator judgements for this row were 'different_entity'.","localisation_and_range":"Both members flagged transmembrane receptors; the ligand is flagged secreted [flag].","caveats":"Zero papers judged for the complex. The PDB structure 2XAC is of VEGFB with FLT1 (P49765 and P17948) [DB:PDB 2XAC], and Reactome describes VEGFA,B,PLGF binding VEGFR1 [DB:Reactome]. A user scoring this complex by its least-expressed subunit should note that the evidence concerns FLT1 alone. UniProt FUNCTION text on P17948 names VEGFB [DB:UniProt].","key_references":[],"covers":["LR007443"]},"LR001548":{"pair":"VEGFC -> ITGB1","headline":"VEGF-C binds alpha9beta1 integrin; ITGB1 is credited only as a chain of this heterodimer, from a single paper.","interaction_type":"direct binding","direction_and_effect":"Recombinant VEGF-C bound purified alpha9beta1 integrin; adhesion and migration on VEGF-C were alpha9beta1-dependent in mouse embryonic fibroblasts, SW-480 cells and microvascular endothelial cells [PMID:15590642].","molecular_requirements":"ITGB1 alone is not tested; the paired alpha9 chain (ITGA9) is required by the evidence, which concerns the alpha9beta1 heterodimer [PMID:15590642].","affinity_potency":[],"species_and_systems":"Recombinant protein plus cell adhesion assays, species of the cells as stated above [PMID:15590642]. Interactions are ortholog-inferred.","localisation_and_range":"VEGFC flagged secreted and ITGB1 not flagged secreted [flag].","caveats":"Chain-only evidence: ITGB1 appears because it pairs with alpha9; beta1 pairs with many alpha chains, so this row may overstate specificity. Single abstract-read paper; no affinity.","key_references":[{"PMID":"15590642","why":"VEGF-C binds alpha9beta1 integrin"}],"covers":["LR001548","LR004937"]},"LR000648":{"pair":"VEGFD -> FLT4","headline":"VEGF-D is a dual VEGFR-2/VEGFR-3 ligand needing proteolytic processing; two abstract-level papers plus database records.","interaction_type":"direct binding","direction_and_effect":"VEGF-D is a ligand for both VEGFR-2 and VEGFR-3 and can activate these receptors [PMID:9435229]. Residues between the reported proteolytic cleavage sites are important for VEGF-D binding and activation of VEGFR-3, but not of VEGFR-2 [PMID:21148085].","molecular_requirements":"VEGF-D is produced as a precursor with propeptides; proteolytic removal enhances VEGFR-2/VEGFR-3 binding [PMID:21148085]. It does not bind VEGFR-1 [PMID:9435229].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, recombinant binding and functional assays; abstract-level reading [PMID:21148085] [PMID:9435229]. Mouse pair is ortholog-inferred.","localisation_and_range":"VEGFD flagged secreted [flag].","caveats":"Affinity not reported in our evidence. BioGRID reconstituted-complex records [DB:BioGRID] and Reactome binding reaction [DB:Reactome]. Two review-only rows and one pending are not shown.","key_references":[{"PMID":"9435229","why":"VEGF-D identified as VEGFR-2/VEGFR-3 ligand"},{"PMID":"21148085","why":"structure and processing requirements of VEGF-D"}],"covers":["LR000648","LR004132"]},"LR004941":{"pair":"VIP -> ADCYAP1R1","headline":"VIP is a lower-affinity, agonist ligand of the PAC1 receptor, well below PACAP; supported by two human recombinant studies and database records.","interaction_type":"direct binding","direction_and_effect":"VIP acts as an agonist at human PAC1 in CHO cells, with cAMP and calcium readouts [PMID:16930633]. GtoPdb lists it as agonist [DB:GtoPdb].","molecular_requirements":"Splice-variant dependent: PAC1n bound VIP with up to 400-fold lower affinity than PACAP, PAC1vs bound VIP with Ki>1000 nM, whereas PAC1s bound all three ligands with high affinity; residues 53-88 of the N-terminus matter for ligand selectivity [PMID:10583729].","affinity_potency":[{"value":"pEC50 8.7","assay":"binding/cAMP in PAC1-variant cells (curator-recorded)","system":"transfected HEK293, human","cite":"PMID:10583729"},{"value":"pEC50 7.8","assay":"cAMP","system":"CHO cells expressing human PAC1","cite":"PMID:16930633"}],"species_and_systems":"Human receptor variants in HEK293 [PMID:10583729] and CHO cells [PMID:16930633].","localisation_and_range":"VIP is flagged secreted and PAC1 transmembrane [flag]; paracrine or endocrine action is implied by the flags only.","caveats":"Both papers read as abstracts only. Potency differs by receptor splice variant, so expression of the PAC1 isoform matters. Calcium EC50 values run about 100-fold higher than cAMP [PMID:16930633]. PDB structures (9P92, 9P93) contain both chains [DB:PDB 9P92]. Mouse pair is projected from human.","key_references":[{"PMID":"10583729","why":"VIP affinity depends on PAC1 splice variant"},{"PMID":"16930633","why":"VIP potency at PAC1 in cAMP and calcium assays"}],"covers":["LR001552","LR004941"]},"LR003447":{"pair":"VTCN1 -> BTLA","headline":"Thin evidence: one abstract-only paper states B7x is a ligand of BTLA; no binding data in our evidence.","interaction_type":"functional only","direction_and_effect":"The abstract states B7x is a ligand of BTLA, an inhibitory receptor with two ITIMs that recruits SHP-1/SHP-2 and attenuates IL-2 [PMID:12796776]. Whether the interaction is activating or inhibitory is not reported in our evidence beyond BTLA being inhibitory.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Species not specified by the curated row [PMID:12796776]; mouse pair is annotated as non-inferred and human as ortholog-inferred.","localisation_and_range":"Neither partner is flagged secreted; BTLA transmembrane [flag].","caveats":"Single abstract sentence; no binding assay, affinity or subunit detail. The dossier uses 'B7x' and does not itself state it equals VTCN1.","key_references":[{"PMID":"12796776","why":"Identifies BTLA and reports B7x as its ligand"}],"covers":["LR003447","LR006648"]},"LR001557":{"pair":"VTN -> ITGA2B","headline":"Vitronectin binds activated human platelets through the GPIIb/IIIa complex; one abstract-only paper with a measured Kd.","interaction_type":"direct binding","direction_and_effect":"Purified vitronectin bound thrombin-stimulated human platelets in a calcium-dependent, specific, saturable manner; binding was inhibited by the RGDS tetrapeptide and anti-GPIIb/IIIa antibodies, and anti-vitronectin antibodies inhibited platelet aggregation [PMID:1692034]. Database records also list the pair [DB:BioGRID] [DB:Reactome].","molecular_requirements":"The receptor in the paper is the GPIIb/IIIa complex, so ITGA2B alone is not shown to suffice; the partner chain (ITGB3) is likely needed but the paper tests the complex, not the chain [PMID:1692034]. Affinity depends on platelet activation state.","affinity_potency":[{"value":"Kd 320 nM","assay":"binding of purified vitronectin to platelets, 8,000 sites per platelet","system":"thrombin-stimulated human platelets","cite":"PMID:1692034"},{"value":"Kd 93 and 116 nM","assay":"binding to platelets","system":"epinephrine- or ADP-stimulated human platelets","cite":"PMID:1692034"}],"species_and_systems":"Human ligand and human platelets [PMID:1692034]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Single paper read as abstract only. Affinity varies with the activator used (320 nM versus 93 and 116 nM) [PMID:1692034]. Reactome and BioGRID entries are database assertions.","key_references":[{"PMID":"1692034","why":"Kd and RGD/antibody inhibition of vitronectin binding to stimulated platelets"}],"covers":["LR001557","LR004946"]},"LR010782":{"pair":"VTN -> ITGAV:ITGB8","headline":"No paper supports this pair; database assertion only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence. Reactome lists vitronectin binding to alphaVbeta3, alphaVbeta5 and alphaVbeta8 [DB:Reactome]; IntAct records a solid phase assay [DB:IntAct].","molecular_requirements":"Two-chain complex ITGAV with ITGB8; requirements not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Vitronectin is flagged as secreted and the complex as transmembrane [flag].","caveats":"No verified papers; the single judged abstract was insufficient. Support is purely from curated databases [DB:Reactome] [DB:IntAct].","key_references":[],"covers":["LR010782"]},"LR004950":{"pair":"VTN -> ITGB1","headline":"Beta1 appears only as the partner chain of alpha8beta1 in a single abstract-only paper.","interaction_type":"direct binding","direction_and_effect":"Alpha8beta1 bound vitronectin-Sepharose, eluted by GRGDSP, and supported adhesion of alpha8-transfected 293 cells [PMID:7559467]. Reactome lists vitronectin binding to alphaVbeta1 among others [DB:Reactome].","molecular_requirements":"ITGB1 is shown only as part of a heterodimer with alpha8; chain-only evidence for beta1 is not available [PMID:7559467].","affinity_potency":[],"species_and_systems":"Human 293 cells and extracts; mouse pair is ortholog-inferred [PMID:7559467].","localisation_and_range":"Vitronectin is flagged as secreted and not transmembrane [flag]; the integrin is a membrane receptor, so signalling is by cell contact with soluble or matrix-bound ligand. The dossier's papers do not describe range further.","caveats":"Chain-only entry: the evidence is for alpha8beta1, not beta1 alone. Abstract only; no affinity. One further abstract was insufficient.","key_references":[{"PMID":"7559467","why":"alpha8beta1 binds vitronectin, supports the beta1 partner"}],"covers":["LR001561","LR004950"]},"LR001566":{"pair":"VTN -> PLAUR","headline":"Vitronectin binds uPAR (PLAUR) on its SMB domain; supported by one abstract-only paper and crystal structures.","interaction_type":"direct binding","direction_and_effect":"uPAR and PAI-1 bind the same site in vitronectin (the amino-terminal somatomedin B domain), and PAI-1 competes with uPAR for SMB binding; PAI-1 dissociates bound VN from uPAR and detaches U937 cells from VN [PMID:8830783]. The paper's curated effect label is agonist.","molecular_requirements":"The uPAR-binding sequence lies in the central region of the SMB domain [PMID:8830783]. Co-receptor or subunit requirements are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human ligand and receptor; U937 cells and domain-swapping/mutagenesis studies [PMID:8830783]. The mouse pair is ortholog-inferred, not tested. Structures of the complex are listed [DB:PDB 3BT1] [DB:PDB 3BT2] [DB:PDB 4K24], with an X-ray record [DB:IntAct].","localisation_and_range":"Vitronectin is flagged secreted and uPAR is flagged secreted, receptor and transmembrane [flag]; vitronectin acts as a matrix substrate for adhesion [PMID:8830783].","caveats":"The paper was read as abstract only. Binding is competed by PAI-1, so PAI-1 levels may change signalling. No affinity is reported in our evidence.","key_references":[{"PMID":"8830783","why":"uPAR and PAI-1 share the SMB binding site on vitronectin"}],"covers":["LR001566","LR004955"]},"LR006651":{"pair":"VWF -> GP9","headline":"GP9 is supported only through the GPIb-IX complex; the one paper concerns GPIbbeta phosphorylation.","interaction_type":"functional only","direction_and_effect":"In CHO cells expressing GPIb-IX, PKA inhibitor PKI reduced Ser166 phosphorylation of GPIbbeta and enhanced VWF binding; the S166A and Delta165 mutants showed enhanced VWF binding and adhesion under flow [PMID:12361948].","molecular_requirements":"The paper studies the whole GPIb-IX complex and the GPIbbeta chain, not GP9 specifically [PMID:12361948]; the pair rests on complex-level evidence. Reactome lists GPIb:IX:V with VWF multimer [DB:Reactome].","affinity_potency":[],"species_and_systems":"CHO cells and human platelets [PMID:12361948]. Mouse pair is ortholog-inferred.","localisation_and_range":"Not reported in our evidence.","caveats":"Abstract-only read. The paper does not test GP9 alone, and the signal is on GPIbbeta regulation, so this is chain-level inference rather than direct GP9 binding.","key_references":[{"PMID":"12361948","why":"PKA phosphorylation of GPIbbeta regulates VWF binding to GPIb-IX"}],"covers":["LR003451","LR006651"]},"LR008514":{"pair":"VWF -> ITGA2B:ITGB3","headline":"VWF engages alphaIIbbeta3 through its RGDS site; one abstract-only paper that names platelets, not the integrin.","interaction_type":"functional only","direction_and_effect":"RADS and RGES mutants of vWF were unable to displace 125I-vWF from activated platelets, and HUVEC attachment to the mutants was reduced and spreading almost completely inhibited [PMID:1737795]. Curated effect is stimulatory.","molecular_requirements":"The RGDS sequence is required [PMID:1737795]. Both integrin chains are the complex; the paper names platelets rather than the integrin, so the assignment is inferred.","affinity_potency":[],"species_and_systems":"Human platelets and HUVEC with CHO-expressed recombinant vWF [PMID:1737795]. Database records of alphaIIbbeta3:VWF are listed [DB:Reactome] [DB:IntAct].","localisation_and_range":"The receptor complex is flagged transmembrane [flag].","caveats":"Abstract-only; curators rate receptor assignment medium confidence. No affinity reported.","key_references":[{"PMID":"1737795","why":"RGDS site of vWF needed for platelet GPIIb/IIIa binding"}],"covers":["LR008514"]},"LR003456":{"pair":"VWF -> ITGB3","headline":"Endothelial cells adhere to VWF via beta3 integrins (alphavbeta3, GPIIb/IIIa); three confirmed abstract-only papers, functional.","interaction_type":"functional only","direction_and_effect":"Anti-beta3 antibodies fully blocked endothelial cell adhesion to vWF and detached seeded cells; anti-beta1 antibodies were poorly active [PMID:2545728]. An RGDS peptide or anti-alphavbeta3 antibody reduced VWF strings on HUVEC [PMID:18927433]. RGDS mutants of vWF lost binding to activated platelets [PMID:1737795]. Curated effect is stimulatory.","molecular_requirements":"beta3 pairs with alphav or alphaIIb; the papers do not isolate beta3 alone. RGDS is required [PMID:1737795].","affinity_potency":[],"species_and_systems":"Human endothelial cells, platelets and recombinant vWF from CHO cells [PMID:2545728] [PMID:1737795] [PMID:18927433]. Mouse pair is ortholog-inferred. IntAct and Reactome records exist [DB:IntAct] [DB:Reactome].","localisation_and_range":"Not reported in our evidence.","caveats":"All three papers are abstract-only; antibody and peptide blocking, not direct binding. Evidence is at complex level. One further paper was abstract_insufficient.","key_references":[{"PMID":"2545728","why":"anti-beta3 antibodies block endothelial adhesion to vWF"},{"PMID":"18927433","why":"alphavbeta3 anchors VWF strings"},{"PMID":"1737795","why":"RGDS mutation impairs platelet GPIIb/IIIa binding"}],"covers":["LR003456","LR006656"]},"LR006660":{"pair":"WFIKKN2 -> IGDCC3","headline":"WFIKKN2 binds IGDCC3 (PUNC) by SPR on recombinant proteins; an axon-guidance paper also names it as a ligand, from abstract only.","interaction_type":"direct binding","direction_and_effect":"WFIKKN2 ECD-Fc and PUNC analyte-Fc were observed in the apECIA screen and listed as SPR-validated [PMID:32822567]. A preprint reports WFIKKN2 as a secreted ligand of Punc, Nope and Prtg that guides axons; the Punc-specific role is not delineated in the abstract [PMID:37398498].","molecular_requirements":"Not reported in our evidence; the SPR work used ECD-Fc fusions of the extracellular domains [PMID:32822567].","affinity_potency":[],"species_and_systems":"Binding: recombinant human ECD-Fc proteins, SPR and apECIA [PMID:32822567]. Axon-guidance work was in mouse axons; the dossier lists human proteins for the pair [PMID:37398498].","localisation_and_range":"WFIKKN2 is flagged secreted [flag]; the receptor is flagged as a receptor [flag].","caveats":"No affinity values for this pair are given in our evidence. The functional paper was read as abstract only and its Nope-mediated repulsion result concerns a different receptor [PMID:37398498].","key_references":[{"PMID":"32822567","why":"SPR-validated binding of WFIKKN2 to PUNC in a cell-surface interactome screen"},{"PMID":"37398498","why":"WFIKKN2 as axon guidance ligand for Punc/Nope/Prtg (abstract only)"}],"covers":["LR003460","LR006660"]},"LR008622":{"pair":"WIF1 -> WNT1","headline":"WIF1-WNT1 rests on a single BioGRID affinity-capture record; no curated paper evidence.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence; the BioGRID record gives no direction or effect.","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"BioGRID lists a WIF1-WNT1 Affinity Capture-Western record; species and system are not stated [DB:BioGRID].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane; WIF1 is flagged non-receptor and non-transmembrane [flag]. This looks like a secreted-secreted binding pair rather than a receptor interaction.","caveats":"Database assertion only; no papers were verified (all judged rows abstract_insufficient). WIF1 is flagged as not a receptor, so a classical ligand-receptor reading is doubtful [flag].","key_references":[],"covers":["LR008622"]},"LR008127":{"pair":"WNT1 -> FZD2:LRP5","headline":"WNT1 to FZD2:LRP5 is supported only by the FZD2 rescue result from one paper plus a UniProt LRP5 note.","interaction_type":"functional only","direction_and_effect":"FZD2 or FZD7 expression rescued Wnt1-dependent reporter activity in HEK293T FZD-knockout cells [PMID:28733458].","molecular_requirements":"The result concerns FZD2 alone; LRP5 involvement is not tested in our evidence. UniProt notes an LRP5 interaction enhanced by WNT1 or WNT3A [DB:UniProt].","affinity_potency":[],"species_and_systems":"HEK293T FZD-knockout reporter cells [PMID:28733458].","localisation_and_range":"WNT1 is flagged secreted and non-transmembrane [flag]; the receptor is flagged as a receptor [flag], so signalling is presumably paracrine, but range is not reported in our evidence.","caveats":"The paper supports the FZD2 half only; the complex is inferred. Other rows were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"FZD2 rescues Wnt1 reporter activity"}],"covers":["LR008127"]},"LR001575":{"pair":"WNT1 -> FZD7","headline":"WNT1 acts through FZD7 in a functional rescue assay in human cells; no direct binding is shown.","interaction_type":"functional only","direction_and_effect":"FZD2 or FZD7 each rescued Wnt1- and Wnt3-dependent TCF4/Wnt reporter activity in FZD-knockout cells, so WNT1 signals through FZD7 to canonical beta-catenin signalling [PMID:28733458].","molecular_requirements":"FZD7 alone rescued Wnt1 signalling, though FZD2 did too, so FZD7 is sufficient but not unique [PMID:28733458]. LRP co-receptor requirement was not tested in the excerpts.","affinity_potency":[],"species_and_systems":"Human HEK293T cells with multiplex CRISPR knockout of FZD1/2/7, full text read [PMID:28733458]. The mouse pair is projected from human.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Loss-of-function plus rescue supports functional dependence, not physical binding. Reactome lists a generic WNT:FZD plasma-membrane complex [DB:Reactome].","key_references":[{"PMID":"28733458","why":"CRISPR FZD-knockout rescue of Wnt1 by FZD7"}],"covers":["LR001575","LR004964"]},"LR008172":{"pair":"WNT1 -> FZD8:LRP5","headline":"Computational docking suggests WNT1 binds FZD8's cysteine-rich domain; LRP5 and any experimental test are missing.","interaction_type":"database-asserted only","direction_and_effect":"Two in silico studies, read as abstracts, report that Wnt1 binds most strongly with FZD8-CRD among FZD-CRDs [PMID:41740485] and that Wnt1 and FZD8-CRD is the best docked complex [PMID:36056132]. BioGRID lists a WNT1-FZD8 reconstituted complex [DB:BioGRID].","molecular_requirements":"Evidence concerns FZD8's CRD; LRP5 is not reported in the papers. UniProt notes an LRP5 subunit interaction enhanced in presence of GSK3B and WNT1 or WNT3A [DB:UniProt].","affinity_potency":[],"species_and_systems":"In silico (docking, molecular dynamics) [PMID:41740485][PMID:36056132]; no wet-lab data.","localisation_and_range":"WNT1 is flagged as secreted [flag], so signalling would be paracrine or autocrine; this comes from the annotation flag, not from a paper.","caveats":"Both papers are computational and abstract-only. The LRP5 member is unsupported by the papers.","key_references":[{"PMID":"41740485","why":"Wnt1-FZD8-CRD binding computed"},{"PMID":"36056132","why":"Wnt1-FZD8-CRD best docked"}],"covers":["LR008172"]},"LR003465":{"pair":"WNT10A -> LRP6","headline":"Functional evidence only: Wnt10a-induced signalling was blocked by anti-LRP6 Fabs in human reporter cells; abstract read only.","interaction_type":"functional only","direction_and_effect":"Wnt10a signalling was specifically inhibited by Wnt1-class anti-LRP6 Fab fragments (A1-Fab, A2-Fab) in a SuperTopFlash reporter in HEK293 cells, consistent with LRP6 acting as a Wnt co-receptor; the Fabs bind LRP6 propeller 1 [PMID:20713706].","molecular_requirements":"Wnt1-class ligands appear to depend on LRP6 propeller 1; Frizzled involvement is not reported in our evidence [PMID:20713706].","affinity_potency":[],"species_and_systems":"Human ligand and receptor, HEK293 reporter cells [PMID:20713706]; mouse entry is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted; LRP6 flagged transmembrane [flag].","caveats":"Antibody blocking is indirect: it shows pathway dependence, not direct WNT10A binding. The curator note says the quote was browser-read and unverified, and the abstract text is truncated; the text is abstract only [PMID:20713706].","key_references":[{"PMID":"20713706","why":"Wnt10a-class signalling blocked by anti-LRP6 propeller 1 Fabs"}],"covers":["LR003465","LR006665"]},"LR010773":{"pair":"WNT10B -> FZD1:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010773"]},"LR010719":{"pair":"WNT10B -> FZD9:LRP6","headline":"Complex-level pair with no curated paper; rests on one IntAct co-immunoprecipitation record only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist or antagonist) not reported in our evidence. The only support is an IntAct record of association by anti-tag coimmunoprecipitation [DB:IntAct EBI-21797268].","molecular_requirements":"Receptor is listed as a two-chain complex; whether both chains, or either alone, are required is not reported in our evidence. ","affinity_potency":[],"species_and_systems":"Pair is human; the experimental system of the IntAct record is not reported in our evidence.","localisation_and_range":"Ligand is flagged secreted [flag]; the receptor chains are flagged as receptors, with LRP chain transmembrane [flag]. Range is not otherwise reported in our evidence.","caveats":"Only one paper row, judged review-only; the pair rests on the database record alone.","key_references":[],"covers":["LR010719"]},"LR005364":{"pair":"WNT11 -> FZD8","headline":"FZD8 is reported as a major WNT11 receptor in prostate cancer cells, shown by co-localisation, co-IP and knockdown.","interaction_type":"direct binding","direction_and_effect":"FZD8 co-localised and co-immunoprecipitated with Wnt-11 and potentiated Wnt-11 activation of ATF2-dependent transcription; FZD8 silencing reduced it by 40% [PMID:29717114]. Annotated agonist.","molecular_requirements":"Endogenous FZD8 was required for the response; FZD5 silencing had no effect, FZD2 silencing reduced it by 20% [PMID:29717114]. FZD8 also forms a TGF-beta-regulated complex with TGF-beta receptors via extracellular domains [PMID:29717114].","affinity_potency":[],"species_and_systems":"Human PC-3M prostate cancer cells (transfected, tagged proteins) and patient datasets; mouse FZD8 rescued siRNA effect [PMID:29717114]. Mouse pair is ortholog-inferred.","localisation_and_range":"Ligand flagged secreted [flag]; signalling is beta-catenin-independent [PMID:29717114].","caveats":"Wnt-11 also co-localised moderately with FZD6 and FZD10, so FZD8 is not exclusive [PMID:29717114]. No affinity.","key_references":[{"PMID":"29717114","why":"FZD8 as Wnt-11 receptor in prostate cancer; co-IP and ATF2 reporter"}],"covers":["LR002038","LR005364"]},"LR008118":{"pair":"WNT2 -> FZD1:LRP5","headline":"WNT2 to FZD1:LRP5 has no verified experiment; only a UniProt statement and review-only rows.","interaction_type":"database-asserted only","direction_and_effect":"UniProt states FZD1 is activated by WNT3A, WNT3, WNT1 and to a lesser extent WNT2 [DB:UniProt].","molecular_requirements":"LRP5 contribution is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Wnt2 flagged secreted [flag].","caveats":"Three review-only rows, no confirmed paper. The UniProt text concerns FZD1 alone.","key_references":[],"covers":["LR008118"]},"LR001584":{"pair":"WNT2 -> LRP6","headline":"Functional only: WNT2 signalling is blocked by Wnt1-class anti-LRP6 Fabs; no direct WNT2-LRP6 binding shown.","interaction_type":"functional only","direction_and_effect":"Wnt2 signalling was inhibited by Wnt1-specific anti-LRP6 Fab fragments (A1-Fab, A2-Fab), implying LRP6 propeller 1 is involved [PMID:20713706].","molecular_requirements":"LRP6 is a co-receptor for Wnt; the paper does not test whether a Frizzled is needed for Wnt2 here [PMID:20713706].","affinity_potency":[],"species_and_systems":"SuperTopFlash reporter in HEK293 cells, human [PMID:20713706]. Mouse pair is projected from human evidence.","localisation_and_range":"WNT2 is annotated as secreted [flag]; LRP6 is transmembrane [flag].","caveats":"Antibody blockade is indirect evidence of the ligand-receptor contact. Full text was read in a browser and the quote is marked unverified in the curation notes [PMID:20713706].","key_references":[{"PMID":"20713706","why":"Anti-LRP6 Fabs block Wnt2-class signalling"}],"covers":["LR001584","LR004973"]},"LR003483":{"pair":"WNT2B -> ROR2","headline":"Direct binding: WNT2B-SFRP2 co-immunoprecipitates with ROR2-ECD but not ROR1-ECD (preprint).","interaction_type":"direct binding","direction_and_effect":"Purified WNT2B-SFRP2 co-immunoprecipitated with ROR2-ECD but not ROR1-ECD, like non-canonical WNT5A-SFRP2; ROR2 rescued Ror1/Ror2-double-knockout cells [PMID:39229119].","molecular_requirements":"ROR2 extracellular domain is bound; the empty SFRP2 carrier did not bind, so WNT2B is the contact [PMID:39229119].","affinity_potency":[],"species_and_systems":"Purified human proteins and HEK293 cells [PMID:39229119]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT2B is annotated as secreted [flag].","caveats":"bioRxiv preprint, not peer reviewed; no affinity value. ROR2 acts as a co-receptor with FZD in this model [PMID:39229119].","key_references":[{"PMID":"39229119","why":"WNT2B-SFRP2 binds ROR2-ECD, not ROR1-ECD"}],"covers":["LR003483","LR006683"]},"LR001593":{"pair":"WNT3 -> FZD1","headline":"Functional evidence from two papers: Hfz1 enhances Wnt3-induced TCF signalling, and FZD1/2/7 knockout abolishes it.","interaction_type":"functional only","direction_and_effect":"Wnt-3a, -3, -1 and less so Wnt-2 cooperated with Hfz1 in a TCF paracrine assay [PMID:10557084]. FZD1, FZD2 and FZD7 are required for Wnt3/3a beta-catenin signalling in HEK293T cells [PMID:28733458]. UniProt also lists WNT3 as an activator [DB:UniProt].","molecular_requirements":"FZD1 acts redundantly with FZD2 and FZD7: re-expressing FZD2 or FZD7 rescued signalling after triple knockout [PMID:28733458].","affinity_potency":[],"species_and_systems":"Human cells: reporter assays in human cells [PMID:10557084] and HEK293T CRISPR mutants [PMID:28733458]. Mouse pair is ortholog-inferred.","localisation_and_range":"WNT3 annotation as secreted is not given in our evidence; localisation not reported.","caveats":"Co-IP of Hfz1 was reported with Wnt-3a and Wnt-5a, so binding alone does not set specificity [PMID:10557084]. One paper read as abstract only.","key_references":[{"PMID":"10557084","why":"Hfz1 enhances Wnt-3 TCF signalling"},{"PMID":"28733458","why":"FZD1/2/7 needed for Wnt3 signalling"}],"covers":["LR001593","LR004982"]},"LR007614":{"pair":"WNT3 -> SFRP1","headline":"Only a computational docking study links WNT3 and SFRP1; it ranks SFRP1 among the lowest-affinity SFRP partners.","interaction_type":"functional only","direction_and_effect":"SFRP1 is an annotated Wnt antagonist class (SFRP family); docking found SFRP3 has the highest binding affinity to Wnt3 while SFRP1 and SFRP5 have the lowest [PMID:40372458].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"In silico homology models and molecular dynamics of human SFRPs; no wet experiment [PMID:40372458]. Abstract only.","localisation_and_range":"SFRPs are secreted antagonists that act near secreting cells when positively charged [PMID:40372458].","caveats":"Computational only; no measured binding. Interaction class is Ligand-Ligand (inhibitor), not a receptor interaction. Docking affinity is a model output without a reported value.","key_references":[{"PMID":"40372458","why":"Docking of SFRPs with Wnt3"}],"covers":["LR007614"]},"LR008181":{"pair":"WNT3A -> FZD8:LRP5","headline":"No curated paper for this complex; database notes only.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect are not reported in our evidence beyond database records.","molecular_requirements":"Complex requirement is not shown; records are IntAct pull-down entries [DB:IntAct] and UniProt notes [DB:UniProt].","affinity_potency":[],"species_and_systems":"Species and experimental system are not reported in our evidence for this complex.","localisation_and_range":"WNT3A carries a secreted flag and no transmembrane flag [flag], so it acts as a secreted ligand; range is not reported in our evidence.","caveats":"No record shows WNT3A binding to the FZD8:LRP5 complex. Papers were review_only.","key_references":[],"covers":["LR008181"]},"LR003492":{"pair":"WNT3A -> GPC3","headline":"WNT3A binds the GPC3 protein core directly in pull-down and co-IP; mutation of a groove around F41 abolishes binding.","interaction_type":"direct binding","direction_and_effect":"GPC3 acts as a Wnt co-receptor that promotes Wnt/beta-catenin activation; mutating the groove inhibits Wnt3a binding and beta-catenin activation [PMID:30963603].","molecular_requirements":"Binding is HS-chain independent: GPC3 without heparan sulfate chains still bound Wnt3a, and F41 with W260, Y264 and M269 are needed. The groove matters most when FZD is not abundant [PMID:30963603].","affinity_potency":[],"species_and_systems":"Purified hFc-GPC3 pulled down recombinant human Wnt3a; co-IP in HEK293T cells; HCC xenografts in nude mice [PMID:30963603]. Human pair, mouse version projected from human.","localisation_and_range":"Ligand flagged secreted, GPC3 not flagged secreted [flag]; GPC3 is described as an HSPG co-receptor [PMID:30963603].","caveats":"Binding sites on Wnt3a were mapped partly by docking models; GPC3 also bound Wnt1, Wnt5b and Wnt8a, so it is not Wnt3a-specific [PMID:30963603]. UniProt also lists the interaction [DB:UniProt].","key_references":[{"PMID":"30963603","why":"pull-down, co-IP, mutagenesis of the GPC3 groove"}],"covers":["LR003492","LR006692"]},"LR011277":{"pair":"WNT4 -> FZD1:LRP5","headline":"No curator-verified paper; only a UniProt statement that argues against WNT4 activating FZD1.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence as confirmed.","molecular_requirements":"The pair is a FZD1 plus LRP5 complex; no verified evidence for the complex.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Papers were judged abstract-insufficient or review-only. UniProt says FZD1 is apparently not activated by WNT4 [DB:UniProt].","key_references":[],"covers":["LR011277"]},"LR008082":{"pair":"WNT4 -> FZD6:LRP6","headline":"Support is for WNT4-FZD6 only; nothing in our evidence tests LRP6 in the complex.","interaction_type":"functional only","direction_and_effect":"Wnt-4 forms a complex with the Frizzled-6 CRD in MDCK cells [PMID:15265686]; Fz6 is a Wnt4 receptor in hematopoietic progenitors [PMID:21541287]. GtoPdb lists agonist [DB:GtoPdb].","molecular_requirements":"LRP6 involvement is not reported in our evidence; both papers concern FZD6 alone.","affinity_potency":[],"species_and_systems":"MDCK cells [PMID:15265686]; hematopoietic progenitor cells [PMID:21541287].","localisation_and_range":"Ligand flagged secreted [flag].","caveats":"Evidence applies to WNT4-FZD6, not the LRP6-containing complex. Both papers abstract-read. FZD6 did not transduce canonical signal in MDCK cells [PMID:15265686].","key_references":[{"PMID":"15265686","why":"Wnt-4 complex with Fz6 CRD"},{"PMID":"21541287","why":"Fz6 as Wnt4 receptor"}],"covers":["LR008082"]},"LR008136":{"pair":"WNT5A -> FZD4:LRP5","headline":"Wnt5a activates beta-catenin signalling when both Fz4 and LRP5 are present in 293 cells; one functional paper.","interaction_type":"functional only","direction_and_effect":"Wnt5a can activate Wnt/beta-catenin signalling in the presence of Fz4 and LRP5 [PMID:16602827]. Wnt5a protein or Wnt5a DNA alone could not activate the STF reporter in cells expressing mFz4 without LRP5 [PMID:16602827].","molecular_requirements":"Both Fz4 and LRP5 were needed for the activation; LRP6 did not support it (data unpublished in that paper) [PMID:16602827].","affinity_potency":[],"species_and_systems":"Human 293 cells with Fz4 and LRP5 co-expression, STF reporter; Wnt5a purified from cells overexpressing mouse Wnt5a [PMID:16602827].","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Functional reporter evidence only, no binding measurement. The LRP6 negative is stated as unpublished data in the paper. One further paper was review-only.","key_references":[{"PMID":"16602827","why":"Wnt5a activates beta-catenin signalling with Fz4 plus LRP5"}],"covers":["LR008136"]},"LR008163":{"pair":"WNT5A -> FZD6:LRP5","headline":"No paper evidence for WNT5A with the FZD6:LRP5 complex; database records only.","interaction_type":"database-asserted only","direction_and_effect":"Not reported in our evidence. GtoPdb lists WNT5A-FZD6 as agonist [DB:GtoPdb].","molecular_requirements":"Not reported in our evidence; records concern individual chains.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"WNT5A is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine by this annotation.","caveats":"Rests on database records alone; the judged papers were review-only.","key_references":[],"covers":["LR008163"]},"LR006705":{"pair":"WNT5A -> FZD9","headline":"Functional evidence in neurons that FZD9 interacts with Wnt-5a and is required for spine formation; one abstract-only paper.","interaction_type":"functional only","direction_and_effect":"FZD9 is required for the Wnt-5a-mediated increase in dendritic spine density; Wnt-5a stimulation dissociates a precoupled FZD9-Galphao complex, and Gbetagamma is needed for the cytosolic calcium increase [PMID:27402827]. Curated stimulatory.","molecular_requirements":"Galphao and Gbetagamma are downstream requirements; co-receptors not reported in our evidence [PMID:27402827].","affinity_potency":[],"species_and_systems":"Cultured hippocampal neurons; the abstract refers to rodent neurons, while the curation lists human, so species should be checked [PMID:27402827].","localisation_and_range":"Ligand flagged secreted [flag]; FZD9 localised to the postsynaptic region [PMID:27402827].","caveats":"Abstract only. The paper reports that FZD9 'interacts' with Wnt-5a, but no binding constant or direct binding assay is reported in our evidence.","key_references":[{"PMID":"27402827","why":"FZD9 required for Wnt-5a spine formation; G protein coupling"}],"covers":["LR003505","LR006705"]},"LR006714":{"pair":"WNT5B -> FZD5","headline":"WNT5B binds the FZD5 CRD with intermediate to strong affinity in a single BLI mapping study.","interaction_type":"direct binding","direction_and_effect":"Binding: WNT-5A and WNT-5B showed intermediate to strong binding to the FZD5 CRD; signalling effect of WNT-5B is not shown [PMID:25605717].","molecular_requirements":"CRD only; co-receptors not reported in our evidence.","affinity_potency":[{"value":"KD = 5\u201322 nm","assay":"bio-layer interferometry, FZD CRD-Fc (+++ to ++++), range given for WNT-5A and WNT-5B","system":"purified mouse proteins","cite":"PMID:25605717"}],"species_and_systems":"Mouse proteins (purified WNT binding to FZD CRD-Fc), bio-layer interferometry [PMID:25605717]; human pair is ortholog-inferred.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Binding only; Wnt5b was not shown to activate signalling in this paper (the abstract reports WNT-3A but not WNT-5A as the activator in 32D cells) [PMID:25605717]. Only the abstract was curated, with excerpts from a browser read. The KD range is shared with WNT-5A.","key_references":[{"PMID":"25605717","why":"FZD5 CRD binding by WNT-5A/5B"}],"covers":["LR003514","LR006714"]},"LR005373":{"pair":"WNT5B -> FZD8","headline":"WNT5B binds the FZD8 CRD in two BLI studies with differing KD, and FZD8 knockdown reduces WNT-5B responses in human fibroblasts.","interaction_type":"direct binding","direction_and_effect":"Stimulatory: FZD8 knockdown reduced WNT-5B-induced fibronectin and alpha-sm-actin expression and WNT-5B-induced impedance changes in lung fibroblasts [PMID:26849959].","molecular_requirements":"CRD alone was used for binding; co-receptor need not reported in our evidence.","affinity_potency":[{"value":"KD = 4\u20138 nm","assay":"bio-layer interferometry, FZD8 CRD-Fc; WNT-5A and WNT-5B","system":"purified mouse proteins","cite":"PMID:25605717"},{"value":"KD = 36 nm","assay":"biolayer interferometry, Wnt5b to Fz8 CRD-Fc","system":"mouse Fz8 CRD","cite":"PMID:20093360"}],"species_and_systems":"Binding with mouse proteins; function in human MRC-5 and primary lung fibroblasts, plus FZD8-deficient mice in a fibrosis model [PMID:26849959].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"The two KD values disagree (4\u20138 nm vs 36 nm) [PMID:25605717, PMID:20093360]. The mouse fibrosis result concerns TGF-beta signalling, and the WNT-5B link is from siRNA in cells [PMID:26849959].","key_references":[{"PMID":"25605717","why":"FZD8 CRD binding by WNT-5A/5B"},{"PMID":"20093360","why":"Wnt5b KD to Fz8 CRD"},{"PMID":"26849959","why":"FZD8-dependent WNT-5B profibrotic signalling"}],"covers":["LR002047","LR005373"]},"LR008091":{"pair":"WNT5B -> FZD8:LRP6","headline":"Only a FZD8 docking study exists; LRP6 is not addressed.","interaction_type":"computational prediction only","direction_and_effect":"Direction not reported; docking of hWnt5b to hFzd isoforms gave the highest binding affinity with hFzd8 [PMID:31285641].","molecular_requirements":"FZD8 only is addressed; LRP6 requirement not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human homology models, docking only [PMID:31285641].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Computational and abstract only; no measured affinity in our evidence. Others were review-only or insufficient.","key_references":[{"PMID":"31285641","why":"docking of hWnt5b against hFzd isoforms"}],"covers":["LR008091"]},"LR007722":{"pair":"WNT5B -> SFRP1","headline":"Molecular-dynamics models suggest the SFRP1 CRD binds Wnt5B; SFRP1 is an inhibitor, not a receptor.","interaction_type":"computational prediction only","direction_and_effect":"Inhibitory (Ligand-Ligand annotation): SFRP1 CRD showed more affinity toward Wnt5B than toward FZ receptors in simulations [PMID:33666148].","molecular_requirements":"SFRP1 CRD or Netrin domains; the Netrin domain favoured FZ receptors [PMID:33666148].","affinity_potency":[],"species_and_systems":"Homology models and molecular dynamics, murine hair follicle stem cell context; no wet-lab data [PMID:33666148].","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"Computational and abstract only; affinity values are not reported in our evidence. One more paper was review-only.","key_references":[{"PMID":"33666148","why":"SFRP1-Wnt5B modelling"}],"covers":["LR007722"]},"LR011286":{"pair":"WNT6 -> FZD1:LRP5","headline":"No verified paper; the only database line says FZD1 is apparently not activated by WNT6.","interaction_type":"database-asserted only","direction_and_effect":"Direction not reported. UniProt says FZD1 is apparently not activated by WNT6 [DB:UniProt].","molecular_requirements":"Not reported in our evidence.","affinity_potency":[],"species_and_systems":"Not reported in our evidence.","localisation_and_range":"Ligand is annotated as secreted [flag], so paracrine or endocrine range is implied by the annotation only.","caveats":"No paper confirmed the pair; the sole database record is a negative statement [DB:UniProt].","key_references":[],"covers":["LR011286"]},"LR003519":{"pair":"WNT7A -> ADGRA2","headline":"WNT7A does not bind ADGRA2 alone in our evidence; the paper shows RECK binds WNT7A and ADGRA2 acts with RECK.","interaction_type":"conflicting","direction_and_effect":"The curated paper reports that WNT7A binds soluble RECK, cell-surface RECK and the GPR124 (ADGRA2):RECK complex, but WNT7A did not appreciably bind sGPR124-Fc and was not pulled down with bSNAP-GPR124 [PMID:30304675]. The ADGRA2 ectodomain mediates RECK/WNT7-induced canonical signalling [PMID:30304675]; UniProt says it works with RECK to let endothelial cells respond to Wnt7 [DB:UniProt].","molecular_requirements":"ADGRA2 needs RECK as the WNT7 binder, with FZD and LRP co-receptors; RECK and WNT7A form a 1:1 complex that stabilises active monomeric WNT7A [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human proteins in HEK293 cells, plus rat brain vessels for the RECK-GPR124 association [PMID:30304675]; the mouse pair is projected from human evidence.","localisation_and_range":"WNT7A is flagged secreted and non-transmembrane [flag]; ADGRA2 is flagged transmembrane [flag]; RECK is GPI-anchored at the cell surface [PMID:30304675].","caveats":"The paper itself shows WNT7A binds RECK, not GPR124 alone, so the direct_binding label for WNT7A to ADGRA2 is not supported by the text shown; the abstract's 'binds the GPR124:RECK complex' is complex-level.","key_references":[{"PMID":"30304675","why":"WNT7A binds RECK and the GPR124:RECK complex, not GPR124 alone"}],"covers":["LR003519","LR006719"]},"LR006723":{"pair":"WNT7A -> FZD8","headline":"WNT7A binds soluble FZD8 in a full-text-verified pull-down; direct binding, single paper.","interaction_type":"direct binding","direction_and_effect":"sFZD8 captured WNT7A more efficiently than sRECK in co-pull-down from HEK293 conditioned medium, i.e. WNT7A binds FZD8 [PMID:30304675]. FZD8 overexpression with WNT7 activated the STF reporter even in FZD1/2/4/5/7/8 knockout cells [PMID:30304675].","molecular_requirements":"RECK drastically enhanced FZD8:WNT7 binding [PMID:30304675]. Functionally, GPR124/RECK/WNT7 signalling depends on endogenous FZDs [PMID:30304675].","affinity_potency":[],"species_and_systems":"Human WNT7A and FZD8 constructs in HEK293 cells, recombinant soluble ECD-Fc [PMID:30304675]. Mouse pair is projected from human.","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence. Receptor is flagged as not secreted [flag].","caveats":"Binding was seen only when sFZD8 was added to the medium of WNT7A-expressing cells; cell-free conditioned medium WNT7A did not bind sFZD8, indicating short-lived active WNT7A [PMID:30304675]. No affinity reported. Single paper.","key_references":[{"PMID":"30304675","why":"Co-pull-down of WNT7A with sFZD8 (full text)"}],"covers":["LR003523","LR006723"]},"LR008019":{"pair":"WNT7B -> ADGRA2:FZD5:LRP5:RECK","headline":"Complex row: WNT7B with GPR124 and RECK has abstract-level support; FZD5 and LRP5 are not shown by the paper.","interaction_type":"direct binding","direction_and_effect":"Reck binds the disordered linker of Wnt7, and Gpr124 plus Reck let brain endothelial cells selectively respond to Wnt7; Reck-bound Wnt7 is recruited into Wnt/Frizzled/Lrp5/6 signalosomes [PMID:30026314]. UniProt agrees [DB:UniProt].","molecular_requirements":"Complex needs ADGRA2, RECK, FZD5 and LRP5 in this row, but only the ADGRA2:RECK part is supported; FZD5 and the LRP are not named in the abstract [PMID:30026314]. Scoring by the least-expressed subunit may over-require them.","affinity_potency":[{"value":"low micromolar","assay":"Reck binding to Wnt7 linker region","system":"abstract states low micromolar affinity, no assay detail","cite":"PMID:30026314"}],"species_and_systems":"Curator lists human proteins in brain endothelial cells; abstract-only reading [PMID:30026314].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Affinity is for RECK-Wnt7, not for the full complex. Ligand is not specified as WNT7B versus WNT7A in the abstract beyond Wnt7.","key_references":[{"PMID":"30026314","why":"Reck binds Wnt7 linker; Gpr124/Reck confer Wnt7 selectivity"}],"covers":["LR008019"]},"LR008046":{"pair":"WNT7B -> FZD10:LRP6","headline":"WNT7B-FZD10:LRP6 rests on a FZD10/LRP5 abstract, so the LRP6 part is unsupported.","interaction_type":"functional only","direction_and_effect":"Wnt7b bound Fzd10 on the cell surface and cooperatively activated canonical signalling with LRP5 [PMID:15923619].","molecular_requirements":"The paper names LRP5, not LRP6, as the co-receptor [PMID:15923619].","affinity_potency":[],"species_and_systems":"Cell-surface binding assay; species not specified in this row [PMID:15923619].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only; LRP6 is not tested in the cited evidence.","key_references":[{"PMID":"15923619","why":"Wnt7b-Fzd10 binding, LRP5 cooperation"}],"covers":["LR008046"]},"LR008145":{"pair":"WNT7B -> FZD4:LRP5","headline":"WNT7B with FZD4 and LRP5 has only a UniProt in vitro note; no paper confirmed it.","interaction_type":"database-asserted only","direction_and_effect":"UniProt records a FZD4 interaction as in vitro [DB:UniProt].","molecular_requirements":"Complex pairs FZD4 with LRP5; no evidence on subunit need.","affinity_potency":[],"species_and_systems":"In vitro per UniProt [DB:UniProt].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Only review-only papers; support is database-only.","key_references":[],"covers":["LR008145"]},"LR003528":{"pair":"WNT7B -> FZD7","headline":"WNT7B-FZD7 is supported by loss-of-function data in neurons; abstract only.","interaction_type":"functional only","direction_and_effect":"Fz7 was identified as the receptor for Wnt7b-mediated dendrite growth; loss of Fz7 prevented Wnt7b from promoting arborisation and caused dendritic defects in mouse hippocampus; signalling induced CaMKII and JNK phosphorylation, non-canonical [PMID:29898920].","molecular_requirements":"No co-receptor reported in our evidence.","affinity_potency":[],"species_and_systems":"Hippocampal neurons and mouse hippocampus in vivo; curator lists human ligand and receptor [PMID:29898920].","localisation_and_range":"Ligand is flagged secreted and non-transmembrane [flag], so paracrine or autocrine action is expected; the paper's own data on range are not reported in our evidence.","caveats":"Abstract only. Functional requirement, not direct binding.","key_references":[{"PMID":"29898920","why":"Fz7 required for Wnt7b dendrite growth"}],"covers":["LR003528","LR006728"]},"LR006732":{"pair":"WNT8A -> PTK7","headline":"WNT8A co-precipitates with PTK7 in one abstract, but PTK7 inhibits rather than activates canonical signalling.","interaction_type":"direct binding","direction_and_effect":"PTK7/Otk co-precipitates canonical Wnt3a and Wnt8, yet PTK7 inhibits rather than activates canonical Wnt activity in Xenopus, Drosophila and luciferase reporter assays [PMID:21772251]. Loss of PTK7 activates canonical signalling and PTK7 acts at the level of the Frizzled receptor [PMID:21772251].","molecular_requirements":"Not reported in our evidence beyond placing PTK7 at the Frizzled level.","affinity_potency":[],"species_and_systems":"Xenopus, Drosophila and luciferase reporter assays; Wnt8 not resolved to WNT8A in the abstract [PMID:21772251]. The mouse pair is projected from human.","localisation_and_range":"WNT ligand is flagged secreted and not transmembrane [flag], so signalling would be paracrine or autocrine; no paper in our evidence measured range.","caveats":"Abstract only; co-precipitation is not proof of direct binding, and the effect is inhibitory (PTK7 turns off canonical signalling), not agonist [PMID:21772251]. Paralog 'Wnt8' is generic.","key_references":[{"PMID":"21772251","why":"PTK7 co-precipitates Wnt8 and inhibits canonical Wnt"}],"covers":["LR003532","LR006732"]},"LR003537":{"pair":"WNT9A -> EGFR","headline":"EGFR is required as a cofactor for WNT9A-FZD9 signalling; functional evidence, with binding to EGFR only suggested.","interaction_type":"functional only","direction_and_effect":"EGFR is required as a cofactor for Wnt9a-Fzd9b signalling; EGFR-mediated phosphorylation of a Fzd9b tail tyrosine promotes internalisation of the signalosome [PMID:31110287]. EGFR knockdown reduced cell-surface Wnt9a binding, including without Fzd9b, which the authors say suggests direct binding [PMID:31110287].","molecular_requirements":"EGFR acts together with FZD9 (Fzd9b in zebrafish) and LRP6; cetuximab, which blocks EGFR ligand binding, dampened the signal [PMID:31110287].","affinity_potency":[],"species_and_systems":"Zebrafish in vivo, human embryonic stem cells and HEK293T cells [PMID:31110287]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Direct Wnt9a-EGFR binding is inferred from knockdown, not measured in our evidence. EGFR acts as a cofactor of FZD9, not as a stand-alone Wnt receptor. Dossier text is from both abstract and excerpts.","key_references":[{"PMID":"31110287","why":"Shows EGFR is a required cofactor for Wnt9a-Fzd9b signalling."}],"covers":["LR003537","LR006737"]},"LR005382":{"pair":"WNT9A -> FZD10","headline":"WNT9A signals through FZD10 in a reporter-cell rescue map; functional evidence from one paper, no binding data.","interaction_type":"functional only","direction_and_effect":"WNT9A signalled only via FZD4 and FZD10 among the FZDs tested, inducing canonical reporter signalling (agonism) [PMID:28733458].","molecular_requirements":"Only the Frizzled receptor is tested; co-receptors are not reported in our evidence.","affinity_potency":[],"species_and_systems":"Experiments used reporter cells in a rescue design with FZD-mutant lines [PMID:28733458]; species of the cells is not stated in the excerpts. The mouse pair is projected from the human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Functional reporter readout only; no direct binding shown. Paper is a genetic rescue map of Wnt-FZD pairs, so paralog FZDs differ in specificity [PMID:28733458].","key_references":[{"PMID":"28733458","why":"Multiplex CRISPR FZD-knockout rescue map of Wnt-Frizzled signalling (full text read)."}],"covers":["LR002056","LR005382"]},"LR006741":{"pair":"WNT9A -> FZD9","headline":"WNT9A signals specifically through FZD9 in zebrafish and human cells; functional evidence, one paper.","interaction_type":"functional only","direction_and_effect":"Wnt9a signals specifically through Fzd9b to elicit beta-catenin-dependent signalling regulating haematopoietic stem and progenitor cell emergence; in the STF reporter assay only human FZD9 coupled effectively with WNT9A [PMID:31110287].","molecular_requirements":"EGFR is required as a cofactor, and LRP6 is needed (synergy with Lrp6 co-transfection) [PMID:31110287].","affinity_potency":[],"species_and_systems":"Zebrafish in vivo, human embryonic stem cells and HEK293T cells [PMID:31110287]. The mouse pair is projected from human evidence (ortholog-inferred).","localisation_and_range":"Secreted ligand per the entity annotation flag [flag]; paracrine range is inferred from that flag only, not reported in the papers.","caveats":"Curated from the abstract for this pair, with supporting full-text passages in the dossier. Functional only; no binding measurement in our evidence.","key_references":[{"PMID":"31110287","why":"Wnt9a-Fzd9b specificity, EGFR and LRP6 requirements."}],"covers":["LR003541","LR006741"]},"LR008154":{"pair":"WNT9B -> FZD5:LRP5","headline":"Complex rests on a single functional reporter study of WNT9B with FZD5; the LRP5 co-receptor was not tested.","interaction_type":"functional only","direction_and_effect":"WNT9B induced canonical signalling with FZD5 in a FZD rescue reporter map; effect is activating (canonical) [PMID:28733458].","molecular_requirements":"The cited study tested FZD receptors in rescue assays and does not report LRP5 as a tested subunit of this complex in our excerpts; the complex is a combination of the pair FZD5 and LRP5 not evaluated as a unit.","affinity_potency":[],"species_and_systems":"Human reporter cells, HEK293 FZD multiplex-knockout panel with rescue; full text read [PMID:28733458].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Evidence is for the Frizzled chain alone; LRP5 is not shown to be required. Functional readout only, no binding measured. Other judged papers were review_only or abstract_insufficient.","key_references":[{"PMID":"28733458","why":"FZD knockout/rescue reporter map showing WNT9B signalling"}],"covers":["LR008154"]},"LR003546":{"pair":"WNT9B -> LRP5","headline":"WNT9B signalling through LRP5 requires LRP5 together with LRP6 in mouse cells; one abstract-level paper.","interaction_type":"functional only","direction_and_effect":"Wnt1, Wnt9b and Wnt10b require both LRP5 and LRP6 to signal at endogenous levels; curators label it agonist [PMID:22433869].","molecular_requirements":"Both LRP5 and LRP6 are required for this ligand subgroup; Wnt3a prefers LRP6 and needs only one; an LRP5-6 heteromer was documented by IFAST immunoprecipitation [PMID:22433869].","affinity_potency":[],"species_and_systems":"Mouse embryonic fibroblasts, mammary epithelial cells and mammary outgrowths in vivo; human pair is ortholog-inferred [PMID:22433869].","localisation_and_range":"WNT9B is flagged as secreted [flag], so signalling would be paracrine; the receptor is a membrane receptor [flag].","caveats":"Functional requirement only, no direct Wnt9b-LRP5 binding; when either LRP is overexpressed the requirement for both disappears. Abstract level only.","key_references":[{"PMID":"22433869","why":"LRP5 and LRP6 both needed for Wnt9b response"}],"covers":["LR003546","LR006746"]},"LR012393":{"pair":"ZNRF3 -> FZD8:LRP6","headline":"Database-asserted only: ZNRF3 (an E3 ligase) is listed as inhibiting a FZD:LRP receptor complex; no curator-verified paper.","interaction_type":"database-asserted only","direction_and_effect":"Marked inhibitory in the resource, with ZNRF3 acting as a membrane receptor-receptor regulator rather than a classical secreted ligand [flag]. UniProt states ZNRF3 interacts with LRP6, FZD4, FZD5, FZD6 and FZD8 [PMID:22575959][DB:UniProt]; IntAct records anti-bait co-immunoprecipitation (Q9ULT6-O75581) [DB:IntAct]; BioGRID records ZNRF3 - LRP6: Affinity Capture-Western; LRP6 - ZNRF3: Affinity Capture-Western [DB:BioGRID]; Reactome lists ZNRF3,RNF43 binding the FZD:LRP5/6 receptor complex [DB:Reactome]. Functional effect not reported in our evidence.","molecular_requirements":"The listed FZD8 partner is named in the UniProt statement; LRP6 evidence is present [DB:UniProt]. Whether FZD or LRP alone suffices is not reported in our evidence.","affinity_potency":[],"species_and_systems":"Human. Experimental system not reported in our evidence beyond the database assay labels.","localisation_and_range":"ZNRF3 is flagged as a receptor, not secreted [flag]; this is a membrane-level interaction.","caveats":"All papers for this pair are pending or insufficient; support comes only from databases. The pair is a receptor-receptor complex projection and a given FZD paralog may not have been tested individually.","key_references":[],"covers":["LR012393"]},"LR000882":{"pair":"IL1B -> IL1R2","headline":"IL1R2 binds IL-1 beta directly and acts as an inhibitory decoy; supported by radioligand binding and structure.","interaction_type":"direct binding","direction_and_effect":"Inhibitory decoy. Soluble type II IL-1 receptor is a specific inhibitor of IL-1 beta, and binding the precursor blocked its processing to the mature 17-kDa form [PMID:7878046].","molecular_requirements":"Single chain. Soluble and cell-surface receptor bound the same regions of IL-1 beta. The cell-surface form did not bind the IL-1 beta precursor, but the released soluble form did [PMID:7878046]. A PDB complex exists [DB:PDB 3O4O].","affinity_potency":[],"species_and_systems":"Human Raji B cell line, competition binding [PMID:7878046]. Mouse pair is ortholog-inferred.","localisation_and_range":"IL1B is annotated secreted [flag]. IL1R2 occurs as a membrane form and a released soluble form, which extends its range [PMID:7878046].","caveats":"Single paper, read as abstract only; no affinity value stated in our evidence. Affinity for IL-1ra dropped by a factor of 2000 for the soluble form [PMID:7878046]. Reactome lists a complex with IL1B [DB:Reactome].","key_references":[{"PMID":"7878046","why":"Competition binding and blocking of IL-1 beta precursor processing by IL1R2."}],"covers":["LR000882","LR004312"]},"LR008406":{"pair":"TXLNA -> STX3","headline":"Database-asserted binding of TXLNA to STX3; no curated papers, support rests on BioGRID, IntAct and Reactome records.","interaction_type":"database-asserted only","direction_and_effect":"Direction and effect (agonist, antagonist or other) are not reported in our evidence. Reactome lists a binding reaction (TXLNA binds syntaxin3) and a TXLNA:STX3 complex at the plasma membrane [DB:Reactome] [PMID:12558796].","molecular_requirements":"Subunit or co-receptor requirements are not reported in our evidence. The records describe a two-protein complex.","affinity_potency":[],"species_and_systems":"Human pair [DB:BioGRID]. BioGRID labels the record a reconstituted complex [PMID:12558796]; IntAct records association by anti tag coimmunoprecipitation [DB:IntAct] [PMID:33961781].","localisation_and_range":"Reactome places the complex at the plasma membrane [DB:Reactome]; range from annotation flags or paper text is not reported in our evidence.","caveats":"No curated paper was judged for this pair (the one judged row was classed different_entity), so support comes only from database records. Papers were not read by curators for this pair.","key_references":[{"PMID":"12558796","why":"Source cited by BioGRID and Reactome for the binding record"},{"PMID":"33961781","why":"Source cited by IntAct for coimmunoprecipitation"}],"covers":["LR008406"]}};